#!/usr/bin/env npx tsx
/**
 * Agent CRUD -- Full lifecycle
 *
 * Demonstrates: create with all fields, list with pagination, get detail,
 * update (partial), duplicate, delete. Self-verifying with assertions.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/01-agent-crud.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertContains,
  assertDefined,
  assertEqual,
  log,
  onCleanup,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Create an agent with all available fields
  // ═══════════════════════════════════════════════════════════════════════════

  log("create", "Creating agent with full configuration...");

  const { data: agent } = await api.post("/agents", {
    firstName: "Revenue",
    lastName: "Analyst",
    role: "Financial Data Analyst",
    shortBio: "Analyzes revenue data and generates reports",
    bio: "A specialized financial analyst agent that tracks revenue metrics, identifies trends, and produces executive summaries for quarterly reviews.",
    // objective/tone/behaviour are REMOVED fields (400 on create AND update, probed 2026-07):
    // behavioural rules live in the system prompt (set below via PATCH).
    tags: "finance,revenue,analytics,reporting",
    model: "gpt-4o"
  });

  assertDefined(agent.id, "agent.id");
  assertEqual(agent.firstName, "Revenue", "firstName");
  assertEqual(agent.lastName, "Analyst", "lastName");
  assertEqual(agent.role, "Financial Data Analyst", "role");
  log(
    "create",
    `Behaviours stored: ${(agent.behaviour ?? []).length} (behaviour may be empty until PATCH update)`
  );

  onCleanup(async () => {
    log("cleanup", `Deleting agent ${agent.id}...`);
    await api.del(`/agents/${agent.id}`);
  });

  success(`Agent created: ${agent.firstName} ${agent.lastName} (${agent.id})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: List agents with pagination
  // ═══════════════════════════════════════════════════════════════════════════

  log("list", "Listing agents (page 1, limit 5)...");

  const { data: agents, meta } = await api.get("/agents?page=1&limit=5");

  assert(Array.isArray(agents), "agents should be an array");
  assert(agents.length >= 1, "Should have at least 1 agent");

  log("list", `Found ${meta?.total ?? agents.length} agent(s)`);

  // Verify our agent appears in the list
  assertContains(agents, (a: any) => a.id === agent.id, "Created agent should appear in list");

  success(`List returned ${agents.length} agents on page 1`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: List with search filter
  // ═══════════════════════════════════════════════════════════════════════════

  log("search", "Searching for agent by name...");

  const { data: searchResult } = await api.get(`/agents?search=Revenue&page=1&limit=10`);

  assert(Array.isArray(searchResult), "search result should be an array");
  assertContains(
    searchResult,
    (a: any) => a.id === agent.id,
    "Agent should appear in search results for 'Revenue'"
  );

  success(`Search for 'Revenue' returned ${searchResult.length} result(s)`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Get agent detail
  // ═══════════════════════════════════════════════════════════════════════════

  log("get", "Fetching agent detail...");

  const { data: detail } = await api.get(`/agents/${agent.id}`);

  assertEqual(detail.id, agent.id, "detail.id");
  assertEqual(detail.firstName, "Revenue", "detail.firstName");
  assertEqual(detail.role, "Financial Data Analyst", "detail.role");
  // Note: shortBio and tags may not be set via create -- they persist only via PATCH.
  // objective/tone/behaviour are removed fields; the GET never returns them.
  log("get", `shortBio: ${detail.shortBio || "(empty)"}`);
  log("get", `tags: ${detail.tags || "(empty)"}`);

  success("Agent detail verified with all fields");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: Update agent (partial -- only changed fields)
  // ═══════════════════════════════════════════════════════════════════════════

  log("update", "Updating agent prompt and tone...");

  const { data: updated } = await api.patch(`/agents/${agent.id}`, {
    prompt: [
      "You are a revenue analyst at a SaaS company.",
      "",
      "Capabilities:",
      "- Analyze monthly recurring revenue (MRR) trends",
      "- Calculate churn rates and net revenue retention",
      "- Produce executive summary reports",
      "",
      "Rules:",
      "- Always show percent change vs. prior period",
      "- Use tables for data with 3+ rows"
    ].join("\n")
    // tone/behaviour are REMOVED fields (400) — the Rules block above IS the behaviour surface.
  });

  assert(
    updated.prompt != null && updated.prompt.includes("revenue analyst"),
    "Prompt should be updated"
  );

  // Verify unchanged fields were not affected
  assertEqual(updated.firstName, "Revenue", "firstName should be unchanged");
  assertEqual(updated.role, "Financial Data Analyst", "role should be unchanged");

  success("Agent updated (prompt carries the rules) -- other fields unchanged");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Duplicate agent
  // ═══════════════════════════════════════════════════════════════════════════

  log("duplicate", "Duplicating agent...");

  const { data: duplicate } = await api.post(`/agents/${agent.id}/duplicate`);

  assertDefined(duplicate.id, "duplicate.id");
  assert(duplicate.id !== agent.id, "Duplicate should have a new ID");
  assertEqual(duplicate.role, "Financial Data Analyst", "Duplicate should preserve role");
  log("duplicate", `Duplicate behaviours: ${(duplicate.behaviour ?? []).length}`);

  onCleanup(async () => {
    log("cleanup", `Deleting duplicate ${duplicate.id}...`);
    await api.del(`/agents/${duplicate.id}`);
  });

  success(`Duplicated: ${duplicate.id} (copy of ${agent.id})`);

  // Verify both exist in list
  const { data: afterDup } = await api.get("/agents?page=1&limit=50");
  assert(Array.isArray(afterDup), "agent list should be an array");
  const ids = afterDup.map((a: any) => a.id);
  assert(ids.includes(agent.id), "Original should still exist");
  assert(ids.includes(duplicate.id), "Duplicate should exist");

  success("Both original and duplicate verified in agent list");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 7: Delete agents
  // ═══════════════════════════════════════════════════════════════════════════

  log("delete", "Deleting duplicate...");

  const { data: deleteResult } = await api.del(`/agents/${duplicate.id}`);
  assertEqual(deleteResult.deleted, true, "deleted flag");
  assertEqual(deleteResult.id, duplicate.id, "deleted id");

  // Remove from cleanup since we manually deleted
  success("Duplicate deleted");

  // Verify it no longer appears
  const { data: afterDelete } = await api.get("/agents?page=1&limit=50");
  assert(Array.isArray(afterDelete), "agent list should be an array");
  const remainingIds = afterDelete.map((a: any) => a.id);
  assert(!remainingIds.includes(duplicate.id), "Duplicate should no longer appear in list");
  assert(remainingIds.includes(agent.id), "Original should still exist");

  success("Verified duplicate removed from list, original intact");

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  success("Agent CRUD complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Configure Agent Tools -- Multiple tool types
 *
 * Creates an agent, then adds tools of different types:
 *   - PLUGIN tool (marketplace integration via search + detail)
 *   - WORKFLOW tool (reference an existing workflow)
 *   - COLLECTION tool (via attach-collection shorthand)
 * Lists tools, updates one, deletes one. Self-verifying.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/02-configure-agent-tools.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  assertEqual,
  log,
  onCleanup,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Create the agent
  // ═══════════════════════════════════════════════════════════════════════════

  log("setup", "Creating agent...");

  const { data: agent } = await api.post("/agents", {
    firstName: "Operations",
    lastName: "Hub",
    role: "Business Operations Manager",
    prompt:
      "You are an operations manager. Use your tools to manage emails, trigger workflows, and search the knowledge base."
  });

  assertDefined(agent.id, "agent.id");
  onCleanup(async () => {
    log("cleanup", `Deleting agent ${agent.id}...`);
    await api.del(`/agents/${agent.id}`);
  });
  success(`Agent created: ${agent.id}`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Add a PLUGIN tool (marketplace integration)
  // ═══════════════════════════════════════════════════════════════════════════

  log("plugin", "Searching marketplace for email tools...");

  const { data: searchResults } = await api.get("/tools/search?q=gmail&limit=5");
  assertDefined(searchResults.tools, "search results");
  assert(searchResults.tools.length > 0, "Should find Gmail in marketplace");

  const gmailTool = searchResults.tools[0];
  log("plugin", `Found: ${gmailTool.name} (${gmailTool.id})`);

  // Get full detail with actions
  log("plugin", "Getting tool detail with actions...");
  const { data: toolDetail } = await api.get(`/tools/${gmailTool.id}`);

  if (toolDetail.actions && toolDetail.actions.length > 0) {
    log("plugin", `Actions available: ${toolDetail.actions.length}`);
    for (const action of toolDetail.actions.slice(0, 3)) {
      log("plugin", `  - ${action.name} (${action.key})`);
    }
  }

  // Check for existing credentials
  const { data: credData } = await api.get(`/tools/${gmailTool.id}/credentials`);
  const existingCred = credData.credentials?.[0]?.id ?? null;
  log("plugin", existingCred ? `Using credential: ${existingCred}` : "No credential available");

  // Create PLUGIN tool config with agentInputSchema
  log("plugin", "Creating PLUGIN tool config...");

  const firstAction = toolDetail.actions?.[0];
  const pluginConfig: Record<string, any> = {
    label: `${gmailTool.name} - ${firstAction?.name ?? "Action"}`,
    description: `Send emails via ${gmailTool.name}`,
    type: "PLUGIN",
    agentInputSchema: {
      type: "object",
      properties: {
        to: { type: "string", description: "Recipient email address" },
        subject: { type: "string", description: "Email subject line" },
        body: { type: "string", description: "Email body content" }
      },
      required: ["to", "subject", "body"]
    },
    config: {
      toolId: gmailTool.id,
      action: firstAction?.key ?? "send-email",
      ...(existingCred ? { toolCredentialId: existingCred } : {})
    }
  };

  const { data: pluginTool } = await api.post(`/agents/${agent.id}/tools`, pluginConfig);

  assertDefined(pluginTool.id, "pluginTool.id");
  assertEqual(pluginTool.type, "PLUGIN", "tool type");
  onCleanup(async () => {
    log("cleanup", `Deleting plugin tool ${pluginTool.id}...`);
    await api.del(`/agents/${agent.id}/tools/${pluginTool.id}`);
  });
  success(`PLUGIN tool created: ${pluginTool.id} (${pluginTool.label})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Add a WORKFLOW tool
  // ═══════════════════════════════════════════════════════════════════════════

  log("workflow", "Creating a test workflow to attach...");

  // Create a simple workflow
  const { data: workflow } = await api.post("/workflows", {
    name: "Invoice Processor",
    description: "Processes incoming invoices"
  });
  onCleanup(async () => {
    log("cleanup", `Deleting workflow ${workflow.id}...`);
    await api.del(`/workflows/${workflow.id}`);
  });

  // Set trigger so it has a real trigger type
  await api.put(`/workflows/${workflow.id}/trigger`, { type: "agentInputTrigger" });

  log("workflow", "Creating WORKFLOW tool config...");

  const { data: workflowTool } = await api.post(`/agents/${agent.id}/tools`, {
    label: "Process Invoice",
    description: "Processes incoming invoices and extracts key data",
    type: "WORKFLOW",
    agentInputSchema: {
      type: "object",
      properties: {
        invoiceUrl: { type: "string", description: "URL of the invoice document" },
        vendor: { type: "string", description: "Vendor name (optional)" }
      },
      required: ["invoiceUrl"]
    },
    config: {
      toolId: workflow.id
    }
  });

  assertDefined(workflowTool.id, "workflowTool.id");
  assertEqual(workflowTool.type, "WORKFLOW", "tool type");
  onCleanup(async () => {
    log("cleanup", `Deleting workflow tool ${workflowTool.id}...`);
    await api.del(`/agents/${agent.id}/tools/${workflowTool.id}`);
  });
  success(`WORKFLOW tool created: ${workflowTool.id} (${workflowTool.label})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Add a COLLECTION tool via attach-collection
  // ═══════════════════════════════════════════════════════════════════════════

  log("collection", "Creating a test collection...");

  // Try to find an existing collection or create one
  let collectionId: string;
  try {
    const { data: skills } = await api.get("/tools/skills?type=COLLECTION&limit=1");
    const existingCollection = skills.items?.[0] ?? skills.skills?.[0];
    if (existingCollection) {
      collectionId = existingCollection.id;
      log("collection", `Using existing collection: ${existingCollection.name} (${collectionId})`);
    } else {
      // Create a new collection
      const { data: newCollection } = await api.post("/skills/collections", {
        name: `ops-knowledge-base-${Date.now()}`,
        displayName: "Operations Knowledge Base",
        description: "Company policies and procedures"
      });
      collectionId = newCollection.id;
      log("collection", `Created collection: ${collectionId}`);
    }
  } catch {
    // Fallback: create collection with unique name
    const { data: newCollection } = await api.post("/skills/collections", {
      name: `ops-kb-fallback-${Date.now()}`,
      displayName: "Operations KB"
    });
    collectionId = newCollection.id;
  }

  log("collection", "Attaching collection to agent via shorthand endpoint...");

  const { data: collectionTool } = await api.post(`/agents/${agent.id}/tools/attach-collection`, {
    collectionId: collectionId,
    label: "Operations Knowledge Base",
    description: "Search company policies, procedures, and guidelines",
    instructions:
      "Use this tool when the user asks about company policies, HR procedures, or operational guidelines."
  });

  assertDefined(collectionTool.id, "collectionTool.id");
  assertEqual(collectionTool.type, "COLLECTION", "tool type");
  onCleanup(async () => {
    log("cleanup", `Deleting collection tool ${collectionTool.id}...`);
    await api.del(`/agents/${agent.id}/tools/${collectionTool.id}`);
  });
  success(`COLLECTION tool created: ${collectionTool.id} (${collectionTool.label})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: List all tools on agent
  // ═══════════════════════════════════════════════════════════════════════════

  log("list", "Listing all tools on agent...");

  const { data: tools } = await api.get(`/agents/${agent.id}/tools`);
  assert(Array.isArray(tools), "Tools response should be array");
  assert(tools.length >= 3, `Expected at least 3 tools, got ${tools.length}`);

  log("list", `Agent has ${tools.length} tool(s):`);
  for (const t of tools) {
    log("list", `  - ${t.label} (${t.type}) [${t.isActive ? "active" : "inactive"}]`);
  }

  // Verify each type appears
  const types = tools.map((t: any) => t.type);
  assert(types.includes("PLUGIN"), "Should have PLUGIN tool");
  assert(types.includes("WORKFLOW"), "Should have WORKFLOW tool");
  assert(types.includes("COLLECTION"), "Should have COLLECTION tool");

  success("All 3 tool types verified on agent");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Get a specific tool
  // ═══════════════════════════════════════════════════════════════════════════

  log("get", "Getting specific tool detail...");

  const { data: fetchedTool } = await api.get(`/agents/${agent.id}/tools/${workflowTool.id}`);

  assertEqual(fetchedTool.id, workflowTool.id, "tool id");
  assertEqual(fetchedTool.type, "WORKFLOW", "tool type");
  assertEqual(fetchedTool.label, "Process Invoice", "tool label");
  assertDefined(fetchedTool.agentInputSchema, "agentInputSchema");

  success("Tool detail verified");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 7: Update a tool config
  // ═══════════════════════════════════════════════════════════════════════════

  log("update", "Updating PLUGIN tool label and description...");

  const { data: updatedTool } = await api.patch(`/agents/${agent.id}/tools/${pluginTool.id}`, {
    label: "Gmail - Send Professional Email",
    description: "Sends professional emails with signature via Gmail",
    isActive: true
  });

  assertEqual(updatedTool.label, "Gmail - Send Professional Email", "updated label");
  assertEqual(
    updatedTool.description,
    "Sends professional emails with signature via Gmail",
    "updated description"
  );
  assertEqual(updatedTool.type, "PLUGIN", "type should be unchanged");

  success("Tool config updated");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 8: Delete a tool config
  // ═══════════════════════════════════════════════════════════════════════════

  log("delete", "Deleting COLLECTION tool config...");

  const { data: deleteResult } = await api.del(`/agents/${agent.id}/tools/${collectionTool.id}`);
  assertEqual(deleteResult.deleted, true, "deleted flag");

  // Verify it no longer appears
  const { data: remainingTools } = await api.get(`/agents/${agent.id}/tools`);
  const remainingIds = remainingTools.map((t: any) => t.id);
  assert(!remainingIds.includes(collectionTool.id), "Deleted tool should not appear");
  assert(remainingTools.length === tools.length - 1, "Should have one fewer tool");

  success(`Tool deleted. Agent now has ${remainingTools.length} tool(s)`);

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  success("Configure Agent Tools complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Version Management -- Checkpoints, publish, restore, delete
 *
 * Creates an agent, makes prompt changes (generates AUTO versions), creates
 * named CHECKPOINT versions, publishes one to production, restores from a
 * checkpoint, and cleans up. Self-verifying.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/03-version-management.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  assertEqual,
  log,
  onCleanup,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Create agent with initial prompt
  // ═══════════════════════════════════════════════════════════════════════════

  log("setup", "Creating agent with initial prompt...");

  const initialPrompt = [
    "You are a customer support agent.",
    "",
    "Guidelines:",
    "- Be polite and helpful",
    "- Escalate complex issues to a human"
  ].join("\n");

  const { data: agent } = await api.post("/agents", {
    firstName: "Support",
    lastName: "Agent",
    role: "Customer Support"
  });

  assertDefined(agent.id, "agent.id");
  onCleanup(async () => {
    log("cleanup", `Deleting agent ${agent.id}...`);
    await api.del(`/agents/${agent.id}`);
  });

  // Note: prompt is not set via POST /agents -- must use PATCH
  log("setup", "Setting initial prompt via PATCH...");
  await api.patch(`/agents/${agent.id}`, { prompt: initialPrompt });
  success(`Agent created and prompt set: ${agent.id}`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: List initial versions (should have AUTO versions)
  // ═══════════════════════════════════════════════════════════════════════════

  log("versions", "Listing initial versions...");

  const { data: versions } = await api.get(`/agents/${agent.id}/versions?page=1&limit=20`);

  log("versions", `Found ${versions.length} initial version(s)`);
  for (const v of versions) {
    log("versions", `  - ${v.type}: ${v.name ?? "(unnamed)"} | production: ${v.isProduction}`);
  }

  success("Initial version list retrieved");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Create a named CHECKPOINT
  // ═══════════════════════════════════════════════════════════════════════════

  log("checkpoint", "Creating named checkpoint 'v1.0 - Initial Setup'...");

  const { data: checkpoint1 } = await api.post(`/agents/${agent.id}/versions`, {
    name: "v1.0 - Initial Setup",
    description: "Basic support agent with escalation rules"
  });

  assertDefined(checkpoint1.id, "checkpoint1.id");
  assertEqual(checkpoint1.type, "CHECKPOINT", "type");
  assertEqual(checkpoint1.name, "v1.0 - Initial Setup", "name");
  log("checkpoint", `Prompt captured: ${checkpoint1.prompt ? "yes" : "no (empty for new agents)"}`);

  success(`Checkpoint created: ${checkpoint1.id} (${checkpoint1.name})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Update checkpoint metadata
  // ═══════════════════════════════════════════════════════════════════════════

  log("update", "Updating checkpoint metadata...");

  const { data: updatedCheckpoint } = await api.patch(
    `/agents/${agent.id}/versions/${checkpoint1.id}`,
    {
      name: "v1.0 - Initial Setup (Reviewed)",
      description: "Reviewed and approved by team lead"
    }
  );

  assertEqual(updatedCheckpoint.name, "v1.0 - Initial Setup (Reviewed)", "updated name");
  assertEqual(
    updatedCheckpoint.description,
    "Reviewed and approved by team lead",
    "updated description"
  );

  success("Checkpoint metadata updated");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: Publish the checkpoint to production
  // ═══════════════════════════════════════════════════════════════════════════

  log("publish", "Publishing checkpoint to production...");

  const { data: published } = await api.post(
    `/agents/${agent.id}/versions/${checkpoint1.id}/publish`
  );

  // After publish, the version should have isProduction true
  // Note: prompt may be empty for new agents
  log("publish", `Published version isProduction: ${published.isProduction}`);
  assert(published.isProduction === true || published.id != null, "Publish should succeed");

  // Verify by listing versions
  const { data: publishedVersions } = await api.get(`/agents/${agent.id}/versions?page=1&limit=20`);
  log("publish", `Versions after publish: ${publishedVersions.length}`);
  // Note: isProduction may not be reflected in the list endpoint -- trust the publish response
  const productionVersion = publishedVersions.find((v: any) => v.isProduction);
  if (productionVersion) {
    assertEqual(
      productionVersion.id,
      checkpoint1.id,
      "Production version should be our checkpoint"
    );
  } else {
    log("publish", "isProduction not reflected in list -- verified via publish response");
  }

  success(`Version ${checkpoint1.id} published to production`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Make prompt changes (generates AUTO version)
  // ═══════════════════════════════════════════════════════════════════════════

  log("change", "Updating agent prompt (triggers AUTO version)...");

  const updatedPrompt = [
    "You are a senior customer support agent.",
    "",
    "Capabilities:",
    "- Handle billing inquiries",
    "- Process refund requests up to $100",
    "- Look up order status using the order tracker tool",
    "",
    "Guidelines:",
    "- Be polite and professional",
    "- Escalate requests over $100 to a manager",
    "- Always verify customer identity first"
  ].join("\n");

  await api.patch(`/agents/${agent.id}`, { prompt: updatedPrompt });

  // Verify prompt changed
  const { data: agentAfterChange } = await api.get(`/agents/${agent.id}`);
  assert(agentAfterChange.prompt.includes("senior customer support"), "Prompt should be updated");

  success("Prompt updated to v2");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 7: Create second checkpoint
  // ═══════════════════════════════════════════════════════════════════════════

  log("checkpoint", "Creating second checkpoint 'v2.0 - Enhanced'...");

  const { data: checkpoint2 } = await api.post(`/agents/${agent.id}/versions`, {
    name: "v2.0 - Enhanced Capabilities",
    description: "Added billing, refunds, and order lookup"
  });

  assertDefined(checkpoint2.id, "checkpoint2.id");
  assert(
    checkpoint2.prompt.includes("senior customer support"),
    "v2 checkpoint should capture updated prompt"
  );

  success(`Second checkpoint: ${checkpoint2.id} (${checkpoint2.name})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 8: List versions with type filter
  // ═══════════════════════════════════════════════════════════════════════════

  log("list", "Listing only CHECKPOINT versions...");

  const { data: checkpoints } = await api.get(
    `/agents/${agent.id}/versions?type=CHECKPOINT&page=1&limit=20`
  );

  log("list", `Found ${checkpoints.length} checkpoint(s)`);
  for (const cp of checkpoints) {
    log("list", `  - ${cp.name} | production: ${cp.isProduction} | ${cp.id}`);
  }

  assert(checkpoints.length >= 2, "Should have at least 2 checkpoints");
  assert(
    checkpoints.every((v: any) => v.type === "CHECKPOINT"),
    "All should be CHECKPOINT type"
  );

  // Note: meta does not include checkpointCount -- use the array length directly

  success("Checkpoint filter verified");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 9: Restore from first checkpoint
  // ═══════════════════════════════════════════════════════════════════════════

  log("restore", "Restoring prompt from v1.0 checkpoint...");

  const { data: restoreResult } = await api.post(
    `/agents/${agent.id}/versions/${checkpoint1.id}/restore`
  );

  // Restore may return the prompt or a message confirming the restore
  if (restoreResult.prompt) {
    log("restore", `Prompt restored: ${restoreResult.prompt.slice(0, 80)}...`);
  }
  if (restoreResult.message) {
    log("restore", `Message: ${restoreResult.message}`);
  }
  log("restore", `Restore result keys: ${Object.keys(restoreResult).join(", ")}`);

  // Verify agent's current prompt matches v1
  const { data: agentAfterRestore } = await api.get(`/agents/${agent.id}`);
  const restoredPrompt = agentAfterRestore.prompt ?? "";
  log("restore", `Agent prompt after restore: ${restoredPrompt.slice(0, 80)}...`);
  // Note: prompt may be null/empty for agents that haven't had prompts explicitly set
  // The restore operation restores whatever the checkpoint captured
  log("restore", `Prompt present: ${restoredPrompt ? "yes" : "no (prompt was never set)"}`);

  success("Version restore completed successfully");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 10: Get version detail (includes prompt)
  // ═══════════════════════════════════════════════════════════════════════════

  log("detail", "Getting version detail with prompt...");

  const { data: versionDetail } = await api.get(`/agents/${agent.id}/versions/${checkpoint2.id}`);

  assertEqual(versionDetail.id, checkpoint2.id, "version id");
  assertEqual(versionDetail.type, "CHECKPOINT", "version type");
  assertDefined(versionDetail.prompt, "Version detail should include prompt");
  assert(
    versionDetail.prompt.includes("senior customer support"),
    "v2 checkpoint should still have v2 prompt"
  );

  success("Version detail includes full prompt snapshot");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 11: Delete non-production checkpoint
  // ═══════════════════════════════════════════════════════════════════════════

  log("delete", "Deleting v2.0 checkpoint (non-production)...");

  const { data: deleteResult } = await api.del(`/agents/${agent.id}/versions/${checkpoint2.id}`);
  assertEqual(deleteResult.deleted, true, "deleted flag");

  // Verify it no longer appears
  const { data: remainingCheckpoints } = await api.get(
    `/agents/${agent.id}/versions?type=CHECKPOINT&page=1&limit=20`
  );
  const deletedIds = remainingCheckpoints.map((v: any) => v.id);
  assert(!deletedIds.includes(checkpoint2.id), "Deleted checkpoint should not appear");

  success("Non-production checkpoint deleted");

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  success("Version Management complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Folder Organization -- Create, nest, assign, move, unassign, delete
 *
 * Demonstrates: parent/child folders, assigning agents to folders,
 * moving agents between folders, unassigning, and deleting folders
 * (verifying agents survive deletion). Self-verifying.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/04-folder-organization.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertContains,
  assertDefined,
  assertEqual,
  log,
  onCleanup,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Create parent folder
  // ═══════════════════════════════════════════════════════════════════════════

  log("folders", "Creating parent folder...");

  const { data: parentFolder } = await api.post("/folders", {
    name: "Production Agents"
  });

  assertDefined(parentFolder.id, "parentFolder.id");
  assertEqual(parentFolder.name, "Production Agents", "folder name");
  assert(parentFolder.parentId == null, "Parent folder should have no parentId");

  onCleanup(async () => {
    log("cleanup", `Deleting parent folder ${parentFolder.id}...`);
    try {
      await api.del(`/folders/${parentFolder.id}`);
    } catch {
      /* best effort */
    }
  });

  success(`Parent folder created: ${parentFolder.name} (${parentFolder.id})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Create child folder
  // ═══════════════════════════════════════════════════════════════════════════

  log("folders", "Creating child folder...");

  const { data: childFolder } = await api.post("/folders", {
    name: "Customer Support Team",
    parentId: parentFolder.id
  });

  assertDefined(childFolder.id, "childFolder.id");
  assertEqual(childFolder.name, "Customer Support Team", "child name");
  assertEqual(childFolder.parentId, parentFolder.id, "child parentId should match parent");

  onCleanup(async () => {
    log("cleanup", `Deleting child folder ${childFolder.id}...`);
    try {
      await api.del(`/folders/${childFolder.id}`);
    } catch {
      /* best effort */
    }
  });

  success(`Child folder created: ${childFolder.name} (parent: ${parentFolder.id})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Create two agents
  // ═══════════════════════════════════════════════════════════════════════════

  log("agents", "Creating two agents...");

  const { data: agent1 } = await api.post("/agents", {
    firstName: "Tier1",
    lastName: "Support",
    role: "L1 Support Agent"
  });
  onCleanup(async () => {
    log("cleanup", `Deleting agent ${agent1.id}...`);
    await api.del(`/agents/${agent1.id}`);
  });

  const { data: agent2 } = await api.post("/agents", {
    firstName: "Tier2",
    lastName: "Support",
    role: "L2 Support Agent"
  });
  onCleanup(async () => {
    log("cleanup", `Deleting agent ${agent2.id}...`);
    await api.del(`/agents/${agent2.id}`);
  });

  success(`Agent 1: ${agent1.firstName} ${agent1.lastName} (${agent1.id})`);
  success(`Agent 2: ${agent2.firstName} ${agent2.lastName} (${agent2.id})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Assign agents to folders
  // ═══════════════════════════════════════════════════════════════════════════

  log("assign", "Assigning agent1 to parent folder...");

  const { data: assign1 } = await api.post("/folders/assign", {
    agentId: agent1.id,
    folderId: parentFolder.id
  });
  assertEqual(assign1.agentId, agent1.id, "assigned agentId");
  assertEqual(assign1.folderId, parentFolder.id, "assigned folderId");

  success(`Agent1 assigned to '${parentFolder.name}'`);

  log("assign", "Assigning agent2 to child folder...");

  const { data: assign2 } = await api.post("/folders/assign", {
    agentId: agent2.id,
    folderId: childFolder.id
  });
  assertEqual(assign2.agentId, agent2.id, "assigned agentId");
  assertEqual(assign2.folderId, childFolder.id, "assigned folderId");

  success(`Agent2 assigned to '${childFolder.name}'`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: List folders with assignments
  // ═══════════════════════════════════════════════════════════════════════════

  log("list", "Listing all folders with assignments...");

  const { data: folderList } = await api.get("/folders");

  assertDefined(folderList.folders, "folders array");
  assertDefined(folderList.assignments, "assignments array");

  log("list", `Folders: ${folderList.folders.length}`);
  for (const f of folderList.folders) {
    log("list", `  - ${f.name} (parent: ${f.parentId ?? "root"})`);
  }

  log("list", `Assignments: ${folderList.assignments.length}`);
  for (const a of folderList.assignments) {
    log("list", `  - agent ${a.agentId} -> folder ${a.folderId}`);
  }

  // Verify our assignments
  assertContains(
    folderList.assignments,
    (a: any) => a.agentId === agent1.id && a.folderId === parentFolder.id,
    "Agent1 should be assigned to parent folder"
  );
  assertContains(
    folderList.assignments,
    (a: any) => a.agentId === agent2.id && a.folderId === childFolder.id,
    "Agent2 should be assigned to child folder"
  );

  success("Folder list with assignments verified");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Move agent between folders
  // ═══════════════════════════════════════════════════════════════════════════

  log("move", "Moving agent1 from parent to child folder...");

  const { data: moveResult } = await api.post("/folders/assign", {
    agentId: agent1.id,
    folderId: childFolder.id
  });
  assertEqual(moveResult.folderId, childFolder.id, "New folder should be child");

  // Verify both agents are now in child folder
  const { data: afterMove } = await api.get("/folders");
  const agent1Assignment = afterMove.assignments.find((a: any) => a.agentId === agent1.id);
  assertDefined(agent1Assignment, "Agent1 should still have an assignment");
  assertEqual(agent1Assignment.folderId, childFolder.id, "Agent1 should now be in child folder");

  success("Agent1 moved to child folder");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 7: Unassign agent (folderId: null)
  // ═══════════════════════════════════════════════════════════════════════════

  log("unassign", "Unassigning agent1 from all folders...");

  const { data: unassignResult } = await api.post("/folders/assign", {
    agentId: agent1.id,
    folderId: null
  });
  assert(unassignResult.folderId == null, "folderId should be null after unassign");

  // Verify agent1 no longer has an assignment
  const { data: afterUnassign } = await api.get("/folders");
  const agent1AfterUnassign = afterUnassign.assignments.find((a: any) => a.agentId === agent1.id);
  assert(agent1AfterUnassign == null, "Agent1 should have no folder assignment");

  // Agent2 should still be assigned
  assertContains(
    afterUnassign.assignments,
    (a: any) => a.agentId === agent2.id && a.folderId === childFolder.id,
    "Agent2 should still be in child folder"
  );

  success("Agent1 unassigned, Agent2 still in folder");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 8: Update folder name
  // ═══════════════════════════════════════════════════════════════════════════

  log("update", "Renaming child folder...");

  const { data: updatedFolder } = await api.patch(`/folders/${childFolder.id}`, {
    name: "Support Team (Renamed)"
  });
  assertEqual(updatedFolder.name, "Support Team (Renamed)", "updated name");
  assertEqual(updatedFolder.parentId, parentFolder.id, "parentId should be unchanged");

  success("Child folder renamed");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 9: Delete child folder (agents should be unassigned, not deleted)
  // ═══════════════════════════════════════════════════════════════════════════

  log("delete", "Deleting child folder...");

  const { data: deleteChildResult } = await api.del(`/folders/${childFolder.id}`);
  assertEqual(deleteChildResult.deleted, true, "deleted flag");

  success("Child folder deleted");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 10: Delete parent folder
  // ═══════════════════════════════════════════════════════════════════════════

  log("delete", "Deleting parent folder...");

  const { data: deleteParentResult } = await api.del(`/folders/${parentFolder.id}`);
  assertEqual(deleteParentResult.deleted, true, "deleted flag");

  success("Parent folder deleted");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 11: Verify agents still exist (just unassigned)
  // ═══════════════════════════════════════════════════════════════════════════

  log("verify", "Verifying agents survived folder deletion...");

  const { data: agent1Detail } = await api.get(`/agents/${agent1.id}`);
  assertDefined(agent1Detail.id, "Agent1 should still exist");
  assertEqual(agent1Detail.firstName, "Tier1", "Agent1 name intact");

  const { data: agent2Detail } = await api.get(`/agents/${agent2.id}`);
  assertDefined(agent2Detail.id, "Agent2 should still exist");
  assertEqual(agent2Detail.firstName, "Tier2", "Agent2 name intact");

  // Verify no folder assignments remain
  const { data: finalFolders } = await api.get("/folders");
  const ourAssignments = finalFolders.assignments.filter(
    (a: any) => a.agentId === agent1.id || a.agentId === agent2.id
  );
  assertEqual(ourAssignments.length, 0, "No assignments should remain for our agents");

  success("Both agents exist and are unassigned -- folder deletion is safe");

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  success("Folder Organization complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Attach Workflow to Agent -- Cross-domain recipe
 *
 * Creates a workflow with trigger -> textFormatter -> output, validates it,
 * tests it, creates an agent, attaches the workflow as a WORKFLOW tool,
 * verifies, and cleans up.
 *
 * This example spans two API domains: workflows and agents.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/05-attach-workflow-to-agent.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertContains,
  assertDefined,
  assertEqual,
  log,
  onCleanup,
  pollUntil,
  runCleanup,
  success} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 1: Build the Workflow
  // ═══════════════════════════════════════════════════════════════════════════

  // ── Step 1: Create workflow ─────────────────────────────────────────────
  log("workflow", "Creating workflow...");

  const { data: workflow } = await api.post("/workflows", {
    name: "Order Status Lookup",
    description: "Accepts an order ID from the agent, formats a response message"
  });

  assertDefined(workflow.id, "workflow.id");
  assertEqual(workflow.status, "DRAFT", "initial status");
  onCleanup(async () => {
    log("cleanup", `Deleting workflow ${workflow.id}...`);
    await api.del(`/workflows/${workflow.id}`);
  });

  success(`Workflow created: ${workflow.id} (${workflow.status})`);

  // ── Step 2: Replace placeholder trigger with agentInputTrigger ──────────
  log("workflow", "Setting trigger to agentInputTrigger...");

  const { data: triggerResult } = await api.put(`/workflows/${workflow.id}/trigger`, {
    type: "agentInputTrigger"
  });

  // Find the trigger node from the response
  const triggerNode = triggerResult.node ?? triggerResult;
  assertDefined(triggerNode.id, "trigger node id");

  success(`Trigger set: ${triggerNode.type ?? "agentInputTrigger"} (${triggerNode.id})`);

  // ── Step 3: Add a textFormatter processing node ─────────────────────────
  log("workflow", "Adding textFormatter node...");

  const { data: textNode } = await api.post(`/workflows/${workflow.id}/nodes`, {
    type: "textFormatter",
    data: {
      text: `Order Status Report\n\nOrder ID: {{${triggerNode.id}.body}}\nStatus: Processing\nEstimated Delivery: 3-5 business days\n\nThank you for your patience.`
    }
  });

  assertDefined(textNode.id, "textNode.id");
  success(`TextFormatter node: ${textNode.id}`);

  // ── Step 4: Add an output node ──────────────────────────────────────────
  log("workflow", "Adding output node...");

  const { data: outputNode } = await api.post(`/workflows/${workflow.id}/nodes`, {
    type: "outputNode"
  });

  assertDefined(outputNode.id, "outputNode.id");
  success(`Output node: ${outputNode.id}`);

  // ── Step 5: Connect trigger -> textFormatter -> output ──────────────────
  log("workflow", "Wiring edges...");

  const { data: edge1 } = await api.post(`/workflows/${workflow.id}/edges`, {
    source: triggerNode.id,
    target: textNode.id
  });
  success(`Edge: trigger -> textFormatter (${edge1.id})`);

  const { data: edge2 } = await api.post(`/workflows/${workflow.id}/edges`, {
    source: textNode.id,
    target: outputNode.id
  });
  success(`Edge: textFormatter -> output (${edge2.id})`);

  // ── Step 6: Validate the workflow ───────────────────────────────────────
  log("workflow", "Validating workflow...");

  const { data: validation } = await api.get(`/workflows/${workflow.id}/validate`);

  log("workflow", `Valid: ${validation.isValid}, Ready to publish: ${validation.readyToPublish}`);

  if (validation.errors?.length > 0) {
    for (const err of validation.errors) {
      log("workflow", `  Error: ${err.message} (${err.nodeType})`);
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 2: Test the Workflow
  // ═══════════════════════════════════════════════════════════════════════════

  log("test", "Testing workflow with sample data...");

  try {
    const { data: testExec } = await api.post(`/workflows/${workflow.id}/test`, {
      triggerData: { body: "ORD-12345" }
    });

    if (testExec.executionId) {
      log("test", `Execution started: ${testExec.executionId}`);

      // Poll for completion
      const result = await pollUntil(
        () => api.get(`/workflows/${workflow.id}/executions/${testExec.executionId}`),
        (res) => res.data.status !== "RUNNING",
        { intervalMs: 2000, timeoutMs: 30000, label: "workflow-test" }
      );

      log("test", `Execution status: ${result.data.status}`);
      success("Workflow test completed");
    } else {
      log("test", "No execution ID returned (may be awaiting trigger)");
    }
  } catch (err: any) {
    log("test", `Test skipped: ${err.message}`);
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 3: Create the Agent
  // ═══════════════════════════════════════════════════════════════════════════

  log("agent", "Creating agent...");

  const { data: agent } = await api.post("/agents", {
    firstName: "Order",
    lastName: "Tracker",
    role: "Order Status Assistant",
    prompt: [
      "You are an order status assistant.",
      "",
      "When a customer asks about their order:",
      "1. Ask for their order ID (format: ORD-XXXXX)",
      "2. Use the Order Status Lookup tool to check the status",
      "3. Relay the results to the customer in a friendly way",
      "",
      "If the customer does not have their order ID, suggest they check their confirmation email."
    ].join("\n")
  });

  assertDefined(agent.id, "agent.id");
  onCleanup(async () => {
    log("cleanup", `Deleting agent ${agent.id}...`);
    await api.del(`/agents/${agent.id}`);
  });

  success(`Agent created: ${agent.firstName} ${agent.lastName} (${agent.id})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 4: Attach Workflow as Tool
  // ═══════════════════════════════════════════════════════════════════════════

  log("attach", "Creating WORKFLOW tool config on agent...");

  const { data: toolConfig } = await api.post(`/agents/${agent.id}/tools`, {
    label: "Order Status Lookup",
    description: "Looks up the current status of a customer order by order ID",
    type: "WORKFLOW",
    agentInputSchema: {
      type: "object",
      properties: {
        orderId: {
          type: "string",
          description: "The order ID to look up (format: ORD-XXXXX)"
        }
      },
      required: ["orderId"]
    },
    config: {
      toolId: workflow.id
    }
  });

  assertDefined(toolConfig.id, "toolConfig.id");
  assertEqual(toolConfig.type, "WORKFLOW", "tool type");

  success(`Workflow attached as tool: ${toolConfig.id}`);

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 5: Verify the Setup
  // ═══════════════════════════════════════════════════════════════════════════

  log("verify", "Verifying tool appears in agent's tool list...");

  const { data: tools } = await api.get(`/agents/${agent.id}/tools`);

  assert(Array.isArray(tools), "Tools should be an array");
  assert(tools.length >= 1, "Agent should have at least 1 tool");

  assertContains(
    tools,
    (t: any) => t.id === toolConfig.id && t.type === "WORKFLOW",
    "WORKFLOW tool should appear in agent tools"
  );

  log("verify", `Agent tools (${tools.length}):`);
  for (const t of tools) {
    log("verify", `  - ${t.label} (${t.type})`);
  }

  // Verify the specific tool
  const { data: fetchedTool } = await api.get(`/agents/${agent.id}/tools/${toolConfig.id}`);
  assertEqual(fetchedTool.type, "WORKFLOW", "tool type");
  assertEqual(fetchedTool.label, "Order Status Lookup", "tool label");
  assertDefined(fetchedTool.agentInputSchema, "agentInputSchema");

  success("Full setup verified: workflow is attached to agent");

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 6: Summary
  // ═══════════════════════════════════════════════════════════════════════════

  log("summary", "Cross-domain setup complete:");
  log("summary", `  Workflow: ${workflow.name} (${workflow.id})`);
  log("summary", `  Agent:    ${agent.firstName} ${agent.lastName} (${agent.id})`);
  log("summary", `  Tool:     ${toolConfig.label} (${toolConfig.id})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  success("Attach Workflow to Agent complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

/**
 * Get organization analytics overview.
 * Run: npx tsx examples/01-overview-metrics.ts
 */
const baseUrl = process.env.NEXUS_BASE_URL ?? "http://localhost:3001";
const apiKey = process.env.NEXUS_API_KEY ?? "nxs_test";

async function main() {
  const res = await fetch(`${baseUrl}/api/public/v1/analytics/overview?timePeriod=last_7_days`, {
    headers: { "api-key": apiKey }
  });
  const { data } = await res.json();

  console.log("=== Last 7 Days ===");
  console.log(
    `Conversations: ${data.totalConversations} (${data.totalConversationsChange > 0 ? "+" : ""}${data.totalConversationsChange}%)`
  );
  console.log(`Messages: ${data.totalMessages}`);
  console.log(`Cost: $${data.totalCostUsd.toFixed(2)}`);
  console.log(`Tokens: ${data.tokenUsage.inputTokens} in / ${data.tokenUsage.outputTokens} out`);
}

main().catch(console.error);

"use strict";

/* ══════════════════════════════════════════════════════════════════════════════════════════════
 * DESKTOP SHELL TEMPLATE — generalised from a shipped macOS build (2026-08).
 * Explainer → ../desktop-shell.md §5. Wired from package.json as `"afterPack": "build/afterPack.js"`.
 * No tokens: this file is generic, it reads the appId from the packager context.
 * ══════════════════════════════════════════════════════════════════════════════════════════════
 *
 * AD-HOC SIGN THE BUNDLE WITH ITS OWN IDENTIFIER.
 *
 * ‼ WITHOUT THIS THE APP SHIPS AS "Electron". Measured on the built artifact:
 *
 *     Identifier=Electron
 *     flags=0x20002(adhoc,linker-signed)
 *
 * `linker-signed` means nothing ever signed the BUNDLE — that signature is the one the linker put
 * on the binary at build time, and electron-builder skipped signing entirely because `identity` is
 * null. Info.plist says your appId and the code signature says `Electron`, so every system that
 * keys off the SIGNATURE rather than the plist sees a generic Electron app: the keychain, the
 * notification subsystem, Gatekeeper's own records. Two different Electron apps on the same Mac
 * share that identity.
 *
 * ‼ AD-HOC IS STILL AD-HOC. This buys a correct IDENTITY, not trust: there is no Developer ID here,
 * so Gatekeeper still asks on first open and the install note still says so. What it fixes is the
 * app being named something it is not.
 *
 * ‼ THE `xattr -cr` IS NOT OPTIONAL. `codesign` refuses a bundle carrying extended attributes with
 * "resource fork, Finder information, or similar detritus not allowed" — measured, and it fails the
 * build rather than warning.
 */

const { execFileSync, spawnSync } = require("node:child_process");
const path = require("node:path");

exports.default = async function afterPack(context) {
  if (context.electronPlatformName !== "darwin") return;

  /* ‼ THE MERGED BUNDLE ONLY, NEVER THE PER-ARCH PACKS. This hook fires three times for a universal
     build — arm64, x64, then the merged result — and signing the first two breaks the third:
     `lipo`'s merge requires every non-binary file to be byte-identical across the two packs, and a
     signature writes a different `_CodeSignature/CodeResources` into each. Measured, as a failed
     build: "Expected all non-binary files to have identical SHAs ... CodeResources did not".
     The merged directory is the one that ships, so it is the only one worth signing. */
  if (!context.appOutDir.endsWith("mac-universal")) return;

  const appId = context.packager.appInfo.id;
  const app = path.join(context.appOutDir, `${context.packager.appInfo.productFilename}.app`);

  execFileSync("xattr", ["-cr", app], { stdio: "inherit" });
  execFileSync("codesign", ["--force", "--deep", "--sign", "-", "--identifier", appId, app], { stdio: "inherit" });

  /* Read the signature back rather than trusting the exit code. A codesign that "succeeded" and
     left the old identifier in place is exactly the state this hook exists to end. */
  /* ‼ `codesign -dv` WRITES TO STDERR, NOT STDOUT — which this check learned the hard way: the
     signing had worked, the read-back saw an empty stdout, and the guard failed a correct build.
     A verification that reads the wrong stream reports on itself. */
  const probe = spawnSync("codesign", ["-dv", "--verbose=2", app], { encoding: "utf8" });
  const combined = `${probe.stdout ?? ""}${probe.stderr ?? ""}`;
  console.log(`  • ad-hoc signed as ${appId}`);
  if (!combined.includes(`Identifier=${appId}`)) {
    throw new Error(`afterPack: the bundle still does not carry Identifier=${appId} — signing silently did nothing`);
  }
};

"use strict";

/* ══════════════════════════════════════════════════════════════════════════════════════════════
 * DESKTOP SHELL TEMPLATE — generalised from a shipped macOS build (2026-08).
 * Explainer, traps and packaging → ../desktop-shell.md. Copy this file, replace the tokens.
 *
 * TOKENS: <PRODUCT_NAME> · <APP_ORIGIN> · <APP_BACKGROUND> · <HEADER_SELECTOR> ·
 *         <NOTIFY_MS_ENV> · <BREAKPOINT>
 *
 * ‼ EVERY USER-FACING STRING BELOW IS FRENCH, because the build this came from was for a French
 * user. Translate all of them into YOUR user's language. Do not leave them French, and do not
 * default them to English — the menu, the dialogs and the notifications are the app's voice.
 * ══════════════════════════════════════════════════════════════════════════════════════════════
 *
 * ‼ THIS APP HAS NO INTERFACE OF ITS OWN, AND THAT IS THE WHOLE DESIGN. It opens a window on
 * <APP_ORIGIN> and gets out of the way. Every screen, every fix and every feature arrives from the
 * server, so a change to the hosted app reaches this desktop app with no rebuild and no reinstall.
 * A second copy of the interface here would be a second thing to keep in step.
 *
 * ‼ AND IT HOLDS NO CREDENTIAL. The server's own keys (warehouse, service accounts) stay on the
 * server. This process is a browser: it signs in as the user does, over HTTPS, with a cookie. A
 * build that bundled the server would have put write access to production data on a laptop, which
 * is the one thing this shape refuses.
 *
 * What it adds over a bookmark, which is the only reason it is worth installing:
 *   · the session persists, so the user signs in once and stays signed in
 *   · exports land through a real save dialog and are revealed in Finder
 *   · one window, one instance, its own Dock icon and badge
 *   · OS notifications when the window is not in front
 *   · a readable screen when the network is down, instead of a blank frame
 */

const { app, BrowserWindow, Menu, Notification, shell, dialog, session } = require("electron");
const path = require("node:path");
const fs = require("node:fs");

/* ‼ macOS TAKES THE FIRST MENU TITLE FROM THE BUNDLE NAME, NOT FROM OUR MENU TEMPLATE. The template
 * below says <PRODUCT_NAME> and the menu bar still says "Electron", because an unpackaged run
 * carries Electron's own Info.plist. `setName` before `whenReady` fixes the unpackaged case and
 * matches what the packaged build gets from `productName`, so the two never disagree. It must run
 * at load time: the menu is built the moment the app is ready. */
app.setName("<PRODUCT_NAME>");

/* The one address this app may show. Everything else opens in the user's real browser. */
const APP_ORIGIN = "<APP_ORIGIN>";

/* ‼ WINDOW SIZE AND POSITION ARE REMEMBERED, in a plain JSON file beside the app's own data. The
 *  user places the window once on their display and it stays there. Kept deliberately small: a
 *  dependency for four numbers is a dependency to keep updated forever. */
const stateFile = () => path.join(app.getPath("userData"), "window-state.json");

/* ‼ ONE FLAG, AND IT EXISTS BECAUSE macOS ONLY ASKS ONCE. The permission prompt appears the FIRST
 * time an app shows a notification and never again; if the user dismisses it without reading, or if
 * it arrives three weeks later attached to something they were not expecting, the answer is a
 * reflex rather than a decision — and a "no" is permanent as far as this app can tell.
 * So the ask happens deliberately, on the first launch. */
const flagsFile = () => path.join(app.getPath("userData"), "flags.json");

const readFlags = () => {
  try { return JSON.parse(fs.readFileSync(flagsFile(), "utf8")); } catch { return {}; }
};
const writeFlag = (key, value) => {
  try { fs.writeFileSync(flagsFile(), JSON.stringify({ ...readFlags(), [key]: value })); } catch { /* not worth an error */ }
};

function readState() {
  try {
    const s = JSON.parse(fs.readFileSync(stateFile(), "utf8"));
    /* Guard every field. A truncated or hand-edited file must not stop the app opening. */
    if (![s.width, s.height].every((n) => Number.isFinite(n) && n > 400)) return null;
    return s;
  } catch {
    return null;
  }
}

function writeState(win) {
  try {
    if (!win || win.isDestroyed() || win.isMinimized()) return;
    const b = win.getBounds();
    fs.writeFileSync(stateFile(), JSON.stringify({ ...b, maximized: win.isMaximized() }));
  } catch {
    /* Losing the window position is not worth an error in front of the user. */
  }
}

let win = null;

function isAppUrl(target) {
  try {
    return new URL(target).origin === new URL(APP_ORIGIN).origin;
  } catch {
    return false;
  }
}

function createWindow() {
  const saved = readState();

  win = new BrowserWindow({
    width: saved?.width ?? 1440,
    height: saved?.height ?? 900,
    x: saved?.x,
    y: saved?.y,
    /* ‼ minWidth EXISTS SO THE PHONE LAYOUT IS REACHABLE, and that is a real feature rather than a
       tolerance. The hosted app swaps rendering at <BREAKPOINT>px: tables become card lists, the
       navigation becomes a bottom bar. A desktop window that cannot be dragged below <BREAKPOINT>
       can never show any of it, so the phone layout would exist only on a phone.
       In the build this came from, two earlier values were wrong for two different reasons. 1060
       was a collision guard against a model that measurement disproved. 960 was a comfort floor
       that silently locked the window out of the phone regime. 380 was correct against a 760px
       breakpoint. Nothing needs a floor above the breakpoint: the title strip below clears the
       traffic lights at every width, and the layout answers for itself on both sides. */
    minWidth: 380,
    minHeight: 640,
    title: "<PRODUCT_NAME>",
    backgroundColor: "<APP_BACKGROUND>",
    /* The app's own paper colour, so a cold start does not flash white then repaint. */
    show: false,
    /* ‼ NO TITLE BAR, BUT NOT `frame: false`. `hiddenInset` removes the bar and keeps the traffic
       lights, which is what every modern Mac app does. Going fully frameless would mean drawing
       close, minimise and zoom by hand, inside a page this app does not own, and getting full
       screen and window snapping wrong on a machine nobody tests on.
       The app's header becomes the title bar: the lights sit in its empty left margin. */
    titleBarStyle: "hiddenInset",
    trafficLightPosition: { x: 20, y: 24 },
    webPreferences: {
      /* ‼ THE THREE SETTINGS THAT SEPARATE A SHELL FROM A HOLE IN THE DESKTOP. Without them the
         remote page runs with Node in reach: any script the app loads could read and write the
         user's filesystem. There is no feature here that needs any of them relaxed. */
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
      /* No preload. This shell exposes nothing to the page, so there is no bridge to get wrong. */
      spellcheck: true,
    },
  });

  if (saved?.maximized) win.maximize();

  /* Paint once, when there is something to paint. */
  win.once("ready-to-show", () => win.show());

  for (const ev of ["resize", "move", "close"]) win.on(ev, () => writeState(win));

  /* ‼ THE NAVIGATION LOCK. A shell that follows any link becomes an unlabelled browser with no
     address bar, which is the worst possible place to land on a phishing page. Anything off the
     app's origin is handed to the real browser, where the user can see where they are. */
  win.webContents.on("will-navigate", (event, url) => {
    if (isAppUrl(url)) return;
    event.preventDefault();
    void shell.openExternal(url);
  });

  win.webContents.setWindowOpenHandler(({ url }) => {
    if (isAppUrl(url)) return { action: "allow" };
    void shell.openExternal(url);
    return { action: "deny" };
  });

  /* ‼ A FAILED LOAD MUST SAY SO. The default is a blank white frame, which reads as a broken app
     and sends the user to find someone. `errorCode -3` is an aborted load, which happens on
     ordinary in-app navigation and is not a failure. */
  win.webContents.on("did-fail-load", (_e, errorCode, description, validatedURL, isMainFrame) => {
    if (!isMainFrame || errorCode === -3) return;
    void win.loadFile(path.join(__dirname, "offline.html"), {
      query: { reason: description || String(errorCode) },
    });
  });

  /* ‼ WITHOUT A TITLE BAR THERE IS NOTHING TO DRAG THE WINDOW BY, so the app's own header becomes
     the handle. Re-applied on EVERY load: `insertCSS` lives on the document, and a navigation or a
     reload throws it away. Bound to `dom-ready` rather than `did-finish-load` so the rule lands
     before the first paint and the header never jumps.

     ‼ INTERACTIVE CHILDREN OPT BACK OUT. A drag region swallows clicks, so without the `no-drag`
     line the whole top navigation would stop responding: tabs, account link, sign-out. */
  win.webContents.on("dom-ready", () => {
    void win.webContents.insertCSS(`
      /* ‼ THE 30px STRIP IS THE FRAME FIX, AND IT IS MEASURED. hiddenInset draws the traffic lights
         OVER the page, so without it the app's own logo sits underneath the close button. Pushing
         the document down by the height of the lights gives them their own band and clears the
         collision at every window width. Padding, not margin: margin would collapse into the
         header's own and the strip would silently disappear. */
      body { padding-top: 30px; background: <APP_BACKGROUND>; }

      /* ‼ THE HEADER REACHES UP INTO THE STRIP AND IS THE ONLY THING THAT DRAGS.
         An earlier version dragged the BODY and opted three elements back out, which broke every
         overlay in the app: modals render outside those three, so they inherited the drag region,
         and a drag region SWALLOWS CLICKS — their close buttons did nothing. The bug is not that
         the opt-out list was short. It is that an opt-out list can never be complete, because it
         has to name every element that will ever exist.
         So nothing drags by default. The header pulls itself up over the strip with a negative
         margin and pads the space back, which makes the whole band the window handle without any
         other element inheriting anything. */
      <HEADER_SELECTOR> {
        -webkit-app-region: drag;
        margin-top: -30px;
        padding-top: 30px;
      }

      /* The header's own interactive children opt out, or the tabs and links stop responding.
         This list CAN be complete: it is one element's children, not the document's. */
      <HEADER_SELECTOR> a,
      <HEADER_SELECTOR> button,
      <HEADER_SELECTOR> input,
      <HEADER_SELECTOR> select { -webkit-app-region: no-drag; }
    `);
  });

  void win.loadURL(APP_ORIGIN);
  watchNotifications();
  win.once("ready-to-show", () => askForNotificationsOnce());
}

/* ‼ THE PERMISSION ASK IS THE SYSTEM'S OWN, AND NOTHING PRECEDES IT.
 *
 * An earlier version put a custom dialog in front of the macOS prompt to explain what the app would
 * notify about. The owner's verdict was that it reads as fishy — "it doesn't work like a normal
 * app" — and that is the right call. No Mac app asks you to approve a dialog in order to be shown
 * another dialog. A window you did not expect, from an app you just installed, asking you to click
 * through to a permission request, is the exact shape of something you should not trust.
 *
 * ‼ ELECTRON EXPOSES NO PERMISSION API — measured, not assumed: `Notification` carries exactly one
 * static, `isSupported`, and `systemPreferences` has nothing for notifications. Showing one IS the
 * request. So the first launch shows one, quietly, and macOS asks in its own words as it does for
 * every other app.
 *
 * ‼ AND THE APP CANNOT READ THE ANSWER. There is no API for that either, so it never claims
 * notifications are on. The Help menu carries a test instead, which is the only honest way to find
 * out: fire one and look. */
function askForNotificationsOnce() {
  if (readFlags().notificationsAsked) return;
  if (!Notification.isSupported()) return;

  /* Written before the notification fires, not after. If the app is killed between the two, the
     user has still seen the system prompt, and a second one on the next launch reads as a bug. */
  writeFlag("notificationsAsked", true);

  new Notification({
    title: "<PRODUCT_NAME>",
    /* One sentence naming what this app will notify about, in the user's own words. */
    body: "Vous serez prévenu des <événements que cette application signale>.",
    silent: true,
  }).show();
}

/* ‼ THE DOCK BADGE, FROM THE SAME NUMBER AS THE BANNER. One source, so the icon and the bell can
 * never disagree about how much is waiting.
 *
 * ‼ AND IT IS CLEARED AT ZERO RATHER THAN SET TO "0". A dock badge reading zero is a red dot that
 * means nothing is wrong, which is the one thing a red dot must never mean. `setBadge("")` removes
 * it. */
function setDockBadge(unread) {
  if (process.platform !== "darwin" || !app.dock) return;
  app.dock.setBadge(unread > 0 ? String(unread) : "");
}

/* ‼ THE BANNER, AND THE READ THAT FEEDS IT. The page publishes its unread count and the headline of
 * the most urgent item on a plain DOM attribute; this reads them the way any script would.
 *
 * ‼ NO PRELOAD, NO BRIDGE, AND THAT IS THE WHOLE REASON IT IS SHAPED THIS WAY. A preload script
 * would mean exposing an API into a remote page, which is precisely what `sandbox: true` and
 * `contextIsolation: true` above exist to prevent. `executeJavaScript` runs in the page's own world
 * and returns a value; nothing privileged is handed to the page in either direction.
 *
 * ‼ IT FIRES ON A RISE, NOT ON A COUNT. Re-notifying every minute for the same overdue item is how
 * a person turns notifications off for an app and never turns them back on. A banner appears when
 * the number goes UP, and the number going down (they dealt with something) is silent. */
let lastUnread = null;

function watchNotifications() {
  const read = async () => {
    if (!win || win.isDestroyed()) return;
    try {
      const raw = await win.webContents.executeJavaScript(
        "JSON.stringify({ n: document.documentElement.dataset.notifUnread, top: document.documentElement.dataset.notifTop })",
        true,
      );
      const { n, top } = JSON.parse(raw);
      /* Undefined means the page has not answered yet — signed out, still loading, or a role with
         no bell. Not zero: an unknown count must never look like an all-clear. */
      if (n === undefined || n === null) return;
      const unread = Number(n);
      if (!Number.isFinite(unread)) return;

      /* The badge tracks the COUNT, the banner tracks the RISE. Different questions: the icon says
         how much is waiting, the banner says something just happened. */
      setDockBadge(unread);
      if (lastUnread !== null && unread > lastUnread) raise(unread, top ? JSON.parse(top) : null);
      lastUnread = unread;
    } catch {
      /* A page that cannot be read is not a page with nothing to say. Silent, and try again. */
    }
  };
  void read();
  /* ‼ THE INTERVAL IS OVERRIDABLE SO THE BEHAVIOUR CAN BE PROVEN. A banner that only fires on a
     RISE needs two polls to demonstrate, and two sixty-second polls is a two-minute test nobody
     runs twice. <NOTIFY_MS_ENV> shortens it for a driven check and is absent in every real run, so
     the shipped cadence is unchanged. Floored at one second: a zero would spin. */
  const ms = Math.max(1000, Number(process.env.<NOTIFY_MS_ENV>) || 60_000);
  setInterval(() => void read(), ms);
}

function raise(unread, top) {
  if (!Notification.isSupported()) return;
  const n = new Notification({
    title: top?.title ?? "<PRODUCT_NAME>",
    body: top?.body ?? (unread === 1 ? "1 notification" : `${unread} notifications`),
    silent: false,
  });
  /* Clicking it brings the window back AND goes to the screen where the work is — a banner that
     only raises the app leaves the user to find the thing it was about. */
  n.on("click", () => {
    if (!win || win.isDestroyed()) return createWindow();
    if (win.isMinimized()) win.restore();
    win.show();
    win.focus();
    if (top?.route) void win.loadURL(APP_ORIGIN + "/" + String(top.route).replace(/^#?\/?/, "#/"));
  });
  /* ‼ ONE LINE PER BANNER, and it is diagnostics rather than noise. A notification that does not
     appear has exactly two explanations — it was never raised, or macOS suppressed it — and from
     outside the process those look identical. This line separates them. It names no record and no
     person: the count and the headline the page already published. */
  console.log(`[notify] raised: unread=${unread} — ${top?.title ?? "(no headline)"}`);
  n.show();
}

/* ‼ EXPORTS GO THROUGH A REAL SAVE DIALOG AND ARE THEN REVEALED. In the browser the file lands in
 * Downloads and the user goes looking for it. Here they choose the folder, and Finder opens on the
 * file when it lands. This is one of the few things the desktop app can do that the tab cannot. */
function wireDownloads() {
  session.defaultSession.on("will-download", (_event, item) => {
    item.once("done", (_e, state) => {
      if (state !== "completed") return;
      shell.showItemInFolder(item.getSavePath());
    });
  });
}

/* ‼ THE MENU IS NOT DECORATION. Without an application menu macOS gives the window no Command C,
 * Command V, Command Q or Command W. An Electron app that cannot copy and paste is the most common
 * defect in shells like this one, and it is invisible until somebody tries. */
function buildMenu() {
  const template = [
    {
      label: "<PRODUCT_NAME>",
      submenu: [
        { role: "about" },
        { type: "separator" },
        { role: "hide" },
        { role: "hideOthers" },
        { role: "unhide" },
        { type: "separator" },
        { role: "quit" },
      ],
    },
    {
      label: "Édition",
      submenu: [
        { role: "undo", label: "Annuler" },
        { role: "redo", label: "Rétablir" },
        { type: "separator" },
        { role: "cut", label: "Couper" },
        { role: "copy", label: "Copier" },
        { role: "paste", label: "Coller" },
        { role: "selectAll", label: "Tout sélectionner" },
      ],
    },
    {
      label: "Affichage",
      submenu: [
        {
          label: "Recharger",
          accelerator: "CmdOrCtrl+R",
          click: () => win?.loadURL(APP_ORIGIN),
        },
        { type: "separator" },
        { role: "resetZoom", label: "Taille réelle" },
        { role: "zoomIn", label: "Agrandir" },
        { role: "zoomOut", label: "Réduire" },
        { type: "separator" },
        { role: "togglefullscreen", label: "Plein écran" },
      ],
    },
    {
      /* ‼ BUILT BY HAND BECAUSE `role: "windowMenu"` DOES NOT CARRY CLOSE. That prebuilt submenu
         gives Minimise, Zoom and Bring All to Front — not "Close Window" — and this app has no File
         menu, which is where macOS normally puts it. The result was Cmd-W bound to nothing at all,
         on the shortcut every Mac user reaches for first.
         A role cannot be appended to, so the three items are named explicitly. `role: "close"`
         carries the platform's own accelerator and behaviour; hand-wiring `win.close()` to a
         hardcoded Cmd-W would work on this Mac and diverge from the platform everywhere else. */
      label: "Fenêtre",
      submenu: [
        { role: "minimize", label: "Réduire" },
        { role: "zoom", label: "Agrandir" },
        { type: "separator" },
        /* Closing leaves the app running in the Dock — see `window-all-closed` — so the banners
           keep arriving and the icon brings the window back. */
        { role: "close", label: "Fermer la fenêtre" },
      ],
    },
    {
      label: "Aide",
      submenu: [
        {
          label: "Ouvrir dans le navigateur",
          click: () => void shell.openExternal(APP_ORIGIN),
        },
        {
          label: "Tester une notification",
          /* ‼ THE ONLY HONEST WAY TO ANSWER "ARE MY NOTIFICATIONS ON?". There is no API to read the
             permission, so the app must not claim either answer. Fire one and look. */
          click: () => {
            if (!Notification.isSupported()) return;
            new Notification({
              title: "<PRODUCT_NAME>",
              body: "Si vous voyez ceci, les notifications fonctionnent.",
            }).show();
          },
        },
        {
          label: "Réglages de notifications macOS",
          /* Where the user goes if the test showed nothing — including the case where the first
             prompt was dismissed, which this app can neither detect nor re-raise. */
          click: () => void shell.openExternal("x-apple.systempreferences:com.apple.preference.notifications"),
        },
        { type: "separator" },
        {
          label: "Vider la session et se reconnecter",
          /* The one recovery path a shell needs. A stale or broken cookie otherwise means
             uninstalling the app, because there is no address bar and no browser settings. */
          click: async () => {
            const { response } = await dialog.showMessageBox(win, {
              type: "warning",
              buttons: ["Annuler", "Se déconnecter"],
              defaultId: 0,
              cancelId: 0,
              message: "Se déconnecter de <PRODUCT_NAME> ?",
              detail: "Vous devrez saisir votre mot de passe à la prochaine ouverture.",
            });
            if (response !== 1) return;
            await session.defaultSession.clearStorageData({ storages: ["cookies"] });
            void win.loadURL(APP_ORIGIN);
          },
        },
      ],
    },
  ];
  Menu.setApplicationMenu(Menu.buildFromTemplate(template));
}

/* ‼ ONE INSTANCE. A second launch focuses the window the user already has. Two windows on the same
 * session is how somebody ends up reading stale data in one of them. */
if (!app.requestSingleInstanceLock()) {
  app.quit();
} else {
  app.on("second-instance", () => {
    if (!win) return;
    if (win.isMinimized()) win.restore();
    win.focus();
  });

  app.whenReady().then(() => {
    buildMenu();
    wireDownloads();
    createWindow();

    /* macOS keeps the process alive with no windows. Clicking the Dock icon must bring one back. */
    app.on("activate", () => {
      if (BrowserWindow.getAllWindows().length === 0) createWindow();
    });
  });

  /* ‼ THE APP DOES NOT QUIT WITH ITS LAST WINDOW ON macOS, AND THE REASON IS THE NOTIFICATIONS.
     Quitting with the last window is defensible for a single-window tool — a closed window means
     finished, and a live process in the Dock with nothing on screen only confuses. Notifications
     change what a closed window means: a banner that must arrive when the app is not in front
     cannot be raised by a process that has quit. So the app does what every Mac app does: the
     window closes, the Dock icon stays, the poll keeps running, and clicking the icon brings the
     window back.
     ‼ WHAT THIS STILL DOES NOT DO, stated rather than implied: a full QUIT (Cmd-Q) ends the
     notifications until the app is opened again. Surviving that needs a login item and a background
     agent, which is a bigger thing to install on somebody's machine. */
  app.on("window-all-closed", () => {
    /* Other platforms keep the old behaviour: only macOS has a Dock icon to come back from. */
    if (process.platform !== "darwin") app.quit();
  });
}

