#!/usr/bin/env node
/* Build ONE page carrying every design alternative inline, generated FROM DISK.
 *
 * W45/I2. Two measured failures this replaces: (1) alternatives delivered as a
 * directory root with no index (404 at the only address the owner was given), and
 * (2) an index of LINKS the owner had to click through one at a time — "not just
 * have a separate menu you have to click upon". Generated from disk so the page
 * cannot drift from what actually exists (the property the throwaway version had,
 * and the reason it was worth keeping).
 *
 * Usage:  node build-alternatives-index.mjs <boards-dir> [--title "<title>"]
 * Input:  <boards-dir>/<lane>/alternatives.json  (app-redesigner Done-when contract)
 *         [{ id, title, axis, entry, worse_at }]
 * Output: <boards-dir>/index.html
 * Then:   serve <boards-dir> and PROBE THE ROOT before sending the URL.
 */
import { readdirSync, readFileSync, writeFileSync, existsSync, statSync } from "node:fs";
import { join, relative } from "node:path";

const dir = process.argv[2];
if (!dir) { console.error("usage: build-alternatives-index.mjs <boards-dir> [--title T]"); process.exit(2); }
const ti = process.argv.indexOf("--title");
const title = ti > -1 ? process.argv[ti + 1] : "Design alternatives";

const groups = [];
for (const lane of readdirSync(dir).sort()) {
  const laneDir = join(dir, lane);
  if (!existsSync(laneDir) || !statSync(laneDir).isDirectory()) continue;
  const mf = join(laneDir, "alternatives.json");
  if (!existsSync(mf)) continue;
  let rows;
  try { rows = JSON.parse(readFileSync(mf, "utf8")); }
  catch (e) { console.error(`SKIP ${lane}: unparseable alternatives.json — ${e.message}`); continue; }
  const alts = (Array.isArray(rows) ? rows : []).filter(r => r && r.entry && existsSync(join(laneDir, r.entry)));
  const dropped = (Array.isArray(rows) ? rows.length : 0) - alts.length;
  if (dropped > 0) console.error(`WARN ${lane}: ${dropped} row(s) name an entry that does not exist — omitted`);
  if (alts.length) groups.push({ lane, alts: alts.map(a => ({ ...a, href: relative(dir, join(laneDir, a.entry)) })) });
}

if (!groups.length) { console.error(`FAIL: no alternatives.json with existing entries under ${dir}`); process.exit(1); }

const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const slug = s => String(s).replace(/[^A-Za-z0-9_-]/g, "-");

const nav = groups.map(g =>
  `<a href="#${slug(g.lane)}">${esc(g.lane)} <span>${g.alts.length}</span></a>`).join("\n      ");

const sections = groups.map(g => `
    <section id="${slug(g.lane)}">
      <h2>${esc(g.lane)}</h2>
      ${g.alts.map(a => `
      <article>
        <h3>${esc(a.title || a.id)} <em>${esc(a.axis || "")}</em></h3>
        ${a.worse_at ? `<p class="worse">Worse at: ${esc(a.worse_at)}</p>` : ""}
        <iframe src="${esc(a.href)}" loading="lazy" title="${esc(a.title || a.id)}"></iframe>
        <p class="open"><a href="${esc(a.href)}" target="_blank">open standalone &rarr;</a></p>
      </article>`).join("")}
    </section>`).join("");

writeFileSync(join(dir, "index.html"), `<!doctype html>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)}</title>
<style>
  :root{color-scheme:light dark}
  body{margin:0;font:14px/1.5 system-ui,sans-serif;display:grid;grid-template-columns:220px 1fr}
  nav{position:sticky;top:0;align-self:start;height:100vh;overflow:auto;padding:20px 16px;border-right:1px solid #8883}
  nav h1{font-size:13px;text-transform:uppercase;letter-spacing:.08em;opacity:.6;margin:0 0 12px}
  nav a{display:flex;justify-content:space-between;gap:8px;padding:6px 8px;border-radius:6px;text-decoration:none;color:inherit}
  nav a:hover{background:#8882} nav a span{opacity:.5}
  main{padding:24px 28px;min-width:0}
  section{margin:0 0 44px} h2{margin:0 0 16px;font-size:20px}
  article{margin:0 0 28px;border:1px solid #8883;border-radius:10px;padding:14px;min-width:0}
  h3{margin:0 0 4px;font-size:15px} h3 em{font-weight:400;opacity:.55;font-style:normal;margin-left:8px}
  .worse{margin:0 0 10px;opacity:.7;font-size:12.5px}
  iframe{width:100%;height:760px;border:1px solid #8883;border-radius:8px;background:#fff}
  .open{margin:8px 0 0;font-size:12.5px}
  @media(max-width:900px){body{grid-template-columns:1fr}nav{position:static;height:auto;border-right:0;border-bottom:1px solid #8883}}
</style>
<nav>
  <h1>${esc(title)}</h1>
      ${nav}
</nav>
<main>${sections}
</main>
`, "utf8");

const n = groups.reduce((a, g) => a + g.alts.length, 0);
console.log(`index.html written: ${groups.length} surface(s), ${n} alternative(s) inline`);
console.log(`NEXT: serve ${dir}, then probe the ROOT (curl -o /dev/null -w '%{http_code}' <url>/) BEFORE sending it.`);

#!/usr/bin/env node
/**
 * build-judges.mjs — generate the BUILT judge files a judging dispatch points at.
 *
 *   node build-judges.mjs [--check]
 *
 * Why this exists. A judging dispatch used to be hand-assembled: the orchestrator pasted a rubric or a
 * QA method into the prompt from memory. Measured blind A/B: a pointed-at FILE reproduced 4/4 blocks
 * byte-exact, while assembling from memory dropped 60% of one block and 100% of another. So the method
 * is composed ONCE, to disk, and the dispatch names the file.
 *
 * Output: references/built/{review-<dimension>.md, assess-<category>.md}
 * Each built file is the source method/rubric VERBATIM, wrapped in a header that names the four things
 * the dispatch must still carry (they are per-build, so they cannot be baked in).
 *
 * --check exits non-zero if any built file is missing or stale vs its source — so a source edit that
 * never regenerated is caught, rather than shipping a judge that silently lags its own rubric.
 */
import { readFileSync, writeFileSync, existsSync, readdirSync, mkdirSync, statSync } from 'node:fs';
import { join, dirname, basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';

const HERE = dirname(fileURLToPath(import.meta.url));
const REFS = dirname(HERE);                        // …/references
const OUT  = join(REFS, 'built');
const CHECK = process.argv.includes('--check');

const HEADER = (kind, name, sourceRel, sha) => `<!-- GENERATED by scripts/build-judges.mjs — do not edit.
     source: ${sourceRel}
     source-sha256: ${sha}
     Regenerate with: node references/scripts/build-judges.mjs -->

# BUILT ${kind.toUpperCase()} JUDGE — ${name}

> Your dispatch names this file because a hand-assembled brief drops blocks and a read file does not.
> Read it IN FULL before you judge anything.
>
> **Four things this file deliberately does NOT contain — they are per-build, and your dispatch owes
> you all four. Any of them missing → STOP and request them:**
>
> 1. **\`REF\` and \`CAP\`** — the absolute paths of the \`references/\` dir and of \`capture.mjs\`. Every
>    \`REF/…\` and \`CAP\` below resolves through them; an agent file has no base directory of its own.
> 2. **The CONTRACT BLOCK** — the build's full signed PRD verbatim + \`docs/DESIGN.md\` (the design lock)
>    + resolved taste + standing arbitrations. Never excerpted. Judgment is AGAINST the contract: a
>    dimension the lock deliberately inverts scores **BY-DESIGN** with an intent-execution number, never
>    a generic-rung fail.
> 3. **The target** — the serve command / URL, the route, the spec viewports, the shot set, and the
>    output path for your JSON.
> 4. **Your routed laws** — the 3-6 that fire for this dimension.

---

`;

const sha = (s) => createHash('sha256').update(s).digest('hex').slice(0, 16);

function build() {
  if (!existsSync(OUT)) mkdirSync(OUT, { recursive: true });
  const made = [];
  const stale = [];

  const emit = (outName, kind, name, srcPath, srcRel) => {
    const src = readFileSync(srcPath, 'utf8');
    const body = HEADER(kind, name, srcRel, sha(src)) + src;
    const dest = join(OUT, outName);
    if (CHECK) {
      if (!existsSync(dest)) { stale.push(`${outName} — MISSING`); return; }
      const cur = readFileSync(dest, 'utf8');
      const m = cur.match(/source-sha256: ([0-9a-f]{16})/);
      if (!m || m[1] !== sha(src)) stale.push(`${outName} — STALE (source changed since generation)`);
      return;
    }
    writeFileSync(dest, body);
    made.push(outName);
  };

  // reviewer methods → one built judge per plannable dimension (+ code, which is review-only)
  const rm = join(REFS, 'review-methods');
  for (const f of readdirSync(rm).filter(x => x.endsWith('-QA-METHOD.md')).sort()) {
    const dim = f.replace('-QA-METHOD.md', '').toLowerCase();
    emit(`review-${dim}.md`, 'reviewer', dim, join(rm, f), `references/review-methods/${f}`);
  }

  // design-library topic rubrics → one built judge per assessor category
  const dl = join(REFS, 'design-library');
  const META = new Set(['DESIGN-PRINCIPLES.md', 'COMPLETENESS.md', 'CROPS.md', 'review-method-and-calibration.md']);
  for (const f of readdirSync(dl).filter(x => x.endsWith('.md') && !META.has(x)).sort()) {
    const cat = basename(f, '.md');
    emit(`assess-${cat}.md`, 'assessor', cat, join(dl, f), `references/design-library/${f}`);
  }

  if (CHECK) {
    if (stale.length) {
      console.log(`build-judges --check: ${stale.length} problem(s)`);
      for (const s of stale) console.log(`  ✗ ${s}`);
      console.log('\nRun: node references/scripts/build-judges.mjs');
      process.exit(1);
    }
    console.log('build-judges --check: every built judge is present and current ✓');
    process.exit(0);
  }
  console.log(`built ${made.length} judge file(s) → references/built/`);
  for (const m of made) console.log(`  ${m}`);
}

build();

#!/usr/bin/env node
/* THE CONSOLIDATED CAPTURE TOOL for the review/build fleet — one instrument, one run folder.
 * Agents CALL this via Bash (never hand-roll Playwright, never use interactive browser tools).
 * Every op is bounded; a global self-timeout guarantees it ALWAYS returns JSON and exits.
 *
 * Usage — a URL as the FIRST argument means `capture`, so the common call is just:
 *   node capture.mjs <url> <outdir> [WxH] [flags]
 *
 *   node capture.mjs [capture] <url> <outdir> [WxH] [flags]   → THE CONSOLIDATED CAPTURE. One run folder:
 *        manifest.json          index + findings (unreachable controls, NO-OP controls, console errors)
 *        state-NNN.json         every addressable control: stable hash + @eN ref, rect in document AND
 *                               viewport space, why it is interactive, occluded?, reachable?, + the full
 *                               design measurement (contrast/spacing/voids/targets) in the same record
 *        state-NNN.tree.txt     indented view, ref-bearing lines and their ancestors only
 *        state-NNN.png / .annotated.png   clean shot + numbered @eN overlay (red = unreachable)
 *        <state>-tNN.transition.json      per action: identity diff (appeared/gone/changed), pixel diff,
 *                               network calls, new console errors, and a NO-OP verdict
 *     flags: --click=@e5|<sel>|<text>  --sweep [--sweep-max=N]  --viewports=1920x1080,390x844
 *            --themes=light,dark  --root=<sel>  --no-measure  --no-annotate  --pixel-threshold=0.1
 *            --attach  → reuse a warm agent-browser daemon (~46ms vs ~2.9s cold). OPT-IN: that browser
 *                        may be driven by another lane; falls back to launching our own if unavailable.
 *   node capture.mjs measure <url> [WxH] [--dark] [--touch] [--root=<sel>]  → full design-rules measurement (JSON)
 *   node capture.mjs shot    <url> <outPath> [WxH] [--dark] [--touch]
 *   node capture.mjs shots   <url> <outdir> [--tabs=a,b] [--viewports=1920x1080,1512x900,390x844]
 *   node capture.mjs scroll  <url> [WxH] [--dark]        → {scrollH,innerH,fits,scrollW,innerW,noHScroll,mustsee[]}
 *   node capture.mjs state   <url> <selector> [WxH] [--dark]   → idle/hover/active/focus computed-style DIFF (pliancy)
 *   node capture.mjs hit     <url> <selector> [WxH] [--dark] [--touch]  → elementFromPoint at the selector's centre
 *   node capture.mjs menu    <url> <selector> [WxH] [--dark]   → right-click → did a context menu appear?
 *   node capture.mjs eval    <url> "<js returning JSON>" [WxH] [--dark] [--touch]
 *   node capture.mjs doctor  → is this machine able to run me, and if not, the exact command to fix it
 *   node capture.mjs bootstrap → RUN that fix: idempotent install into ~/.nexus-tools; no-ops when ready
 * Env: PW=<abs path to node_modules/playwright/index.js> (default: ./node_modules/playwright/index.js)
 * Run under Bash with a timeout (e.g. timeout:120000). It self-exits well before the 600s watchdog.
 *
 * CONTRAST is now RELIABLE for oklab()/oklch() accent tokens (resolved to sRGB in-page); only color-mix()
 * with unresolved vars is skipped. COUNTS + GEOMETRY remain authoritative.
