import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

// `capture` is the DEFAULT: a first argument that is a URL means the consolidated run, so the
// common call is `capture.mjs <url> <outdir>`. The narrow modes stay explicit by name.
const _argv = process.argv.slice(2);
if (/^(https?|file):\/\//.test(_argv[0] || '')) _argv.unshift('capture');
const [mode, url, arg3, arg4] = _argv;
const rest = _argv;
const touch = rest.includes('--touch');
const dark = rest.includes('--dark');
const vp = (rest.find(a => /^\d+x\d+$/.test(a)) || '1512x900').split('x').map(Number);
