    process.env.PW,                                                   // explicit override wins
    path.join(NEXUS_TOOLS, 'node_modules/playwright/index.js'),        // the durable tools home
    path.join(here, 'node_modules/playwright/index.js'),               // beside this script
    path.join(process.cwd(), 'node_modules/playwright/index.js'),      // the caller's project
    'playwright',                                                      // node resolution / global
