    if(h[0]==='#'){return [parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)];}
    const mm=(h.match(/[\\d.]+/g)||[]); return mm.length>=3?mm.slice(0,3).map(Number):null; };
  const lum = (c) => { const s=c.map(v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)}); return 0.2126*s[0]+0.7152*s[1]+0.0722*s[2]; };
