      if(r!=null&&r<need) contrasts.push({t:(el.textContent||'').trim().slice(0,28),size,ratio:r,need,cls:el.className?.toString?.().slice(0,40)}); } }
    if(el.matches('button,a,[role=button],input,select,[onclick],[data-testid]')){ const r=el.getBoundingClientRect(); if(r.width>0&&(r.width<24||r.height<24)) targets.push({cls:(el.className?.toString?.()||'').slice(0,40),w:Math.round(r.width),h:Math.round(r.height)}); }
