// browser-use's whitelist: only what visibility/interactivity needs. More styles crash Chrome on heavy pages.
const CAP_STYLES = ['display', 'visibility', 'opacity', 'overflow', 'overflow-x', 'overflow-y',
                'cursor', 'pointer-events', 'position', 'background-color'];

// ── rect union (port of browser-use RectUnionPure) ───────────────────────────
// Maintains a DISJOINT set of rects. contains(r) is true iff r is fully covered.
// The cap prevents exponential fragmentation on pages with many translucent layers;
// past it we stop adding, so occlusion becomes conservative (nothing hidden) not wrong.
const MAX_RECTS = 5000;
class RectUnion {
  constructor() { this.rects = []; }
  static isects(a, b) { return !(a[2] <= b[0] || b[2] <= a[0] || a[3] <= b[1] || b[3] <= a[1]); }
  static holds(a, b) { return a[0] <= b[0] && a[1] <= b[1] && a[2] >= b[2] && a[3] >= b[3]; }
  static splitDiff(a, b) {                       // a \ b, up to 4 pieces
    const parts = [];
    if (a[1] < b[1]) parts.push([a[0], a[1], a[2], b[1]]);       // below
    if (b[3] < a[3]) parts.push([a[0], b[3], a[2], a[3]]);       // above
    const yLo = Math.max(a[1], b[1]), yHi = Math.min(a[3], b[3]);
    if (a[0] < b[0]) parts.push([a[0], yLo, b[0], yHi]);         // left
    if (b[2] < a[2]) parts.push([b[2], yLo, a[2], yHi]);         // right
    return parts;
  }
  contains(r) {
    if (!this.rects.length) return false;
    let stack = [r];
    for (const s of this.rects) {
      const next = [];
      for (const piece of stack) {
        if (RectUnion.holds(s, piece)) continue;                 // piece fully eaten
        if (RectUnion.isects(piece, s)) next.push(...RectUnion.splitDiff(piece, s));
        else next.push(piece);
      }
      if (!next.length) return true;                             // everything eaten → covered
      stack = next;
    }
    return false;
  }
  add(r) {
    if (this.rects.length >= MAX_RECTS) return false;
    if (this.contains(r)) return false;
    let pending = [r];
    for (const s of this.rects) {
      const next = [];
      for (const piece of pending) {
        if (RectUnion.isects(piece, s)) next.push(...RectUnion.splitDiff(piece, s));
        else next.push(piece);
      }
      pending = next;
      if (!pending.length) break;
    }
    this.rects.push(...pending);
    return true;
  }
}

// ── interactivity ladder (port of browser-use ClickableElementDetector) ──────
// Order matters: the cheap authoritative signals first, the fuzzy heuristics last.
const INTERACTIVE_TAGS = new Set(['button', 'input', 'select', 'textarea', 'a', 'details', 'summary', 'option', 'optgroup']);
const INTERACTIVE_ATTRS = ['onclick', 'onmousedown', 'onmouseup', 'onkeydown', 'onkeyup', 'tabindex'];
const INTERACTIVE_ROLES = new Set(['button', 'link', 'menuitem', 'option', 'radio', 'checkbox', 'tab', 'textbox',
                                   'combobox', 'slider', 'spinbutton', 'listbox', 'search', 'searchbox', 'row', 'cell', 'gridcell']);
const SEARCH_HINTS = ['search', 'magnify', 'glass', 'lookup', 'find', 'query', 'searchbox'];
// A node's reason is STRONG when the element carries its own interactivity signal, WEAK when the
// signal could have been inherited or guessed. `cursor` INHERITS in CSS, so every child of a
// pointer-styled button computes pointer too — left unfiltered that one rule produced 87 of 126
// "controls" on a real page, nearly all of them a ::before, an 8x8 svg or a 4x2 path inside a
// button already detected by its click listener. A WEAK node nested inside any interactive
// element is that element's own paintwork, not a separate control.
const WEAK_REASONS = new Set(['cursor-pointer', 'icon-sized', 'search-hint']);

function isInteractive(n, ctx) {
  if (n.tag === 'html' || n.tag === 'body') return { yes: false };
  // 1. Chrome's OWN click-handler detection, free in the snapshot. Catches React/Vue/Angular
  //    handlers that leave no attribute behind — the class our old 6-condition test missed.
  if (n.snapClickable) return { yes: true, why: 'js-listener' };
  // 2. iframes big enough to hold their own scrollable UI
  if ((n.tag === 'iframe' || n.tag === 'frame') && n.rect.width > 100 && n.rect.height > 100) return { yes: true, why: 'iframe' };
  // 3. labels/spans that WRAP a control (Ant/MUI radio+checkbox pattern). A label with `for`
  //    is skipped so we don't double-activate the input it points at.
  if (n.tag === 'label') {
    if (n.attrs.for) return { yes: false };
    if (ctx.wrapsFormControl(n)) return { yes: true, why: 'label-wraps-control' };
  }
  if (n.tag === 'span' && ctx.wrapsFormControl(n)) return { yes: true, why: 'span-wraps-control' };
  // 4. AX properties. disabled/hidden are a hard NO and must beat everything below.
  for (const p of n.axProps) {
    if ((p.name === 'disabled' || p.name === 'hidden') && p.value) return { yes: false, why: 'ax-' + p.name };
    if (['focusable', 'editable', 'settable', 'required'].includes(p.name) && p.value) return { yes: true, why: 'ax-' + p.name };
    if (['checked', 'expanded', 'pressed', 'selected'].includes(p.name)) return { yes: true, why: 'ax-state' };
    if (p.name === 'keyshortcuts' && p.value) return { yes: true, why: 'ax-keyshortcut' };
  }
  // 5. tag / attribute / role
  if (INTERACTIVE_TAGS.has(n.tag)) return { yes: true, why: 'tag' };
  if (INTERACTIVE_ATTRS.some(a => a in n.attrs)) return { yes: true, why: 'handler-attr' };
  if (n.attrs.role && INTERACTIVE_ROLES.has(n.attrs.role)) return { yes: true, why: 'role-attr' };
  if (n.role && INTERACTIVE_ROLES.has(n.role.toLowerCase())) return { yes: true, why: 'ax-role' };
  // 6. search affordances that carry no role (the bare magnifier icon)
  const idcls = ((n.attrs.class || '') + ' ' + (n.attrs.id || '')).toLowerCase();
  if (SEARCH_HINTS.some(h => idcls.includes(h))) return { yes: true, why: 'search-hint' };
  // 7. icon-sized with any addressing attribute
  const { width: w, height: h } = n.rect;
  if (w >= 10 && w <= 50 && h >= 10 && h <= 50 &&
      ['class', 'role', 'onclick', 'data-action', 'aria-label'].some(a => a in n.attrs)) return { yes: true, why: 'icon-sized' };
  // 8. last resort: the page says it's clickable by styling it so
  if (n.styles.cursor === 'pointer') return { yes: true, why: 'cursor-pointer' };
  return { yes: false };
}

// ── build the model from one snapshot + AX tree ──────────────────────────────
// COORDINATE SPACE, settled empirically against getBoundingClientRect rather than assumed:
//   · layout.bounds is in DOCUMENT space and in CSS pixels. It does NOT move when the page
//     scrolls; document.scrollOffsetY carries the scroll, and viewportY = bounds.y - scrollOffsetY
//     (measured: bounds 900, scroll 500, DOM rect 400).
//   · bounds are NOT device pixels under a Playwright deviceScaleFactor context (measured:
//     raw [12, 104.296875, 207, 31.5] identical to getBoundingClientRect at dpr=2). browser-use
//     divides by devicePixelRatio because their capture path applies Emulation.setDeviceMetricsOverride
//     with a scale factor; ours does not. Dividing blind halves every rect and silently
//     mis-locates every hit test, so the scale is CALIBRATED per run instead of assumed.
function build(snap, axNodes, scale, scrollX, scrollY, vpW, vpH) {
  const S = snap.strings;
  const str = i => (i >= 0 && i < S.length ? S[i] : '');
  const doc = snap.documents[0];
  const N = doc.nodes, L = doc.layout;

  // AX join on backendDOMNodeId
  const ax = new Map();
  for (const a of axNodes) if (a.backendDOMNodeId != null) ax.set(a.backendDOMNodeId, a);

  // layout arrays are per LAID-OUT node; index them back by node index (first occurrence wins)
  const lay = new Map();
  for (let li = 0; li < L.nodeIndex.length; li++) {
    const ni = L.nodeIndex[li];
    if (lay.has(ni)) continue;
    lay.set(ni, {
      bounds: L.bounds?.[li], styleIdx: L.styles?.[li],
      paintOrder: L.paintOrders?.[li], text: L.text ? str(L.text[li]) : '',
      clientRect: L.clientRects?.[li],
    });
  }
  // rare-boolean lists → Set. As a list, `index in list` is O(n) and this was browser-use's
  // measured #1 bottleneck: 5,925ms → 2ms at 20k elements.
  const clickable = new Set(N.isClickable?.index || []);
  const inputChecked = new Set(N.inputChecked?.index || []);
  const optionSelected = new Set(N.optionSelected?.index || []);
  const textValue = new Map((N.textValue?.index || []).map((ni, k) => [ni, str(N.textValue.value[k])]));
  const inputValue = new Map((N.inputValue?.index || []).map((ni, k) => [ni, str(N.inputValue.value[k])]));

  const attrsOf = (i) => {
    const a = N.attributes[i] || [], m = {};
    for (let k = 0; k + 1 < a.length; k += 2) m[str(a[k])] = str(a[k + 1]);
    return m;
  };
  const tagOf = (i) => str(N.nodeName[i]).toLowerCase();

  // children index, for text reconstruction and form-control wrapping
  const kids = new Map();
  for (let i = 0; i < N.parentIndex.length; i++) {
    const p = N.parentIndex[i];
    if (p >= 0) { if (!kids.has(p)) kids.set(p, []); kids.get(p).push(i); }
  }

  // STABLE identity: the path of tags from root to this node, plus attributes that survive
  // a re-render. `class` is deliberately excluded — CSS-in-JS regenerates it every build.
  const STABLE_ATTRS = ['id', 'name', 'type', 'placeholder', 'aria-label', 'data-testid', 'role', 'href', 'alt', 'title'];
  const branchOf = (i) => {
    const parts = []; let c = i, guard = 0;
    while (c >= 0 && guard++ < 200) { parts.push(tagOf(c)); c = N.parentIndex[c]; }
    return parts.reverse().join('/');
  };

  // TEXT: layout.text is null on many React trees (it only carries laid-out TEXT nodes).
  // browser-use never relies on it alone; reconstruct from AX name, then child text nodes.
  const ownText = (i) => {
    const parts = [];
    for (const c of kids.get(i) || []) if (N.nodeType[c] === 3) {
      const v = str(N.nodeValue[c]).trim();
      if (v) parts.push(v);
    }
    return parts.join(' ');
  };

  const wrapsFormControl = (n, depth = 2) => {
    const walk = (i, d) => {
      if (d <= 0) return false;
      for (const c of kids.get(i) || []) {
        if (N.nodeType[c] !== 1) continue;
        const t = tagOf(c);
        if (t === 'input' || t === 'select' || t === 'textarea') return true;
        if (walk(c, d - 1)) return true;
      }
      return false;
    };
    return walk(n.idx, depth);
  };

  // Pseudo-elements (::before/::after) render, carry inherited styles, and can never be
  // addressed by a click. They must not enter the model at all.
  const pseudo = new Set(N.pseudoType?.index || []);

  const nodes = [];
  for (let i = 0; i < N.nodeName.length && nodes.length < MAXEL; i++) {
    if (N.nodeType[i] !== 1) continue;                 // elements only
    if (pseudo.has(i)) continue;
    const lo = lay.get(i);
    if (!lo || !lo.bounds) continue;                   // not laid out → not rendered
    const styles = {};
    if (lo.styleIdx) CAP_STYLES.forEach((k, j) => { styles[k] = str(lo.styleIdx[j]); });
    const [bx, by, bw, bh] = lo.bounds;
    // rect = DOCUMENT space (stable across scroll; the space occlusion and identity live in)
    const rect = { x: Math.round(bx / scale), y: Math.round(by / scale), width: Math.round(bw / scale), height: Math.round(bh / scale) };
    // viewportRect = what is on screen right now; the space hit tests and screenshots live in
    const viewportRect = { x: rect.x - scrollX, y: rect.y - scrollY, width: rect.width, height: rect.height };
    const attrs = attrsOf(i);
    const backend = N.backendNodeId[i];
    const a = ax.get(backend);
    const axName = a?.name?.value || '';
    const axProps = (a?.properties || []).map(p => ({ name: p.name, value: p.value?.value }));

    const visible = rect.width > 0 && rect.height > 0 &&
      styles.visibility !== 'hidden' && styles.display !== 'none' && parseFloat(styles.opacity || '1') > 0.05;

    const text = axName || ownText(i) || lo.text || attrs['aria-label'] || attrs.placeholder ||
                 inputValue.get(i) || textValue.get(i) || attrs.alt || attrs.title || '';

    nodes.push({
      idx: i, backend, tag: tagOf(i), attrs, styles, rect, viewportRect, visible,
      inViewport: viewportRect.y < vpH && viewportRect.y + rect.height > 0 && viewportRect.x < vpW && viewportRect.x + rect.width > 0,
      role: a?.role?.value || attrs.role || null, axProps, axIgnored: !!a?.ignored,
      snapClickable: clickable.has(i), paintOrder: lo.paintOrder ?? null,
      text: String(text).replace(/\s+/g, ' ').trim().slice(0, 140),
      checked: inputChecked.has(i) || undefined, selected: optionSelected.has(i) || undefined,
      _branch: branchOf(i),
    });
  }

  const ctx = { wrapsFormControl };
  for (const n of nodes) {
    const v = isInteractive(n, ctx);
    n.interactive = v.yes; n.interactiveWhy = v.why || null;
    const basis = `${n._branch}|` + STABLE_ATTRS.map(k => n.attrs[k] ? `${k}=${n.attrs[k]}` : '').join('') + (n.text || '');
    n.hash = crypto.createHash('sha256').update(basis).digest('hex').slice(0, 12);
  }

  // ── dedup pass: collapse a control's own paintwork into the control ────────
  // browser-use calls this bounding-box filtering. Two rules, both DOM-ancestry based,
  // because that is what actually causes the duplication:
  //   (a) a WEAK node inside any interactive element is that element's decoration;
  //   (b) two STRONG nodes nested with the same box are a wrapper plus its real control —
  //       keep the INNER one, which is what a click resolves to anyway.
  const nodeByIdx = new Map(nodes.map(n => [n.idx, n]));
  const sameBox = (a, b) => Math.abs(a.x - b.x) <= 2 && Math.abs(a.y - b.y) <= 2 &&
                            Math.abs(a.width - b.width) <= 2 && Math.abs(a.height - b.height) <= 2;
  for (const n of nodes) {
    if (!n.interactive) continue;
    let p = N.parentIndex[n.idx], guard = 0;
    while (p >= 0 && guard++ < 200) {
      const anc = nodeByIdx.get(p);
      if (anc?.interactive) {
        if (WEAK_REASONS.has(n.interactiveWhy)) { n.interactive = false; n.suppressedBy = anc.hash; n.suppressReason = 'inherited-from-ancestor'; break; }
        if (sameBox(n.rect, anc.rect) && !WEAK_REASONS.has(anc.interactiveWhy)) { anc.interactive = false; anc.suppressedBy = n.hash; anc.suppressReason = 'wrapper-of-inner-control'; }
      }
      p = N.parentIndex[p];
    }
  }

  // ── occlusion: walk paint order HIGH→LOW; anything already covered by what paints
  //    above it is hidden from the user, however present it is in the DOM.
  const byPaint = new Map();
  for (const n of nodes) {
    if (n.paintOrder == null || !n.visible) continue;
    if (!byPaint.has(n.paintOrder)) byPaint.set(n.paintOrder, []);
    byPaint.get(n.paintOrder).push(n);
  }
  const union = new RectUnion();
  let occludedCount = 0;
  for (const po of [...byPaint.keys()].sort((a, b) => b - a)) {
    const toAdd = [];
    for (const n of byPaint.get(po)) {
      const r = [n.rect.x, n.rect.y, n.rect.x + n.rect.width, n.rect.y + n.rect.height];
      if (union.contains(r)) { n.occluded = true; occludedCount++; }
      // Only OPAQUE things occlude. A transparent or faded layer sits on top without hiding.
      const bg = n.styles['background-color'] || 'rgba(0, 0, 0, 0)';
      if (bg === 'rgba(0, 0, 0, 0)' || parseFloat(n.styles.opacity || '1') < 0.8) continue;
      toAdd.push(r);
    }
    for (const r of toAdd) union.add(r);
  }

  // ── addressable set + @eN refs, in document order
  const addressable = nodes.filter(n => n.interactive && n.visible && !n.occluded);
  addressable.forEach((n, k) => { n.ref = `@e${k + 1}`; });

  return { nodes, addressable, occludedCount, unionSize: union.rects.length };
}

// ── indented tree, ref-bearing lines and their ancestors only (agent-browser compact_tree) ──
function renderTree(model, N_parentIndex) {
  const keep = new Set();
  const byIdx = new Map(model.nodes.map(n => [n.idx, n]));
  for (const n of model.addressable) {
    keep.add(n.idx);
    let p = N_parentIndex[n.idx], guard = 0;
    while (p >= 0 && guard++ < 200) { if (byIdx.has(p)) keep.add(p); p = N_parentIndex[p]; }
  }
  const depth = (i) => { let d = 0, p = N_parentIndex[i], g = 0; while (p >= 0 && g++ < 200) { if (keep.has(p)) d++; p = N_parentIndex[p]; } return d; };
  const lines = [];
  for (const n of model.nodes) {
    if (!keep.has(n.idx)) continue;
    const attrs = [];
    if (n.ref) attrs.push(`ref=${n.ref}`);
    if (n.checked) attrs.push('checked');
    if (n.selected) attrs.push('selected');
    if (n.attrs.disabled != null) attrs.push('disabled');
    if (n.attrs.href) attrs.push(`url=${n.attrs.href.slice(0, 60)}`);
    if (n.ref) attrs.push(`${n.rect.width}x${n.rect.height}`);
    if (n.ref && !n.inViewport) attrs.push('off-screen');
    const label = n.text ? ` ${JSON.stringify(n.text)}` : '';
    lines.push(`${'  '.repeat(depth(n.idx))}- ${n.role || n.tag}${label}${attrs.length ? ` [${attrs.join(', ')}]` : ''}`);
  }
  return lines.join('\n');
}

// ── numbered set-of-marks overlay: draw @eN badges over the live page, shoot, remove ──
// Vision seats can then cite a ref they can SEE, instead of guessing from a bare screenshot.
// NOTE these are REAL functions, not strings: Playwright's page.evaluate(<string>, arg)
// silently DROPS the argument (measured), which made a string version write a plain
// screenshot labelled "annotated" — a mislabelled artifact with no error anywhere.
const annotateMarks = (items) => {
  const old = document.getElementById('__probe_marks__'); if (old) old.remove();
  const L = document.createElement('div'); L.id = '__probe_marks__';
  L.style.cssText = 'position:fixed;inset:0;z-index:2147483647;pointer-events:none;font:700 11px ui-monospace,monospace';
  for (const it of items) {
    const r = it.rect; if (!r || r.width <= 0 || r.height <= 0) continue;
    const box = document.createElement('div');
    const col = it.reachable === false ? '#e11d48' : '#2563eb';
    box.style.cssText = `position:absolute;left:${r.x}px;top:${r.y}px;width:${r.width}px;height:${r.height}px;` +
      `outline:1.5px solid ${col};outline-offset:-1px;background:${col}14`;
    const tag = document.createElement('span');
    tag.textContent = it.ref.replace('@', '') + (it.reachable === false ? '!' : '');
    tag.style.cssText = `position:absolute;left:0;top:-13px;padding:0 3px;background:${col};color:#fff;line-height:13px;border-radius:2px;white-space:nowrap`;
    box.appendChild(tag); L.appendChild(box);
  }
  document.documentElement.appendChild(L);
  return L.children.length;                       // proof the overlay actually landed
};
const clearMarks = () => { const e = document.getElementById('__probe_marks__'); if (e) { e.remove(); return true; } return false; };

// ── pixel diff, run IN THE PAGE via canvas so the tool needs no image library ──
// Ported from agent-browser's diff_screenshot: per-pixel colour DISTANCE against a threshold
// (not equality, which flags anti-aliasing noise), a dimension guard, and a red-marked diff image.
const pixelDiff = async ([aSrc, bSrc, threshold]) => {
  const load = (src) => new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = src; });
  const [ia, ib] = await Promise.all([load(aSrc), load(bSrc)]);
  if (ia.width !== ib.width || ia.height !== ib.height)
    return { dimensionMismatch: { before: [ia.width, ia.height], after: [ib.width, ib.height] }, mismatchPct: 100, changed: true };
  const w = ia.width, h = ia.height;
  const ca = new OffscreenCanvas(w, h), cb = new OffscreenCanvas(w, h);
  const xa = ca.getContext('2d'), xb = cb.getContext('2d');
  xa.drawImage(ia, 0, 0); xb.drawImage(ib, 0, 0);
  const da = xa.getImageData(0, 0, w, h).data, db = xb.getImageData(0, 0, w, h).data;
  const out = xa.createImageData(w, h); const o = out.data;
  const maxDist = threshold * 255 * Math.sqrt(3);
  let diff = 0, minX = w, minY = h, maxX = -1, maxY = -1;
  for (let i = 0; i < da.length; i += 4) {
    const dr = da[i] - db[i], dg = da[i + 1] - db[i + 1], dbl = da[i + 2] - db[i + 2];
    if (Math.sqrt(dr * dr + dg * dg + dbl * dbl) > maxDist) {
      diff++; o[i] = 255; o[i + 1] = 0; o[i + 2] = 0; o[i + 3] = 255;
      const px = (i / 4) % w, py = Math.floor((i / 4) / w);
      if (px < minX) minX = px; if (px > maxX) maxX = px;
      if (py < minY) minY = py; if (py > maxY) maxY = py;
    } else {
      const g = ((da[i] + da[i + 1] + da[i + 2]) / 3) * 0.3;
      o[i] = o[i + 1] = o[i + 2] = g; o[i + 3] = 255;
    }
  }
  let png = null;
  if (diff > 0) {
    xa.putImageData(out, 0, 0);
    const blob = await ca.convertToBlob({ type: 'image/png' });
    png = await new Promise(r => { const fr = new FileReader(); fr.onload = () => r(fr.result); fr.readAsDataURL(blob); });
  }
  const total = w * h;
  return { totalPixels: total, differentPixels: diff,
           mismatchPct: Math.round((diff / total) * 10000) / 100, changed: diff > 0,
           changedRegion: maxX >= 0 ? { x: minX, y: minY, width: maxX - minX + 1, height: maxY - minY + 1 } : null,
           diffPng: png };
};

// ── semantic state diff, on the STABLE hash rather than on text ───────────────
// A text diff of two renders is mostly renumbering noise. Identity-based diffing says what
// actually happened: which controls APPEARED, which went away, which changed label or box.
// browser-use marks appeared elements with `*`; the same idea, made explicit in the record.
function diffStates(before, after) {
  const A = new Map(before.elements.map(e => [e.hash, e]));
  const B = new Map(after.elements.map(e => [e.hash, e]));
  const appeared = [...B.values()].filter(e => !A.has(e.hash));
  const gone = [...A.values()].filter(e => !B.has(e.hash));
  const changed = [];
  for (const [h, b] of B) {
    const a = A.get(h); if (!a) continue;
    const d = [];
    if (a.text !== b.text) d.push('text');
    if (JSON.stringify(a.rect) !== JSON.stringify(b.rect)) d.push('rect');
    if (a.reachable !== b.reachable) d.push('reachable');
    if (d.length) changed.push({ ref: b.ref, hash: h, text: b.text.slice(0, 48), changed: d,
                                 from: d.includes('text') ? a.text.slice(0, 48) : undefined });
  }
  const slim = e => ({ ref: e.ref, hash: e.hash, tag: e.tag, role: e.role, text: e.text.slice(0, 60), rect: e.rect, reachable: e.reachable });
  const cb = before.content, ca = after.content;
  const contentChanged = !!(cb && ca && (cb.textHash !== ca.textHash || cb.elementCount !== ca.elementCount));
  return {
    urlChanged: before.url !== after.url, from: before.url, to: after.url,
    titleChanged: before.title !== after.title,
    contentChanged, contentDelta: (cb && ca) ? { textLen: ca.textLen - cb.textLen, elements: ca.elementCount - cb.elementCount } : null,
    counts: { before: before.counts, after: after.counts },
    appeared: appeared.map(slim), gone: gone.map(slim), changed: changed.slice(0, 40),
    summary: `${appeared.length} appeared, ${gone.length} gone, ${changed.length} changed` +
             (contentChanged ? `, content ${ca.elementCount - cb.elementCount >= 0 ? '+' : ''}${ca.elementCount - cb.elementCount} els` : ''),
  };
}

// ── one full state capture: acquire → identify → filter → reach → measure → write ─────
async function captureState(page, cdp, outdir, tag, opts = {}) {
  const t0 = Date.now();
  const [snap, axr] = await Promise.all([
    cdp.send('DOMSnapshot.captureSnapshot', { computedStyles: CAP_STYLES, includePaintOrder: true, includeDOMRects: true }),
    cdp.send('Accessibility.getFullAXTree', {}),
  ]);
  const tAcquire = Date.now() - t0;

  // CALIBRATE: never assume the bounds-to-CSS ratio — it differs between a deviceScaleFactor
  // context and a metrics override, and assuming it silently mis-locates every hit test.
  const cal = await page.evaluate(() => {
    const r = document.body.getBoundingClientRect();
    return { cssW: r.width, dpr: window.devicePixelRatio, scrollX: Math.round(window.scrollX), scrollY: Math.round(window.scrollY) };
  });
  const scale = (() => {
    const S = snap.strings, d = snap.documents[0], Nn = d.nodes, Ll = d.layout;
    let bi = -1; for (let i = 0; i < Nn.nodeName.length; i++) if (S[Nn.nodeName[i]].toLowerCase() === 'body') { bi = i; break; }
    const li = Ll.nodeIndex.indexOf(bi); const w = li >= 0 ? Ll.bounds[li]?.[2] : null;
    if (!w || !cal.cssW) return 1;
    const s = w / cal.cssW;
    return (s > 0.2 && s < 8) ? Math.round(s * 100) / 100 : 1;
  })();
  const scrollX = snap.documents[0].scrollOffsetX || cal.scrollX || 0;
  const scrollY = snap.documents[0].scrollOffsetY || cal.scrollY || 0;

  const t1 = Date.now();
  const vpz = page.viewportSize() || { width: 1512, height: 900 };
  const model = build(snap, axr.nodes || [], scale, scrollX, scrollY, vpz.width, vpz.height);
  const tBuild = Date.now() - t1;

  // REACHABILITY: rect-union catches TOTAL occlusion; this catches PARTIAL occlusion, which
  // kills a click just as dead (measured: a panel covering 77% of a link left it unclickable).
  const reach = await page.evaluate((items) => items.map(it => {
    const r = it.viewportRect, cx = Math.round(r.x + r.width / 2), cy = Math.round(r.y + r.height / 2);
    if (cx < 0 || cy < 0 || cx >= innerWidth || cy >= innerHeight) return { ref: it.ref, reachable: null, note: 'offscreen' };
    const hit = document.elementFromPoint(cx, cy);
    if (!hit) return { ref: it.ref, reachable: false, note: 'nothing-at-point' };
    const near = (a, b) => Math.abs(a.x - b.x) <= 2 && Math.abs(a.y - b.y) <= 2 &&
                           Math.abs(a.width - b.width) <= 2 && Math.abs(a.height - b.height) <= 2;
    let e = hit, d = 0;
    while (e && d++ < 40) { if (near(e.getBoundingClientRect(), r)) return { ref: it.ref, reachable: true }; e = e.parentElement; }
    const br = hit.getBoundingClientRect();
    return { ref: it.ref, reachable: false, note: 'intercepted',
             interceptedBy: hit.tagName.toLowerCase() + (hit.className ? '.' + String(hit.className).split(' ')[0] : ''),
             interceptorRect: { x: Math.round(br.x), y: Math.round(br.y), width: Math.round(br.width), height: Math.round(br.height) } };
  }), model.addressable.map(n => ({ ref: n.ref, viewportRect: n.viewportRect })));
  const rBy = new Map(reach.map(r => [r.ref, r]));
  for (const n of model.addressable) { const r = rBy.get(n.ref); n.reachable = r?.reachable; n.reachNote = r?.note; n.interceptedBy = r?.interceptedBy; n.interceptorRect = r?.interceptorRect; }

  // L4 DESIGN MEASUREMENT — the same block `measure` mode runs, folded in so ONE capture
  // answers both "what is here and does it work" and "is it any good".
  let measure = null;
  if (opts.measure !== false) {
    try { measure = await page.evaluate(`(${MEASURE_FN})(${JSON.stringify(opts.root || null)})`); }
    catch (e) { measure = { error: String(e).slice(0, 140) }; }
  }

  // CONTENT SIGNATURE: the element diff only covers CONTROLS, so a click that adds a row or a
  // success message would read as "nothing changed". This catches the whole visible text body.
  const content = await page.evaluate(() => {
    const t = (document.body && document.body.innerText) || '';
    let h = 0; for (let i = 0; i < t.length; i++) h = (Math.imul(h, 31) + t.charCodeAt(i)) | 0;
    return { textLen: t.length, textHash: (h >>> 0).toString(36), elementCount: document.querySelectorAll('*').length };
  }).catch(() => null);

  const tree = renderTree(model, snap.documents[0].nodes.parentIndex);
  const shotPath = `${outdir}/${tag}.png`;
  await page.screenshot({ path: shotPath, timeout: 15000 });
  let annotated = null;
  if (opts.annotate !== false && model.addressable.length) {
    try {
      const drawn = await page.evaluate(annotateMarks, model.addressable.map(n => ({ ref: n.ref, rect: n.viewportRect, reachable: n.reachable })));
      if (!drawn) throw new Error('overlay drew 0 marks');   // never label an un-annotated shot "annotated"
      annotated = `${tag}.annotated.png`;
      await page.screenshot({ path: `${outdir}/${annotated}`, timeout: 15000 });
      await page.evaluate(clearMarks);
    } catch { annotated = null; }
  }

  const state = {
    tag, capturedAt: new Date().toISOString(), url: page.url(), title: await page.title(),
    viewport: vpz, dpr: cal.dpr, boundsScale: scale, scroll: { x: scrollX, y: scrollY },
    theme: opts.theme || 'light', content,
    counts: {
      rendered: model.nodes.length, visible: model.nodes.filter(n => n.visible).length,
      interactive: model.nodes.filter(n => n.interactive).length,
      occluded: model.occludedCount, addressable: model.addressable.length,
      unreachable: model.addressable.filter(n => n.reachable === false).length,
    },
    timingMs: { acquire: tAcquire, build: tBuild },
    files: { screenshot: `${tag}.png`, annotated, tree: `${tag}.tree.txt`, json: `${tag}.json` },
    consoleErrors: (opts.consoleErrors || []).slice(0, 12),
    tree,
    elements: model.addressable.map(n => ({
      ref: n.ref, hash: n.hash, tag: n.tag, role: n.role, text: n.text,
      rect: n.rect, viewportRect: n.viewportRect, inViewport: n.inViewport,
      why: n.interactiveWhy, reachable: n.reachable, paintOrder: n.paintOrder,
      testid: n.attrs['data-testid'] || n.attrs.id || null, href: n.attrs.href || null,
    })),
    unreachable: model.addressable.filter(n => n.reachable === false).map(n => ({
      ref: n.ref, hash: n.hash, tag: n.tag, text: n.text, viewportRect: n.viewportRect,
      note: n.reachNote, interceptedBy: n.interceptedBy, interceptorRect: n.interceptorRect })),
    hiddenInteractive: model.nodes.filter(n => n.interactive && n.visible && n.occluded)
      .slice(0, 40).map(n => ({ hash: n.hash, tag: n.tag, text: n.text, rect: n.rect, why: n.interactiveWhy })),
    measure,
  };
  fs.writeFileSync(`${outdir}/${tag}.json`, JSON.stringify(state, null, 1));
  fs.writeFileSync(`${outdir}/${tag}.tree.txt`, tree);
  return state;
}

// ── resolve a click target: @eN ref from the last state, a CSS selector, or visible text ──
async function resolveTarget(page, state, target) {
  if (/^@e\d+$/.test(target)) {
    const el = state.elements.find(e => e.ref === target);
    if (!el) return { ok: false, error: `${target} not in ${state.tag}` };
    return { ok: true, kind: 'ref', point: { x: el.viewportRect.x + el.viewportRect.width / 2, y: el.viewportRect.y + el.viewportRect.height / 2 }, label: el.text || el.tag };
  }
  const bySel = target.startsWith('#') || target.startsWith('.') || target.includes('[');
  const loc = bySel ? page.locator(target).first() : page.getByText(target, { exact: false }).first();
  const n = await loc.count().catch(() => 0);
  if (!n) return { ok: false, error: `no element for ${JSON.stringify(target)}` };
  return { ok: true, kind: bySel ? 'selector' : 'text', locator: loc, label: target };
}

// ── helper: apply dark theme + settle ──
const goDark = async (p) => { await p.evaluate(() => { document.documentElement.setAttribute('data-theme','dark'); document.documentElement.classList.add('dark'); }); await p.waitForTimeout(500); };

// ── doctor: answer "is this machine able to run me, and if not, what exactly do I run?" ──
// A lane that hits a missing dependency should be able to diagnose it in ONE call instead of
// guessing, and the answer must be actionable rather than a stack trace.
async function doctor() {
  const out = { tool: 'capture.mjs', node: process.version, platform: process.platform, checks: {}, fixes: [] };
  const pw = await resolveChromium();
  out.checks.playwright = pw.chromium
    ? { ok: true, resolvedFrom: pw.from }
    : { ok: false, tried: pw.tried };
  if (!pw.chromium) out.fixes.push({ what: 'playwright (REQUIRED)', run: PW_INSTALL_HINT });

  // the browser binaries live in a shared cache, separate from the npm package
  const cacheDirs = [path.join(process.env.HOME || '', 'Library/Caches/ms-playwright'),
                     path.join(process.env.HOME || '', '.cache/ms-playwright')];
  const cache = cacheDirs.find(d => { try { return fs.existsSync(d); } catch { return false; } });
  out.checks.browsers = cache
    ? { ok: true, cache, entries: fs.readdirSync(cache).length }
    : { ok: false, note: 'no ms-playwright cache found' };
  if (!cache) out.fixes.push({ what: 'chromium binary', run: 'npx playwright install chromium' });

  // launching is the only proof that the package AND a usable binary are both present
  if (pw.chromium) {
    try {
      const t = Date.now();
      const br = await pw.chromium.launch({ args: ['--no-sandbox'] });
      const v = br.version(); await br.close();
      out.checks.launch = { ok: true, ms: Date.now() - t, chromium: v };
    } catch (e) {
      out.checks.launch = { ok: false, error: String(e).split('\n')[0].slice(0, 200) };
      if (!out.fixes.some(f => f.what === 'chromium binary'))
        out.fixes.push({ what: 'chromium binary', run: 'npx playwright install chromium' });
    }
  }

  // OPTIONAL: agent-browser. Absence is never an error — it only gates the opt-in `--attach` path.
  try {
    const { execSync } = await import('node:child_process');
    const ver = execSync('agent-browser --version', { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim();
    let ws = null;
    try { ws = execSync('agent-browser get cdp-url', { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim(); } catch {}
    out.checks.agentBrowser = { ok: true, optional: true, version: ver, daemonUp: !!ws, cdpUrl: ws || null };
  } catch {
    out.checks.agentBrowser = { ok: false, optional: true, note: 'not installed — `--attach` unavailable; every capture launches its own chromium (the default)' };
  }

  out.ready = !!(out.checks.playwright.ok && out.checks.launch?.ok);
  return out;
}

// ── bootstrap: make this machine able to run the tool, idempotently ──────────
// `doctor` diagnoses; `bootstrap` repairs. Safe to run any number of times: if everything is already
// present it installs nothing and says so. Installs into the DURABLE home so the result survives the
// session — a toolchain rooted in a session scratchpad is the failure this exists to prevent.
async function bootstrap() {
  const { execSync } = await import('node:child_process');
  const steps = [];
  const run = (label, cmd, cwd) => {
    try {
      execSync(cmd, { cwd, stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf8', timeout: 300000 });
      steps.push({ step: label, ok: true, cmd });
    } catch (e) {
      steps.push({ step: label, ok: false, cmd, error: String(e.stderr || e.message).split('\n')[0].slice(0, 160) });
    }
  };

  let before = await doctor();
  if (before.ready) return { alreadyReady: true, steps: [], resolvedFrom: before.checks.playwright.resolvedFrom, doctor: before };

  // The durable home must exist BEFORE any step runs in it. The package and the browser binary are
  // independent: a machine can resolve playwright by node resolution while its HOME-scoped binary cache
  // is empty, in which case only the binary step runs — and it ran with a non-existent cwd
  // (`spawnSync /bin/sh ENOENT`) while this mkdir sat inside the package branch.
  try { fs.mkdirSync(NEXUS_TOOLS, { recursive: true }); } catch {}

  // Install into the DURABLE home unconditionally, even when bare node resolution already finds a
  // playwright somewhere: the resolver prefers this home (candidate 2) over bare resolution
  // (candidate 5), so this is the copy that will actually run. npm is idempotent and fast when present.
  // Write the manifest directly rather than `npm init -y`: npm rejects a dot-prefixed directory as a
  // package name ("Invalid name: .nexus-tools"), which reported a FAILED step on a bootstrap that
  // actually succeeded — a false red is as bad as a false green.
  const manifest = path.join(NEXUS_TOOLS, 'package.json');
  if (!fs.existsSync(manifest)) {
    try {
      fs.writeFileSync(manifest, JSON.stringify({ name: 'nexus-tools', private: true, version: '1.0.0' }, null, 2));
      steps.push({ step: 'init durable tools home', ok: true, cmd: `write ${manifest}` });
    } catch (e) { steps.push({ step: 'init durable tools home', ok: false, error: String(e).slice(0, 120) }); }
  }
  run('install playwright', 'npm install playwright --no-audit --no-fund', NEXUS_TOOLS);

  // The browser binary MUST be installed by the SAME playwright that will launch it. `npx --yes
  // playwright install` fetches the LATEST playwright and downloads ITS revision — measured: that put
  // chromium r1234 on disk while the resolved package wanted a different revision, so the cache looked
  // healthy and the launch still failed. Invoke the durable copy's own CLI instead.
  const pwCli = path.join(NEXUS_TOOLS, 'node_modules', 'playwright', 'cli.js');
  const afterPkg = await doctor();
  if (!afterPkg.checks.launch?.ok) {
    if (fs.existsSync(pwCli)) run('install chromium binary (matched revision)', `node "${pwCli}" install chromium`, NEXUS_TOOLS);
    else run('install chromium binary (fallback)', 'npx --yes playwright install chromium', NEXUS_TOOLS);
  }

  const after = await doctor();
  return { alreadyReady: false, steps, ready: after.ready,
           resolvedFrom: after.checks.playwright.resolvedFrom || null,
           remaining: after.fixes, doctor: after };
}

(async () => {
  let b;
  try {
    if (mode === 'doctor') { emit({ status: 'ok', ...(await doctor()) }); clearTimeout(HARD); process.exit(0); }
    if (mode === 'bootstrap') { const r = await bootstrap(); emit({ status: r.ready === false ? 'error' : 'ok', ...r }); clearTimeout(HARD); process.exit(0); }
    const pw = await resolveChromium();
    if (!pw.chromium) {
      emit({ status: 'error', error: 'playwright not found', triedPaths: pw.tried, fix: PW_INSTALL_HINT,
             hint: 'or set PW=<abs path to node_modules/playwright/index.js>' });
      clearTimeout(HARD); process.exit(0);
    }
    // ── ATTACH (opt-in) vs LAUNCH (default) ────────────────────────────────────
    // Attaching to a warm agent-browser daemon costs ~46ms against ~2.9s for a cold launch, and the
    // CDP session it yields is fully capable (DOMSnapshot with paintOrder + isClickable, the AX tree,
    // evaluate-with-args, screenshots). It is OPT-IN, never automatic: that browser may be driven by
    // another lane at the same time, and silently sharing it would reintroduce exactly the
    // one-writer collision this fleet has already paid for. `--attach` is the caller accepting that.
    let attached = false, attachNote = null;
    if (rest.includes('--attach')) {
      try {
        const { execSync } = await import('node:child_process');
        // `get cdp-url` is NOT side-effect free: with no session running it LAUNCHES a browser and
        // prints "[agent-browser] launched browser" before the url. Calling it unguarded means
        // --attach silently SPAWNS a browser, reports it as "attached", gains nothing, and leaves the
        // process behind. Gate on `session list`, which is read-only and prints "No active sessions".
        const sessions = execSync('agent-browser session list', { encoding: 'utf8', stdio: ['ignore','pipe','ignore'] }).trim();
        if (/no active sessions/i.test(sessions) || !sessions) throw new Error('no warm session to attach to');
        const raw = execSync('agent-browser get cdp-url', { encoding: 'utf8', stdio: ['ignore','pipe','ignore'] });
        // pull the url OUT of the output rather than testing the whole blob — it may carry a banner line
        const ws = (raw.split(/\r?\n/).find(l => /^wss?:\/\//.test(l.trim())) || '').trim();
        if (!ws) throw new Error('no cdp url in output');
        b = await pw.chromium.connectOverCDP(ws);
        attached = true;
      } catch (e) {
        attachNote = `attach failed, launched our own instead: ${String(e.message || e).slice(0, 90)}`;
      }
    }
    try {
      if (!attached) b = await pw.chromium.launch({ args: ['--no-sandbox'] });
    } catch (e) {
      const msg = String(e);
      const missingBinary = /Executable doesn't exist|playwright install/i.test(msg);
      emit({ status: 'error', error: missingBinary ? 'playwright browser binary missing' : 'browser launch failed',
             detail: msg.split('\n')[0].slice(0, 200),
             playwrightFrom: pw.from,
             fix: missingBinary ? 'npx playwright install chromium' : null,
             hint: missingBinary ? `run it from ${NEXUS_TOOLS} so the binary lands in the shared cache, then re-run` : 'run `capture.mjs doctor` for a full diagnosis' });
      clearTimeout(HARD); process.exit(0);
    }

    // ── shots: MULTI-VIEWPORT clean screenshot SET (viewport × theme [× tab]) for the fresh-eye judges ──
    if (mode === 'shots') {
      const outdir = arg3;
      const tabsArg = rest.find(a => a.startsWith('--tabs=')); const tabs = tabsArg ? tabsArg.split('=')[1].split(',') : [null];
      const vpArg = rest.find(a => a.startsWith('--viewports='));
      // DEFAULT now includes 1920 (real desktop width) + 1512 (laptop) + 390 (phone) so the council sees every scale.
      const vps = vpArg
        ? vpArg.split('=')[1].split(',').map(s=>{const [w,h]=s.split('x').map(Number); return {w,h,tag:`${w}w`,touch:w<=480};})
        : [{ w:1920, h:1080, tag:'desktop', touch:false }, { w:1512, h:900, tag:'laptop', touch:false }, { w:390, h:844, tag:'phone', touch:true }];
      const shots = [];
      for (const V of vps) for (const theme of ['light','dark']) for (const tab of tabs) {
        const pg = await b.newPage({ viewport:{width:V.w,height:V.h}, deviceScaleFactor:2, hasTouch:V.touch, isMobile:V.touch });
        pg.setDefaultTimeout(15000);
        try {
          await pg.goto(url, { timeout:20000, waitUntil:'domcontentloaded' }); await pg.waitForTimeout(2200);
          if (theme==='dark') { await pg.evaluate(()=>{document.documentElement.setAttribute('data-theme','dark');document.documentElement.classList.add('dark');}); await pg.waitForTimeout(400); }
          if (tab) { try { await pg.evaluate((t)=>{const el=[...document.querySelectorAll('button,a,[role=tab],.tab')].find(e=>(e.textContent||'').trim().toLowerCase()===t.toLowerCase()); if(el)el.click();}, tab); await pg.waitForTimeout(1200); } catch {} }
          const name = `${V.tag}-${theme}${tab?('-'+tab.toLowerCase()):''}.png`; await pg.screenshot({ path:`${outdir}/${name}`, timeout:15000 }); shots.push(name);
        } catch(e) { shots.push(`FAILED ${V.tag}-${theme}${tab?('-'+tab):''}: ${String(e).slice(0,80)}`); }
        finally { await pg.close(); }
      }
      emit({ status:'ok', outdir, viewports:vps.map(v=>`${v.w}x${v.h}`), shots }); clearTimeout(HARD); await b.close(); process.exit(0);
    }

    // ── capture: the consolidated agent-view + transition recorder ──────────────
    // ONE run folder answers: what is on this page, does every control actually work,
    // is it well made, and what does each control DO. See the usage header.
    if (mode === 'capture') {
      const outdir = arg3;
      if (!outdir || /^\d+x\d+$/.test(outdir)) { emit({ status: 'error', error: 'capture needs an <outdir>: capture.mjs capture <url> <outdir> [WxH]' }); clearTimeout(HARD); await b.close(); process.exit(0); }
      fs.mkdirSync(outdir, { recursive: true });

      const flag = (name, dflt) => { const f = rest.find(a => a.startsWith(`--${name}=`)); return f ? f.split('=').slice(1).join('=') : dflt; };
      const clickTarget = flag('click', null);
      const sweep = rest.includes('--sweep');
      const sweepMax = Number(flag('sweep-max', '20'));
      const pixThreshold = Number(flag('pixel-threshold', '0.1'));
      const root = flag('root', null);
      const wantMeasure = !rest.includes('--no-measure');
      const wantAnnotate = !rest.includes('--no-annotate');
      const vps = flag('viewports', null)
        ? flag('viewports', '').split(',').map(s => { const [w, h] = s.split('x').map(Number); return { w, h, touch: w <= 480 }; })
        : [{ w: vp[0], h: vp[1], touch }];
