#!/usr/bin/env node
/* Deterministic feedback collator — REPLACES the LLM consolidator.
 * Reads every reviewer's typed handoff JSON from a dir and emits the FULL feedback (no summarization,
 * no dropped detail): a scores table, then EVERY defect grouped by severity, each tagged with its
 * dimension + element + fix + evidence, plus regression flags, cross-notes, and open conflicts.
 * The output is what the fix executor consumes verbatim.
 *
 * Usage: node collate.mjs <reviews-dir> [--ledger <path>] [--round r1]
 *   each file = one reviewer handoff {dimension,score,verdict,defects:[...],...}
 *   --ledger  ALSO write/update docs/ISSUE-LEDGER.md — the round's findings with STABLE ids,
 *             so round N+1 can tell a reappearing defect from a new one. Without it a round's
 *             findings live only in scattered per-lane files nobody re-reads at ship time,
 *             which is how a category scoring 2.14 against a bar of 9 was treated as closed.
 * Reviewers write their handoff to <reviews-dir>/<dimension>.json as their final action.
 *
 * TWO handoff shapes are accepted and normalized here:
 *   REVIEWER  {dimension, score, verdict, defects:[{severity,element,defect,corrected_target,evidence}], …}
 *   ASSESSOR  {category, category_score, summary, dimensions:[{id,name,weight,score,reasoning,evidence,climb}], …}
 * A council file used to collate to `| ? | — | — |` and contribute zero rows. It no longer does.
 *
 * IT REJECTS NON-CONFORMANT OUTPUT (exit 1), because the agent files promise that it does:
 *   - a scored dimension with no `reasoning` (a bare number defending nothing)
 *   - a scored dimension with no `evidence`
 *   - a defect whose `severity` is outside the known vocabulary (it would otherwise sort as `low`,
 *     i.e. silently below the critical/HIGH stop condition)
 * The full collation is still printed, so one sloppy seat never destroys the other seats' work —
 * the non-zero exit plus the REJECTED block is the signal.
 */
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'fs';
import { createHash } from 'crypto';
const argv = process.argv.slice(2);
const dir = argv.find(a => !a.startsWith('--')) || '.';
const ledgerPath = argv.includes('--ledger') ? argv[argv.indexOf('--ledger') + 1] : null;
const round = argv.includes('--round') ? argv[argv.indexOf('--round') + 1] : 'r1';
const files = readdirSync(dir).filter(f => f.endsWith('.json'));
const rank = { blocker:0, critical:0, high:1, major:1, medium:2, moderate:2, low:3, minor:3, trivial:4 };
const SEVERITIES = Object.keys(rank);
// A climb/fix entry may be a plain string OR an object ({rung, action, …} shapes vary by rubric).
// Naive join() renders "[object Object]" and silently destroys the one thing the executor needs.
const flat = (v) => {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(flat).filter(Boolean).join('; ');
  if (typeof v === 'object') {
    const t = v.action || v.climb || v.fix || v.corrected_target || v.to || v.text || v.description;
    if (t) return v.rung != null ? `rung ${v.rung}: ${flat(t)}` : flat(t);
    return JSON.stringify(v);            // never "[object Object]" — show the data
  }
  return String(v);
};
const nonconformant = [];
const raw = [];
for (const f of files) {
  try { raw.push({ file: f, obj: JSON.parse(readFileSync(`${dir}/${f}`, 'utf8')) }); }
  catch (e) { raw.push({ file: f, obj: { dimension: f.replace('.json',''), parseError: String(e).slice(0,120) } }); }
}

// ── normalize: an ASSESSOR handoff becomes one row per rubric dimension ──
const reviews = [];
for (const { file, obj: r } of raw) {
  if (r && r.category && Array.isArray(r.dimensions)) {
    for (const d of r.dimensions) {
      if (d.score !== undefined && d.score !== null && String(d.score) !== 'N/A') {
        if (!d.reasoning) nonconformant.push(`${file} · ${r.category}/${d.id||d.name||'?'} — scored ${d.score} with NO \`reasoning\`: a bare number defends nothing`);
        else if (!d.evidence) nonconformant.push(`${file} · ${r.category}/${d.id||d.name||'?'} — \`reasoning\` present but NO \`evidence\` cited`);
      }
    }
    reviews.push({
      dimension: r.category,
      score: r.category_score,
      verdict: r.summary || '—',
      defects: r.dimensions.filter(d => d.climb).map(d => ({
        severity: d.severity || (Number(d.score) <= 5 ? 'high' : 'medium'),
        element: `${d.id||''} ${d.name||''}`.trim(),
        defect: d.reasoning,
        corrected_target: flat(d.climb),
        evidence: d.evidence,
      })),
      by_design: r.dimensions.filter(d => String(d.score) === 'BY-DESIGN')
        .map(d => `${d.id||d.name}: ${d.contract||''} — intent_execution ${d.intent_execution ?? '?'}`),
      contract_challenges: r.contract_challenges || [],
      cross_notes: r.cross_notes || [],
      category: r.category,
    });
  } else {
    reviews.push(r);
  }
