// ── severity vocabulary check: an unknown value would sort as `low` and slip under the stop condition ──
for (const r of reviews) for (const d of (r.defects || [])) {
  const s = (d.severity || '').toLowerCase();
  if (s && !(s in rank)) nonconformant.push(`${r.dimension||'?'} — defect severity "${d.severity}" is outside the vocabulary (${SEVERITIES.join('|')}); it would sort as \`low\` and pass under the critical/HIGH stop condition`);
  if (!s) nonconformant.push(`${r.dimension||'?'} — defect with NO severity: "${String(d.defect||d.element||'').slice(0,60)}"`);
}
const out = [];
out.push('# CONSOLIDATED REVIEW FEEDBACK (deterministic collation — full detail, nothing dropped)\n');
out.push('## Scores\n| Dimension | Score | Verdict |\n|---|---|---|');
for (const r of reviews) out.push(`| ${r.dimension||'?'} | ${r.score??'—'} | ${r.verdict||(r.parseError?'PARSE-ERROR':'—')} |`);
out.push('');

// Collect every defect across dimensions, tag with dimension, sort by severity.
const defects = [];
for (const r of reviews) for (const d of (r.defects||[])) defects.push({ ...d, dimension: r.dimension });
defects.sort((a,b) => (rank[(a.severity||'low').toLowerCase()] ?? 3) - (rank[(b.severity||'low').toLowerCase()] ?? 3));

out.push('## Every defect (grouped by severity — ALL reviewers, verbatim)\n');
let lastSev = null;
for (const d of defects) {
  const sev = (d.severity||'low').toUpperCase();
  if (sev !== lastSev) { out.push(`\n### ${sev}`); lastSev = sev; }
  out.push(`- **[${d.dimension}]** ${flat(d.element||d.el||d.region)}`);
  out.push(`  - defect: ${flat(d.defect||d.what_is_wrong||d.summary||d.failure_scenario)}`);
  const fx = flat(d.corrected_target || d.fix || d.suggested_fix_described);
  if (fx) out.push(`  - fix: ${fx}`);
  const ev=[d.law,d['file:line'],d.measured_value,d.measured_ratio,d.estimated_magnitude,d.which_shot,d.evidence].filter(Boolean).map(flat).join(' · ');
  if (ev) out.push(`  - evidence: ${ev}`);
}

// Regression flags + scope deltas + cross notes + gut tests + the judgment layer
// (by-design verdicts + contract challenges) — kept in full.
const blocks = [
  ['Regression / scope deltas', reviews.flatMap(r => [].concat(r.regression_flags||[], r.scope_delta?[r.scope_delta]:[]).map(x => `[${r.dimension}] ${flat(x)}`))],
  ['By-design (contract-overridden — NOT defects; never enter the fix loop)', reviews.flatMap(r => (r.by_design||[]).map(x => `[${r.dimension}] ${flat(x)}`))],
  ['Contract challenges (user re-pick items — sign-off, never fix-loop rows)', reviews.flatMap(r => (r.contract_challenges||[]).map(x => `[${r.dimension||r.category||'?'}] ${flat(x)}`))],
  ['Cross-notes (inter-reviewer)', reviews.flatMap(r => (r.cross_notes||[]).map(x => `[${r.dimension}] ${flat(x)}`))],
  ['Gut-test answers', reviews.filter(r=>r.gut_test).map(r => `[${r.dimension}] ${JSON.stringify(r.gut_test)}`)],
  ['Missing / not-verified', reviews.flatMap(r => (r.missing_captures||r.missing||[]).map(x => `[${r.dimension}] ${flat(x)}`))],
];
for (const [title, items] of blocks) if (items.length) { out.push(`\n## ${title}`); for (const it of items) out.push(`- ${it}`); }

out.push(`\n---\n_Collated from ${reviews.length} reviewer handoffs in ${dir}. ${defects.length} total defects._`);

if (nonconformant.length) {
  out.push(`\n## ⛔ REJECTED — non-conformant handoff output (${nonconformant.length})`);
  out.push('These rows do not meet the handoff contract. The collation above is still complete, but this');
  out.push('run exits non-zero: a score that defends nothing, or a severity outside the vocabulary, is not');
  out.push('reviewable output and must be re-emitted by its seat.\n');
  for (const n of nonconformant) out.push(`- ${n}`);
}

// ── ISSUE-LEDGER (opt-in via --ledger) ────────────────────────────────────────
// STABLE ID = sha1(dimension|element)[:6]. Chosen by measurement, not taste: replayed on a real
// 6-seat review round, keying on the defect TEXT re-minted 100% of ids when seats re-worded the
// same defect next round, while dimension|element re-matched every one. The cost is that one
// element carrying two distinct defects shares an id — reported as a within-round collision
// count rather than hidden.
if (ledgerPath) {
  const sha = (x) => createHash('sha1').update(x).digest('hex').slice(0, 6);
  const norm = (x) => String(x || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const idOf = (d) => 'I' + sha(norm(d.dimension) + '|' + norm(flat(d.element || d.el || d.region)));
  const rows = new Map();
  if (existsSync(ledgerPath)) {
    for (const line of readFileSync(ledgerPath, 'utf8').split('\n')) {
      const m = line.match(/^\| (I[0-9a-f]{6}) \| (\S+) \| (.*?) \| (\S+) \| (.*?) \| (.*?) \|$/);
      if (m) rows.set(m[1], { id: m[1], severity: m[2], issue: m[3], status: m[4], history: m[5], fix: m[6] });
    }
  }
  let minted = 0, rematched = 0, regressed = 0, collisions = 0;
  const seen = new Map();
  for (const d of defects) {
    const id = idOf(d);
    seen.set(id, (seen.get(id) || 0) + 1);
    if (seen.get(id) > 1) collisions++;
    const ex = rows.get(id);
    const text = flat(d.defect || d.what_is_wrong || d.summary || d.failure_scenario);
    if (!ex) {
      minted++;
      rows.set(id, {
        id, severity: (d.severity || 'low').toLowerCase(),
        issue: `[${d.dimension}] ${flat(d.element || d.el || d.region)} — ${text.slice(0, 160)}`,
        status: 'open', history: `${round}:found`,
        fix: flat(d.corrected_target || d.fix).slice(0, 120),
      });
    } else {
      rematched++;
      // A row previously marked `fixed` that a seat finds AGAIN is a REGRESSION, and a
      // regression outranks new work (gates-and-ledger.md).
      if (ex.status === 'fixed') { ex.status = 'regressed'; regressed++; ex.history += ` · ${round}:REGRESSED`; }
      else if (!ex.history.includes(round)) ex.history += ` · ${round}:found`;
    }
  }
  const led = ['# ISSUE-LEDGER', '', '## In-scope issues',
    '| id | severity | issue | status | history (round: state) | fix / evidence |',
    '|----|----------|-------|--------|------------------------|----------------|'];
  for (const r of [...rows.values()].sort((a, b) => (rank[a.severity] ?? 3) - (rank[b.severity] ?? 3)))
    led.push(`| ${r.id} | ${r.severity} | ${String(r.issue).replace(/\|/g, '/')} | ${r.status} | ${r.history} | ${String(r.fix).replace(/\|/g, '/')} |`);
  led.push('', `## Round ${round} close-out`,
    `findings ingested: ${defects.length} · minted: ${minted} · rematched: ${rematched} · ` +
    `REGRESSIONS: ${regressed} · within-round id collisions: ${collisions} · total rows: ${rows.size}`,
    '', 'Closure columns are Cue\'s to set: a row moves to `fixed` only with evidence, and a `fixed`',
    'row found again next round is re-opened as `regressed` by this script, not by memory.');
  writeFileSync(ledgerPath, led.join('\n'));
  out.push(`\n_ISSUE-LEDGER → ${ledgerPath} (minted ${minted} · rematched ${rematched} · regressions ${regressed} · collisions ${collisions})_`);
}

console.log(out.join('\n'));
process.exit(nonconformant.length ? 1 : 0);

#!/usr/bin/env node
/**
 * divergence.mjs — the gate for the `Read-path:` row's `divergence` clause.
 * Called by `guard.sh divergence`, never by hand.
 *
 *   node divergence.mjs <worktree> [--json]
 *   node divergence.mjs --self-test
 *
 * WHY THIS EXISTS. `performance-playbook.md` D1 says a serving projection is a SECOND
 * COPY and that divergence is a correctness class, then states plainly: "Enablement
 * therefore requires a divergence journey that FAILS when a table lies — NOT gated: no
 * `guard.sh` layer reads divergence, so this is a DISCIPLINE you keep, and the gate that
 * would make it a wall is unbuilt." This is that wall. The playbook line is now a
 * description of a gate rather than an apology for its absence.
 *
 * The two measured failures it exists to catch are different shapes, and both passed
 * every gate that existed at the time:
 *   · a projection hid an OPEN COUNTING ROUND from a user — the rows were stale
 *   · a column present in both spec and warehouse was ABSENT from the projection, and
 *     it took two screens down
 * Neither is visible to tsc, to a build, to a screenshot, or to a reactivity predicate.
 * Only a check that compares the copy against the canonical store can see them, and only
 * the app knows how to make that comparison — so this layer does not attempt it. It
 * enforces that the comparison EXISTS, RUNS, and PASSES.
 *
 * WHAT IT READS. The PRD's machine row, one per read surface:
 *
 *     Read-path: /#/o/deals projection · host bigtable-serving · divergence journeys/divergence.mjs
 *     Read-path: /#/o/companies direct · host warehouse-eu · divergence none
 *
 * No `Read-path:` row = reasoned GREEN (prints why, writes nothing). A skipped check
 * must never look like a passed one, and an app with no declared read path has not
 * reached the decision this gate guards.
 *
 * WHAT IT DECIDES, per row:
 *   · projection + `divergence none`        → FAIL. A second copy with NO check is
 *     precisely the unguarded state D1 forbids. `none` is legal for the modes that keep
 *     no copy, and only for those.
 *   · projection + a named check that is ABSENT on disk → FAIL. A declared check whose
 *     file does not exist is the GATE-EXEC lesson: a promise someone will trust.
 *   · projection + a named check that EXITS NON-ZERO → FAIL, its output quoted.
 *   · direct / connector                    → PASS, reasoned. No copy, no divergence
 *     class. A check named anyway is still run: declaring one is a claim.
 *   · a row a machine cannot read (no mode, or no `host`) → FAIL. The row exists to be
 *     read by a gate; prose that merely contains the words is not a row, which is the
 *     same judgement `TANK-HOME`'s `host` token guard already makes.
 *
 * Exit 0 = no FAIL row. Exit 1 = at least one FAIL. Exit 2 = the checker itself is broken.
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const has = (n) => argv.includes(n);

/** A per-app check may be slow, but it may not hang the build. */
const CHECK_TIMEOUT_MS = 120_000;

/** Modes that keep a SECOND COPY of the canonical store, and therefore can diverge. */
const COPYING_MODES = new Set(['projection']);
const KNOWN_MODES = new Set(['projection', 'direct', 'connector']);

const rows = [];
const R = (surface, verdict, detail) => rows.push({ surface, verdict, detail });

/**
 * Every `Read-path:` row → [{ raw, surface, mode, host, divergence }].
 *
 * Fields are null when the row does not carry them, rather than defaulted — a
 * defaulted mode would silently turn an unreadable row into a passing one, which is
 * the failure this whole file is about.
 */
export function parseReadPathRows(text) {
  const out = [];
  for (const raw of (text || '').split('\n')) {
    if (!raw.includes('Read-path:')) continue;
    const body = raw.slice(raw.indexOf('Read-path:') + 'Read-path:'.length).trim();
    if (!body) continue;
    const mode = (body.match(/\b(projection|direct|connector)\b/i) || [])[1] || null;
    const host = (body.match(/\bhost\s+([^\s·|]+)/i) || [])[1] || null;
    const divergence = (body.match(/\bdivergence\s+([^\s·|]+)/i) || [])[1] || null;
    // The surface is the first token — the route or name the row is about. A row whose
    // first token IS the mode names no surface, which is itself unreadable.
    const first = body.split(/\s+/)[0] || '';
    const surface = KNOWN_MODES.has(first.toLowerCase()) ? null : first;
    out.push({ raw: raw.trim(), surface, mode: mode && mode.toLowerCase(), host, divergence });
  }
  return out;
}

/** Run a per-app divergence check. Returns {ok, output}. */
function runCheck(worktree, rel) {
  const abs = path.resolve(worktree, rel);
  if (!fs.existsSync(abs)) return { ok: false, missing: true, output: '' };
  let cmd, args;
  if (/\.(mjs|cjs|js)$/.test(abs)) { cmd = process.execPath; args = [abs]; }
  else if (/\.sh$/.test(abs)) { cmd = 'bash'; args = [abs]; }
  else if (/\.py$/.test(abs)) { cmd = 'python3'; args = [abs]; }
  else { cmd = abs; args = []; }
  try {
    const out = execFileSync(cmd, args, {
      cwd: worktree, encoding: 'utf8', timeout: CHECK_TIMEOUT_MS,
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    return { ok: true, output: out || '' };
  } catch (e) {
    const out = ((e.stdout || '') + (e.stderr || '')) || String(e.message || e);
    // A timeout is not a pass. It is the check failing to answer, which for a
    // correctness gate is the same verdict as answering "no".
    return { ok: false, timedOut: e.killed === true || e.signal === 'SIGTERM', output: out };
  }
}

function judge(worktree, row) {
  const label = row.surface || row.raw.slice(0, 48);
  if (!row.mode || !row.host) {
    R(label, 'FAIL', `row is not machine-readable — ${!row.mode ? 'no mode (projection|direct|connector)' : 'no `host <where>` token'}. `
      + 'A read path decided only in prose is how an in-process projection reached a container while every gate stayed green.');
    return;
  }
  const copies = COPYING_MODES.has(row.mode);
  const decl = (row.divergence || '').toLowerCase();

  if (!row.divergence) {
    R(label, 'FAIL', `${row.mode} row carries no \`divergence <check or none>\` clause — the clause is what says whether a copy is checked.`);
    return;
  }
  if (decl === 'none') {
    if (copies) {
      R(label, 'FAIL', 'a PROJECTION is a second copy and `divergence none` leaves it unchecked. '
        + 'Measured: a projection hid an open counting round from a user while every gate stayed green, and a column '
        + 'present in spec and warehouse but absent from the projection took two screens down. Name a check that FAILS '
        + 'when a table lies, or move this surface to `direct` and keep no copy.');
    } else {
      R(label, 'PASS', `${row.mode} keeps no copy of the canonical store, so there is no divergence class to check.`);
    }
    return;
  }

  const res = runCheck(worktree, row.divergence);
  if (res.missing) {
    R(label, 'FAIL', `declared divergence check \`${row.divergence}\` does not exist in the worktree. `
      + 'A declared check is one the next person will trust — write it or drop the claim.');
    return;
  }
  if (res.timedOut) {
    R(label, 'FAIL', `divergence check \`${row.divergence}\` timed out after ${CHECK_TIMEOUT_MS / 1000}s — `
      + 'a check that cannot answer is not a check that passed.');
    return;
  }
  if (!res.ok) {
    R(label, 'FAIL', `divergence check \`${row.divergence}\` exited non-zero — the copy disagrees with the canonical store. `
      + `Output: ${res.output.trim().slice(0, 300).replace(/\n/g, ' ⏎ ')}`);
    return;
  }
  R(label, 'PASS', `divergence check \`${row.divergence}\` ran and passed${copies ? '' : ` (${row.mode} keeps no copy; the check is a bonus claim)`}.`);
}

function run(worktree) {
  const prd = path.join(worktree, 'docs', 'PRD.md');
  const entries = fs.existsSync(prd) ? parseReadPathRows(fs.readFileSync(prd, 'utf8')) : [];
  if (!entries.length) {
    console.log('divergence gate: reasoned GREEN — docs/PRD.md carries no `Read-path:` row '
      + '(no declared read path to check; declare one to arm this layer)');
    return 0;
  }
  for (const row of entries) judge(worktree, row);

  const fails = rows.filter((r) => r.verdict === 'FAIL');
  const md = ['# DIVERGENCE — serving-copy correctness evidence ('
    + new Date().toISOString().slice(0, 16).replace('T', ' ') + ')', '',
    'A projection is a SECOND COPY. This layer does not compare the copies itself — only the app '
    + 'knows how. It enforces that the comparison exists, runs, and passes.', '',
    '| surface | verdict | detail |', '|---|---|---|',
    ...rows.map((r) => `| \`${r.surface}\` | ${r.verdict} | ${r.detail} |`), '',
    `${fails.length === 0 ? 'GREEN' : `${fails.length} FAIL row(s)`}`, ''].join('\n');
  fs.mkdirSync(path.join(worktree, 'docs'), { recursive: true });
  fs.writeFileSync(path.join(worktree, 'docs', 'DIVERGENCE.md'), md);

  if (has('--json')) console.log(JSON.stringify({ ok: fails.length === 0, rows }, null, 2));
  else {
    for (const r of rows) {
      const g = r.verdict === 'FAIL' ? '\x1b[31m' : '\x1b[32m';
      console.log(`${g}${r.verdict.padEnd(6)}\x1b[0m ${r.surface} — ${r.detail}`);
    }
    console.log('\nevidence written: docs/DIVERGENCE.md');
  }
  return fails.length === 0 ? 0 : 1;
}

// ── SELF-TEST ─────────────────────────────────────────────────────────────────
// Every arm must be SEEN RED on a planted fixture before its green is trusted, and the
// clean fixture must stay GREEN — a check that fires on correct input gets removed, and
// then the real violations flow again.

function fixture(prdLines, files = {}) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'diverge-'));
  fs.mkdirSync(path.join(dir, 'docs'), { recursive: true });
  fs.writeFileSync(path.join(dir, 'docs', 'PRD.md'), '# PRD\n' + prdLines.join('\n') + '\n');
  for (const [rel, body] of Object.entries(files)) {
    const p = path.join(dir, rel);
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, body);
    fs.chmodSync(p, 0o755);
  }
  return dir;
}

const PASSING_CHECK = '#!/usr/bin/env node\nprocess.exit(0);\n';
const FAILING_CHECK = '#!/usr/bin/env node\nconsole.log("deals: 41 rows in projection, 42 canonical");\nprocess.exit(1);\n';

function selfTest() {
  console.log('SELF-TEST — every arm must be seen RED on a planted fixture, and clean input must stay GREEN.\n');
  const cases = [
    ['clean: projection + a passing check', 0,
      fixture(['Read-path: /#/o/deals projection · host bigtable · divergence journeys/div.mjs'],
        { 'journeys/div.mjs': PASSING_CHECK })],
    ['clean: direct + none (no copy, no class)', 0,
      fixture(['Read-path: /#/o/deals direct · host warehouse-eu · divergence none'])],
    ['clean: no Read-path row at all (layer unarmed)', 0, fixture(['Access: PRIVATE — group ops'])],
    ['RED: projection + divergence none', 1,
      fixture(['Read-path: /#/o/deals projection · host bigtable · divergence none'])],
    ['RED: projection + declared check MISSING on disk', 1,
      fixture(['Read-path: /#/o/deals projection · host bigtable · divergence journeys/div.mjs'])],
    ['RED: projection + check exits non-zero', 1,
      fixture(['Read-path: /#/o/deals projection · host bigtable · divergence journeys/div.mjs'],
        { 'journeys/div.mjs': FAILING_CHECK })],
    ['RED: row with no host token is prose, not a row', 1,
      fixture(['Read-path: we read the deals projection straight from bigtable'])],
    ['RED: projection row with no divergence clause', 1,
      fixture(['Read-path: /#/o/deals projection · host bigtable'])],
    ['RED: one clean row and one bad row still fails', 1,
      fixture(['Read-path: /#/o/a direct · host wh · divergence none',
               'Read-path: /#/o/b projection · host bt · divergence none'])],
  ];
  let ok = true;
  for (const [name, want, dir] of cases) {
    rows.length = 0;
    let got;
    try { got = run(dir); } catch (e) { got = 2; console.error(e); }
    const good = got === want;
    console.log(`  ${good ? 'PASS' : 'FAIL'}  ${name.padEnd(52)} (exit=${got}, want=${want})`);
    if (!good) ok = false;
    fs.rmSync(dir, { recursive: true, force: true });
  }

  // The parser, driven directly: the fields the exit code cannot show.
  rows.length = 0;
  const p = parseReadPathRows(
    'Read-path: /#/o/deals projection · host bigtable-serving · divergence journeys/div.mjs\n'
    + 'noise line\nRead-path: /#/o/a direct · host wh · divergence none\n');
  const parseOk = p.length === 2 && p[0].mode === 'projection' && p[0].host === 'bigtable-serving'
    && p[0].divergence === 'journeys/div.mjs' && p[0].surface === '/#/o/deals'
    && p[1].mode === 'direct' && p[1].divergence === 'none';
  console.log(`  ${parseOk ? 'PASS' : 'FAIL'}  ${'parser: two rows, all fields, noise ignored'.padEnd(52)}`);
  if (!parseOk) ok = false;

  console.log(`\nself-test: ${ok ? 'PASS — every arm proved it can fail, and none fires on clean input'
    : 'FAIL — an arm never went red, or fired on clean input; its green means nothing'}`);
  return ok ? 0 : 2;
}

// ── entry ─────────────────────────────────────────────────────────────────────
if (has('--self-test')) process.exit(selfTest());
const [wt] = argv.filter((a) => !a.startsWith('--'));
if (!wt) {
  console.error('usage: divergence.mjs <worktree> [--json]   |   divergence.mjs --self-test');
  process.exit(2);
}
process.exit(run(wt));

# AUTHORING guard-fix.mjs — the per-app deterministic fix-gate

> LOAD WHEN: adding a check to the build's fix-gate (the check-ratchet fires — a defect was
> fixed, so a permanent driven check joins the gate the same round). `guard.sh fix <wt> <url>`
> runs the file this guide authors. One check per fixed defect; each asserts the *visible
> outcome* of the fix on the served app — never the fixer's word.

---

## File skeleton

```js
// Deterministic FIX gate — drives the live app and mechanically asserts each CONFIRMED
// defect from the fix bundle is actually gone. Exit 0 = every check green.
import { readFileSync, readdirSync, statSync } from 'fs';
import { join } from 'path';
const [WT, URL] = process.argv.slice(2);
if (!WT || !URL) { console.error('usage: guard-fix.mjs <worktree> <url>'); process.exit(2); }
const PW = `${WT}/node_modules/playwright/index.js`;
let FAIL = 0;
const red = (m, ev) => { console.log(`RED   ${m}${ev ? ' :: ' + ev : ''}`); FAIL = 1; };
const grn = (m) => console.log(`GREEN ${m}`);
const HARD = setTimeout(() => { console.log('RED   guard-fix self-timeout'); process.exit(1); }, 900000);
let chromium;
try { const mod = await import(PW); chromium = (mod.default || mod).chromium; }
catch (e) { red('playwright import', String(e).slice(0,120)); process.exit(1); }

async function run() {
  // static checks first (fast, no browser) …
  const b = await chromium.launch();
  // … driven checks, one isolated block each …
  await b.close();
}
try { await run(); } catch (e) { red('guard-fix fatal', String(e).slice(0,150)); }
clearTimeout(HARD);
console.log(FAIL ? '\nFIX-GATE FAIL — not done' : '\nFIX-GATE PASS');
process.exit(FAIL ? 1 : 0);
```

The final line prints `FIX-GATE PASS`/`FIX-GATE FAIL` — `guard.sh fix` greps for it; keep
the strings exact.

---

## Check anatomy (driven checks)

Every driven check is one self-contained block with this shape:

```js
// --- <gateId> (<ledger id / defect>): <one-line claim the check falsifies> ---
{ const pg = await (await b.newContext({ viewport:{width:1512,height:900}, deviceScaleFactor:2 })).newPage();
  await pg.goto(URL, { waitUntil:'domcontentloaded' });
  await pg.waitForSelector('[data-mustsee]', { timeout: 9000 }).catch(()=>{});
  await pg.waitForTimeout(2500);                       // settle for canvas/animation
  try {
    /* drive → observe → assert IDENTITY with evidence */
  } catch (e) { red('<gateId>: drive error', String(e).slice(0,100)); }
  await pg.close(); }
```

The rules, each one a paid-for failure mode:

1. **Isolated context per check.** A fresh `newContext`/`newPage` per block — shared pages
   leak state between checks (a prior check's mutation poisons the next one's baseline).
2. **`domcontentloaded`, never `networkidle`.** A WebGL canvas or long-poll never goes
   network-idle; the wait hangs to the harness watchdog. Readiness = `waitForSelector` on a
   real element (`[data-mustsee]`), then a short fixed settle.
3. **Assert with evidence.** Every `red()` carries the observed value (`ev`), not just the
   verdict — the executor fixes from the evidence string. Assert identity, not shape (L02):
   the value equals the expectation / the state changed to X, never "an element exists".
4. **Both poles.** A check asserting a transition captures BEFORE and AFTER the action and
   asserts the delta — so a shared/seeded store that is already in the end state cannot
   false-fail it, and an initial state that already satisfies the assertion cannot
   false-pass it. (Example class: "one click must NOT commit" — read the committed flag
   before the click; only a before=false → after=true transition is the defect.)
5. **State-aware reasoned GREEN.** When a check's precondition is absent by design (the
   record is sealed so the control is *correctly* disabled; the optional surface is not in
   this dataset), print a GREEN that says *why it did not run* — never a silent pass, never
   a RED for a legitimate state. A skipped check must be distinguishable from a passed one
   in the output.
6. **Bounded retries on flaky physical gestures.** Drags/pointer sequences get a small
   retry loop (≤3) with a settle between attempts — then a hard verdict. Never unbounded.
7. **Adversarial variants are separate checks.** The paced drag AND the fast drag; portrait
   AND landscape; light AND dark when the defect was theme-scoped. A fix that holds only on
   the paced/portrait/light variant is not fixed.
8. **Self-cleanup + hard exit.** `b.close()` in the run tail, the global `HARD` timeout so
   the script ALWAYS returns, `process.exit` with the real status. `guard.sh` must never
   hang on this file.

## Static checks

Defects provable from the source/CSS (a banned class still present, a bare hex where a
token belongs, a font-size below the legibility floor, a file over the line-limit) get a
file-scan check instead of a browser drive — same `red/grn` contract, runs first, costs
milliseconds. Walk the target directory excluding `node_modules`/`.git`/`dist`; report
`file:line` in the evidence.

## Measurement math

- **Contrast:** compute real WCAG ratios (relative luminance, the 4.5:1 / 3:1 thresholds by
  size+weight) — never eyeball, never trust a library's "accessible" boolean. `capture.mjs`
  carries the reference implementation, including oklab()/oklch() resolution in-page (canvas alone
  mis-resolves those tokens and yields a false ~1:1; the script does not use canvas alone). *Superseded
  2026-07: accent-element contrast fails no longer need a shot-confirm — they are real findings.*
  `color-mix()` with unresolved custom properties is skipped rather than guessed.
- **Geometry:** `getBoundingClientRect` deltas with an explicit tolerance (±1px for
  layout, a stated px budget for landing accuracy) — the tolerance is part of the check's
  contract, printed in the GREEN line.
- **Money/derived values:** re-derive the expectation in the check (`net = adjusted −
  deductible`) and compare — never assert the on-screen number against itself.

## data-testid discipline — a BUILD deliverable

Checks address elements by `data-testid` (and act-critical elements by `[data-mustsee]`).
The executor adds these hooks AS PART OF the feature, not as test scaffolding bolted on
later: stable ids on every interactive control and every asserted value. A check that has
to address `.class > div:nth-child(3)` breaks on the next refactor and the gate goes silent
— brittle selectors are a gate defect (fix the build to expose the id, then the check).

## Meta-gate obligation

Every new check is proven against its known-bad state once before it counts: re-introduce
the defect (or check out the pre-fix commit / temporarily invert the CSS), run the gate,
watch THIS check go RED on that exact case, restore. A fix-gate check that has never been
red is decoration (L01). Record the observed red in the ledger row's evidence cell.

#!/usr/bin/env node
/**
 * reactivity.mjs — the driven gate for the R1–R6 acceptance predicates
 * (`frontend-architecture.md` §6). Called by `guard.sh reactivity`, never by hand.
 *
 *   node reactivity.mjs <worktree> <urlbase> [--json]
 *   node reactivity.mjs --self-test
 *
 * Why this exists: §6 says a data surface with NO asserted predicate is `❌ untested`,
 * "the same class as a UI feature with no primitive" — and then delegated R1–R6 to a
 * prose instruction in an agent file. R7 got a gate in W42 (a machine row, a guard
 * layer, a Stop check, a registry row); R1–R6 stayed on rung 3, which
 * `gates-and-ledger.md` says fails silently and unevenly. This is that same gate,
 * ported, for the predicates a browser can actually decide.
 *
 * WHAT IT READS. The PRD's machine row, the `Perf-budget:` precedent:
 *
 *     Reactivity: /#/o/companies R1,R2,R4,R5,R6 · /#/o/deals R1,R2
 *
 * A route, then the predicates that surface carries. No row = reasoned GREEN (prints
 * why, writes nothing): a skipped check must never look like a passed one.
 *
 * WHAT THE APP DECLARES. Two attributes, the `[data-mustsee]` precedent — the build
 * tags, the gate drives what is tagged, and ZERO tagged is a RED rather than a pass.
 *   [data-surface]         the content root of a data surface (R1, R2)
 *   [data-surface-filter]  that surface's filter/search input   (R1-filter, R4, R5, R6)
 *
 * WHAT IT DECIDES, and what it deliberately does not — read `frontend-architecture.md`
 * §6a before trusting a green. R3 is RECORDED, never gated. R2 is gated against the
 * word-gate half of its predicate only. Every partial is printed as its own row.
 *
 * Exit 0 = no FAIL row. Exit 1 = at least one FAIL. Exit 2 = the checker itself is broken.
 */
import fs from 'node:fs';
import path from 'node:path';
import http from 'node:http';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const has = (n) => argv.includes(n);

// ── dependency resolution: find Playwright without being TOLD where it is (capture.mjs) ──
const NEXUS_TOOLS = path.join(process.env.HOME || process.env.USERPROFILE || '', '.nexus-tools');
const PW_CANDIDATES = () => [
  process.env.PW,
  path.join(NEXUS_TOOLS, 'node_modules/playwright/index.js'),
  path.join(HERE, 'node_modules/playwright/index.js'),
  path.join(process.cwd(), 'node_modules/playwright/index.js'),
  'playwright',
].filter(Boolean);
const PW_INSTALL_HINT = `mkdir -p ${NEXUS_TOOLS} && cd ${NEXUS_TOOLS} && npm init -y && npm i playwright && npx playwright install chromium`;
async function resolveChromium() {
  const tried = [];
  for (const c of PW_CANDIDATES()) {
    try {
      const m = await import(c);
      const chromium = (m.default || m).chromium;
      if (chromium) return { chromium, from: c };
      tried.push(`${c} (no chromium export)`);
    } catch { tried.push(c); }
  }
  return { chromium: null, tried };
}

// ── verdict rows ──────────────────────────────────────────────────────────────
// PASS / FAIL are the gated verdicts. RECORDED is measured-and-printed with no
// verdict (the `guard.sh perf` cold-read precedent). NOT-DRIVEN is a reasoned
// GREEN: the check states why it could not run, and never passes silently.
const rows = [];
const R = (route, pred, verdict, detail) => rows.push({ route, pred, verdict, detail });

/** The declared row → [{ route, preds:Set }]. */
export function parseReactivityRow(text) {
  const ln = (text || '').split('\n').find((l) => l.includes('Reactivity:') && /\bR[1-6]\b/.test(l));
  if (!ln) return null;
  const body = ln.slice(ln.indexOf('Reactivity:') + 'Reactivity:'.length);
  const out = [];
  for (const chunk of body.split('·')) {
    const preds = [...chunk.matchAll(/\bR([1-6])\b/g)].map((m) => `R${m[1]}`);
    if (!preds.length) continue;
    const route = chunk.trim().split(/\s+/)[0];
    if (!route || /^R[1-6]/.test(route)) continue;
    out.push({ route, preds: [...new Set(preds)] });
  }
  return out.length ? out : null;
}

// ── the in-page sampler ───────────────────────────────────────────────────────
// Installed at document_start so the FIRST paint is sampled, not just the settled
// frame. Per animation frame it records, for every [data-surface], the descendant
// count and a text head; plus the body text head, which is how a word-gate that
// replaces the WHOLE app (rather than one surface) stays visible to R2.
const SAMPLER = `
window.__nxR = { log: [], marks: [] };
window.__nxR.mark = (p) => window.__nxR.marks.push({ p, t: performance.now(), i: window.__nxR.log.length });
(function tick() {
  try {
    const els = document.querySelectorAll('[data-surface]');
    const marks = {};
    els.forEach((el, i) => {
      const key = el.getAttribute('data-surface') || ('#' + i);
      marks[key] = { n: el.getElementsByTagName('*').length,
                     txt: (el.textContent || '').replace(/\\s+/g, ' ').trim().slice(0, 120) };
    });
    // RENDERED body text only. A bare document.body.textContent also returns every
    // inline <script> source, which reads as 120 chars of JS and hides the word-gate
    // frame this sampler exists to catch.
    let body = '';
    if (document.body) for (const c of document.body.children) {
      if (!/^(SCRIPT|STYLE|TEMPLATE|NOSCRIPT|LINK|META)$/.test(c.tagName)) body += (c.textContent || '') + ' ';
    }
    window.__nxR.log.push({ t: performance.now(), marks,
      body: body.replace(/\\s+/g, ' ').trim().slice(0, 120),
      surfaces: els.length });
  } catch (e) { /* a sampler that throws must never take the page with it */ }
  requestAnimationFrame(tick);
})();
`;

/** The word-gate vocabulary. A loading STATE whose entire rendered text is one of these
 *  is the "first paint is a word" defect verbatim. WORD_MAX bounds "a word, not content":
 *  a content-shaped skeleton renders either no text or far more than this. */
const WORD_RE = /^(loading|fetching|please wait|chargement|cargando|caricamento|laden|carregando)\b/i;
const WORD_MAX = 60;
const isWordGate = (t) => !!t && t.length <= WORD_MAX && WORD_RE.test(t);

const nav = (page, route) => page.evaluate((r) => {
  window.__nxR.mark('nav:' + r);
  const before = window.__nxNavStamp;
  window.__nxNavStamp = before === undefined ? 1 : before;
  if (r.includes('#')) location.hash = r.slice(r.indexOf('#') + 1);
  else { history.pushState({}, '', r); dispatchEvent(new PopStateEvent('popstate')); }
}, route);

const readLog = (page) => page.evaluate(() => ({ log: window.__nxR.log, marks: window.__nxR.marks }));
const clearLog = (page) => page.evaluate(() => { window.__nxR.log.length = 0; window.__nxR.marks.length = 0; });

async function settle(page, ms = 1500) {
  await page.waitForFunction(
    () => document.querySelectorAll('[data-surface]').length > 0,
    null, { timeout: 15000 },
  ).catch(() => {});
  await page.waitForTimeout(ms);
}

/** min / final descendant count per surface key over a log slice. */
function counts(log) {
  const keys = new Set();
  for (const s of log) for (const k of Object.keys(s.marks)) keys.add(k);
  const out = {};
  for (const k of keys) {
    const seen = log.map((s) => s.marks[k]).filter(Boolean).map((m) => m.n);
    if (!seen.length) continue;
    out[k] = { min: Math.min(...seen), final: seen[seen.length - 1], frames: seen.length };
  }
  return out;
}

// ── the probe token: drawn from the surface's OWN visible data ─────────────────
// A fixture token would only prove the fixture matches itself. The first word of
// length >= 4 inside a tagged surface is a string the app is currently displaying,
// so a search for it must find at least the row it came from.
async function probeToken(page) {
  return page.evaluate(() => {
    const el = document.querySelector('[data-surface]');
    if (!el) return null;
    const words = (el.textContent || '').split(/[^\p{L}\p{N}]+/u).filter((w) => w.length >= 4);
    return words[0] || null;
  });
}
const ACCENTED = { a: 'á', e: 'é', i: 'í', o: 'ó', u: 'ú', c: 'ç', n: 'ñ' };
/** Put ONE accent on the token. Tests accented-query-finds-unaccented-data, so the
 *  arm runs on any token — it never depends on the app's data carrying diacritics. */
function accentise(tok) {
  for (let i = 0; i < tok.length; i++) {
    const a = ACCENTED[tok[i].toLowerCase()];
    if (a) return tok.slice(0, i) + a + tok.slice(i + 1);
  }
  return null;
}

async function typeFilter(page, value) {
  const ok = await page.evaluate((v) => {
    const el = document.querySelector('[data-surface-filter]');
    if (!el) return false;
    const setter = Object.getOwnPropertyDescriptor(el.constructor.prototype, 'value')?.set;
    if (setter) setter.call(el, v); else el.value = v;
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    return true;
  }, value);
  if (ok) await page.waitForTimeout(900);
  return ok;
}
const surfaceState = (page) => page.evaluate(() => {
  const el = document.querySelector('[data-surface]');
  return el ? { n: el.getElementsByTagName('*').length,
                txt: (el.textContent || '').replace(/\s+/g, ' ').trim() } : null;
});

// ── the drive ─────────────────────────────────────────────────────────────────
async function driveRoute(page, urlbase, entry, all) {
  const { route, preds } = entry;
  const want = (p) => preds.includes(p);
  const reqs = [];
  const onReq = (r) => reqs.push({ url: r.url(), start: Date.now() });
  const onRes = (r) => { const e = reqs.find((x) => x.url === r.url() && !x.end); if (e) e.end = Date.now(); };
  page.on('request', onReq);
  page.on('response', onRes);

  await page.goto(urlbase + route, { waitUntil: 'commit' }).catch(() => {});
  await settle(page);
  const first = await readLog(page);
  page.off('request', onReq);
  page.off('response', onRes);

  if (!first.log.length || !first.log[first.log.length - 1].surfaces) {
    R(route, 'ALL', 'FAIL', 'no [data-surface] element on this route — the build must tag each '
      + 'data surface\'s content root; zero tagged is a RED, not a pass (the [data-mustsee] rule)');
    return;
  }

  // ── R2 — the word-gate half of "first paint is content-shaped, not a word" ──
  if (want('R2')) {
    const hits = [];
    for (const s of first.log) {
      for (const [k, m] of Object.entries(s.marks)) if (isWordGate(m.txt)) hits.push(`${k}: "${m.txt}"`);
      if (!s.surfaces && isWordGate(s.body)) hits.push(`<body>: "${s.body}"`);
    }
    if (hits.length) {
      R(route, 'R2', 'FAIL', `first paint is a WORD, not content — ${[...new Set(hits)][0]} `
        + `(seen in ${hits.length} sampled frame(s))`);
    } else {
      R(route, 'R2', 'PASS', 'no loading-word frame during the cold load');
    }
    R(route, 'R2-shape', 'NOT-DRIVEN', 'the "content-shaped" half is not decided here — no '
      + 'app-independent definition of a content-shaped skeleton exists that does not either '
      + 'invent a threshold or contradict the layer-3 no-scroll assertion. Rung 3, by design');
  }

  // ── R3 — RECORDED, never gated ──
  if (want('R3')) {
    const app = reqs.filter((r) => r.end && !/\.(js|css|png|svg|woff2?|ico|map)(\?|$)/.test(r.url));
    let serial = 0;
    for (let i = 0; i < app.length; i++) {
      for (let j = 0; j < app.length; j++) if (i !== j && app[j].end && app[i].start >= app[j].end) { serial++; break; }
    }
    R(route, 'R3', 'RECORDED', `${app.length} non-asset request(s) on route load, ${serial} of them `
      + 'started after another had already finished. NOT gated: this gate cannot tell a legitimately '
      + 'DEPENDENT chain from a serial waterfall, and a version driven by an author declaration '
      + 'passes by under-declaring. Read the chain, do not read a verdict');
  }

  const tok = await probeToken(page);
  const hasFilter = await page.evaluate(() => !!document.querySelector('[data-surface-filter]'));
  const needsFilter = ['R4', 'R5', 'R6'].filter(want).concat(want('R1') ? ['R1-filter'] : []);
  if (needsFilter.length && !hasFilter) {
    for (const p of needsFilter) {
      R(route, p, 'FAIL', 'no [data-surface-filter] on a route that declares this predicate — tag the '
        + 'surface\'s filter control, or drop the predicate from the PRD row');
    }
  }

  // ── R1 — never-blank-what-was-shown ──
  if (want('R1')) {
    // axis A: client-side nav away and back. Threshold-free: the surface may never dip
    // below BOTH what it had and what it ends with — that dip IS the blank frame.
    const other = all.find((e) => e.route !== route);
    if (!other) {
      R(route, 'R1-nav', 'NOT-DRIVEN', 'the nav axis needs a second declared route to leave for — '
        + 'declare one in the PRD Reactivity row');
    } else {
      const before = counts(first.log.slice(-8));
      await clearLog(page);
      await nav(page, other.route);
      await page.waitForTimeout(1200);
      const stamp = await page.evaluate(() => window.__nxR ? window.__nxR.log.length : -1);
      if (stamp <= 0) {
        R(route, 'R1-nav', 'NOT-DRIVEN', `leaving for ${other.route} reloaded the document, so there `
          + 'was no prior frame to preserve — R1\'s nav axis does not apply across a full page load');
      } else {
        await clearLog(page);
        await nav(page, route);
        await page.waitForTimeout(2500);
        const back = counts((await readLog(page)).log);
        const bad = [];
        for (const [k, c] of Object.entries(back)) {
          const floor = Math.min(before[k]?.final ?? c.final, c.final);
          if (c.min < floor) bad.push(`${k}: dipped to ${c.min} descendants (had ${before[k]?.final ?? '?'}, settled at ${c.final})`);
        }
        if (bad.length) R(route, 'R1-nav', 'FAIL', `returning from ${other.route} blanked what was shown — ${bad[0]}`);
        else R(route, 'R1-nav', 'PASS', `returning from ${other.route} never dipped below the prior content`);
      }
    }
    // axis B: filter refetch.
    if (hasFilter && tok) {
      await typeFilter(page, '');
      await page.waitForTimeout(600);
      const pre = counts((await readLog(page)).log.slice(-8));
      await clearLog(page);
      await typeFilter(page, tok);
      await page.waitForTimeout(400);
      const dur = counts((await readLog(page)).log);
      const bad = [];
      for (const [k, c] of Object.entries(dur)) {
        const floor = Math.min(pre[k]?.final ?? c.final, c.final);
        if (c.min < floor) bad.push(`${k}: dipped to ${c.min} (had ${pre[k]?.final ?? '?'}, settled at ${c.final})`);
      }
      if (bad.length) R(route, 'R1-filter', 'FAIL', `filtering on "${tok}" blanked the surface — ${bad[0]}`);
      else R(route, 'R1-filter', 'PASS', `filtering on "${tok}" kept prior content on screen`);
      await typeFilter(page, '');
    }
    R(route, 'R1-write', 'NOT-DRIVEN', 'the post-write refetch axis is not driven — this gate has no '
      + 'app-independent way to perform a write. Rung 3, by design');
  }

  // ── R4 — no inert control ──
  if (want('R4') && hasFilter) {
    const before = await surfaceState(page);
    await typeFilter(page, 'zz' + Math.random().toString(16).slice(2, 10));
    const after = await surfaceState(page);
    if (before && after && before.n === after.n && before.txt === after.txt) {
      R(route, 'R4', 'FAIL', 'a token that can match nothing changed nothing on the surface — the '
        + 'control is inert (no rows change, no explanation appears)');
    } else {
      R(route, 'R4', 'PASS', 'a no-match token visibly changed the surface');
    }
    await typeFilter(page, '');
  }
  if (want('R4')) {
    R(route, 'R4-scope', 'NOT-DRIVEN', 'only the TAGGED filter is driven — a control this build did '
      + 'not tag is invisible to the gate. Under-tagging is the residual hole');
  }

  // ── R5 — in-progress input survives navigation ──
  if (want('R5') && hasFilter) {
    const other = all.find((e) => e.route !== route);
    if (!other) {
      R(route, 'R5', 'NOT-DRIVEN', 'needs a second declared route to navigate to');
    } else {
      const probe = 'nx' + Math.random().toString(16).slice(2, 8);
      await typeFilter(page, probe);
      await nav(page, other.route);
      await page.waitForTimeout(900);
      await nav(page, route);
      await page.waitForTimeout(1500);
      const got = await page.evaluate(() => document.querySelector('[data-surface-filter]')?.value ?? null);
      if (got === probe) R(route, 'R5', 'PASS', `typed "${probe}" survived a round trip to ${other.route}`);
      else R(route, 'R5', 'FAIL', `typed "${probe}" did not survive a round trip to ${other.route} (came back as ${JSON.stringify(got)})`);
      await typeFilter(page, '');
    }
    R(route, 'R5-scope', 'NOT-DRIVEN', 'only the tagged FILTER value is driven — an unsaved form '
      + 'field and the failed-write axis are not. Rung 3, by design');
  }

  // ── R6 — one search idiom app-wide ──
  if (want('R6') && hasFilter && tok) {
    await typeFilter(page, tok);
    const base = await surfaceState(page);
    await typeFilter(page, tok.toUpperCase());
    const upper = await surfaceState(page);
    // Compare the RENDERED state, not just the element count: an empty-state card and a
    // one-row result can carry the same number of descendants, and a count-only compare
    // then reads "case-insensitive" off two surfaces that share nothing but their shape.
    const same = (a, b) => !!a && !!b && a.n === b.n && a.txt === b.txt;
    const caseOk = same(base, upper);
    R(route, 'R6-case', caseOk ? 'PASS' : 'FAIL',
      caseOk ? `"${tok}" and "${tok.toUpperCase()}" return the same surface`
             : `"${tok}" and "${tok.toUpperCase()}" return DIFFERENT surfaces — the search is case-sensitive`);
    const acc = accentise(tok);
    if (!acc) {
      R(route, 'R6-accent', 'NOT-DRIVEN', `"${tok}" carries no accentable letter — no accent probe exists for this surface`);
    } else {
      await typeFilter(page, acc);
      const folded = await surfaceState(page);
      const accOk = same(base, folded);
      R(route, 'R6-accent', accOk ? 'PASS' : 'FAIL',
        accOk ? `"${acc}" folds to "${tok}"` : `"${acc}" does not fold to "${tok}" — the search is accent-sensitive`);
    }
    await typeFilter(page, '');
  }
}

/** The cross-surface arm of R6: one idiom app-wide means every declared surface lands in
 *  the SAME verdict class. Two surfaces disagreeing is the predicate's defect verbatim. */
function r6Consistency() {
  for (const arm of ['R6-case', 'R6-accent']) {
    const seen = rows.filter((r) => r.pred === arm && (r.verdict === 'PASS' || r.verdict === 'FAIL'));
    const verdicts = new Set(seen.map((r) => r.verdict));
    if (seen.length >= 2 && verdicts.size > 1) {
      R('(app-wide)', `${arm}-consistency`, 'FAIL', 'declared surfaces disagree on this arm — '
        + seen.map((r) => `${r.route}=${r.verdict}`).join(', ') + '. R6 is one idiom EVERYWHERE');
    } else if (seen.length >= 2) {
      R('(app-wide)', `${arm}-consistency`, 'PASS', `${seen.length} declared surfaces agree`);
    }
  }
}

// ── main run ──────────────────────────────────────────────────────────────────
async function run(worktree, urlbase) {
  const prd = path.join(worktree, 'docs', 'PRD.md');
  const entries = fs.existsSync(prd) ? parseReactivityRow(fs.readFileSync(prd, 'utf8')) : null;
  if (!entries) {
    console.log('reactivity gate: reasoned GREEN — docs/PRD.md carries no route-bearing '
      + '`Reactivity:` row (nothing to drive; declare one to arm this layer)');
    return 0;
  }
  const { chromium, tried } = await resolveChromium();
  if (!chromium) {
    console.error(`reactivity gate: playwright not resolvable (tried: ${tried.join(', ')})\n  fix: ${PW_INSTALL_HINT}`);
    return 2;
  }
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1512, height: 900 } });
  await ctx.addInitScript(SAMPLER);
  const page = await ctx.newPage();
  try {
    for (const e of entries) await driveRoute(page, urlbase, e, entries);
    r6Consistency();
  } finally {
    await browser.close();
  }

  const fails = rows.filter((r) => r.verdict === 'FAIL');
  const md = ['# REACTIVITY — driven R1–R6 evidence (' + new Date().toISOString().slice(0, 16).replace('T', ' ') + ')',
    '', 'Surfaces: `' + entries.map((e) => `${e.route} ${e.preds.join(',')}`).join(' · ') + '`',
    '', '| route | predicate | verdict | detail |', '|---|---|---|---|',
    ...rows.map((r) => `| \`${r.route}\` | ${r.pred} | ${r.verdict} | ${r.detail} |`),
    '', `${fails.length === 0 ? 'GREEN' : `${fails.length} FAIL row(s)`} — RECORDED and NOT-DRIVEN rows carry no verdict by design.`, ''].join('\n');
  fs.mkdirSync(path.join(worktree, 'docs'), { recursive: true });
  fs.writeFileSync(path.join(worktree, 'docs', 'REACTIVITY.md'), md);

  if (has('--json')) console.log(JSON.stringify({ ok: fails.length === 0, rows }, null, 2));
  else {
    for (const r of rows) {
      const g = r.verdict === 'FAIL' ? '[31m' : r.verdict === 'PASS' ? '[32m' : '[33m';
      console.log(`${g}${r.verdict.padEnd(10)}[0m ${r.route} ${r.pred} — ${r.detail}`);
    }
    console.log(`\nevidence written: docs/REACTIVITY.md`);
  }
  return fails.length === 0 ? 0 : 1;
}

// ── SELF-TEST ─────────────────────────────────────────────────────────────────
// Every gated arm gets a planted-bad fixture and must be SEEN RED on it; the GOOD
// fixture must be green on all of them, or a check that always fires would "pass".
// (`gates-and-ledger.md`: a guard that has never fired is not a guard.)
const APP = (opts) => `<!doctype html><meta charset="utf-8"><title>fx</title>
<body><div id="root"></div><script>
const ROWS = ["Brightline Freight","Cargolane Dispatch","Northwind Depot","Solstice Rail",
              "Verity Haulage","Ashgrove Yard","Beacon Transit","Coastal Lines"];
let q = ${opts.dropInput ? 'null' : '""'};
const norm = (s) => { let t = String(s).${opts.caseSensitive ? '' : 'toLowerCase().'}normalize('NFD')${opts.accentSensitive ? '' : ".replace(/[\\u0300-\\u036f]/g,'')"}; return t; };
const match = (r) => ${opts.inert ? 'true' : 'norm(r).includes(norm(q ?? ""))'};
let painted = false;
function render(blank) {
  const route = location.hash || '#/a';
  const root = document.getElementById('root');
  if (${opts.wordGate ? 'true' : 'false'} && !painted) { root.innerHTML = '<div>Loading…</div>'; painted = true; setTimeout(() => render(false), 260); return; }
  painted = true;
  const list = blank ? [] : ROWS.filter(match);
  root.innerHTML = '<h1>' + route + '</h1>'
    + '<input data-surface-filter value="' + String(q ?? "").replace(/"/g,'&quot;') + '">'
    + '<div data-surface="list">' + (blank ? '' : (list.length ? list.map(r => '<div class="row"><span>' + r + '</span></div>').join('') : '<div class="empty"><span>No matches</span></div>')) + '</div>';
  root.querySelector('[data-surface-filter]').addEventListener('input', (e) => {
    q = e.target.value;
    if (${opts.blankOnFilter ? 'true' : 'false'}) { render(true); setTimeout(() => render(false), 220); } else render(false);
  });
}
addEventListener('hashchange', () => {
  ${opts.dropInput ? 'q = "";' : ''}
  if (${opts.blankOnNav ? 'true' : 'false'}) { render(true); setTimeout(() => render(false), 300); } else render(false);
});
render(false);
</script>`;

const FIXTURES = {
  good:          {},
  'R1-nav':      { blankOnNav: true },
  'R1-filter':   { blankOnFilter: true },
  R2:            { wordGate: true },
  R4:            { inert: true },
  R5:            { dropInput: true },
  'R6-case':     { caseSensitive: true },
  'R6-accent':   { accentSensitive: true },
};

async function selfTest() {
  console.log('SELF-TEST — every gated arm must be SEEN RED on a planted fixture before its green is trusted.\n');
  const server = http.createServer((req, res) => {
    const name = (req.url || '/').split('?')[0].split('#')[0].replace(/^\/|\/$/g, '') || 'good';
    const opts = FIXTURES[name];
    res.writeHead(opts ? 200 : 404, { 'content-type': 'text/html; charset=utf-8' });
    res.end(opts ? APP(opts) : 'no such fixture');
  });
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  const base = `http://127.0.0.1:${server.address().port}`;
  const { chromium, tried } = await resolveChromium();
  if (!chromium) { console.error(`playwright not resolvable (tried: ${tried.join(', ')})\n  fix: ${PW_INSTALL_HINT}`); server.close(); return 2; }

  const drive = async (fixture) => {
    rows.length = 0;
    const browser = await chromium.launch();
    const ctx = await browser.newContext({ viewport: { width: 1512, height: 900 } });
    await ctx.addInitScript(SAMPLER);
    const page = await ctx.newPage();
    const entries = [{ route: `/${fixture}#/a`, preds: ['R1', 'R2', 'R3', 'R4', 'R5', 'R6'] },
                     { route: `/${fixture}#/b`, preds: ['R1', 'R2', 'R4', 'R5', 'R6'] }];
    try { for (const e of entries) await driveRoute(page, base, e, entries); r6Consistency(); }
    finally { await browser.close(); }
    return rows.slice();
  };

  let ok = true;
  const goodRows = await drive('good');
  const goodFails = goodRows.filter((r) => r.verdict === 'FAIL');
  console.log(`  ${goodFails.length === 0 ? 'GREEN ✓' : 'RED   ✗'}  good fixture${goodFails.length ? '   ← A CHECK FIRES ON CLEAN INPUT: ' + goodFails.map((r) => `${r.pred} (${r.detail})`).join(' | ') : ''}`);
  if (goodFails.length) ok = false;

  for (const arm of Object.keys(FIXTURES).filter((k) => k !== 'good')) {
    const got = await drive(arm);
    const red = got.some((r) => r.pred === arm && r.verdict === 'FAIL');
    const other = got.filter((r) => r.verdict === 'FAIL' && r.pred !== arm).map((r) => r.pred);
    console.log(`  ${red ? 'RED  ✓' : 'GREEN ✗'}  ${arm.padEnd(11)}${red ? '' : '   ← FIXTURE DID NOT TRIP THE CHECK'}`
      + (other.length ? `   (collateral: ${[...new Set(other)].join(', ')})` : ''));
    if (!red) ok = false;
  }

  // The STATIC word-gate arm lives in `guard.sh structural` CHECK 4; drive it here so
  // one command proves every arm of this gate, wherever the arm is implemented.
  const stat = await staticSelfTest();
  console.log(`  ${stat ? 'RED  ✓' : 'GREEN ✗'}  R2-static ${stat ? '' : '  ← guard.sh structural did not flag a planted word-gate'}`);
  if (!stat) ok = false;

  server.close();
  console.log(`\nself-test: ${ok ? 'PASS — every gated arm proved it can fail, and none fires on clean input' : 'FAIL — an arm never went red; its green means nothing'}`);
  return ok ? 0 : 2;
}

async function staticSelfTest() {
  const { execFileSync, } = await import('node:child_process');
  const os = await import('node:os');
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'react-static-'));
  fs.mkdirSync(path.join(tmp, 'src'), { recursive: true });
  fs.writeFileSync(path.join(tmp, 'src', 'Bad.tsx'),
    'export function Bad({ c }: { c: unknown }) {\n  if (!c) return <div className="content">Loading…</div>;\n  return <div>ok</div>;\n}\n');
  let out = '';
  try {
    out = execFileSync('bash', [path.join(HERE, 'guard.sh'), 'structural', tmp, path.join(tmp, 'src', 'Bad.tsx')],
      { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (e) { out = (e.stdout || '') + (e.stderr || ''); }
  fs.rmSync(tmp, { recursive: true, force: true });
  return /word-gate/.test(out);
}

// ── entry ─────────────────────────────────────────────────────────────────────
if (has('--self-test')) {
  process.exit(await selfTest());
}
const [wt, url] = argv.filter((a) => !a.startsWith('--'));
if (!wt || !url) {
