#!/usr/bin/env npx tsx
/**
 * 01-hello-nexus.ts -- First API call
 *
 * Demonstrates the basic CRUD cycle: create an agent, list agents,
 * get detail, update, duplicate, and delete. Each step verifies the
 * result with assertions.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/01-hello-nexus.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  assertEqual,
  log,
  onCleanup,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  log("setup", "Starting Hello Nexus example...");

  // ── 1. Create an agent ────────────────────────────────────────────────────

  log("create", "Creating agent...");
  const { data: agent } = await api.post("/agents", {
    firstName: "Hello",
    lastName: "Nexus",
    role: "Getting Started Demo Agent",
    prompt: "You are a demo agent created by the getting-started example script."
  });

  assertDefined(agent.id, "agent.id");
  assertEqual(agent.firstName, "Hello", "firstName");
  assertEqual(agent.lastName, "Nexus", "lastName");
  onCleanup(async () => {
    log("cleanup", `Deleting agent ${agent.id}...`);
    await api.del(`/agents/${agent.id}`);
  });
  success(`Created agent: ${agent.id} (${agent.firstName} ${agent.lastName})`);

  // ── 2. List agents and find ours ──────────────────────────────────────────

  log("list", "Listing agents...");
  const { data: agents, meta } = await api.get<any[]>("/agents?page=1&limit=50");

  assertDefined(meta, "meta should be present on list response");
  assert(meta!.total > 0, "Should have at least 1 agent");
  assert(meta!.page === 1, "Should be page 1");

  const found = agents.find((a: any) => a.id === agent.id);
  assertDefined(found, "Our agent should appear in the list");
  success(`Listed agents: ${agents.length} on page 1 (total: ${meta!.total})`);

  // ── 3. Get agent detail ───────────────────────────────────────────────────

  log("get", "Fetching agent detail...");
  const { data: detail } = await api.get(`/agents/${agent.id}`);

  assertEqual(detail.id, agent.id, "id should match");
  assertEqual(detail.firstName, "Hello", "firstName should match");
  assertEqual(detail.role, "Getting Started Demo Agent", "role should match");
  assert("role" in detail, "Detail should include role field");
  success(`Got agent detail: ${detail.firstName} ${detail.lastName} (role: ${detail.role})`);

  // ── 4. Update agent ──────────────────────────────────────────────────────

  log("update", "Updating agent...");
  const { data: updated } = await api.patch(`/agents/${agent.id}`, {
    firstName: "Updated",
    role: "Modified Demo Agent"
  });

  assertEqual(updated.firstName, "Updated", "firstName should be updated");
  assertEqual(updated.lastName, "Nexus", "lastName should be unchanged");
  assertEqual(updated.role, "Modified Demo Agent", "role should be updated");
  success(`Updated agent: ${updated.firstName} ${updated.lastName}`);

  // Verify the update persists
  const { data: refetched } = await api.get(`/agents/${agent.id}`);
  assertEqual(refetched.firstName, "Updated", "Update should persist on re-fetch");
  success("Update verified via re-fetch");

  // ── 5. Duplicate agent ────────────────────────────────────────────────────

  log("duplicate", "Duplicating agent...");
  const { data: duplicate } = await api.post(`/agents/${agent.id}/duplicate`);

  assertDefined(duplicate.id, "duplicate.id");
  assert(duplicate.id !== agent.id, "Duplicate should have different ID");
  // Duplicate inherits config from source
  assertEqual(duplicate.role, "Modified Demo Agent", "Duplicate should inherit role");
  onCleanup(async () => {
    log("cleanup", `Deleting duplicate ${duplicate.id}...`);
    await api.del(`/agents/${duplicate.id}`);
  });
  success(`Duplicated agent: ${duplicate.id}`);

  // ── 6. Search agents ──────────────────────────────────────────────────────

  log("search", "Searching agents by name...");
  const { data: searchResults } = await api.get<any[]>(`/agents?search=Updated&page=1&limit=10`);
  const searchFound = searchResults.find((a: any) => a.id === agent.id);
  assertDefined(searchFound, "Updated agent should appear in search results");
  success(`Search returned ${searchResults.length} result(s) matching 'Updated'`);

  // ── 7. Delete agents ──────────────────────────────────────────────────────

  log("delete", "Deleting duplicate agent...");
  const { data: deleteResult } = await api.del(`/agents/${duplicate.id}`);
  assertDefined(deleteResult.id, "Delete response should include ID");
  success(`Deleted duplicate: ${deleteResult.id}`);

  // Verify 404 after delete
  log("delete", "Verifying duplicate is gone...");
  try {
    await api.get(`/agents/${duplicate.id}`);
    throw new Error("Should have thrown 404");
  } catch (err: any) {
    assert(err.status === 404 || err.message.includes("404"), "Should get 404 for deleted agent");
    success("Confirmed: deleted agent returns 404");
  }

  // ── 8. Clean up original ──────────────────────────────────────────────────

  log("delete", "Deleting original agent...");
  await api.del(`/agents/${agent.id}`);
  success("Original agent deleted");

  // Clear cleanup since we already deleted manually
  await runCleanup();

  // ── Done ──────────────────────────────────────────────────────────────────

  console.log("\n" + "=".repeat(60));
  success("Hello Nexus complete! All operations verified.");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

