import { createClient } from "../../shared/api-client";
import {
  assert,
  assertContains,
  assertDefined,
  log,
  onCleanup,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Create a fully configured agent
  // ═══════════════════════════════════════════════════════════════════════════

  log("agent", "Creating agent with full configuration...");

  const { data: agent } = await api.post("/agents", {
    firstName: "Email",
    lastName: "Coordinator",
    role: "Email Management Specialist",
    prompt: [
      "You are an email management specialist.",
      "",
      "Your capabilities:",
      "- Send emails on behalf of the user using the Gmail tool",
      "- Summarize email threads",
      "- Draft professional replies",
      "",
      "Guidelines:",
      "- Always confirm the recipient and subject before sending",
      "- Use a professional tone unless instructed otherwise",
      "- Include a signature: 'Sent via Nexus AI Assistant'"
    ].join("\n")
  });

  assertDefined(agent.id, "agent.id");
  onCleanup(async () => {
    log("cleanup", `Deleting agent ${agent.id}...`);
    await api.del(`/agents/${agent.id}`);
  });
