  // Verify the agent detail
  const { data: agentDetail } = await api.get(`/agents/${agent.id}`);
  assert(agentDetail.role != null, "Agent detail should include role");
  success("Agent detail verified with full prompt");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Search marketplace for tools
  // ═══════════════════════════════════════════════════════════════════════════

  log("marketplace", "Searching marketplace for email tools...");

  // Search without query to get all tools (keyword search may return 0 on fresh DB)
  const { data: searchResults } = await api.get("/tools/search?limit=10");

  assertDefined(searchResults.tools, "Search should return tools array");
  if (searchResults.tools.length === 0) {
    log("marketplace", "No tools found in marketplace — skipping tool config steps");
    await runCleanup();
    success("Done (marketplace empty, tool config skipped)");
    return;
  }

  log("marketplace", `Found ${searchResults.tools.length} tool(s):`);
  for (const tool of searchResults.tools.slice(0, 5)) {
    log("marketplace", `  - ${tool.name} (${tool.type ?? "plugin"}) -- ${tool.id}`);
  }

  const selectedTool = searchResults.tools[0];
  success(`Selected tool: ${selectedTool.name} (${selectedTool.id})`);

  // Also search by category to demonstrate faceted search
  log("marketplace", "Browsing by category...");
  const { data: categoryResults } = await api.get("/tools/search?limit=5&offset=0");
  log(
    "marketplace",
    `Category browse: ${categoryResults.tools?.length ?? 0} tools, total: ${categoryResults.total ?? "?"}`
  );
  if (categoryResults.categories) {
    log(
      "marketplace",
      `Available categories: ${categoryResults.categories.map((c: any) => c.name ?? c).join(", ")}`
    );
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Get full tool detail
  // ═══════════════════════════════════════════════════════════════════════════

  log("tool-detail", "Getting full tool detail...");

  const { data: toolDetail } = await api.get(`/tools/${selectedTool.id}`);

  log("tool-detail", `Tool: ${toolDetail.name}`);
  log("tool-detail", `Description: ${toolDetail.description?.slice(0, 100) ?? "N/A"}`);

  if (toolDetail.actions && toolDetail.actions.length > 0) {
    log("tool-detail", `Actions (${toolDetail.actions.length}):`);
    for (const action of toolDetail.actions.slice(0, 5)) {
      const paramCount = action.parameters?.length ?? 0;
      const dynamicCount = action.parameters?.filter((p: any) => p.remoteOptions).length ?? 0;
      log(
        "tool-detail",
        `  - ${action.name} (${action.key}): ${paramCount} params, ${dynamicCount} dynamic`
      );

      // Show parameter details for the first action
      if (action === toolDetail.actions[0] && action.parameters) {
        for (const param of action.parameters.slice(0, 3)) {
          log(
            "tool-detail",
            `      ${param.name} [${param.type}]${param.optional ? " (optional)" : " (required)"}${param.remoteOptions ? " [DYNAMIC]" : ""}`
          );
        }
        if (action.parameters.length > 3) {
          log("tool-detail", `      ... and ${action.parameters.length - 3} more`);
        }
      }
    }
  } else {
    log("tool-detail", "No actions found on this tool");
  }

  success("Tool detail retrieved with actions and parameter schemas");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Check for existing credentials
  // ═══════════════════════════════════════════════════════════════════════════

  log("credentials", "Checking for existing credentials...");

  const { data: credData } = await api.get(`/tools/${selectedTool.id}/credentials`);
  const credentials = credData.credentials ?? credData;

  let selectedCredentialId: string | null = null;

  if (Array.isArray(credentials) && credentials.length > 0) {
    log("credentials", `Found ${credentials.length} credential(s):`);
    for (const cred of credentials) {
      log("credentials", `  - ${cred.name ?? cred.id} (${cred.id})`);
    }
    selectedCredentialId = credentials[0].id;
    success(`Using credential: ${selectedCredentialId}`);
  } else {
    log("credentials", "No credentials found. In production, you would:");
    log("credentials", "  1. Call POST /tools/:toolId/connect with authType 'oauth'");
    log("credentials", "  2. Open the returned authorizationUrl in a browser");
    log("credentials", "  3. Poll GET /tools/connect/:handshakeId/status until complete");
    log("credentials", "  4. Use the resulting credential ID");
    success("Credential check complete (none available)");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: List organization skills
  // ═══════════════════════════════════════════════════════════════════════════

  log("skills", "Listing organization skills...");

  const { data: skills } = await api.get("/tools/skills?limit=20");
  const skillItems = skills.items ?? skills.skills ?? skills;

  log("skills", `Found ${Array.isArray(skillItems) ? skillItems.length : 0} skill(s)`);
  if (Array.isArray(skillItems)) {
    const byType: Record<string, number> = {};
    for (const s of skillItems) {
      byType[s.type] = (byType[s.type] ?? 0) + 1;
    }
    for (const [type, count] of Object.entries(byType)) {
      log("skills", `  ${type}: ${count}`);
    }
  }
  success("Skills list retrieved");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Create PLUGIN tool config on agent
  // ═══════════════════════════════════════════════════════════════════════════

  log("tool-config", "Creating PLUGIN tool config on agent...");

  const firstAction = toolDetail.actions?.[0];
  if (!firstAction) {
    log("tool-config", "No actions available -- skipping tool config creation");
  } else {
    const toolConfigBody: Record<string, any> = {
      label: `${selectedTool.name} - ${firstAction.name}`,
      description: `Configured ${selectedTool.name} action: ${firstAction.name}`,
      type: "PLUGIN",
      agentInputSchema: {
        type: "object",
        properties: {
          input: { type: "string", description: "Input for the tool action" }
        },
        required: ["input"]
      },
      config: {
        toolId: selectedTool.id,
        action: firstAction.key ?? firstAction.id,
        ...(selectedCredentialId ? { toolCredentialId: selectedCredentialId } : {})
      }
    };

    const { data: toolConfig } = await api.post(`/agents/${agent.id}/tools`, toolConfigBody);

    assertDefined(toolConfig.id, "toolConfig.id");
    assert(toolConfig.type === "PLUGIN", "Tool type should be PLUGIN");
    onCleanup(async () => {
      log("cleanup", `Deleting tool config ${toolConfig.id}...`);
      await api.del(`/agents/${agent.id}/tools/${toolConfig.id}`);
    });
    success(`Tool config created: ${toolConfig.id} (${toolConfig.label})`);

    // ═════════════════════════════════════════════════════════════════════════
    // STEP 7: Verify tool config on agent
    // ═════════════════════════════════════════════════════════════════════════

    log("verify", "Verifying tool configuration...");

    // List all tools on agent
    const { data: allTools } = await api.get(`/agents/${agent.id}/tools`);
    assert(Array.isArray(allTools), "Tools response should be array");
    assertContains(
      allTools,
      (t: any) => t.id === toolConfig.id,
      "Tool config should appear in agent tools"
    );
    log("verify", `Agent has ${allTools.length} tool(s) configured`);

    // Get specific tool
    const { data: singleTool } = await api.get(`/agents/${agent.id}/tools/${toolConfig.id}`);
    assert(singleTool.id === toolConfig.id, "Should fetch the correct tool");
    assert(singleTool.type === "PLUGIN", "Type should be PLUGIN");
    success(`Tool verified: ${singleTool.label}`);

    // ═════════════════════════════════════════════════════════════════════════
    // STEP 8: Update tool config
    // ═════════════════════════════════════════════════════════════════════════

    log("update", "Updating tool config label...");

    const { data: updatedTool } = await api.patch(`/agents/${agent.id}/tools/${toolConfig.id}`, {
      label: "Gmail - Send Professional Email"
    });
    assert(updatedTool.label === "Gmail - Send Professional Email", "Label should be updated");
    success("Tool config updated");

    // ═════════════════════════════════════════════════════════════════════════
    // STEP 9: Test the tool (if configured with credential)
    // ═════════════════════════════════════════════════════════════════════════

    if (selectedCredentialId) {
      log("test", "Testing configured tool...");
      try {
        const { data: testResult } = await api.post(
          `/agents/${agent.id}/tools/${toolConfig.id}/test`,
          { input: {} }
        );
        log("test", `Test result: ${testResult.status ?? "completed"}`);
        success("Tool test executed");
      } catch (err: any) {
        log("test", `Test skipped or failed: ${err.message}`);
      }
    } else {
      log("test", "Skipping tool test (no credential configured)");
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  success("Create Agent with Tools complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * 03-end-to-end.ts -- Full deployment pipeline
 *
 * Complete pipeline: create agent, build workflow with multiple nodes and
 * edges, create knowledge collection with documents, create AI task,
 * attach all tools, verify, and clean up.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/03-end-to-end.ts
 */

import { createClient } from "../../shared/api-client";
import { assert, assertDefined, log, onCleanup, runCleanup, success } from "../../shared/helpers";

async function main() {
  const api = createClient();
  const created: { type: string; id: string; label: string }[] = [];

  function track(type: string, id: string, label: string) {
    created.push({ type, id, label });
  }

  log("start", "Beginning end-to-end deployment pipeline...\n");

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 1: Create folder and agent
  // ═══════════════════════════════════════════════════════════════════════════

  log("phase-1", "--- Creating folder and agent ---");

  const { data: folder } = await api.post("/folders", {
    name: "E2E Test Agents"
  });
  track("folder", folder.id, folder.name);
  onCleanup(() => api.del(`/folders/${folder.id}`));
  success(`Folder: ${folder.name} (${folder.id})`);

  const { data: agent } = await api.post("/agents", {
    firstName: "Full",
    lastName: "Stack Bot",
    role: "Multi-capability AI Assistant",
    prompt: [
      "You are a multi-capability AI assistant with access to:",
      "1. An order processing workflow for handling order-related queries",
      "2. A document summarizer for condensing long texts",
      "3. A company knowledge base for policy and procedure questions",
      "",
      "Routing rules:",
      "- Order queries -> use the Order Processor workflow",
      "- 'Summarize this' requests -> use the Summarizer task",
      "- Policy/procedure questions -> search the Knowledge Base first"
    ].join("\n")
  });
  track("agent", agent.id, `${agent.firstName} ${agent.lastName}`);
  onCleanup(() => api.del(`/agents/${agent.id}`));
  success(`Agent: ${agent.firstName} ${agent.lastName} (${agent.id})`);

  // Assign agent to folder
  await api.post("/folders/assign", { agentId: agent.id, folderId: folder.id });
  success("Agent assigned to folder");

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 2: Build workflow
  // ═══════════════════════════════════════════════════════════════════════════

  log("phase-2", "\n--- Building workflow ---");

  const { data: workflow } = await api.post("/workflows", {
    name: "E2E Order Processor",
    description:
      "Receives order queries via agent trigger and processes them through validation and response generation"
  });
  track("workflow", workflow.id, workflow.name);
  onCleanup(() => api.del(`/workflows/${workflow.id}`));
  success(`Workflow: ${workflow.name} (${workflow.id})`);

  // Replace trigger with agentInputTrigger
  log("phase-2", "Setting trigger type...");
  await api.put(`/workflows/${workflow.id}/trigger`, { type: "agentInputTrigger" });
  success("Trigger set to agentInputTrigger");

  // Get workflow to find the trigger node
  const { data: wfDetail } = await api.get(`/workflows/${workflow.id}`);
  const triggerNode = wfDetail.nodes.find(
    (n: any) => n.type === "agentInputTrigger" || n.type === "trigger"
  );
  assertDefined(triggerNode, "Trigger node should exist after replacement");
  log("phase-2", `Trigger node: ${triggerNode.id} (${triggerNode.type})`);

  // Add AI processing node
  log("phase-2", "Adding AI node...");
  const { data: aiNode } = await api.post(`/workflows/${workflow.id}/nodes`, {
    type: "textFormatter",
    data: {
      label: "Validate & Parse Query",
      prompt:
        "Parse the incoming query. Extract: order_id, query_type (status/return/cancel). Return JSON: {order_id, query_type, valid: boolean, error?: string}"
    }
  });
  track("node", aiNode.id, "Validate & Parse Query");
  success(`AI node: ${aiNode.id}`);

  // Add branching node
  log("phase-2", "Adding branching node...");
  const { data: branchNode } = await api.post(`/workflows/${workflow.id}/nodes`, {
    type: "branching",
    data: {
      label: "Route by Query Type"
    }
  });
  track("node", branchNode.id, "Route by Query Type");
  success(`Branching node: ${branchNode.id}`);

  // Create branches on the branching node
  log("phase-2", "Creating branches...");
  const { data: statusBranch } = await api.post(
    `/workflows/${workflow.id}/nodes/${branchNode.id}/branches`,
    { name: "Status Check", description: "Order status inquiry" }
  );
  success(`Branch: ${statusBranch.name ?? statusBranch.id}`);

  const { data: returnBranch } = await api.post(
    `/workflows/${workflow.id}/nodes/${branchNode.id}/branches`,
    { name: "Return Request", description: "Order return or refund" }
  );
  success(`Branch: ${returnBranch.name ?? returnBranch.id}`);

  // List branches to verify
  const { data: branches } = await api.get(
    `/workflows/${workflow.id}/nodes/${branchNode.id}/branches`
  );
  const branchList = Array.isArray(branches) ? branches : (branches.branches ?? []);
  log("phase-2", `Branches on node: ${branchList.length}`);

  // Add output nodes for each branch
  log("phase-2", "Adding output nodes...");
  const { data: statusOutput } = await api.post(`/workflows/${workflow.id}/nodes`, {
    type: "outputNode",
    data: { label: "Status Response" }
  });
  track("node", statusOutput.id, "Status Response");

  const { data: returnOutput } = await api.post(`/workflows/${workflow.id}/nodes`, {
    type: "outputNode",
    data: { label: "Return Response" }
  });
  track("node", returnOutput.id, "Return Response");
  success("Output nodes created");

  // Connect edges: trigger -> ai -> branching -> outputs
  log("phase-2", "Creating edges...");

  const { data: edge1 } = await api.post(`/workflows/${workflow.id}/edges`, {
    source: triggerNode.id,
    target: aiNode.id
  });
  track("edge", edge1.id, "trigger -> ai");

  const { data: edge2 } = await api.post(`/workflows/${workflow.id}/edges`, {
    source: aiNode.id,
    target: branchNode.id
  });
  track("edge", edge2.id, "ai -> branching");

  // Branch edges use sourceHandle to identify which branch
  const statusBranchId = statusBranch.id ?? branchList[0]?.id;
  const returnBranchId = returnBranch.id ?? branchList[1]?.id;

  if (statusBranchId) {
    const { data: edge3 } = await api.post(`/workflows/${workflow.id}/edges`, {
      source: branchNode.id,
      target: statusOutput.id,
      sourceHandle: statusBranchId
    });
    track("edge", edge3.id, "branching -> status output");
  }

  if (returnBranchId) {
    const { data: edge4 } = await api.post(`/workflows/${workflow.id}/edges`, {
      source: branchNode.id,
      target: returnOutput.id,
      sourceHandle: returnBranchId
    });
    track("edge", edge4.id, "branching -> return output");
  }
  success("All edges created");

  // Auto-layout
  log("phase-2", "Applying auto-layout...");
  await api.post(`/workflows/${workflow.id}/layout`);
  success("Layout applied");

  // Get overview
  log("phase-2", "Getting workflow overview...");
  const { data: overview } = await api.get(`/workflows/${workflow.id}/overview`);
  const nodeList = overview.nodes ?? [];
  log("phase-2", `Overview: ${nodeList.length} nodes`);
  for (const node of nodeList) {
    log("phase-2", `  ${node.label ?? node.type} -- config: ${node.configStatus ?? "?"}`);
  }

  // Check available variables on AI node
  log("phase-2", "Checking available variables for AI node...");
  const { data: vars } = await api.get(
    `/workflows/${workflow.id}/nodes/${aiNode.id}/available-variables`
  );
  const varList = Array.isArray(vars) ? vars : (vars.variables ?? []);
  log("phase-2", `Available variables: ${varList.length} group(s)`);

  // Validate
  log("phase-2", "Validating workflow...");
  const { data: validation } = await api.get(`/workflows/${workflow.id}/validate`);
  log("phase-2", `Valid: ${validation.isValid}`);
  if (validation.nodeIssues?.length > 0) {
    for (const issue of validation.nodeIssues.slice(0, 3)) {
      log("phase-2", `  Issue: ${issue.message ?? JSON.stringify(issue)}`);
    }
  }

  // Publish if valid
  if (validation.isValid) {
    log("phase-2", "Publishing workflow...");
    const { data: pub } = await api.post(`/workflows/${workflow.id}/publish`);
    assert(pub.status === "PUBLISHED", "Should be published");
    success("Workflow published");
  } else {
    log("phase-2", "Workflow has issues -- skipping publish (expected in test environment)");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 3: Create knowledge base
  // ═══════════════════════════════════════════════════════════════════════════

  log("phase-3", "\n--- Creating knowledge base ---");

  const { data: collection } = await api.post("/skills/collections", {
    name: `e2e-kb-${Date.now()}`,
    displayName: "E2E Company Knowledge Base"
  });
  track("collection", collection.id, collection.displayName ?? collection.name);
  success(`Collection: ${collection.displayName ?? collection.name} (${collection.id})`);

  // Create multiple documents
  const docs = [
    {
      name: "Refund Policy",
      content:
        "Refund Policy v3.2\n\nAll refunds must be requested within 30 days. Digital products are non-refundable. Physical products must be returned in original packaging. Refunds are processed to the original payment method within 5-10 business days. Expedited refunds (2 business days) available for premium customers.",
      description: "Company refund policy"
    },
    {
      name: "Order Processing SLA",
      content:
        "Order Processing Service Level Agreement\n\nStandard orders: processed within 24 hours\nPriority orders: processed within 4 hours\nBulk orders (>100 items): processed within 48 hours\nInternational orders: additional 24-hour customs processing\n\nEscalation path: L1 Support -> L2 Operations -> L3 Management",
      description: "SLA for order processing times"
    },
    {
      name: "Return Shipping Guide",
      content:
        "Return Shipping Instructions\n\n1. Print the return label from your order confirmation email\n2. Pack items securely in original packaging\n3. Drop off at any authorized shipping location\n4. Keep the tracking receipt\n5. Return tracking is sent via email within 24 hours\n\nNote: Oversized items require a scheduled pickup -- call 1-800-RETURNS",
      description: "Step-by-step return shipping guide"
    }
  ];

  const docIds: string[] = [];
  for (const doc of docs) {
    const { data: created } = await api.post("/documents/text", doc);
    docIds.push(created.id);
    track("document", created.id, doc.name);
    success(`Document: ${doc.name} (${created.id})`);
  }

  // Attach all documents to collection
  log("phase-3", "Attaching documents to collection...");
  await api.post(`/skills/collections/${collection.id}/documents`, {
    documentIds: docIds
  });
  success(`Attached ${docIds.length} documents to collection`);

  // Verify collection detail
  const { data: collDetail } = await api.get(`/skills/collections/${collection.id}`);
  log("phase-3", `Collection detail: ${collDetail.displayName ?? collDetail.name}`);

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 4: Create AI task
  // ═══════════════════════════════════════════════════════════════════════════

  log("phase-4", "\n--- Creating AI task ---");

  let taskId: string | null = null;
  try {
    const { data: task } = await api.post("/skills/tasks", {
      name: "E2E Document Summarizer",
      description:
        "Takes any text and produces a structured summary with key points and action items",
      modelName: "gpt-4o",
      modelProvider: "OPEN_AI",
      generation: {
        expectedInput: "A document, email, or article of any length",
        expectedOutput: "JSON with: { summary: string, keyPoints: string[], actionItems: string[] }"
      }
    });
    track("task", task.id, task.name);
    taskId = task.id;
    success(`Task: ${task.name} (${task.id})`);
  } catch (err: any) {
    log("phase-4", `Task creation skipped: ${err.message} (may need specific model config)`);
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 5: Attach all tools to agent
  // ═══════════════════════════════════════════════════════════════════════════

  log("phase-5", "\n--- Attaching tools to agent ---");

  // 5a: Attach workflow (if published)
  const { data: wfFinal } = await api.get(`/workflows/${workflow.id}`);
  if (wfFinal.status === "PUBLISHED") {
    const { data: wfTool } = await api.post(`/agents/${agent.id}/tools`, {
      label: "Order Processor",
      description: "Processes order status checks and return requests",
      type: "WORKFLOW",
      agentInputSchema: {
        type: "object",
        properties: {
          query: { type: "string", description: "The order-related query to process" }
        },
        required: ["query"]
      },
      config: {
        toolId: workflow.id
      }
    });
    track("tool-config", wfTool.id, "Order Processor (WORKFLOW)");
    success(`Workflow tool: ${wfTool.id}`);
  } else {
    log("phase-5", "Workflow not published -- skipping WORKFLOW tool attachment");
  }

  // 5b: Attach task (if created)
  if (taskId) {
    const { data: taskTool } = await api.post(`/agents/${agent.id}/tools`, {
      label: "Document Summarizer",
      description: "Summarizes documents into structured key points and action items",
      type: "TASK",
      agentInputSchema: {
        type: "object",
        properties: {
          document: { type: "string", description: "The document text to summarize" }
        },
        required: ["document"]
      },
      config: {
        toolId: taskId
      }
    });
    track("tool-config", taskTool.id, "Document Summarizer (TASK)");
    success(`Task tool: ${taskTool.id}`);
  } else {
    log("phase-5", "Task not created -- skipping TASK tool attachment");
  }

  // 5c: Attach collection
  try {
    const { data: collTool } = await api.post(`/agents/${agent.id}/tools/attach-collection`, {
      collectionId: collection.id,
      label: "Company Knowledge Base",
      description: "Searchable knowledge base with company policies, SLAs, and procedures",
      instructions:
        "Always search this knowledge base when users ask about refunds, returns, shipping, or order processing timelines."
    });
    track("tool-config", collTool.id, "Company Knowledge Base (COLLECTION)");
    success(`Collection tool: ${collTool.id}`);
  } catch (err: any) {
    log("phase-5", `Collection attachment skipped: ${err.message}`);
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // PHASE 6: Validate full setup
  // ═══════════════════════════════════════════════════════════════════════════

  log("phase-6", "\n--- Validating full setup ---");

  // Check agent
  const { data: finalAgent } = await api.get(`/agents/${agent.id}`);
  assert(finalAgent.firstName === "Full", "Agent name should be correct");
  success(`Agent: ${finalAgent.firstName} ${finalAgent.lastName}`);

  // Check tools -- data is a flat array
  const { data: finalTools } = await api.get(`/agents/${agent.id}/tools`);
  assert(Array.isArray(finalTools), "Tools should be array");
  log("phase-6", `Agent has ${finalTools.length} tool(s) configured`);

  const toolTypes = finalTools.map((t: any) => t.type);
  log("phase-6", `Tool types: ${toolTypes.join(", ")}`);

  log("phase-6", `Tools (${finalTools.length}):`);
  for (const t of finalTools) {
    log("phase-6", `  - ${t.label} [${t.type}] (${t.id})`);
  }

  // Check folder assignment
  const { data: foldersData } = await api.get("/folders");
  const folderList = foldersData.folders ?? [];
  log("phase-6", `Folders: ${folderList.length}`);

  // Create a version checkpoint
  log("phase-6", "Creating version checkpoint...");
  const { data: checkpoint } = await api.post(`/agents/${agent.id}/versions`, {
    name: "E2E Complete Setup",
    description: "Full deployment with workflow, task, and knowledge base"
  });
  track("version", checkpoint.id, checkpoint.name);
  success(`Checkpoint: ${checkpoint.name}`);

  // ═══════════════════════════════════════════════════════════════════════════
  // Summary
  // ═══════════════════════════════════════════════════════════════════════════

  console.log("\n" + "=".repeat(60));
  log("summary", "Resources created during this run:");
  for (const r of created) {
    log("summary", `  [${r.type}] ${r.label} (${r.id})`);
  }
  console.log("=".repeat(60));

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════

  log("cleanup", "\nCleaning up...");
  await runCleanup();

  console.log("=".repeat(60));
  success("End-to-end pipeline complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  if (err.details) console.error("Details:", JSON.stringify(err.details, null, 2));
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * 04-error-handling.ts -- Error handling patterns
 *
 * Demonstrates all error types: 401 (bad key), 404 (missing resource),
 * 400 (validation), 409 (conflict), and shows try/catch patterns for
 * each. Also shows how to handle 204 No Content responses.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/04-error-handling.ts
 */

import { createClient, NexusApiError } from "../../shared/api-client";
import {
  assert,
  fail,
  log,
  onCleanup,
  runCleanup,
  success} from "../../shared/helpers";

async function main() {
  const api = createClient();

  let passCount = 0;
  let failCount = 0;

  function passed(msg: string) {
    passCount++;
    success(msg);
  }

  function failed(msg: string) {
    failCount++;
    fail(msg);
  }

  log("start", "Error Handling Examples\n");

  // ═══════════════════════════════════════════════════════════════════════════
  // TEST 1: Authentication error (401) with bad API key
  // ═══════════════════════════════════════════════════════════════════════════

  log("test-1", "--- 401 Unauthorized: Invalid API key ---");

  try {
    const badClient = createClient({ apiKey: "nxs_this_is_not_a_real_key_12345" });
    await badClient.get("/agents");
    failed("Should have thrown 401 for bad API key");
  } catch (err: any) {
    if (err instanceof NexusApiError) {
      assert(err.status === 401, "Status should be 401");
      log("test-1", `  Status: ${err.status}`);
      log("test-1", `  Code: ${err.code}`);
      log("test-1", `  Message: ${err.message}`);
      passed("401 error caught correctly via NexusApiError");
    } else if (err.message?.includes("401")) {
      passed("401 error caught (generic Error)");
    } else {
      // API might return a different error if the server rejects differently
      log("test-1", `  Got: ${err.message}`);
      passed("Authentication error caught");
    }
  }

  // Pattern: Type-safe error handler
  log("test-1", "\n  Pattern -- type-safe error handler:");
  log("test-1", `  try {`);
  log("test-1", `    await api.get("/agents");`);
  log("test-1", `  } catch (err) {`);
  log("test-1", `    if (err instanceof NexusApiError && err.status === 401) {`);
  log("test-1", `      console.error("Auth failed:", err.code);`);
  log("test-1", `    }`);
  log("test-1", `  }`);

  // ═══════════════════════════════════════════════════════════════════════════
  // TEST 2: Not Found error (404) with non-existent resource
  // ═══════════════════════════════════════════════════════════════════════════

  log("test-2", "\n--- 404 Not Found: Non-existent resource ---");

  const fakeId = "00000000-0000-0000-0000-000000000000";

  try {
    await api.get(`/agents/${fakeId}`);
    failed("Should have thrown 404 for non-existent agent");
  } catch (err: any) {
    if (err instanceof NexusApiError) {
      assert(err.status === 404, "Status should be 404");
      log("test-2", `  Status: ${err.status}`);
      log("test-2", `  Code: ${err.code}`);
      log("test-2", `  Message: ${err.message}`);
      passed("404 error caught for non-existent agent");
    } else {
      log("test-2", `  Error: ${err.message}`);
      passed("Not found error caught");
    }
  }

  // Also test 404 on nested resources
  try {
    await api.get(`/agents/${fakeId}/tools`);
    // Some APIs return empty array instead of 404 for nested list
    log("test-2", "  (Agent tools list returned success -- API returns empty for missing parent)");
  } catch (err: any) {
    if (err instanceof NexusApiError && err.status === 404) {
      passed("404 on nested resource (agent tools)");
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // TEST 3: Validation error (400) with bad request body
  // ═══════════════════════════════════════════════════════════════════════════

  log("test-3", "\n--- 400 Validation Error: Bad request body ---");

  // 3a: Missing required fields
  try {
    await api.post("/agents", {});
    failed("Should have thrown 400 for empty body");
  } catch (err: any) {
    if (err instanceof NexusApiError) {
      assert(err.status === 400, "Status should be 400");
      log("test-3", `  Status: ${err.status}`);
      log("test-3", `  Code: ${err.code}`);
      log("test-3", `  Message: ${err.message}`);
      if (err.details) {
        log("test-3", `  Details: ${JSON.stringify(err.details).slice(0, 200)}`);
      }
      passed("400 validation error caught for missing required fields");
    } else {
      log("test-3", `  Error: ${err.message}`);
      passed("Validation error caught");
    }
  }

  // 3b: Wrong field types
  try {
    await api.post("/agents", {
      firstName: 12345, // should be string
      lastName: null, // should be string
      role: true // should be string
    });
    failed("Should have thrown 400 for wrong types");
  } catch (err: any) {
    if (err instanceof NexusApiError && err.status === 400) {
      log("test-3", `  Caught type validation: ${err.code}`);
      passed("400 error for wrong field types");
    } else {
      passed("Type validation error caught");
    }
  }

  // 3c: Invalid enum values
  try {
    await api.get("/agents?status=INVALID_STATUS");
    // May succeed with empty results or throw 400
    log("test-3", "  (Invalid status enum passed -- API may ignore unknown query params)");
  } catch (err: any) {
    if (err instanceof NexusApiError && err.status === 400) {
      passed("400 error for invalid enum value");
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // TEST 4: Conflict error (409)
  // ═══════════════════════════════════════════════════════════════════════════

  log("test-4", "\n--- 409 Conflict: Resource state conflicts ---");

  // Create a workflow and try to publish it twice
  const { data: conflictWf } = await api.post("/workflows", {
    name: "Conflict Test Workflow"
  });
  onCleanup(() => api.del(`/workflows/${conflictWf.id}`));

  // Try to publish (may fail if workflow is not complete enough)
  try {
    await api.post(`/workflows/${conflictWf.id}/publish`);
    // If publish succeeded, try again for 409
    try {
      await api.post(`/workflows/${conflictWf.id}/publish`);
      log("test-4", "  Double publish did not throw (API may be idempotent)");
    } catch (err: any) {
      if (err instanceof NexusApiError && err.status === 409) {
        log("test-4", `  Status: ${err.status}`);
        log("test-4", `  Code: ${err.code}`);
        log("test-4", `  Message: ${err.message}`);
        passed("409 conflict caught on double publish");
      } else {
        log("test-4", `  Got ${err.status ?? "error"}: ${err.message}`);
        passed("Conflict-like error caught");
      }
    }
  } catch (err: any) {
    log(
      "test-4",
      `  First publish failed (expected -- incomplete workflow): ${err.message?.slice(0, 100)}`
    );
    log("test-4", "  Attempting edge conflict test instead...");

    // Alternative conflict: duplicate edge
    const { data: edgeWf } = await api.get(`/workflows/${conflictWf.id}`);
    const nodes = edgeWf.nodes ?? [];
    if (nodes.length >= 2) {
      try {
        // Create edge, then try to create the same edge again
        await api.post(`/workflows/${conflictWf.id}/edges`, {
          source: nodes[0].id,
          target: nodes[1].id
        });
        await api.post(`/workflows/${conflictWf.id}/edges`, {
          source: nodes[0].id,
          target: nodes[1].id
        });
        log("test-4", "  Duplicate edge did not throw");
      } catch (dupErr: any) {
        if (dupErr instanceof NexusApiError && (dupErr.status === 409 || dupErr.status === 400)) {
          passed(`${dupErr.status} caught on duplicate edge`);
        }
      }
    } else {
      log("test-4", "  Not enough nodes to test edge conflict");
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // TEST 5: Handling 204 No Content (DELETE responses)
  // ═══════════════════════════════════════════════════════════════════════════

  log("test-5", "\n--- 204 No Content: DELETE responses ---");

  // Create a workflow with a node, then delete the node
  const { data: delTestWf } = await api.post("/workflows", {
    name: "Delete Test Workflow"
  });
  onCleanup(() => api.del(`/workflows/${delTestWf.id}`));

  // Add a node
  const { data: testNode } = await api.post(`/workflows/${delTestWf.id}/nodes`, {
    type: "textFormatter",
    data: { label: "Temporary Node" }
  });
  log("test-5", `  Created node: ${testNode.id}`);

  // Delete the node (returns 204)
  try {
    const result = await api.del(`/workflows/${delTestWf.id}/nodes/${testNode.id}`);
    // The api-client wraps 204 as { success: true, data: {} }
    log("test-5", `  DELETE returned: ${JSON.stringify(result)}`);
    passed("204 No Content handled correctly for node DELETE");
  } catch (err: any) {
    log("test-5", `  DELETE error: ${err.message}`);
    // 204 might be handled differently
    if (err.status === 204 || err.message.includes("204")) {
      passed("204 identified (client may need special handling)");
    } else {
      failed(`Unexpected error on DELETE: ${err.message}`);
    }
  }

  // Verify node is gone
  try {
    await api.get(`/workflows/${delTestWf.id}/nodes/${testNode.id}`);
    failed("Deleted node should return 404");
  } catch (err: any) {
    if (err instanceof NexusApiError && err.status === 404) {
      passed("Deleted node correctly returns 404");
    } else {
      log("test-5", `  Post-delete fetch: ${err.message}`);
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // TEST 6: Generic error wrapper pattern
  // ═══════════════════════════════════════════════════════════════════════════

  log("test-6", "\n--- Generic error wrapper pattern ---");

  /**
   * Reusable wrapper that handles common API errors gracefully.
   * Returns { ok, data?, error? } instead of throwing.
   */
  async function safeApiCall<T>(
    fn: () => Promise<{ data: T }>
  ): Promise<{ ok: true; data: T } | { ok: false; status: number; code: string; message: string }> {
    try {
      const result = await fn();
      return { ok: true, data: result.data };
    } catch (err: any) {
      if (err instanceof NexusApiError) {
        return {
          ok: false,
          status: err.status,
          code: err.code,
          message: err.message
        };
      }
      return {
        ok: false,
        status: 0,
        code: "UNKNOWN",
        message: err.message ?? String(err)
      };
    }
  }

  // Use the safe wrapper
  const result1 = await safeApiCall(() => api.get(`/agents/${fakeId}`));
  assert(!result1.ok, "Should fail for fake ID");
  if (!result1.ok) {
    log(
      "test-6",
      `  safeApiCall returned: ok=false, status=${result1.status}, code=${result1.code}`
    );
    passed("Generic error wrapper works for 404");
  }

  const result2 = await safeApiCall(() => api.get("/agents?page=1&limit=1"));
  assert(result2.ok, "Should succeed for valid request");
  if (result2.ok) {
    log(
      "test-6",
      `  safeApiCall returned: ok=true, data has ${Array.isArray(result2.data) ? result2.data.length : "?"} items`
    );
    passed("Generic error wrapper works for success");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // TEST 7: Retry pattern for transient errors
  // ═══════════════════════════════════════════════════════════════════════════

  log("test-7", "\n--- Retry pattern for transient errors ---");

  async function withRetry<T>(
    fn: () => Promise<T>,
    opts: { maxRetries?: number; delayMs?: number; retryOn?: number[] } = {}
  ): Promise<T> {
    const maxRetries = opts.maxRetries ?? 3;
    const delayMs = opts.delayMs ?? 1000;
    const retryOn = opts.retryOn ?? [500, 502, 503, 504];

    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      try {
        return await fn();
      } catch (err: any) {
        const status = err instanceof NexusApiError ? err.status : 0;
        if (attempt === maxRetries || !retryOn.includes(status)) {
          throw err;
        }
        log("test-7", `  Attempt ${attempt} failed (${status}), retrying in ${delayMs}ms...`);
        await new Promise((r) => setTimeout(r, delayMs));
      }
    }
    throw new Error("Unreachable");
  }

  // Demonstrate the retry pattern (this succeeds on first try)
  const agents = await withRetry(() => api.get("/agents?limit=1"));
  passed("Retry pattern executed successfully");

  // ═══════════════════════════════════════════════════════════════════════════
  // Summary
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  log("summary", `Results: ${passCount} passed, ${failCount} failed`);
  if (failCount > 0) {
    fail("Some tests failed -- see output above");
  } else {
    success("All error handling tests passed!");
  }
  console.log("=".repeat(60));

  if (failCount > 0) process.exit(1);
}

main().catch((err) => {
  console.error("\n\x1b[31mFatal:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * 05-pagination-and-search.ts -- Pagination, search, and filtering
 *
 * Demonstrates paginated listing with page/limit, the meta.hasMore loop
 * pattern, search by name, filter by status, and the offset/limit pattern
 * used by skills endpoints. Creates test data, iterates through pages,
 * and verifies completeness.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/05-pagination-and-search.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  log,
  onCleanup,
  runCleanup,
  success} from "../../shared/helpers";

async function main() {
  const api = createClient();
  const testPrefix = `PagTest-${Date.now().toString(36)}`;

  log("start", "Pagination and Search Examples\n");

  // ═══════════════════════════════════════════════════════════════════════════
  // SETUP: Create test data (7 agents for pagination testing)
  // ═══════════════════════════════════════════════════════════════════════════

  log("setup", "Creating test agents for pagination...");

  const agentIds: string[] = [];
  const agentNames = ["Alice", "Bob", "Charlie", "Diana", "Eve", "Frank", "Grace"];

  for (let i = 0; i < agentNames.length; i++) {
    const name = agentNames[i];
    const status = i < 4 ? "ACTIVE" : "DRAFT"; // First 4 active, last 3 draft concept
    const { data: agent } = await api.post("/agents", {
      firstName: `${testPrefix}-${name}`,
      lastName: "TestAgent",
      role: `Test Agent #${i + 1} for pagination`
    });
    agentIds.push(agent.id);
    onCleanup(() => api.del(`/agents/${agent.id}`));
  }
  success(`Created ${agentIds.length} test agents with prefix: ${testPrefix}`);

  // ═══════════════════════════════════════════════════════════════════════════
  // DEMO 1: Basic pagination with page/limit
  // ═══════════════════════════════════════════════════════════════════════════

  log("demo-1", "\n--- Basic Pagination (page/limit) ---");

  // Fetch page 1 with small limit to force multiple pages
  const { data: page1, meta: meta1 } = await api.get<any[]>(
    `/agents?page=1&limit=3&search=${testPrefix}`
  );
  assertDefined(meta1, "meta should be present");
  log(
    "demo-1",
    `Page 1: ${page1.length} items (total: ${meta1!.total}, hasMore: ${meta1!.hasMore})`
  );
  for (const a of page1) {
    log("demo-1", `  - ${a.firstName} ${a.lastName}`);
  }

  if (meta1!.hasMore) {
    const { data: page2, meta: meta2 } = await api.get<any[]>(
      `/agents?page=2&limit=3&search=${testPrefix}`
    );
    log("demo-1", `Page 2: ${page2.length} items (hasMore: ${meta2!.hasMore})`);
    for (const a of page2) {
      log("demo-1", `  - ${a.firstName} ${a.lastName}`);
    }

    if (meta2!.hasMore) {
      const { data: page3, meta: meta3 } = await api.get<any[]>(
        `/agents?page=3&limit=3&search=${testPrefix}`
      );
      log("demo-1", `Page 3: ${page3.length} items (hasMore: ${meta3!.hasMore})`);
    }
  }
  success("Manual pagination through pages");

  // ═══════════════════════════════════════════════════════════════════════════
  // DEMO 2: Automatic pagination loop using meta.hasMore
  // ═══════════════════════════════════════════════════════════════════════════

  log("demo-2", "\n--- Automatic Pagination Loop ---");

  /**
   * Generic paginator that fetches all items across pages.
   * Works with any paginated endpoint that returns { data, meta: { hasMore } }.
   */
  async function fetchAllPages<T>(
    basePath: string,
    opts: { limit?: number; maxPages?: number } = {}
  ): Promise<{ items: T[]; totalFromMeta: number; pagesTraversed: number }> {
    const limit = opts.limit ?? 10;
    const maxPages = opts.maxPages ?? 50;
    const items: T[] = [];
    let page = 1;
    let hasMore = true;
    let totalFromMeta = 0;

    while (hasMore && page <= maxPages) {
      const separator = basePath.includes("?") ? "&" : "?";
      const { data, meta } = await api.get<T[]>(
        `${basePath}${separator}page=${page}&limit=${limit}`
      );
      items.push(...data);
      hasMore = meta?.hasMore ?? false;
      totalFromMeta = meta?.total ?? items.length;
      page++;
    }

    return { items, totalFromMeta, pagesTraversed: page - 1 };
  }

  const allAgents = await fetchAllPages<any>(`/agents?search=${testPrefix}`, { limit: 2 });

  log("demo-2", `Fetched ${allAgents.items.length} items across ${allAgents.pagesTraversed} pages`);
  log("demo-2", `Meta total: ${allAgents.totalFromMeta}`);
  assert(
    allAgents.items.length >= agentIds.length,
    `Should fetch all ${agentIds.length} test agents (got ${allAgents.items.length})`
  );

  // Verify no duplicates
  const ids = new Set(allAgents.items.map((a) => a.id));
  assert(ids.size === allAgents.items.length, "Should have no duplicate items across pages");
  success(`Auto-pagination: ${allAgents.items.length} unique items, no duplicates`);

  // ═══════════════════════════════════════════════════════════════════════════
  // DEMO 3: Search by name
  // ═══════════════════════════════════════════════════════════════════════════

  log("demo-3", "\n--- Search by Name ---");

  // Search for a specific agent name
  const searchName = `${testPrefix}-Alice`;
  const { data: searchResults, meta: searchMeta } = await api.get<any[]>(
    `/agents?search=${encodeURIComponent(searchName)}&limit=10`
  );

  log(
    "demo-3",
    `Search "${searchName}": ${searchResults.length} result(s) (total: ${searchMeta?.total})`
  );
  for (const a of searchResults) {
    log("demo-3", `  - ${a.firstName} ${a.lastName} (${a.id})`);
  }

  const aliceFound = searchResults.some((a: any) => a.firstName.includes("Alice"));
  assert(aliceFound, "Alice should appear in search results");
  success("Name search works correctly");

  // Partial search
  const { data: partialResults } = await api.get<any[]>(
    `/agents?search=${encodeURIComponent(testPrefix)}&limit=50`
  );
  log("demo-3", `Partial search "${testPrefix}": ${partialResults.length} result(s)`);
  assert(partialResults.length >= agentIds.length, "Partial search should find all test agents");
  success("Partial name search works correctly");

  // ═══════════════════════════════════════════════════════════════════════════
  // DEMO 4: Filter by status
  // ═══════════════════════════════════════════════════════════════════════════

  log("demo-4", "\n--- Filter by Status ---");

  const { data: activeAgents, meta: activeMeta } = await api.get<any[]>(
    `/agents?status=ACTIVE&limit=50`
  );
  log("demo-4", `ACTIVE agents: ${activeAgents.length} (total: ${activeMeta?.total})`);

  const { data: draftAgents, meta: draftMeta } = await api.get<any[]>(
    `/agents?status=DRAFT&limit=50`
  );
  log("demo-4", `DRAFT agents: ${draftAgents.length} (total: ${draftMeta?.total})`);

  // Status filter with search combined
  const { data: activeSearched } = await api.get<any[]>(
    `/agents?status=ACTIVE&search=${encodeURIComponent(testPrefix)}&limit=50`
  );
  log("demo-4", `ACTIVE + search "${testPrefix}": ${activeSearched.length} result(s)`);
  success("Status filtering works (can combine with search)");

  // ═══════════════════════════════════════════════════════════════════════════
  // DEMO 5: Skills endpoints use offset/limit (not page/limit)
  // ═══════════════════════════════════════════════════════════════════════════

  log("demo-5", "\n--- Skills Pagination (offset/limit) ---");

  // Skills endpoints: /skills/workflows, /skills/tasks, /skills/collections, etc.
  // These use offset-based pagination, not page-based

  /**
   * Offset-based paginator for skills endpoints.
   */
  async function fetchAllSkills<T>(
    path: string,
    opts: { limit?: number; maxIterations?: number } = {}
  ): Promise<T[]> {
    const limit = opts.limit ?? 10;
    const maxIterations = opts.maxIterations ?? 20;
    const items: T[] = [];
    let offset = 0;

    for (let i = 0; i < maxIterations; i++) {
      const { data } = await api.get(`${path}?limit=${limit}&offset=${offset}`);
      const resultItems = data.items ?? data;
      if (!Array.isArray(resultItems) || resultItems.length === 0) break;
      items.push(...resultItems);
      if (resultItems.length < limit) break; // Last page
      offset += limit;
    }

    return items;
  }

  // List workflows with offset pagination
  const workflows = await fetchAllSkills<any>("/skills/workflows", { limit: 5 });
  log("demo-5", `Workflows (offset pagination): ${workflows.length} total`);
  for (const wf of workflows.slice(0, 3)) {
    log("demo-5", `  - ${wf.name} (${wf.status ?? "?"})`);
  }
