## Recipe 1: Create Agent + Attach Workflow

Creates an agent, creates a workflow, publishes the workflow, then attaches it as a
WORKFLOW-type tool on the agent.

```typescript
import { createClient } from "../../shared/api-client";
import { assert, onCleanup, runCleanup, log, success } from "../../shared/helpers";

const api = createClient();

try {
  // ── Step 1: Create the agent ──────────────────────────────────────────────
  log("recipe-1", "Creating agent...");
  const { data: agent } = await api.post("/agents", {
    firstName: "Customer",
    lastName: "Support Bot",
    role: "Customer Support Representative",
    prompt:
      "You are a helpful customer support agent. Use the order-lookup workflow when customers ask about their orders."
  });
  onCleanup(() => api.del(`/agents/${agent.id}`));
  success(`Agent created: ${agent.id}`);

  // ── Step 2: Create the workflow ───────────────────────────────────────────
  log("recipe-1", "Creating workflow...");
  const { data: workflow } = await api.post("/workflows", {
    name: "Order Lookup",
    description: "Looks up order status by order ID and returns tracking info"
  });
  onCleanup(() => api.del(`/workflows/${workflow.id}`));
  success(`Workflow created: ${workflow.id} (status: ${workflow.status})`);

  // ── Step 3: Replace trigger with agentTrigger ─────────────────────────────
  // New workflows start with a selectTrigger placeholder; replace it
  log("recipe-1", "Setting trigger to agentTrigger...");
  const { data: triggerResult } = await api.put(`/workflows/${workflow.id}/trigger`, {
    type: "agentTrigger"
  });
  const triggerNode =
    triggerResult.nodes?.find((n: any) => n.type === "agentTrigger") ?? triggerResult;
  success(`Trigger set: ${triggerNode.id ?? triggerNode.type}`);

  // ── Step 4: Publish the workflow ──────────────────────────────────────────
  log("recipe-1", "Publishing workflow...");
  const { data: published } = await api.post(`/workflows/${workflow.id}/publish`);
  assert(published.status === "PUBLISHED", "Workflow should be PUBLISHED");
  success(`Workflow published`);

  // ── Step 5: Attach workflow to agent as tool ──────────────────────────────
  log("recipe-1", "Attaching workflow to agent...");
  const { data: toolConfig } = await api.post(`/agents/${agent.id}/tools`, {
    label: "Look Up Order",
    description: "Finds order details and tracking information",
    type: "WORKFLOW",
    workflowId: workflow.id
  });
  success(`Tool attached: ${toolConfig.id} (type: ${toolConfig.type})`);

  // ── Step 6: Verify ────────────────────────────────────────────────────────
  log("recipe-1", "Verifying setup...");
  const { data: tools } = await api.get(`/agents/${agent.id}/tools`);
  const attached = tools.find((t: any) => t.id === toolConfig.id);
  assert(attached != null, "Tool config should appear in agent tools list");
  assert(attached.type === "WORKFLOW", "Tool type should be WORKFLOW");
  success("Recipe 1 complete: Agent has workflow tool attached");
} finally {
  await runCleanup();
}
```

