## Recipe 3: Build Workflow + Connect Plugin + Test + Publish + Attach to Agent

Searches the marketplace for a tool, retrieves credentials, creates a workflow with
a plugin node, configures it, tests it, publishes, and attaches to an agent.

```typescript
import { createClient } from "../../shared/api-client";
import { assert, onCleanup, runCleanup, log, success, pollUntil } from "../../shared/helpers";

const api = createClient();

try {
  // ── Step 1: Search marketplace for Google Sheets ──────────────────────────
  log("recipe-3", "Searching marketplace...");
  const { data: searchResults } = await api.get("/tools/search?q=google+sheets&limit=5");
  assert(searchResults.tools.length > 0, "Should find Google Sheets in marketplace");
  const sheetsTool = searchResults.tools[0];
  success(`Found: ${sheetsTool.name} (${sheetsTool.id})`);

  // ── Step 2: Get tool detail with actions ──────────────────────────────────
  log("recipe-3", "Getting tool detail...");
  const { data: toolDetail } = await api.get(`/tools/${sheetsTool.id}`);
  log("recipe-3", `Tool has ${toolDetail.actions?.length ?? 0} actions`);
  const addRowAction = toolDetail.actions?.find(
    (a: any) => a.name?.toLowerCase().includes("add") || a.key?.toLowerCase().includes("add-row")
  );
  success(`Target action: ${addRowAction?.name ?? "first available"}`);

  // ── Step 3: Check for existing credentials ────────────────────────────────
  log("recipe-3", "Checking credentials...");
  const { data: creds } = await api.get(`/tools/${sheetsTool.id}/credentials`);
  if (creds.credentials?.length > 0) {
    success(`Found ${creds.credentials.length} existing credential(s)`);
  } else {
    log("recipe-3", "No credentials found -- tool connection required before plugin use");
  }
  const credentialId = creds.credentials?.[0]?.id;

  // ── Step 4: Create workflow ───────────────────────────────────────────────
  log("recipe-3", "Creating workflow...");
  const { data: workflow } = await api.post("/workflows", {
    name: "Log to Google Sheets",
    description: "Receives data from agent trigger and appends a row to a Google Sheet"
  });
  onCleanup(() => api.del(`/workflows/${workflow.id}`));
  success(`Workflow created: ${workflow.id}`);

  // ── Step 5: Replace trigger ───────────────────────────────────────────────
  log("recipe-3", "Setting trigger...");
  await api.put(`/workflows/${workflow.id}/trigger`, { type: "agentTrigger" });
  success("Trigger set to agentTrigger");

  // ── Step 6: Scaffold plugin node + edge in one batch call ──────────────────
  log("recipe-3", "Batch-scaffolding plugin node and edge...");
  const { data: batch } = await api.post(`/workflows/${workflow.id}/batch`, {
    nodes: [
      {
        ref: "add_sheet_row",
        type: "plugin",
        data: {
          label: "add_sheet_row",
          appName: toolDetail.appName ?? "google_sheets",
          actionId: addRowAction?.key ?? addRowAction?.id,
          ...(credentialId ? { toolCredentialId: credentialId } : {})
        }
      }
    ],
    edges: [
      { source: "@trigger", target: "@add_sheet_row" }
    ]
  });
  const pluginNode = batch.nodes[0];
  success(`Batch scaffold complete: plugin node ${pluginNode.id}`);

  // ── Step 7: Validate workflow ─────────────────────────────────────────────
  log("recipe-3", "Validating workflow...");
  const { data: validation } = await api.get(`/workflows/${workflow.id}/validate`);
  log("recipe-3", `Validation: ${validation.isValid ? "VALID" : "ISSUES FOUND"}`);
  if (validation.nodeIssues?.length > 0) {
    for (const issue of validation.nodeIssues) {
      log("recipe-3", `  Node ${issue.nodeId}: ${issue.message}`);
    }
  }

  // ── Step 8: Publish (if valid) ────────────────────────────────────────────
  if (validation.isValid) {
    log("recipe-3", "Publishing workflow...");
    const { data: published } = await api.post(`/workflows/${workflow.id}/publish`);
    assert(published.status === "PUBLISHED", "Should be published");
    success("Workflow published");

    // ── Step 9: Create agent and attach ───────────────────────────────────
    log("recipe-3", "Creating agent and attaching workflow...");
    const { data: agent } = await api.post("/agents", {
      firstName: "Data",
      lastName: "Logger",
      role: "Data Entry Assistant"
    });
    onCleanup(() => api.del(`/agents/${agent.id}`));

    const { data: tool } = await api.post(`/agents/${agent.id}/tools`, {
      label: "Log to Sheets",
      type: "WORKFLOW",
      workflowId: workflow.id
    });
    success(`Workflow attached to agent: tool ${tool.id}`);
  } else {
    log(
      "recipe-3",
      "Skipping publish -- workflow has validation issues (expected if no credentials)"
    );
  }

  success("Recipe 3 complete");
} finally {
  await runCleanup();
}
```

