  log("step-4", `Description: ${detail.description ?? "(none)"}`);
  log("step-4", `Document Count: ${detail.documentCount}`);
  log("step-4", `Is Active: ${detail.isActive}`);
  log("step-4", `k (retrieval depth): ${detail.k}`);
  log("step-4", `Reranker: ${detail.reranker ?? "(none)"}`);
  log("step-4", `Precise Responses: ${detail.preciseResponses}`);
  log("step-4", `Include Metadata: ${detail.includeMetadata}`);

  // Document count should reflect the attached documents
  assert(
    detail.documentCount >= docIds.length,
    `Document count should be >= ${docIds.length}, got ${detail.documentCount}`
  );
  success("Collection detail verified");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: List collections with search
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-5", "\n--- Listing collections ---");

  // List all collections
  const { data: listAll } = await api.get("/skills/collections?limit=50&offset=0");
  const allItems = listAll.items ?? listAll;
  log(
    "step-5",
    `Total collections: ${listAll.total ?? (Array.isArray(allItems) ? allItems.length : "?")}`
  );

  // Search for our collection
  const { data: searchResult } = await api.get(
    `/skills/collections?search=support-kb&limit=10&offset=0`
  );
  const searchItems = searchResult.items ?? searchResult;

  if (Array.isArray(searchItems)) {
    log("step-5", `Search results for 'support-kb': ${searchItems.length}`);
    assertContains(
      searchItems,
      (c: any) => c.id === collection.id,
      "Our collection should appear in search results"
    );
    success("Collection found via search");
  } else {
    log("step-5", `Search returned: ${JSON.stringify(searchResult).slice(0, 200)}`);
    success("Search completed");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Demonstrate collection settings and their effects
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-6", "\n--- Collection settings guide ---");

  log("step-6", "Settings explanation:");
  log("step-6", `  k=${detail.k} -- retrieves ${detail.k} chunks per search query`);
  log(
    "step-6",
    `  preciseResponses=${detail.preciseResponses} -- ${detail.preciseResponses ? "answers restricted to exact document content" : "allows paraphrasing and inference"}`
  );
  log(
    "step-6",
    `  includeMetadata=${detail.includeMetadata} -- ${detail.includeMetadata ? "document metadata included in results" : "only content returned"}`
  );
  log(
    "step-6",
    `  reranker=${detail.reranker ?? "none"} -- ${detail.reranker ? "results reranked for relevance" : "default ranking"}`
  );

  success("Settings explained");

  // ═══════════════════════════════════════════════════════════════════════════
  // Summary
  // ═══════════════════════════════════════════════════════════════════════════

  console.log("\n" + "=".repeat(60));
  log("summary", "Collection created and populated:");
  log("summary", `  Collection: ${detail.displayName ?? detail.name} (${detail.id})`);
  log("summary", `  Documents: ${detail.documentCount}`);
  log("summary", `  Settings: k=${detail.k}, precise=${detail.preciseResponses}`);
  log("summary", "\nThis collection can now be attached to an agent as a COLLECTION tool.");
  log("summary", "See nexus-agent-management skill for agent tool attachment.");
  success("Create collections example complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * 03-google-sheets-import.ts -- Import data from Google Sheets
 *
 * Demonstrates: POST /documents/google-sheet, GET /documents/:id
 * Shows: Google Sheets import, folder/sheet structure, status tracking
 *
 * NOTE: Requires a connected Google Sheets OAuth credential in the org.
 * If no Google credential is available, the script logs a warning and exits
 * gracefully. Connect Google Sheets via the tool-connection flow first.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/03-google-sheets-import.ts
 */

import { createClient, NexusApiError } from "../../shared/api-client";
import { assert, assertDefined, log, runCleanup, success } from "../../shared/helpers";

async function main() {
  const api = createClient();

  log("start", "Google Sheets Import Example\n");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Attempt Google Sheets import
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-1", "--- Importing Google Sheet ---");
  log("step-1", "NOTE: This requires a Google Sheets OAuth credential.");
  log("step-1", "If no credential exists, the API will return a 400 error.\n");

  // Replace with a real Google Sheets URL for testing
  const sheetUrl =
    "https://docs.google.com/spreadsheets/d/1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgVE2upms/edit";

  try {
    const { data: result } = await api.post("/documents/google-sheet", {
      name: `Import Test ${Date.now()}`,
      url: sheetUrl,
      metadata: {
        hasHeaderRow: true
      }
    });

    // ═════════════════════════════════════════════════════════════════════════
    // STEP 2: Inspect the folder + sheet structure
    // ═════════════════════════════════════════════════════════════════════════

    log("step-2", "\n--- Inspecting import result ---");

    assertDefined(result.folder, "result should have a folder");
    assertDefined(result.sheets, "result should have sheets array");

    const folder = result.folder;
    log("step-2", `Folder: ${folder.name} (${folder.id})`);
    log("step-2", `  Type: ${folder.type}`);
    log("step-2", `  Status: ${folder.status}`);

    log("step-2", `\nSheets (${result.sheets.length}):`);
    for (const sheet of result.sheets) {
      log("step-2", `  - ${sheet.name} (${sheet.id})`);
      log("step-2", `    Type: ${sheet.type}, Status: ${sheet.status}`);
    }

    log("step-2", `\nMessage: ${result.message}`);
    success("Google Sheet imported successfully");

    // ═════════════════════════════════════════════════════════════════════════
    // STEP 3: Get folder detail to track processing
    // ═════════════════════════════════════════════════════════════════════════

    log("step-3", "\n--- Getting folder detail ---");

    const { data: folderDetail } = await api.get(`/documents/${folder.id}`);

    log("step-3", `Name: ${folderDetail.name}`);
    log("step-3", `Is Folder: ${folderDetail.isFolder}`);
    log("step-3", `Status: ${folderDetail.status}`);
    log("step-3", `Total Children: ${folderDetail.totalChildren}`);
    log("step-3", `Ready Children: ${folderDetail.readyChildren}`);
    log("step-3", `Processing Children: ${folderDetail.processingChildren}`);
    log("step-3", `Processing Progress: ${folderDetail.processingProgress}%`);

    assert(folderDetail.isFolder === true, "Google Sheet import creates a folder");
    success("Folder detail retrieved");

    // ═════════════════════════════════════════════════════════════════════════
    // STEP 4: Get individual sheet detail
    // ═════════════════════════════════════════════════════════════════════════

    if (result.sheets.length > 0) {
      log("step-4", "\n--- Getting individual sheet detail ---");

      const firstSheet = result.sheets[0];
      const { data: sheetDetail } = await api.get(`/documents/${firstSheet.id}`);

      log("step-4", `Sheet: ${sheetDetail.name}`);
      log("step-4", `Type: ${sheetDetail.type}`);
      log("step-4", `Status: ${sheetDetail.status}`);
      log("step-4", `Size: ${sheetDetail.size ?? "unknown"} bytes`);

      success("Sheet detail retrieved");
    }

    // Summary
    console.log("\n" + "=".repeat(60));
    log("summary", "Google Sheet import complete:");
    log("summary", `  Folder: ${folder.name} (${folder.id})`);
    log("summary", `  Sheets: ${result.sheets.length}`);
    log("summary", "\nThese documents can be attached to a collection.");
    success("Google Sheets import example complete!");
    console.log("=".repeat(60));
  } catch (err: any) {
    // ═════════════════════════════════════════════════════════════════════════
    // Handle missing Google credential gracefully
    // ═════════════════════════════════════════════════════════════════════════

    if (err instanceof NexusApiError && err.status === 400) {
      console.log("\n" + "=".repeat(60));
      log("warning", "Google Sheets import requires an OAuth credential.");
      log("warning", "");
      log("warning", "To connect Google Sheets:");
      log("warning", "  1. Use the nexus-tool-connection skill to search for Google Sheets");
      log("warning", "  2. Connect via OAuth: POST /tools/:toolId/connect");
      log("warning", "  3. Complete the OAuth flow in the browser");
      log("warning", "  4. Retry this import");
      log("warning", "");
      log("warning", `Error: ${err.message}`);
      console.log("=".repeat(60));
      console.log("\nSkipping -- no Google Sheets credential available.");
    } else if (err instanceof NexusApiError && err.status === 401) {
      console.error("\nAuthentication failed. Check your NEXUS_API_KEY.");
      process.exit(1);
    } else {
      throw err;
    }
  }
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * 04-website-crawl.ts -- Import website content via crawling
 *
 * Demonstrates: POST /documents/website, GET /documents/:id, polling
 * Shows: website crawl creation, processing status tracking,
 *   polling until completion or timeout
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/04-website-crawl.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assertDefined,
  log,
  pollUntil,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  log("start", "Website Crawl Example\n");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Start a website crawl
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-1", "--- Starting website crawl ---");

  const { data: doc } = await api.post("/documents/website", {
    url: "https://example.com",
    mode: "crawl",
    config: {
      max_pages: 5,
      max_depth: 2
    },
    description: "Example.com documentation import"
  });

  assertDefined(doc.id, "doc.id");
  log("step-1", `Document ID: ${doc.id}`);
  log("step-1", `Name: ${doc.name}`);
  log("step-1", `Type: ${doc.type}`);
  log("step-1", `Status: ${doc.status}`);
  success("Website crawl initiated");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Get initial document detail
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-2", "\n--- Getting document detail ---");

  const { data: detail } = await api.get(`/documents/${doc.id}`);

  log("step-2", `Name: ${detail.name}`);
  log("step-2", `Type: ${detail.type}`);
  log("step-2", `Source Type: ${detail.sourceType ?? "(none)"}`);
  log("step-2", `Is Folder: ${detail.isFolder}`);
  log("step-2", `Status: ${detail.status}`);
  log("step-2", `Source URL: ${detail.sourceUrl ?? "(none)"}`);
  log("step-2", `Total Children: ${detail.totalChildren}`);
  log("step-2", `Ready Children: ${detail.readyChildren}`);
  log("step-2", `Processing Children: ${detail.processingChildren}`);
  log("step-2", `Pending Children: ${detail.pendingChildren}`);
  log("step-2", `Error Children: ${detail.errorChildren}`);
  log("step-2", `Processing Progress: ${detail.processingProgress}%`);
  success("Document detail retrieved");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Poll for processing completion
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-3", "\n--- Polling for processing completion ---");
  log("step-3", "Website crawls are async. Polling every 3s with 60s timeout.\n");

  try {
    const completed = await pollUntil(
      async () => {
        const { data: current } = await api.get(`/documents/${doc.id}`);
        return current;
      },
      (current: any) => {
        const status = current.status;
        const progress = current.processingProgress ?? 0;
        log(
          "step-3",
          `  Status: ${status} | Progress: ${progress}% | Ready: ${current.readyChildren ?? 0}/${current.totalChildren ?? 0}`
        );
        return status === "READY" || status === "ERROR";
      },
      {
        intervalMs: 3000,
        timeoutMs: 60000,
        label: "website-crawl"
      }
    );

    log("step-3", `\nFinal status: ${completed.status}`);
    log("step-3", `Total pages: ${completed.totalChildren ?? 0}`);
    log("step-3", `Ready pages: ${completed.readyChildren ?? 0}`);
    log("step-3", `Error pages: ${completed.errorChildren ?? 0}`);

    if (completed.status === "READY") {
      success("Website crawl completed successfully");
    } else {
      log("step-3", "Website crawl completed with errors");
    }
  } catch (err: any) {
    if (err.message?.includes("timed out")) {
      log("step-3", "\nCrawl still processing after timeout (this is normal for large sites)");
      log("step-3", "In production, use longer timeouts or check back later.");

      // Show current progress
      const { data: current } = await api.get(`/documents/${doc.id}`);
      log("step-3", `Current progress: ${current.processingProgress ?? 0}%`);
      log("step-3", `Ready: ${current.readyChildren ?? 0} / ${current.totalChildren ?? 0}`);
      success("Timeout is expected for demo -- crawl continues in background");
    } else {
      throw err;
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Demonstrate sitemap mode (alternative to crawl)
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-4", "\n--- Sitemap mode (alternative) ---");
  log("step-4", "Sitemap mode parses a site's sitemap.xml to discover pages.");
  log("step-4", "This is faster and more predictable than crawling.\n");

  log("step-4", "Usage:");
  log("step-4", "  POST /documents/website");
  log("step-4", '  { "url": "https://docs.example.com", "mode": "sitemap" }');
  log("step-4", "");
  log("step-4", "The sitemap mode:");
  log("step-4", "  1. Fetches the sitemap.xml from the URL");
  log("step-4", "  2. Extracts all page URLs from the sitemap");
  log("step-4", "  3. Creates a child document for each page");
  log("step-4", "  4. Processes all pages in parallel");

  success("Sitemap mode documented");

  // ═══════════════════════════════════════════════════════════════════════════
  // Summary
  // ═══════════════════════════════════════════════════════════════════════════

  console.log("\n" + "=".repeat(60));
  log("summary", "Website crawl example complete:");
  log("summary", `  Document: ${doc.name} (${doc.id})`);
  log("summary", `  Mode: crawl (max_pages: 5, max_depth: 2)`);
  log("summary", "");
  log("summary", "Polling pattern:");
  log("summary", "  1. POST /documents/website to start the crawl");
  log("summary", "  2. GET /documents/:id to check status");
  log("summary", '  3. Poll until status is "READY" or "ERROR"');
  log("summary", "  4. Check readyChildren/totalChildren for page counts");
  log("summary", "");
  log("summary", "Once complete, attach the document to a collection.");
  success("Website crawl example complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Generate an agent prompt via the Prompt Assistant, then create the agent.
 *
 * Demonstrates the full agent-mode flow:
 *   1. Start a conversation with the prompt assistant
 *   2. Answer the assistant's questions
 *   3. Wait for prompt generation (polling)
 *   4. Create an agent and apply the generated prompt
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  dashboardUrl,
  log,
  onCleanup,
  pollUntil,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // Step 1 — Start the conversation
  // ═══════════════════════════════════════════════════════════════════════════
  log("step-1", "Starting prompt assistant conversation (agent mode)...");

  const { data: turn1 } = await api.post<{
    threadId: string;
    response: string;
    status: string;
  }>("/prompt-assistant/chat", {
    message:
      "I want to create a customer support agent for an e-commerce company called ShopMax " +
      "that sells fashion, electronics, and home goods.",
    mode: "agent"
  });

  assertDefined(turn1.threadId, "threadId");
  assert(turn1.status === "in_progress", `Expected in_progress, got ${turn1.status}`);

  const threadId = turn1.threadId;
  log("step-1", `Thread: ${threadId}`);
  log("step-1", `Assistant: ${turn1.response.substring(0, 150)}...`);
  success("Conversation started");

  // Register cleanup
  onCleanup(async () => {
    log("cleanup", `Deleting thread ${threadId}...`);
    await api.del(`/prompt-assistant/threads/${threadId}`);
  });

  // ═══════════════════════════════════════════════════════════════════════════
  // Step 2 — Provide comprehensive details to minimize back-and-forth
  // ═══════════════════════════════════════════════════════════════════════════
  log("step-2", "Providing agent details...");

  const { data: turn2 } = await api.post<{
    threadId: string;
    response: string;
    status: string;
  }>("/prompt-assistant/chat", {
    message:
      "Here is all the info: " +
      "Name: Sophie Chen. Role: Senior Customer Support Specialist. " +
      "Organization: ShopMax - online marketplace for fashion, electronics, home goods. " +
      "Objective: Help customers with order tracking, returns, refunds, product questions, complaints. " +
      "Type: Question answerer. " +
      "Boundaries: Never process payments, never share other customer data, escalate legal threats. " +
      "Tone: Friendly, professional, empathetic. " +
      "Format: Bullet points for instructions, concise under 200 words. " +
      "Behavior: Greet by name, apologize for inconvenience, offer alternatives for out-of-stock. " +
      "For order tracking she needs order number or email. She accesses ShopMax order system and CRM. " +
      "When unsure she says she'll check with the team and follow up within 24 hours.",
    mode: "agent",
    threadId
  });

  log("step-2", `Status: ${turn2.status}`);
  log("step-2", `Assistant: ${turn2.response.substring(0, 150)}...`);

  // ═══════════════════════════════════════════════════════════════════════════
  // Step 3 — Keep chatting until status becomes "generating"
  // ═══════════════════════════════════════════════════════════════════════════
  let currentStatus = turn2.status;

  if (currentStatus === "in_progress") {
    log("step-3", "Assistant asked follow-up questions. Pushing for generation...");

    const { data: turn3 } = await api.post<{
      threadId: string;
      response: string;
      status: string;
    }>("/prompt-assistant/chat", {
      message: "That is all the information I have. Please generate the prompt now.",
      mode: "agent",
      threadId
    });

    currentStatus = turn3.status;
    log("step-3", `Status: ${currentStatus}`);
  }

  // If still in_progress, try once more
  if (currentStatus === "in_progress") {
    log("step-3", "Trying once more to trigger generation...");

    const { data: turn4 } = await api.post<{
      threadId: string;
      response: string;
      status: string;
    }>("/prompt-assistant/chat", {
      message: "I confirm all information is complete. Create the prompt now.",
      mode: "agent",
      threadId
    });

    currentStatus = turn4.status;
    log("step-3", `Status: ${currentStatus}`);
  }

  assert(
    currentStatus === "generating",
    `Expected generating status, got ${currentStatus}. The assistant may need more info.`
  );
  success("Prompt generation started");

  // ═══════════════════════════════════════════════════════════════════════════
  // Step 4 — Poll for completion
  // ═══════════════════════════════════════════════════════════════════════════
  log("step-4", "Polling for prompt generation completion...");

  interface ThreadResponse {
    threadId: string;
    status: string;
    messages: Array<{ role: string; content: string; timestamp: string }>;
    promptResult?: {
      prompt: string;
      name: string;
      description: string;
      agentFields?: {
        explanation?: string;
        objective?: string;
        tone?: string;
        format?: string[];
        behaviour?: string[];
      };
    };
  }

  const threadResult = await pollUntil<{ data: ThreadResponse }>(
    () => api.get<ThreadResponse>(`/prompt-assistant/threads/${threadId}`),
    (r) => r.data.status === "completed" || r.data.status === "failed",
    { intervalMs: 10_000, timeoutMs: 300_000, label: "prompt-generation" }
  );

  const thread = threadResult.data;
  assert(thread.status === "completed", `Generation failed with status: ${thread.status}`);
  assertDefined(thread.promptResult, "promptResult");

  const pr = thread.promptResult!;
  log("step-4", `Name: ${pr.name}`);
  log("step-4", `Description: ${pr.description}`);
  log("step-4", `Prompt length: ${pr.prompt.length} chars`);
  if (pr.agentFields) {
    log("step-4", `Agent fields: ${Object.keys(pr.agentFields).join(", ")}`);
  }
  success("Prompt generated");

  // ═══════════════════════════════════════════════════════════════════════════
  // Step 5 — Create the agent and apply the prompt
  // ═══════════════════════════════════════════════════════════════════════════
  log("step-5", "Creating agent...");

  const { data: agent } = await api.post<{ id: string; firstName: string; lastName: string }>(
    "/agents",
    {
      firstName: "Sophie",
      lastName: "Chen",
      role: "Senior Customer Support Specialist",
      shortBio: "ShopMax customer support specialist"
    }
  );

  assertDefined(agent.id, "agent.id");
  log("step-5", `Agent created: ${agent.id}`);

  onCleanup(async () => {
    log("cleanup", `Deleting agent ${agent.id}...`);
    await api.del(`/agents/${agent.id}`);
  });

  // Build markdown prompt from agent fields
  const af = pr.agentFields ?? {};
  const promptParts: string[] = [];
  if (af.explanation) promptParts.push(af.explanation);
  if (af.objective) promptParts.push("## Objective\n" + af.objective);
  if (af.tone) promptParts.push("## Tone\n" + af.tone);
  if (af.format) promptParts.push("## Format\n" + af.format.map((f) => "- " + f).join("\n"));
  if (af.behaviour)
    promptParts.push("## Behaviour\n" + af.behaviour.map((b) => "- " + b).join("\n"));
  const prompt = promptParts.join("\n\n");

  log("step-5", "Updating agent with generated prompt...");

  const { data: updated } = await api.patch<{ id: string; prompt: string | null }>(
    `/agents/${agent.id}`,
    { prompt }
  );

  assert((updated.prompt?.length ?? 0) > 0, "Prompt should be non-empty after update");
  log("step-5", `Prompt applied: ${updated.prompt!.length} chars`);
  log("step-5", `View in dashboard: ${dashboardUrl(`/app/my-agents/${agent.id}/tabs/prompt`)}`);
  success("Agent created and prompt applied");

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════
  await runCleanup();
  success("All resources cleaned up");
}

main().catch(async (err) => {
  console.error("\n\x1b[31m✗ FAILED:\x1b[0m", err.message);
  await runCleanup();
  process.exit(1);
});

#!/usr/bin/env npx tsx
/**
 * Generate an AI task prompt via the Prompt Assistant, then create the task.
 *
 * Demonstrates the full ai-task-mode flow:
 *   1. Start a conversation with the prompt assistant
 *   2. Answer the assistant's questions
 *   3. Wait for prompt generation (polling)
 *   4. Create an AI task with the generated prompt and schemas
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  dashboardUrl,
  log,
  onCleanup,
  pollUntil,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // Step 1 — Start the conversation with comprehensive details
  // ═══════════════════════════════════════════════════════════════════════════
  log("step-1", "Starting prompt assistant conversation (ai-task mode)...");

  const { data: turn1 } = await api.post<{
    threadId: string;
    response: string;
    status: string;
  }>("/prompt-assistant/chat", {
    message:
      "I want to create an AI task that takes a customer review text as input " +
      "and outputs a JSON with: summary (1-2 sentences), sentiment (positive/negative/neutral), " +
      "key_topics array (from fixed set: pricing, quality, shipping, customer_service, usability, features), " +
      "and urgency_score (1-5 where 1=minor feedback, 5=customer threatening to leave). " +
      "The task is for our product team to prioritize feedback. Reviews come in English and French, " +
      "output should always be English.",
    mode: "ai-task"
  });

  assertDefined(turn1.threadId, "threadId");
  assert(turn1.status === "in_progress", `Expected in_progress, got ${turn1.status}`);

  const threadId = turn1.threadId;
  log("step-1", `Thread: ${threadId}`);
  log("step-1", `Assistant: ${turn1.response.substring(0, 150)}...`);
  success("Conversation started");

  onCleanup(async () => {
    log("cleanup", `Deleting thread ${threadId}...`);
    await api.del(`/prompt-assistant/threads/${threadId}`);
  });

  // ═══════════════════════════════════════════════════════════════════════════
  // Step 2 — Answer follow-up questions and push for generation
  // ═══════════════════════════════════════════════════════════════════════════
  log("step-2", "Providing additional details and requesting generation...");

  let currentStatus = turn1.status;
  let attempts = 0;

  while (currentStatus === "in_progress" && attempts < 5) {
    attempts++;
    const messages = [
      "The urgency scale: 1=minor feedback, 2=improvement suggestion, 3=notable complaint, " +
        "4=serious issue affecting usage, 5=customer threatening to leave or requesting refund. " +
        "Output always in English regardless of input language. That is everything I have.",
      "I confirm all information is complete. Please generate the task specification now.",
      "Create the task now. All details have been provided.",
      "Generate it now please.",
      "Yes, proceed."
    ];

    const { data: turn } = await api.post<{
      threadId: string;
      response: string;
      status: string;
    }>("/prompt-assistant/chat", {
      message: messages[Math.min(attempts - 1, messages.length - 1)],
      mode: "ai-task",
      threadId
    });

    currentStatus = turn.status;
    log("step-2", `Attempt ${attempts}: status=${currentStatus}`);
    log("step-2", `Response: ${turn.response.substring(0, 120)}...`);

    if (currentStatus === "generating") break;
  }

  assert(
    currentStatus === "generating",
    `Expected generating status after ${attempts} attempts, got ${currentStatus}`
  );
  success("Prompt generation started");

  // ═══════════════════════════════════════════════════════════════════════════
  // Step 3 — Poll for completion
  // ═══════════════════════════════════════════════════════════════════════════
  log("step-3", "Polling for prompt generation completion...");

  interface ThreadResponse {
    threadId: string;
    status: string;
    messages: Array<{ role: string; content: string; timestamp: string }>;
    promptResult?: {
      prompt: string;
      name: string;
      description: string;
      input?: { type: string; content?: unknown };
      output?: { type: string; content?: Record<string, unknown> };
    };
  }

  const threadResult = await pollUntil<{ data: ThreadResponse }>(
    () => api.get<ThreadResponse>(`/prompt-assistant/threads/${threadId}`),
    (r) => r.data.status === "completed" || r.data.status === "failed",
    { intervalMs: 10_000, timeoutMs: 300_000, label: "prompt-generation" }
  );

  const thread = threadResult.data;
  assert(thread.status === "completed", `Generation failed with status: ${thread.status}`);
  assertDefined(thread.promptResult, "promptResult");

  const pr = thread.promptResult!;
  log("step-3", `Name: ${pr.name}`);
  log("step-3", `Description: ${pr.description?.substring(0, 100)}...`);
  log("step-3", `Prompt length: ${pr.prompt.length} chars`);
  log("step-3", `Input type: ${pr.input?.type ?? "not specified"}`);
  log("step-3", `Output type: ${pr.output?.type ?? "not specified"}`);
  success("Prompt generated");

  // ═══════════════════════════════════════════════════════════════════════════
  // Step 4 — Create the AI task with the generated prompt
  // ═══════════════════════════════════════════════════════════════════════════
  log("step-4", "Creating AI task...");

  const inputType = pr.input?.type ?? "text";
  const outputType = pr.output?.type ?? "json";
  const outputSchema = pr.output?.content;

  const taskBody: Record<string, unknown> = {
    name: pr.name,
    description: pr.description,
    modelName: "claude-sonnet-4-6",
    modelProvider: "ANTHROPIC",
    temperature: 0.3,
    inputFormat: inputType,
    outputFormat: outputType,
    prompt: pr.prompt,
    generation: {
      expectedInput:
        typeof pr.input?.content === "string"
          ? pr.input.content
          : "Customer review text in English or French"
    }
  };

  // Add output schema if we got one
  if (outputType === "json" && outputSchema) {
    (taskBody.generation as Record<string, unknown>).jsonOutputSchema = outputSchema;
  }

  const { data: task } = await api.post<{
    id: string;
    name: string;
    category: string;
  }>("/skills/tasks", taskBody);

  assertDefined(task.id, "task.id");
  log("step-4", `Task created: ${task.id}`);
  log("step-4", `Name: ${task.name}`);
  log("step-4", `Category: ${task.category}`);
  log("step-4", `View in dashboard: ${dashboardUrl(`/app/my-ai-tasks/${task.id}`)}`);

  onCleanup(async () => {
    log(
      "cleanup",
      `Note: AI task ${task.id} was created but not deleted (no delete endpoint for tasks)`
    );
  });

  success("AI task created with generated prompt");

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════
  await runCleanup();
  success("Done");
}

main().catch(async (err) => {
  console.error("\n\x1b[31m✗ FAILED:\x1b[0m", err.message);
  await runCleanup();
  process.exit(1);
});

