#!/usr/bin/env npx tsx
/**
 * 01-browse-skills.ts -- Browse available organization skills
 *
 * Demonstrates: GET /skills/workflows, GET /skills/tasks,
 *   GET /skills/collections, GET /skills/document-templates,
 *   GET /skills/external-tools
 *
 * Shows: listing each skill type, search filtering, getting detail
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/01-browse-skills.ts
 */

import { createClient } from "../../shared/api-client";
import { log, success } from "../../shared/helpers";

async function main() {
  const api = createClient();

  log("start", "Browse Skills Example\n");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: List workflows
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-1", "--- Workflows ---");

  const { data: wfData } = await api.get("/skills/workflows?limit=10&offset=0");
  const workflows = wfData.items ?? wfData;
  const wfTotal = wfData.total ?? (Array.isArray(workflows) ? workflows.length : 0);

  log("step-1", `Total workflows: ${wfTotal}`);
  if (Array.isArray(workflows)) {
    for (const wf of workflows.slice(0, 5)) {
      log("step-1", `  - ${wf.name} [${wf.status}] trigger: ${wf.triggerType ?? "none"}`);
    }
    if (workflows.length > 5) {
      log("step-1", `  ... and ${workflows.length - 5} more`);
    }
  }

  // Get detail of first workflow (if any)
  if (Array.isArray(workflows) && workflows.length > 0) {
    const firstWf = workflows[0];
    const { data: wfDetail } = await api.get(`/skills/workflows/${firstWf.id}`);
    log("step-1", `\n  Detail for "${wfDetail.name}":`);
    log("step-1", `    ID: ${wfDetail.id}`);
    log("step-1", `    Status: ${wfDetail.status}`);
    log("step-1", `    Trigger: ${wfDetail.triggerType ?? "none"}`);
    log("step-1", `    Input Schema: ${wfDetail.agentInputSchema ? "defined" : "none"}`);
    success("Workflow detail retrieved");
  } else {
    log("step-1", "  No workflows found (create some via nexus-workflow-builder)");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: List AI tasks
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-2", "\n--- AI Tasks ---");

  const { data: taskData } = await api.get("/skills/tasks?limit=10&offset=0");
  const tasks = taskData.items ?? taskData;
  const taskTotal = taskData.total ?? (Array.isArray(tasks) ? tasks.length : 0);

  log("step-2", `Total tasks: ${taskTotal}`);
  if (Array.isArray(tasks)) {
    for (const task of tasks.slice(0, 5)) {
      log("step-2", `  - ${task.name} [${task.category}] ${task.modelProvider}/${task.modelName}`);
      log("step-2", `    Input: ${task.inputFormat} -> Output: ${task.outputFormat}`);
    }
  }

  // Get detail of first task (if any)
  if (Array.isArray(tasks) && tasks.length > 0) {
    const firstTask = tasks[0];
    const { data: taskDetail } = await api.get(`/skills/tasks/${firstTask.id}`);
    log("step-2", `\n  Detail for "${taskDetail.name}":`);
    log("step-2", `    ID: ${taskDetail.id}`);
    log("step-2", `    Category: ${taskDetail.category}`);
    log("step-2", `    Model: ${taskDetail.modelProvider}/${taskDetail.modelName}`);
    log("step-2", `    Input Format: ${taskDetail.inputFormat}`);
    log("step-2", `    Output Format: ${taskDetail.outputFormat}`);
    log("step-2", `    Input Schema: ${taskDetail.jsonInputSchema ? "defined" : "none"}`);
    log("step-2", `    Output Schema: ${taskDetail.jsonOutputSchema ? "defined" : "none"}`);
    log("step-2", `    Multimodal: ${taskDetail.multimodal}`);
    success("Task detail retrieved");
  } else {
    log("step-2", "  No tasks found (create some via 02-create-ai-task.ts)");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: List collections
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-3", "\n--- Collections ---");

  const { data: collData } = await api.get("/skills/collections?limit=10&offset=0");
  const collections = collData.items ?? collData;
  const collTotal = collData.total ?? (Array.isArray(collections) ? collections.length : 0);

  log("step-3", `Total collections: ${collTotal}`);
  if (Array.isArray(collections)) {
    for (const coll of collections.slice(0, 5)) {
      log(
        "step-3",
        `  - ${coll.displayName ?? coll.name} (${coll.documentCount} docs) active: ${coll.isActive}`
      );
    }
  }

  // Get detail of first collection (if any)
  if (Array.isArray(collections) && collections.length > 0) {
    const firstColl = collections[0];
    const { data: collDetail } = await api.get(`/skills/collections/${firstColl.id}`);
    log("step-3", `\n  Detail for "${collDetail.displayName ?? collDetail.name}":`);
    log("step-3", `    ID: ${collDetail.id}`);
    log("step-3", `    Documents: ${collDetail.documentCount}`);
    log("step-3", `    k: ${collDetail.k}`);
    log("step-3", `    Precise Responses: ${collDetail.preciseResponses}`);
    log("step-3", `    Reranker: ${collDetail.reranker ?? "none"}`);
    success("Collection detail retrieved");
  } else {
    log("step-3", "  No collections found (create some via nexus-knowledge-base)");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: List document templates
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-4", "\n--- Document Templates ---");

  const { data: tmplData } = await api.get("/skills/document-templates?limit=10&offset=0");
  const templates = tmplData.items ?? tmplData;
  const tmplTotal = tmplData.total ?? (Array.isArray(templates) ? templates.length : 0);

  log("step-4", `Total templates: ${tmplTotal}`);
  if (Array.isArray(templates)) {
    for (const tmpl of templates.slice(0, 5)) {
      log("step-4", `  - ${tmpl.name} [${tmpl.type}] status: ${tmpl.status}`);
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: List external tools
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-5", "\n--- External Tools ---");

  const { data: toolData } = await api.get("/skills/external-tools?limit=10&offset=0");
  const externalTools = toolData.items ?? toolData;
  const toolTotal = toolData.total ?? (Array.isArray(externalTools) ? externalTools.length : 0);

  log("step-5", `Total external tools: ${toolTotal}`);
  if (Array.isArray(externalTools)) {
    for (const tool of externalTools.slice(0, 5)) {
      log(
        "step-5",
        `  - ${tool.name} [${tool.authType}] actions: ${tool.actionsCount} status: ${tool.status}`
      );
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Demonstrate search filtering
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-6", "\n--- Search Filtering ---");

  // Search tasks by name
  const { data: searchTasks } = await api.get("/skills/tasks?search=summar&limit=5&offset=0");
  const searchItems = searchTasks.items ?? searchTasks;
  log("step-6", `Tasks matching 'summar': ${Array.isArray(searchItems) ? searchItems.length : 0}`);

  // Search workflows
  const { data: searchWf } = await api.get("/skills/workflows?search=order&limit=5&offset=0");
