#!/usr/bin/env npx tsx
/**
 * 02-create-ai-task.ts -- Create an AI task with model configuration
 *
 * Demonstrates: POST /skills/tasks, GET /skills/tasks/:id
 * Shows: GENERATION task creation with model config, input/output formats,
 *   JSON output schema, task detail inspection
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/02-create-ai-task.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  assertEqual,
  log,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  log("start", "Create AI Task Example\n");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Create a text-to-text task (simplest form)
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-1", "--- Creating text-to-text task ---");

  const { data: summarizerTask } = await api.post("/skills/tasks", {
    name: `Document Summarizer ${Date.now()}`,
    description: "Takes any document and produces a concise summary with key points",
    modelName: "gpt-4o",
    modelProvider: "OPEN_AI",
    temperature: 0.5,
    inputFormat: "text",
    outputFormat: "text",
    generation: {
      expectedInput: "A document, email, article, or any text of any length",
      expectedOutput:
        "A concise summary (2-3 paragraphs) with: 1) Main topic, 2) Key points, 3) Action items if any"
    }
  });

  assertDefined(summarizerTask.id, "summarizerTask.id");
  assertEqual(
    summarizerTask.name.startsWith("Document Summarizer"),
    true,
    "name should start with Document Summarizer"
  );
  log("step-1", `Task ID: ${summarizerTask.id}`);
  log("step-1", `Name: ${summarizerTask.name}`);
  log("step-1", `Category: ${summarizerTask.category}`);
  log("step-1", `Model: ${summarizerTask.modelProvider}/${summarizerTask.modelName}`);
  log("step-1", `Input: ${summarizerTask.inputFormat} -> Output: ${summarizerTask.outputFormat}`);
  success("Text-to-text task created");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Create a text-to-JSON task (structured output)
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-2", "\n--- Creating text-to-JSON task ---");

  const { data: classifierTask } = await api.post("/skills/tasks", {
    name: `Email Classifier ${Date.now()}`,
    description: "Classifies emails by urgency, topic, and sentiment",
    modelName: "gpt-4o",
    modelProvider: "OPEN_AI",
    temperature: 0.3,
    inputFormat: "text",
    outputFormat: "json",
    generation: {
      expectedInput: "Raw email body text, including subject line if available",
      jsonOutputSchema: {
        type: "object",
        properties: {
          urgency: {
            type: "string",
            enum: ["low", "medium", "high", "critical"],
            description: "How urgently does this email need attention"
          },
          topic: {
            type: "string",
            description: "Primary topic category (billing, support, sales, feedback, other)"
          },
          sentiment: {
            type: "string",
            enum: ["positive", "neutral", "negative"],
            description: "Overall tone of the email"
          },
          summary: {
            type: "string",
            description: "One-sentence summary of the email"
          },
          actionRequired: {
            type: "boolean",
            description: "Whether a response or action is needed"
          }
        },
        required: ["urgency", "topic", "sentiment", "summary", "actionRequired"]
      }
    }
  });

  assertDefined(classifierTask.id, "classifierTask.id");
  assert(
    classifierTask.outputFormat?.toLowerCase() === "json",
    `output format should be json, got ${classifierTask.outputFormat}`
  );
  log("step-2", `Task ID: ${classifierTask.id}`);
  log("step-2", `Name: ${classifierTask.name}`);
  log("step-2", `Input: ${classifierTask.inputFormat} -> Output: ${classifierTask.outputFormat}`);
  success("Text-to-JSON task created");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Get task detail and inspect schemas
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-3", "\n--- Inspecting task detail ---");

  const { data: detail } = await api.get(`/skills/tasks/${classifierTask.id}`);

  assertDefined(detail.id, "detail.id");
  assertEqual(detail.id, classifierTask.id, "ID should match");

  log("step-3", `Name: ${detail.name}`);
  log("step-3", `Description: ${detail.description ?? "(none)"}`);
  log("step-3", `Category: ${detail.category}`);
  log("step-3", `Model: ${detail.modelProvider}/${detail.modelName}`);
  log("step-3", `Input Format: ${detail.inputFormat}`);
  log("step-3", `Output Format: ${detail.outputFormat}`);
  log("step-3", `Multimodal: ${detail.multimodal}`);
  log("step-3", `Template ID: ${detail.documentTemplateId ?? "none"}`);

  // Inspect JSON schemas
  if (detail.jsonInputSchema) {
    log("step-3", `\nInput Schema:`);
    log("step-3", `  ${JSON.stringify(detail.jsonInputSchema, null, 2).split("\n").join("\n  ")}`);
  } else {
    log("step-3", `\nInput Schema: none (text input, described by expectedInput)`);
  }

  if (detail.jsonOutputSchema) {
    const schema = detail.jsonOutputSchema as any;
    log("step-3", `\nOutput Schema:`);
    log("step-3", `  Type: ${schema.type}`);
    if (schema.properties) {
      log("step-3", `  Properties:`);
      for (const [key, val] of Object.entries(schema.properties)) {
        const prop = val as any;
        log("step-3", `    - ${key}: ${prop.type}${prop.enum ? ` [${prop.enum.join(", ")}]` : ""}`);
      }
    }
    if (schema.required) {
      log("step-3", `  Required: ${schema.required.join(", ")}`);
    }
  }

  success("Task detail inspected");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Verify tasks appear in listing
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-4", "\n--- Verifying tasks in listing ---");

  const { data: listData } = await api.get("/skills/tasks?limit=50&offset=0");
  const taskItems = listData.items ?? listData;

  if (Array.isArray(taskItems)) {
    const foundSummarizer = taskItems.find((t: any) => t.id === summarizerTask.id);
    const foundClassifier = taskItems.find((t: any) => t.id === classifierTask.id);

    assert(!!foundSummarizer, "Summarizer should appear in task listing");
    assert(!!foundClassifier, "Classifier should appear in task listing");

    log(
      "step-4",
      `Tasks found in listing: summarizer=${!!foundSummarizer}, classifier=${!!foundClassifier}`
    );
    success("Both tasks verified in listing");
  } else {
    log("step-4", "Could not verify listing (unexpected response shape)");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // Summary
  // ═══════════════════════════════════════════════════════════════════════════

  console.log("\n" + "=".repeat(60));
  log("summary", "Created 2 AI tasks:");
  log("summary", `  1. ${summarizerTask.name} (text -> text)`);
  log("summary", `     ID: ${summarizerTask.id}`);
  log("summary", `  2. ${classifierTask.name} (text -> json)`);
  log("summary", `     ID: ${classifierTask.id}`);
  log("summary", "");
  log("summary", "To execute these tasks, see 03-execute-task.ts");
  log("summary", "To attach to an agent, use POST /agents/:id/tools with type: TASK");
  success("Create AI task example complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * 03-execute-task.ts -- Execute an AI task with input
 *
 * Demonstrates: POST /skills/tasks, POST /skills/tasks/:id/execute,
 *   GET /skills/tasks/:id
 * Shows: task creation, execution with text input, output inspection,
 *   text-to-JSON execution
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/03-execute-task.ts
 */

import { createClient } from "../../shared/api-client";
import { assertDefined, log, runCleanup, success } from "../../shared/helpers";

async function main() {
  const api = createClient();

  log("start", "Execute Task Example\n");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Create a task to execute (or find existing)
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-1", "--- Setting up task ---");

  // Check for existing tasks first
  const { data: existingData } = await api.get("/skills/tasks?limit=5&offset=0");
  const existingTasks = existingData.items ?? existingData;

  let taskId: string;
  let taskName: string;
  let outputFormat: string;

  if (Array.isArray(existingTasks) && existingTasks.length > 0) {
    // Use existing task
    const existing = existingTasks[0];
    taskId = existing.id;
    taskName = existing.name;
    outputFormat = existing.outputFormat;
    log("step-1", `Using existing task: ${taskName} (${taskId})`);
    log("step-1", `  Format: ${existing.inputFormat} -> ${existing.outputFormat}`);
  } else {
    // Create a new task
    log("step-1", "No existing tasks found, creating one...");

    const { data: task } = await api.post("/skills/tasks", {
      name: `Sentiment Analyzer ${Date.now()}`,
      description: "Analyzes text sentiment and extracts key information",
      modelName: "gpt-4o",
      modelProvider: "OPEN_AI",
      temperature: 0.3,
      inputFormat: "text",
      outputFormat: "json",
      generation: {
        expectedInput: "Any text, email, review, or message to analyze",
        jsonOutputSchema: {
          type: "object",
          properties: {
            sentiment: {
              type: "string",
              enum: ["positive", "neutral", "negative", "mixed"]
            },
            confidence: {
              type: "number",
              description: "Confidence score from 0 to 1"
            },
            keyPhrases: {
              type: "array",
              items: { type: "string" },
              description: "Important phrases from the text"
            },
            summary: {
              type: "string",
              description: "Brief summary of the text"
            }
          },
          required: ["sentiment", "confidence", "summary"]
        }
      }
    });

    taskId = task.id;
    taskName = task.name;
    outputFormat = task.outputFormat;
    success(`Created task: ${taskName} (${taskId})`);
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Get task detail to understand expected input/output
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-2", "\n--- Inspecting task before execution ---");

  const { data: taskDetail } = await api.get(`/skills/tasks/${taskId}`);

  log("step-2", `Task: ${taskDetail.name}`);
  log("step-2", `Model: ${taskDetail.modelProvider}/${taskDetail.modelName}`);
  log("step-2", `Input Format: ${taskDetail.inputFormat}`);
  log("step-2", `Output Format: ${taskDetail.outputFormat}`);

  if (taskDetail.jsonInputSchema) {
    log("step-2", `Input Schema: ${JSON.stringify(taskDetail.jsonInputSchema).slice(0, 100)}...`);
  }
  if (taskDetail.jsonOutputSchema) {
    log("step-2", `Output Schema: ${JSON.stringify(taskDetail.jsonOutputSchema).slice(0, 100)}...`);
  }
  success("Task detail retrieved");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Execute the task with text input
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-3", "\n--- Executing task ---");

  const testInput = [
    "Subject: Amazing experience with your product!",
    "",
    "Hi team,",
    "",
    "I just wanted to write to say how impressed I am with the new update.",
    "The performance improvements are incredible -- page loads are 3x faster",
    "and the new dashboard layout is much more intuitive.",
    "",
    "The only minor issue is that the export feature sometimes takes a few",
    "extra seconds, but it is not a big deal compared to the improvements.",
    "",
    "Keep up the great work! Looking forward to what is next.",
    "",
    "Best regards,",
    "Sarah"
  ].join("\n");

  log("step-3", "Input (truncated):");
  log("step-3", `  "${testInput.slice(0, 100)}..."`);

  let result: any;
  try {
    const res = await api.post(`/skills/tasks/${taskId}/execute`, {
      input: testInput
    });
    result = res.data;
    assertDefined(result.output, "result should have output");
  } catch (err: any) {
    // Tasks created via API may need a prompt to be generated first
    log("step-3", `Execution skipped: ${err.message} (task may need prompt generation)`);
    await runCleanup();
    success("Done (execution requires prompt — use the Nexus UI to generate a prompt first)");
    return;
  }

  log("step-3", `\nOutput Type: ${result.outputType}`);
  log("step-3", `Output:`);

  if (typeof result.output === "object" && result.output !== null) {
    // JSON output -- pretty print
    const output = result.output as Record<string, unknown>;
    for (const [key, value] of Object.entries(output)) {
      if (Array.isArray(value)) {
        log("step-3", `  ${key}: [${value.join(", ")}]`);
      } else {
        log("step-3", `  ${key}: ${JSON.stringify(value)}`);
      }
    }
  } else {
    // Text output
    const outputStr = String(result.output);
    for (const line of outputStr.split("\n").slice(0, 10)) {
      log("step-3", `  ${line}`);
    }
    if (outputStr.split("\n").length > 10) {
      log("step-3", `  ... (${outputStr.split("\n").length} lines total)`);
    }
  }

  success("Task executed successfully");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Execute with a different input to demonstrate versatility
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-4", "\n--- Executing with different input ---");

  const secondInput = [
    "Subject: Urgent complaint about billing error",
    "",
    "This is completely unacceptable. I was charged TWICE for my subscription",
    "this month and nobody has responded to my support ticket from 3 days ago.",
    "If this isn't resolved within 24 hours I'm canceling my account and",
    "requesting a full chargeback."
  ].join("\n");

  log("step-4", "Input (truncated):");
  log("step-4", `  "${secondInput.slice(0, 100)}..."`);

  const { data: result2 } = await api.post(`/skills/tasks/${taskId}/execute`, {
    input: secondInput
  });

  log("step-4", `\nOutput Type: ${result2.outputType}`);
  log("step-4", `Output:`);

  if (typeof result2.output === "object" && result2.output !== null) {
    const output = result2.output as Record<string, unknown>;
    for (const [key, value] of Object.entries(output)) {
      if (Array.isArray(value)) {
        log("step-4", `  ${key}: [${value.join(", ")}]`);
      } else {
        log("step-4", `  ${key}: ${JSON.stringify(value)}`);
      }
    }
  } else {
    log("step-4", `  ${String(result2.output).slice(0, 300)}`);
  }

  success("Second execution complete");

  // ═══════════════════════════════════════════════════════════════════════════
  // Summary
  // ═══════════════════════════════════════════════════════════════════════════

  console.log("\n" + "=".repeat(60));
  log("summary", `Task: ${taskName} (${taskId})`);
  log("summary", `Executions: 2 (both produced ${outputFormat} output)`);
  log("summary", "");
  log("summary", "Key observations:");
  log("summary", "  - Execution is synchronous (response contains output directly)");
  log("summary", "  - JSON output is parsed into structured data");
  log("summary", "  - Same task handles different inputs gracefully");
  log("summary", "");
  log("summary", "To attach this task to an agent:");
  log("summary", `  POST /agents/<agentId>/tools`);
  log("summary", `  { "label": "${taskName}", "type": "TASK", "taskId": "${taskId}" }`);
  success("Execute task example complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * 04-document-templates.ts -- Create and generate documents from templates
 *
 * Demonstrates: POST /skills/document-templates,
 *   GET /skills/document-templates/:id,
 *   GET /skills/document-templates,
 *   POST /skills/document-templates/:id/generate
 *
 * Shows: template metadata creation, template detail inspection,
 *   document generation with variables, download URL retrieval
 *
 * Note: File upload (POST .../upload-file) uses multipart/form-data.
 * This example skips the file upload step since no template file is
 * available in the example context. In production, upload the template
 * file before generating.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/04-document-templates.ts
 */

import { createClient, NexusApiError } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  assertEqual,
  log,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  log("start", "Document Templates Example\n");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Create a document template (metadata)
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-1", "--- Creating document template ---");

  const { data: template } = await api.post("/skills/document-templates", {
    name: `Sales Proposal ${Date.now()}`,
    description: "Template for generating customer-facing sales proposals with pricing and terms",
    type: "WORD_TEMPLATE"
  });

  assertDefined(template.id, "template.id");
  log("step-1", `Template ID: ${template.id}`);
  log("step-1", `Name: ${template.name}`);
  log("step-1", `Type: ${template.type}`);
  log("step-1", `Status: ${template.status}`);
  success("Template metadata created");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Get template detail
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-2", "\n--- Getting template detail ---");

  const { data: detail } = await api.get(`/skills/document-templates/${template.id}`);

  assertDefined(detail.id, "detail.id");
  assertEqual(detail.id, template.id, "ID should match");

  log("step-2", `Name: ${detail.name}`);
  log("step-2", `Description: ${detail.description ?? "(none)"}`);
  log("step-2", `Type: ${detail.type}`);
  log("step-2", `Status: ${detail.status}`);
  log("step-2", `File URL: ${detail.fileUrl ?? "(not uploaded yet)"}`);
  log("step-2", `Preview URL: ${detail.previewFileUrl ?? "(not available)"}`);
  log(
    "step-2",
    `Input Format: ${detail.inputFormat ? JSON.stringify(detail.inputFormat).slice(0, 100) : "(not defined)"}`
  );
  log("step-2", `Slides Input Format: ${detail.slidesInputFormat?.length ?? 0} entries`);
  success("Template detail retrieved");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: File upload (documented but skipped)
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-3", "\n--- File upload (skipped in example) ---");
  log("step-3", "In production, upload the template file before generating:");
  log("step-3", "");
  log("step-3", "  const fileBuffer = fs.readFileSync('./proposal-template.docx');");
  log("step-3", "  const { data } = await api.upload(");
  log("step-3", `    '/skills/document-templates/${template.id}/upload-file',`);
  log("step-3", "    fileBuffer,");
  log("step-3", "    'proposal-template.docx'");
  log("step-3", "  );");
  log("step-3", "");
  log("step-3", "The template file should contain variable placeholders that match");
  log("step-3", "the keys in the 'variables' object passed to the generate endpoint.");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Attempt document generation with variables
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-4", "\n--- Generating document from template ---");

  const variables = {
    customerName: "Acme Corporation",
    contactPerson: "Jane Smith",
    contactEmail: "jane.smith@acme.com",
    proposalDate: "2026-03-19",
    validUntil: "2026-04-19",
    projectName: "Cloud Migration Phase 2",
    items: [
      { name: "Cloud Platform License", quantity: 1, unitPrice: 25000, total: 25000 },
      { name: "Implementation Services", quantity: 200, unitPrice: 150, total: 30000 },
      { name: "Training Package", quantity: 5, unitPrice: 2000, total: 10000 }
    ],
    subtotal: "$65,000",
    tax: "$5,850",
    totalAmount: "$70,850",
    paymentTerms: "Net 30",
    notes: "This proposal is valid for 30 days from the issue date."
  };

  log("step-4", "Variables:");
  log("step-4", `  Customer: ${variables.customerName}`);
  log("step-4", `  Project: ${variables.projectName}`);
  log("step-4", `  Total: ${variables.totalAmount}`);
  log("step-4", `  Items: ${variables.items.length}`);

  try {
    const { data: generated } = await api.post(
      `/skills/document-templates/${template.id}/generate`,
      { variables }
    );

    if (generated.url) {
      log("step-4", `\nGenerated document URL: ${generated.url}`);
      log("step-4", "This is a temporary download link.");
      success("Document generated successfully");
    } else {
      log("step-4", `Generate response: ${JSON.stringify(generated).slice(0, 200)}`);
      success("Generate request completed");
    }
  } catch (err: any) {
    if (err instanceof NexusApiError && (err.status === 400 || err.status === 500)) {
      log("step-4", `\nGeneration failed (expected -- no template file uploaded): ${err.status}`);
      log("step-4", `  ${err.message}`);
      log("step-4", "");
      log("step-4", "To generate documents, first upload a template file via:");
      log("step-4", `  POST /skills/document-templates/${template.id}/upload-file`);
      success("Generation correctly requires uploaded template");
    } else {
      throw err;
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: List templates
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-5", "\n--- Listing document templates ---");

  const { data: listData } = await api.get("/skills/document-templates?limit=20&offset=0");
  const items = listData.items ?? listData;

  if (Array.isArray(items)) {
    log("step-5", `Total templates: ${listData.total ?? items.length}`);
    for (const tmpl of items.slice(0, 5)) {
      log("step-5", `  - ${tmpl.name} [${tmpl.type}] status: ${tmpl.status}`);
    }
  }

