#!/usr/bin/env npx tsx
/**
 * 05-external-tools.ts -- Create and test external OpenAPI tools
 *
 * Demonstrates: POST /skills/external-tools,
 *   GET /skills/external-tools, GET /skills/external-tools/:id,
 *   POST /skills/external-tools/:id/execute
 *
 * Shows: external tool creation from inline OpenAPI spec,
 *   listing and detail retrieval, action testing
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/05-external-tools.ts
 */

import { createClient, NexusApiError } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  assertEqual,
  log,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  log("start", "External Tools Example\n");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Define an OpenAPI spec inline
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-1", "--- Preparing OpenAPI spec ---");

  // Simple weather API spec for demonstration
  const openApiSpec = {
    openapi: "3.0.0",
    info: {
      title: "Weather API",
      version: "1.0.0",
      description: "Simple weather data API"
    },
    paths: {
      "/weather/current": {
        get: {
          operationId: "getCurrentWeather",
          summary: "Get current weather for a location",
          parameters: [
            {
              name: "location",
              in: "query",
              required: true,
              schema: { type: "string" },
              description: "City name or coordinates"
            },
            {
              name: "units",
              in: "query",
              required: false,
              schema: { type: "string", enum: ["metric", "imperial"] },
              description: "Temperature units"
            }
          ],
          responses: {
            "200": {
              description: "Current weather data",
              content: {
                "application/json": {
                  schema: {
                    type: "object",
                    properties: {
                      location: { type: "string" },
                      temperature: { type: "number" },
                      conditions: { type: "string" },
                      humidity: { type: "number" }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "/weather/forecast": {
        get: {
          operationId: "getForecast",
          summary: "Get 5-day forecast",
          parameters: [
            {
              name: "location",
              in: "query",
              required: true,
              schema: { type: "string" }
            },
            {
              name: "days",
              in: "query",
              required: false,
              schema: { type: "integer", minimum: 1, maximum: 7 }
            }
          ],
          responses: {
            "200": {
              description: "Forecast data",
              content: {
                "application/json": {
                  schema: {
                    type: "object",
                    properties: {
                      location: { type: "string" },
                      forecast: {
                        type: "array",
                        items: {
                          type: "object",
                          properties: {
                            date: { type: "string" },
                            high: { type: "number" },
                            low: { type: "number" },
                            conditions: { type: "string" }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  };

  log("step-1", `Spec: ${openApiSpec.info.title} v${openApiSpec.info.version}`);
  log("step-1", `Paths: ${Object.keys(openApiSpec.paths).length}`);
  log("step-1", `Operations: getCurrentWeather, getForecast`);
  success("OpenAPI spec prepared");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Create the external tool
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-2", "\n--- Creating external tool ---");

  const { data: tool } = await api.post("/skills/external-tools", {
    name: `Weather API ${Date.now()}`,
    description: "Get current weather and forecasts for any location",
    endpointUrl: "https://api.weather.example.com",
    openApiSpec: JSON.stringify(openApiSpec),
    auth: {
      type: "none" as const
    }
  });

  assertDefined(tool.id, "tool.id");
  log("step-2", `Tool ID: ${tool.id}`);
  log("step-2", `Name: ${tool.name}`);
  log("step-2", `Type: ${tool.type}`);
  log("step-2", `Status: ${tool.status}`);
  log("step-2", `Actions Count: ${tool.actionsCount}`);
  log("step-2", `Auth Type: ${tool.authType}`);
  log("step-2", `Endpoint: ${tool.endpointUrl}`);
  success("External tool created");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Get tool detail
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-3", "\n--- Getting tool detail ---");

  const { data: detail } = await api.get(`/skills/external-tools/${tool.id}`);

  assertDefined(detail.id, "detail.id");
  assertEqual(detail.id, tool.id, "ID should match");

  log("step-3", `Name: ${detail.name}`);
  log("step-3", `Description: ${detail.description ?? "(none)"}`);
  log("step-3", `Type: ${detail.type}`);
  log("step-3", `Endpoint: ${detail.endpointUrl ?? "(none)"}`);
  log("step-3", `Actions: ${detail.actionsCount}`);
  log("step-3", `Auth: ${detail.authType}`);
  log("step-3", `Status: ${detail.status}`);
  success("Tool detail retrieved");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: List external tools
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-4", "\n--- Listing external tools ---");

  const { data: listData } = await api.get("/skills/external-tools?limit=20&offset=0");
  const items = listData.items ?? listData;

  if (Array.isArray(items)) {
    log("step-4", `Total external tools: ${listData.total ?? items.length}`);
    for (const t of items.slice(0, 5)) {
      log("step-4", `  - ${t.name} [${t.authType}] ${t.actionsCount} actions (${t.status})`);
    }

    const found = items.find((t: any) => t.id === tool.id);
    assert(!!found, "Our tool should appear in the listing");
    success("Tool found in listing");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: Test an action
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-5", "\n--- Testing an action ---");
  log("step-5", "Testing 'getCurrentWeather' operation...\n");

  try {
    const { data: testResult } = await api.post(`/skills/external-tools/${tool.id}/execute`, {
      action: "getCurrentWeather",
      input: {
        location: "San Francisco, CA",
        units: "metric"
      }
    });

    log("step-5", `Status: ${testResult.status}`);
    log("step-5", `Execution Time: ${testResult.executionTimeMs}ms`);

    if (testResult.status === "success") {
      log("step-5", `Output: ${JSON.stringify(testResult.output, null, 2)}`);
      success("Action test succeeded");
    } else {
      log("step-5", `Error: ${testResult.error ?? "unknown"}`);
      log("step-5", "(This is expected for a demo endpoint that does not exist)");
      success("Action test completed (error expected for demo URL)");
    }
  } catch (err: any) {
    if (err instanceof NexusApiError) {
      log("step-5", `Test request error: ${err.message}`);
      log("step-5", "(Expected for demo -- the endpoint URL is not real)");
      success("Test request completed (connection error expected for demo URL)");
    } else {
      throw err;
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Show authenticated tool creation patterns
  // ═══════════════════════════════════════════════════════════════════════════

  log("step-6", "\n--- Auth configuration patterns ---");

  log("step-6", "No auth (public APIs):");
  log("step-6", '  { "type": "none" }');
  log("step-6", "");
  log("step-6", "Bearer token (most common):");
  log(
    "step-6",
    '  { "type": "service_http", "apiKey": "sk-abc123", "authorization_type": "bearer" }'
  );
  log("step-6", "");
  log("step-6", "Basic auth:");
  log(
    "step-6",
    '  { "type": "service_http", "apiKey": "base64-encoded-creds", "authorization_type": "basic" }'
  );
  log("step-6", "");
  log("step-6", "Custom header:");
  log("step-6", '  { "type": "service_http", "apiKey": "key-value",');
  log("step-6", '    "authorization_type": "custom", "custom_header_name": "X-Api-Key" }');
  log("step-6", "");
  log("step-6", "Per-user auth (agent users provide their own keys):");
  log("step-6", '  { "type": "user_http", "authorization_type": "bearer" }');
  log("step-6", "");
  log("step-6", "OAuth 2.0:");
  log("step-6", '  { "type": "oauth", "grant_type": "authorization_code",');
  log("step-6", '    "client_id": "...", "client_secret": "...",');
  log("step-6", '    "client_url": "https://...", "authorization_url": "https://..." }');

  success("Auth patterns documented");

  // ═══════════════════════════════════════════════════════════════════════════
  // Summary
  // ═══════════════════════════════════════════════════════════════════════════

  console.log("\n" + "=".repeat(60));
  log("summary", "External tools workflow:");
  log("summary", "  1. Define OpenAPI 3.0 spec (JSON string)");
  log("summary", "  2. Create tool (POST /skills/external-tools)");
  log("summary", "  3. Execute actions (POST .../execute with action + input)");
  log("summary", "  4. Attach to agent for use");
  log("summary", "");
  log("summary", `Created: ${tool.name} (${tool.id})`);
  log("summary", `  Actions: ${tool.actionsCount}`);
  log("summary", `  Auth: ${tool.authType}`);
  success("External tools example complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
