#!/usr/bin/env npx tsx
/**
 * Create Bug Ticket -- Report a bug with structured context
 *
 * Demonstrates: create a bug ticket with full debugging context,
 * verify it appears in the list, and add a follow-up comment.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/01-create-bug-ticket.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  assertEqual,
  log,
  onCleanup,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Create a bug ticket with full context
  // ═══════════════════════════════════════════════════════════════════════════

  log("create", "Creating bug ticket with structured context...");

  const { data: ticket } = await api.post("/tickets", {
    title: "PATCH /agents/:id returns 500 for valid modelConfig",
    type: "BUG",
    priority: "HIGH",
    description: [
      "When updating an agent's model config with a valid Anthropic model,",
      "the server returns a 500 instead of updating the agent.",
      "",
      "This blocks all agent model configuration via the API."
    ].join("\n"),
    context: {
      endpoint: "/agents/abc-123",
      method: "PATCH",
      statusCode: 500,
      errorCode: "INTERNAL_ERROR",
      requestBody: JSON.stringify({
        modelConfig: {
          modelName: "claude-sonnet-4-6",
          modelProvider: "ANTHROPIC"
        }
      }),
      responseBody: JSON.stringify({
        success: false,
        error: { code: "INTERNAL_ERROR", message: "Internal server error" }
      }),
      reproductionSteps: [
        "1. Create an agent via POST /agents",
        "2. PATCH /agents/:id with modelConfig body",
        "3. Observe 500 PrismaClientValidationError"
      ].join("\n"),
      expectedBehavior: "200 with updated agent including new model config",
      actualBehavior: "500 PrismaClientValidationError — enum value not recognized"
    }
  });

  assertDefined(ticket.id, "ticket.id");
  assertEqual(ticket.type, "BUG", "type");
  assertEqual(ticket.priority, "HIGH", "priority");
  assertDefined(ticket.url, "ticket.url (Linear link)");

  onCleanup(async () => {
    log("cleanup", `Ticket ${ticket.id} will remain on Linear for tracking.`);
  });

  success(`Bug ticket created: ${ticket.title} (${ticket.id})`);
  log("create", `Linear URL: ${ticket.url}`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Verify ticket appears in list
  // ═══════════════════════════════════════════════════════════════════════════

  log("list", "Verifying ticket appears in bug list...");

  const { data: bugList } = await api.get("/tickets?type=BUG&page=1&limit=10");

  assert(Array.isArray(bugList.tickets), "tickets should be an array");
  const found = bugList.tickets.find((t: any) => t.id === ticket.id);
  assertDefined(found, "Created ticket should appear in BUG list");

  success(`Ticket found in bug list (${bugList.meta?.total ?? bugList.tickets.length} total bugs)`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Get ticket detail with context
  // ═══════════════════════════════════════════════════════════════════════════

  log("get", "Fetching ticket detail...");

  const { data: detail } = await api.get(`/tickets/${ticket.id}`);

  assertEqual(detail.id, ticket.id, "detail.id");
  assertDefined(detail.context, "detail.context");
  assertEqual(detail.context.method, "PATCH", "context.method");
  assertEqual(detail.context.statusCode, 500, "context.statusCode");

  success("Ticket detail verified with structured context");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Add a comment with root cause analysis
  // ═══════════════════════════════════════════════════════════════════════════

  log("comment", "Adding root cause comment...");

  const { data: comment } = await api.post(`/tickets/${ticket.id}/comments`, {
    body: [
      "**Root cause identified:**",
      "",
      "The Prisma schema expects `ANTHROPIC` as the enum value for model provider,",
      "but the API validation layer was converting the value to lowercase before",
      "passing it to Prisma, causing a validation error.",
      "",
      "**Fix:** Skip the lowercase transform for enum fields in the model config",
      "validation middleware."
    ].join("\n")
  });

  assertDefined(comment.id, "comment.id");
  assert(comment.body.includes("Root cause"), "Comment body should contain root cause");

  success(`Comment added: ${comment.id}`);

  // ═══════════════════════════════════════════════════════════════════════════
  // Done
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  success("Bug ticket creation complete!");
  console.log(`  Ticket: ${ticket.url}`);
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

