/**
 * List, Get, Update, and Comment -- Ticket management lifecycle
 *
 * Demonstrates: list tickets with filters, get detail, update priority,
 * and add a comment. Self-verifying with assertions.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/02-list-and-update.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertContains,
  assertDefined,
  assertEqual,
  log,
  onCleanup,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Create a ticket to work with
  // ═══════════════════════════════════════════════════════════════════════════

  log("setup", "Creating a feature request ticket...");

  const { data: ticket } = await api.post("/tickets", {
    title: "Add bulk agent creation endpoint",
    type: "FEATURE_REQUEST",
    priority: "MEDIUM",
    description:
      "Allow creating multiple agents in a single API call to speed up onboarding workflows."
  });

  assertDefined(ticket.id, "ticket.id");

  onCleanup(async () => {
    log("cleanup", `Ticket ${ticket.id} will remain on Linear for tracking.`);
  });

  success(`Feature request created: ${ticket.id}`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: List all tickets with pagination
  // ═══════════════════════════════════════════════════════════════════════════

  log("list", "Listing all tickets (page 1, limit 10)...");

  const { data: allTickets, meta } = await api.get("/tickets?page=1&limit=10");

  assert(Array.isArray(allTickets.tickets), "tickets should be an array");
  assert(allTickets.tickets.length >= 1, "Should have at least 1 ticket");

  log("list", `Found ${meta?.total ?? allTickets.tickets.length} ticket(s)`);

  success(`Listed ${allTickets.tickets.length} tickets on page 1`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Filter by type
  // ═══════════════════════════════════════════════════════════════════════════

  log("filter", "Filtering for FEATURE_REQUEST tickets...");

  const { data: featureRequests } = await api.get("/tickets?type=FEATURE_REQUEST&page=1&limit=10");

  assert(Array.isArray(featureRequests.tickets), "filtered tickets should be an array");
  assertContains(
    featureRequests.tickets,
    (t: any) => t.id === ticket.id,
    "Created ticket should appear in FEATURE_REQUEST list"
  );

  success(`Found ${featureRequests.tickets.length} feature request(s)`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Search by keyword
  // ═══════════════════════════════════════════════════════════════════════════

  log("search", "Searching for 'bulk agent'...");

  const { data: searchResults } = await api.get("/tickets?search=bulk+agent&page=1&limit=10");

  assert(Array.isArray(searchResults.tickets), "search results should be an array");
  assertContains(
    searchResults.tickets,
    (t: any) => t.id === ticket.id,
