  );

  success(`Search returned ${searchResults.tickets.length} result(s)`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: Get ticket detail
  // ═══════════════════════════════════════════════════════════════════════════

  log("get", "Fetching ticket detail...");

  const { data: detail } = await api.get(`/tickets/${ticket.id}`);

  assertEqual(detail.id, ticket.id, "detail.id");
  assertEqual(detail.type, "FEATURE_REQUEST", "detail.type");
  assertEqual(detail.priority, "MEDIUM", "detail.priority");
  assert(detail.description.includes("bulk"), "Description should contain 'bulk'");

  success("Ticket detail verified");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Update priority to HIGH
  // ═══════════════════════════════════════════════════════════════════════════

  log("update", "Escalating priority to HIGH...");

  const { data: updated } = await api.patch(`/tickets/${ticket.id}`, {
    priority: "HIGH",
    title: "Add bulk agent creation endpoint (needed for enterprise onboarding)"
  });

  assertEqual(updated.priority, "HIGH", "updated priority");
  assert(updated.title.includes("enterprise"), "Title should be updated");
  assertEqual(updated.type, "FEATURE_REQUEST", "Type should be unchanged");

  success("Ticket updated: priority HIGH, title refined");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 7: Add a comment with implementation notes
  // ═══════════════════════════════════════════════════════════════════════════

  log("comment", "Adding implementation comment...");

  const { data: comment } = await api.post(`/tickets/${ticket.id}/comments`, {
    body: [
      "**Proposed API design:**",
      "",
      "```",
      "POST /agents/bulk",
      '{ "agents": [{ "firstName": "...", ... }, ...] }',
      "```",
      "",
      "Max 50 agents per request. Returns array of created agents.",
      "Failed items return inline errors without rolling back successes."
    ].join("\n")
  });

  assertDefined(comment.id, "comment.id");
  assert(comment.body.includes("Proposed API"), "Comment should contain proposal");

  success(`Comment added: ${comment.id}`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 8: List comments on the ticket
  // ═══════════════════════════════════════════════════════════════════════════

  log("comments", "Listing comments on ticket...");

  const { data: commentList } = await api.get(`/tickets/${ticket.id}/comments`);

  assert(Array.isArray(commentList.comments), "comments should be an array");
  assert(commentList.comments.length >= 1, "Should have at least 1 comment");
  assertContains(
    commentList.comments,
    (c: any) => c.id === comment.id,
    "Our comment should appear in the list"
  );

  success(`Found ${commentList.comments.length} comment(s) on ticket`);

  // ═══════════════════════════════════════════════════════════════════════════
  // Done
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  success("Ticket list, update, and comment lifecycle complete!");
  console.log(`  Ticket: ${updated.url || ticket.url}`);
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

