  }

  // Show facets (category counts) if available
  if (searchResults.facets && searchResults.facets.length > 0) {
    log("search", "\nCategory facets:");
    for (const facet of searchResults.facets.slice(0, 5)) {
      log("search", `  ${facet.category}: ${facet.count} tool(s)`);
    }
  }

  success(`Search returned ${searchResults.tools.length} tools`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Paginate through results
  // ═══════════════════════════════════════════════════════════════════════════

  log("paginate", "Paginating marketplace (3 pages of 5)...");

  let totalFetched = 0;
  const allToolNames: string[] = [];

  for (let offset = 0; offset < 15; offset += 5) {
    const { data: page } = await api.get(`/tools/search?q=&limit=5&offset=${offset}`);
    const pageTools = page.tools ?? [];

    if (pageTools.length === 0) {
      log("paginate", `  Page at offset ${offset}: empty (no more results)`);
      break;
    }

    totalFetched += pageTools.length;
    for (const t of pageTools) {
      allToolNames.push(t.name);
    }

    log(
      "paginate",
      `  Offset ${offset}: ${pageTools.length} tool(s) (total available: ${page.total})`
    );
  }

  assert(totalFetched > 0, "Should fetch at least some tools");
  success(`Paginated through ${totalFetched} tools across pages`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Get full tool detail
  // ═══════════════════════════════════════════════════════════════════════════

  // Pick the first tool from our initial search
  const targetTool = searchResults.tools[0];
  if (!targetTool) {
    log("detail", "No tools found in search -- skipping detail step");
    return;
  }

  log("detail", `Getting full detail for: ${targetTool.name} (${targetTool.id})...`);

  const { data: toolDetail } = await api.get(`/tools/${targetTool.id}`);

  assertDefined(toolDetail.id, "toolDetail.id");
  log("detail", `Tool: ${toolDetail.name ?? toolDetail.id}`);
  log("detail", `Type: ${toolDetail.type ?? "unknown"}`);
  log("detail", `Auth: ${toolDetail.authType ?? "none"}`);

  if (toolDetail.description) {
    log("detail", `Description: ${toolDetail.description.slice(0, 120)}...`);
  }

  success("Tool detail retrieved");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Inspect actions and parameters
  // ═══════════════════════════════════════════════════════════════════════════

  if (!toolDetail.actions || toolDetail.actions.length === 0) {
    log("actions", "No actions found on this tool");
  } else {
    log("actions", `\nActions (${toolDetail.actions.length}):`);

    for (const action of toolDetail.actions.slice(0, 5)) {
      const paramCount = action.parameters?.length ?? 0;
      const requiredParams = action.parameters?.filter((p: any) => p.required)?.length ?? 0;
      const dynamicParams = action.parameters?.filter((p: any) => p.remoteOptions)?.length ?? 0;

      log("actions", `\n  ${action.name} (key: "${action.key}")`);
      log(
        "actions",
        `    ${paramCount} params (${requiredParams} required, ${dynamicParams} dynamic)`
      );

      if (action.description) {
        log("actions", `    ${action.description.slice(0, 100)}`);
      }

      // Show parameter details
      if (action.parameters && action.parameters.length > 0) {
        log("actions", "    Parameters:");
        for (const param of action.parameters.slice(0, 6)) {
          const flags = [
            param.required ? "REQUIRED" : "optional",
            param.remoteOptions ? "DYNAMIC" : null,
            param.default != null ? `default: ${JSON.stringify(param.default)}` : null
          ]
            .filter(Boolean)
            .join(", ");

          log("actions", `      ${param.name} [${param.type}] (${flags})`);

          if (param.label) {
            log("actions", `        Label: ${param.label}`);
          }
          if (param.description) {
            log("actions", `        ${param.description.slice(0, 80)}`);
          }
        }

        if (action.parameters.length > 6) {
          log("actions", `      ... and ${action.parameters.length - 6} more parameter(s)`);
        }
      }
    }

    if (toolDetail.actions.length > 5) {
      log("actions", `\n  ... and ${toolDetail.actions.length - 5} more action(s)`);
    }
  }

  success("Action and parameter inspection complete");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: Search for a specific tool type
  // ═══════════════════════════════════════════════════════════════════════════

  log("specific", "Searching for 'slack'...");

  const { data: slackResults } = await api.get("/tools/search?q=slack&limit=5");

  if (slackResults.tools.length > 0) {
    const slackTool = slackResults.tools[0];
    log("specific", `Found: ${slackTool.name} (${slackTool.id})`);

    // Get detail to check authType
    const { data: slackDetail } = await api.get(`/tools/${slackTool.id}`);
    log("specific", `Auth type: ${slackDetail.authType ?? "none"}`);
    log("specific", `Actions: ${slackDetail.actions?.length ?? 0}`);

    if (slackDetail.authType) {
      log(
        "specific",
        `Connection method: ${slackDetail.authType === "oauth" ? "OAuth (browser flow)" : "HTTP (API key)"}`
      );
    }
  } else {
    log("specific", "No Slack tools found");
  }

  success("Specific tool search complete");

  // ═══════════════════════════════════════════════════════════════════════════
  // Summary
  // ═══════════════════════════════════════════════════════════════════════════

  console.log("\n" + "=".repeat(60));
  success("Search Marketplace complete!");
  log("summary", `Total tools discovered: ${searchResults.total}`);
  log(
    "summary",
    `Tool inspected: ${toolDetail.name ?? toolDetail.id} (${toolDetail.actions?.length ?? 0} actions)`
  );
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  process.exit(1);
});

#!/usr/bin/env npx tsx
/**
 * Connect Pipedream Tool -- Full OAuth flow
 *
 * Demonstrates: search for Google Sheets, start OAuth connection,
 * display authorization URL for user, poll handshake status until
 * COMPLETED, verify credential was created.
 *
 * NOTE: This is interactive -- requires the user to open a URL in
 * their browser. Detects TTY and skips with warning if non-interactive.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/02-connect-pipedream-tool.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  fail,
  log,
  pollUntil,
  runCleanup,
  success} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Search for Google Sheets tool
  // ═══════════════════════════════════════════════════════════════════════════

  log("search", "Searching marketplace for Google Sheets...");

  const { data: searchResults } = await api.get("/tools/search?q=google+sheets&limit=5");

  assertDefined(searchResults.tools, "tools array");
  assert(searchResults.tools.length > 0, "Should find Google Sheets in marketplace");

  const sheetsTool = searchResults.tools[0];
  log("search", `Found: ${sheetsTool.name} (${sheetsTool.id})`);
  success("Google Sheets tool found");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Get tool detail to verify auth type
  // ═══════════════════════════════════════════════════════════════════════════

  log("detail", "Getting tool detail...");

  const { data: toolDetail } = await api.get(`/tools/${sheetsTool.id}`);

  log("detail", `Auth type: ${toolDetail.authType ?? "none"}`);
  log("detail", `Actions: ${toolDetail.actions?.length ?? 0}`);

  success("Tool detail retrieved");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Check for existing credentials
  // ═══════════════════════════════════════════════════════════════════════════

  log("credentials", "Checking for existing credentials...");

  const { data: credData } = await api.get(`/tools/${sheetsTool.id}/credentials`);
  const existingCredentials = credData.credentials ?? [];

  if (existingCredentials.length > 0) {
    log("credentials", `Found ${existingCredentials.length} existing credential(s):`);
    for (const cred of existingCredentials) {
      log("credentials", `  - ${cred.name ?? "Unnamed"} (${cred.id}) [${cred.type}]`);
    }
    success("Existing credentials found -- OAuth flow may be optional");
  } else {
    log("credentials", "No existing credentials -- OAuth connection required");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Check if we are in an interactive terminal
  // ═══════════════════════════════════════════════════════════════════════════

  const isInteractive = process.stdout.isTTY === true;

  if (!isInteractive) {
    log("warning", "");
    log("warning", "=== NON-INTERACTIVE ENVIRONMENT DETECTED ===");
    log("warning", "OAuth flows require a browser. Skipping connection.");
    log("warning", "Run this script in a terminal to complete the flow.");
    log("warning", "===========================================");
    log("warning", "");

    // Still demonstrate the API call structure
    log("demo", "The following API calls would be made:");
    log("demo", `  1. POST /tools/${sheetsTool.id}/connect`);
    log("demo", '     { authType: "oauth", service: "google_sheets" }');
    log("demo", "  2. GET /tools/connect/<handshakeId>/status  (poll every 3s)");
    log("demo", `  3. GET /tools/${sheetsTool.id}/credentials  (verify)`);

    success("OAuth flow documented (skipped in non-interactive mode)");

    console.log("\n" + "=".repeat(60));
    success("Connect Pipedream Tool complete (non-interactive demo)!");
    console.log("=".repeat(60));
    return;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: Start the OAuth connection flow
  // ═══════════════════════════════════════════════════════════════════════════

  log("connect", "Starting OAuth connection for Google Sheets...");

  const { data: connectResult } = await api.post(`/tools/${sheetsTool.id}/connect`, {
    authType: "oauth",
    service: "google_sheets"
  });

  assertDefined(connectResult.authorizationUrl, "authorizationUrl");
  assertDefined(connectResult.handshakeId, "handshakeId");

  const handshakeId = connectResult.handshakeId;

  log("connect", "");
  log("connect", "=".repeat(60));
  log("connect", "OPEN THIS URL IN YOUR BROWSER TO CONNECT:");
  log("connect", "");
  log("connect", `  ${connectResult.authorizationUrl}`);
  log("connect", "");

  if (connectResult.expiresAt) {
    log("connect", `Link expires: ${connectResult.expiresAt}`);
  }

  log("connect", "=".repeat(60));
  log("connect", "");
  log("connect", "Waiting for you to complete the OAuth flow...");

  success("OAuth flow initiated");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Poll handshake status until COMPLETED
  // ═══════════════════════════════════════════════════════════════════════════

  log("poll", "Polling handshake status...");

  try {
    const result = await pollUntil(
      async () => {
        const { data: status } = await api.get(`/tools/connect/${handshakeId}/status`);
        return status;
      },
      (status: any) => {
        // Stop polling when status is terminal
        return (
          status.status === "COMPLETED" || status.status === "FAILED" || status.status === "EXPIRED"
        );
      },
      {
        intervalMs: 3000,
        timeoutMs: 120000,
        label: "oauth-handshake"
      }
    );

    if (result.status === "COMPLETED") {
      log("poll", `Connection successful! Connection ID: ${result.connectionId}`);
      success("OAuth handshake completed");
    } else if (result.status === "FAILED") {
      fail(`OAuth failed: ${result.errorMessage ?? "Unknown error"}`);
      log("poll", "You can retry by running this script again.");
    } else if (result.status === "EXPIRED") {
      fail("OAuth handshake expired. Run the script again to get a new link.");
    }
  } catch (err: any) {
    if (err.message.includes("timed out")) {
      fail("Polling timed out after 120 seconds.");
      log("poll", "The handshake may still be valid. Check manually:");
      log("poll", `  GET /tools/connect/${handshakeId}/status`);
    } else {
      throw err;
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 7: Verify credential was created
  // ═══════════════════════════════════════════════════════════════════════════

  log("verify", "Checking credentials after OAuth flow...");

  const { data: afterOAuth } = await api.get(`/tools/${sheetsTool.id}/credentials`);
  const afterCredentials = afterOAuth.credentials ?? [];

  log("verify", `Credentials now: ${afterCredentials.length}`);
  for (const cred of afterCredentials) {
    log(
      "verify",
      `  - ${cred.name ?? "Unnamed"} (${cred.id}) [${cred.type}] created: ${cred.createdAt}`
    );
  }

  if (afterCredentials.length > existingCredentials.length) {
    success("New credential created via OAuth flow!");
    const newCred = afterCredentials.find(
      (c: any) => !existingCredentials.some((e: any) => e.id === c.id)
    );
    if (newCred) {
      log("verify", `New credential ID: ${newCred.id}`);
      log("verify", "You can now use this credential when creating PLUGIN tool configs:");
      log(
        "verify",
        `  config: { toolId: "${sheetsTool.id}", action: "...", toolCredentialId: "${newCred.id}" }`
      );
    }
  } else {
    log("verify", "No new credential found -- may have been an existing account reconnection");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // Summary
  // ═══════════════════════════════════════════════════════════════════════════

  console.log("\n" + "=".repeat(60));
  success("Connect Pipedream Tool complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Connect HTTP Tool -- Create API key credential
 *
 * Demonstrates: find a tool that supports HTTP auth, create an HTTP
 * credential directly (no browser needed), verify it appears in the
 * credentials list, and clean up.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/03-connect-http-tool.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertContains,
  assertDefined,
  log,
  onCleanup,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Search for tools and find one that supports HTTP auth
  // ═══════════════════════════════════════════════════════════════════════════

  log("search", "Searching marketplace for tools...");

  const { data: searchResults } = await api.get("/tools/search?q=&limit=50&offset=0");

  assertDefined(searchResults.tools, "tools array");
  log("search", `Found ${searchResults.total} tool(s) in marketplace`);

  // Inspect tools to find one with HTTP auth
  let httpTool: any = null;

  for (const tool of searchResults.tools) {
    const { data: detail } = await api.get(`/tools/${tool.id}`);

    if (
      detail.authType &&
      (detail.authType.toLowerCase().includes("http") ||
        detail.authType.toLowerCase().includes("keys") ||
        detail.authType.toLowerCase().includes("api_key"))
    ) {
      httpTool = detail;
      break;
    }
  }

  if (!httpTool) {
    // If no HTTP tool found, we will demonstrate with any tool that exists
    log("search", "No tool with HTTP authType found in first 50 results.");
    log("search", "Demonstrating HTTP credential creation with the first available tool...");

    if (searchResults.tools.length > 0) {
      const { data: detail } = await api.get(`/tools/${searchResults.tools[0].id}`);
      httpTool = detail;
      log(
        "search",
        `Using: ${httpTool.name ?? httpTool.id} (authType: ${httpTool.authType ?? "none"})`
      );
    } else {
      log("search", "No tools available. Exiting.");
      return;
    }
  } else {
    log(
      "search",
      `Found HTTP tool: ${httpTool.name ?? httpTool.id} (authType: ${httpTool.authType})`
    );
  }

  success(`Selected tool: ${httpTool.name ?? httpTool.id} (${httpTool.id})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: List existing credentials before connecting
  // ═══════════════════════════════════════════════════════════════════════════

  log("before", "Checking existing credentials...");

  const { data: beforeCreds } = await api.get(`/tools/${httpTool.id}/credentials`);
  const credsBefore = beforeCreds.credentials ?? [];

  log("before", `Existing credentials: ${credsBefore.length}`);
  for (const cred of credsBefore) {
    log("before", `  - ${cred.name ?? "Unnamed"} (${cred.id})`);
  }

  success("Pre-connection credential check done");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Create HTTP credential
  // ═══════════════════════════════════════════════════════════════════════════

  log("connect", "Creating HTTP credential...");

  // NOTE: In production, use a real API key. This is a test placeholder.
  const testKeyName = `Test API Key (${new Date().toISOString().slice(0, 19)})`;

  let createdCredentialId: string | null = null;

  try {
    const { data: connectResult } = await api.post(`/tools/${httpTool.id}/connect`, {
      authType: "http",
      apiKey: "test-api-key-for-demonstration-only",
      name: testKeyName
    });

    assertDefined(connectResult.credentialId, "credentialId");
    createdCredentialId = connectResult.credentialId;

    log("connect", `Credential created directly (no browser needed):`);
    log("connect", `  ID:   ${connectResult.credentialId}`);
    log("connect", `  Name: ${connectResult.name ?? testKeyName}`);

    // Register cleanup
    onCleanup(async () => {
      if (createdCredentialId) {
        log("cleanup", `Deleting credential ${createdCredentialId}...`);
        try {
          await api.del(`/tools/${httpTool.id}/credentials/${createdCredentialId}`);
        } catch {
          // best effort
        }
      }
    });

    success("HTTP credential created synchronously");
  } catch (err: any) {
    // Some tools may not support HTTP auth -- that is expected
    log("connect", `HTTP connect failed: ${err.message}`);
    log("connect", "This tool may only support OAuth. Demonstrating the pattern:");
    log("connect", '  POST /tools/:id/connect { authType: "http", apiKey: "...", name: "..." }');
    log("connect", '  => { credentialId: "cred-uuid", name: "..." }');
    success("HTTP flow pattern demonstrated (tool may not support it)");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Verify credential appears in list
  // ═══════════════════════════════════════════════════════════════════════════

  if (createdCredentialId) {
    log("verify", "Verifying credential in list...");

    const { data: afterCreds } = await api.get(`/tools/${httpTool.id}/credentials`);
    const credsAfter = afterCreds.credentials ?? [];

    log("verify", `Credentials after: ${credsAfter.length} (was: ${credsBefore.length})`);

    assertContains(
      credsAfter,
      (c: any) => c.id === createdCredentialId,
      "New credential should appear in list"
    );

    const newCred = credsAfter.find((c: any) => c.id === createdCredentialId);
    log("verify", `Verified credential: ${newCred.name ?? "Unnamed"} (${newCred.id})`);

    success("Credential verified in list");

    // ═══════════════════════════════════════════════════════════════════════
    // STEP 5: Show how to use the credential
    // ═══════════════════════════════════════════════════════════════════════

    log("usage", "\nHow to use this credential:");
    log("usage", "");
    log("usage", "1. In a PLUGIN tool config on an agent:");
    log("usage", `   POST /agents/<agentId>/tools`);
    log("usage", `   {`);
    log("usage", `     "label": "My Tool",`);
    log("usage", `     "type": "PLUGIN",`);
    log("usage", `     "agentInputSchema": { ... },`);
    log("usage", `     "config": {`);
    log("usage", `       "toolId": "${httpTool.id}",`);
    log("usage", `       "action": "<action-key>",`);
    log("usage", `       "toolCredentialId": "${createdCredentialId}"`);
    log("usage", `     }`);
    log("usage", `   }`);
    log("usage", "");
    log("usage", "2. In a workflow plugin node:");
    log("usage", `   PATCH /workflows/<wfId>/nodes/<nodeId>`);
    log("usage", `   { "data": { "toolCredentialId": "${createdCredentialId}" } }`);

    // ═══════════════════════════════════════════════════════════════════════
    // STEP 6: Delete credential (cleanup)
    // ═══════════════════════════════════════════════════════════════════════

    log("delete", "Deleting test credential...");

    const { data: deleteResult } = await api.del(
      `/tools/${httpTool.id}/credentials/${createdCredentialId}`
    );
    assert(deleteResult.deleted === true, "deleted flag");

    // Verify removal
    const { data: finalCreds } = await api.get(`/tools/${httpTool.id}/credentials`);
    const finalList = finalCreds.credentials ?? [];
    const stillExists = finalList.some((c: any) => c.id === createdCredentialId);
    assert(!stillExists, "Deleted credential should not appear in list");

    // Clear cleanup since we manually deleted
    createdCredentialId = null;

    success("Credential deleted and removal verified");
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  success("Connect HTTP Tool complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Resolve Dynamic Options -- Dropdown values for Pipedream tools
 *
 * Demonstrates: get tool detail, find parameters with remoteOptions: true,
 * list credentials, resolve options for a dynamic field, and show
 * cascading resolution (passing configuredProps for dependent fields).
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/04-resolve-dynamic-options.ts
 */

import { createClient } from "../../shared/api-client";
import { assert, assertDefined, log, success } from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Find a tool with dynamic parameters
  // ═══════════════════════════════════════════════════════════════════════════

  log("search", "Searching for Google Sheets (has dynamic parameters)...");

  const { data: searchResults } = await api.get("/tools/search?q=google+sheets&limit=5");

  assert(searchResults.tools.length > 0, "Should find Google Sheets");

  const sheetsTool = searchResults.tools[0];
  log("search", `Found: ${sheetsTool.name} (${sheetsTool.id})`);

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Get tool detail and identify dynamic parameters
  // ═══════════════════════════════════════════════════════════════════════════

  log("detail", "Getting tool detail with parameter schemas...");

  const { data: toolDetail } = await api.get(`/tools/${sheetsTool.id}`);

  if (!toolDetail.actions || toolDetail.actions.length === 0) {
    log("detail", "No actions found. Exiting.");
    return;
  }

  // Find actions with dynamic parameters
  const actionsWithDynamic = toolDetail.actions.filter((a: any) =>
    a.parameters?.some((p: any) => p.remoteOptions)
  );

  log(
    "detail",
    `Actions with dynamic params: ${actionsWithDynamic.length}/${toolDetail.actions.length}`
  );

  if (actionsWithDynamic.length === 0) {
    log("detail", "No dynamic parameters found. Showing static parameters instead.");
    const firstAction = toolDetail.actions[0];
    log("detail", `Action: ${firstAction.name} (${firstAction.key})`);
    for (const p of firstAction.parameters ?? []) {
      log("detail", `  ${p.name} [${p.type}] ${p.required ? "REQUIRED" : "optional"}`);
    }
    success("Parameter inspection complete (no dynamic fields)");
    return;
  }

  // Pick the first action with dynamic params
  const targetAction = actionsWithDynamic[0];
  log("detail", `\nTarget action: ${targetAction.name} (${targetAction.key})`);
  log("detail", "Parameters:");

  const dynamicParams: any[] = [];
  for (const param of targetAction.parameters ?? []) {
    const isDynamic = param.remoteOptions === true;
    const flags = [param.required ? "REQUIRED" : "optional", isDynamic ? "DYNAMIC" : "static"].join(
      ", "
    );

    log("detail", `  ${param.name} [${param.type}] (${flags})`);

    if (isDynamic) {
      dynamicParams.push(param);
    }
  }

  log("detail", `\nDynamic fields that need resolution: ${dynamicParams.length}`);
  for (const dp of dynamicParams) {
    log("detail", `  - ${dp.name}: ${dp.label ?? dp.description ?? "(no description)"}`);
  }

  success("Dynamic parameters identified");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: List credentials for this tool
  // ═══════════════════════════════════════════════════════════════════════════

  log("credentials", "Listing credentials for option resolution...");

  const { data: credData } = await api.get(`/tools/${sheetsTool.id}/credentials`);
  const credentials = credData.credentials ?? [];

  if (credentials.length === 0) {
    log("credentials", "");
    log("credentials", "No credentials found for this tool.");
    log("credentials", "Dynamic options require a valid credential to query the service.");
    log("credentials", "");
    log("credentials", "To connect:");
    log(
      "credentials",
      `  1. POST /tools/${sheetsTool.id}/connect { authType: "oauth", service: "google_sheets" }`
    );
    log("credentials", "  2. Open the authorization URL in your browser");
    log("credentials", "  3. Poll the handshake until COMPLETED");
    log("credentials", "  4. Re-run this script");
    log("credentials", "");
    log("credentials", "See: 02-connect-pipedream-tool.ts for the full OAuth flow");

    success("Credential check complete (none available -- showing resolution pattern)");

    // Show the resolve-options pattern even without a credential
    log("pattern", "\nResolve-options request pattern:");
    log("pattern", `  POST /tools/${sheetsTool.id}/resolve-options`);
    log("pattern", "  {");
    log("pattern", `    "componentId": "${targetAction.key}",`);
    log("pattern", `    "propName": "${dynamicParams[0]?.name ?? "spreadsheetId"}",`);
    log("pattern", '    "credentialId": "<your-credential-id>"');
    log("pattern", "  }");
    log("pattern", "");

    if (dynamicParams.length > 1) {
      log("pattern", "Cascading resolution (pass previous selections):");
      log("pattern", `  POST /tools/${sheetsTool.id}/resolve-options`);
      log("pattern", "  {");
      log("pattern", `    "componentId": "${targetAction.key}",`);
      log("pattern", `    "propName": "${dynamicParams[1]?.name ?? "sheetName"}",`);
      log("pattern", '    "credentialId": "<your-credential-id>",');
      log("pattern", '    "configuredProps": {');
      log("pattern", `      "${dynamicParams[0]?.name ?? "spreadsheetId"}": "<selected-value>"`);
      log("pattern", "    }");
      log("pattern", "  }");
    }

    console.log("\n" + "=".repeat(60));
    success("Resolve Dynamic Options complete (pattern demonstrated)!");
    console.log("=".repeat(60));
    return;
  }

  const credential = credentials[0];
  log("credentials", `Using credential: ${credential.name ?? "Unnamed"} (${credential.id})`);

  success("Credential ready for option resolution");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Resolve options for the first dynamic field
  // ═══════════════════════════════════════════════════════════════════════════

  const firstDynamic = dynamicParams[0];
  log("resolve", `Resolving options for '${firstDynamic.name}'...`);

  try {
    const { data: options1 } = await api.post(`/tools/${sheetsTool.id}/resolve-options`, {
      componentId: targetAction.key,
      propName: firstDynamic.name,
      credentialId: credential.id
    });

    assertDefined(options1.options, "options array");
    assert(Array.isArray(options1.options), "options should be array");

    log("resolve", `Got ${options1.options.length} option(s) for '${firstDynamic.name}':`);
    for (const opt of options1.options.slice(0, 10)) {
      log("resolve", `  - ${opt.label} => ${JSON.stringify(opt.value)}`);
    }
    if (options1.options.length > 10) {
      log("resolve", `  ... and ${options1.options.length - 10} more`);
    }

    success(`Resolved ${options1.options.length} options for '${firstDynamic.name}'`);

    // ═══════════════════════════════════════════════════════════════════════
    // STEP 5: Cascading resolution (if we have a second dynamic field)
    // ═══════════════════════════════════════════════════════════════════════

    if (dynamicParams.length > 1 && options1.options.length > 0) {
      const secondDynamic = dynamicParams[1];
      const selectedValue = options1.options[0].value;

      log("cascade", `\nCascading resolution for '${secondDynamic.name}'...`);
      log("cascade", `Passing configured '${firstDynamic.name}': ${JSON.stringify(selectedValue)}`);

      try {
        const { data: options2 } = await api.post(`/tools/${sheetsTool.id}/resolve-options`, {
          componentId: targetAction.key,
          propName: secondDynamic.name,
          credentialId: credential.id,
          configuredProps: {
            [firstDynamic.name]: selectedValue
          }
        });

        assertDefined(options2.options, "cascading options");

        log("cascade", `Got ${options2.options.length} option(s) for '${secondDynamic.name}':`);
        for (const opt of options2.options.slice(0, 10)) {
          log("cascade", `  - ${opt.label} => ${JSON.stringify(opt.value)}`);
        }

        success(`Cascading resolution: ${options2.options.length} options`);

        // ═════════════════════════════════════════════════════════════════
        // STEP 6: Show how these values feed into tool config
        // ═════════════════════════════════════════════════════════════════

        if (options2.options.length > 0) {
          const secondValue = options2.options[0].value;

          log("usage", "\nHow to use resolved values in a PLUGIN tool config:");
          log("usage", `  POST /agents/<agentId>/tools`);
          log("usage", "  {");
          log("usage", `    "label": "${targetAction.name}",`);
          log("usage", '    "type": "PLUGIN",');
          log("usage", '    "agentInputSchema": { ... },');
          log("usage", '    "config": {');
          log("usage", `      "toolId": "${sheetsTool.id}",`);
          log("usage", `      "action": "${targetAction.key}",`);
          log("usage", `      "toolCredentialId": "${credential.id}",`);
          log("usage", '      "parameters": {');
          log(
            "usage",
            `        "${firstDynamic.name}": { "type": "string", "handler": "manual", "value": ${JSON.stringify(selectedValue)} },`
          );
          log(
            "usage",
            `        "${secondDynamic.name}": { "type": "string", "handler": "manual", "value": ${JSON.stringify(secondValue)} }`
          );
          log("usage", "      }");
          log("usage", "    }");
          log("usage", "  }");
        }
      } catch (err: any) {
        log("cascade", `Cascading resolution failed: ${err.message}`);
        log("cascade", "This may happen if the second field does not depend on the first.");
      }
    } else if (dynamicParams.length <= 1) {
      log("cascade", "Only one dynamic field -- no cascading to demonstrate.");
    } else {
      log("cascade", "No options returned for first field -- cannot cascade.");
    }
  } catch (err: any) {
    log("resolve", `Resolution failed: ${err.message}`);
    log(
      "resolve",
      "The credential may not have access to this service, or the tool may be offline."
    );
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // Summary
  // ═══════════════════════════════════════════════════════════════════════════

  console.log("\n" + "=".repeat(60));
  success("Resolve Dynamic Options complete!");
  log("summary", `Tool: ${toolDetail.name ?? toolDetail.id}`);
  log("summary", `Action: ${targetAction.name} (${targetAction.key})`);
  log("summary", `Dynamic fields: ${dynamicParams.length}`);
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  process.exit(1);
});

#!/usr/bin/env npx tsx
/**
 * Manage Credentials (Org-Wide) -- List, get, rename, delete credentials
 *
 * Demonstrates: list all org credentials with filtering, get detail,
 * rename a credential, and delete (with cleanup).
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/05-manage-credentials.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertDefined,
  log,
  onCleanup,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: List all credentials (org-wide)
  // ═══════════════════════════════════════════════════════════════════════════

  log("list", "Listing all org credentials...");

  const { data: allCreds } = await api.get("/credentials");

  assertDefined(allCreds.credentials, "credentials array");
  log("list", `Total credentials: ${allCreds.credentials.length}`);

  for (const cred of allCreds.credentials) {
    log(
      "list",
      `  - ${cred.name ?? "Unnamed"} (${cred.id}) [${cred.source ?? "unknown"}] status: ${cred.status ?? "unknown"}`
    );
  }

  success("Listed all org credentials");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Filter credentials by status
  // ═══════════════════════════════════════════════════════════════════════════

  log("filter", "Filtering credentials by status=CONNECTED...");

  const { data: connectedCreds } = await api.get("/credentials?status=CONNECTED");

  log("filter", `Connected credentials: ${connectedCreds.credentials.length}`);

  for (const cred of connectedCreds.credentials) {
    log("filter", `  - ${cred.name ?? "Unnamed"} (${cred.id})`);
  }

  success("Filtered by CONNECTED status");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Filter by source
  // ═══════════════════════════════════════════════════════════════════════════

  log("source", "Filtering credentials by source=oauth_connection...");

  const { data: oauthCreds } = await api.get("/credentials?source=oauth_connection");

  log("source", `OAuth credentials: ${oauthCreds.credentials.length}`);

  success("Filtered by oauth_connection source");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: Get credential detail
  // ═══════════════════════════════════════════════════════════════════════════

  if (allCreds.credentials.length === 0) {
    log("detail", "No credentials found -- skipping detail/rename/delete steps");
    return;
  }

  const targetCred = allCreds.credentials[0];
  log("detail", `Getting detail for: ${targetCred.name ?? targetCred.id}...`);

  const { data: credDetail } = await api.get(`/credentials/${targetCred.id}`);

  assertDefined(credDetail.id, "credDetail.id");
  log("detail", `  ID:        ${credDetail.id}`);
  log("detail", `  Name:      ${credDetail.name ?? "Unnamed"}`);
  log("detail", `  Source:    ${credDetail.source ?? "unknown"}`);
  log("detail", `  Status:    ${credDetail.status ?? "unknown"}`);
  log("detail", `  Created:   ${credDetail.createdAt}`);

  success("Credential detail retrieved");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: Rename a credential (and restore original name)
  // ═══════════════════════════════════════════════════════════════════════════

  const originalName = credDetail.name;
  const testName = `Renamed (${new Date().toISOString().slice(0, 19)})`;

  log("rename", `Renaming credential to: "${testName}"...`);

  const { data: updated } = await api.patch(`/credentials/${targetCred.id}`, {
    name: testName
  });

  assert(updated.name === testName, "Name should match after rename");
  log("rename", `Renamed: ${updated.name}`);

  // Register cleanup to restore original name
  onCleanup(async () => {
    if (originalName) {
      log("cleanup", `Restoring original name: "${originalName}"...`);
      try {
        await api.patch(`/credentials/${targetCred.id}`, { name: originalName });
      } catch {
        // best effort
      }
    }
  });

  success("Credential renamed (will restore original name on cleanup)");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Show how credential IDs connect to tool configs
  // ═══════════════════════════════════════════════════════════════════════════

  log("usage", "\nHow credential IDs are used:");
  log("usage", "");
  log("usage", "1. In agent PLUGIN tool configs:");
  log("usage", `   "toolCredentialId": "${targetCred.id}"`);
  log("usage", "");
  log("usage", "2. In workflow plugin nodes:");
  log("usage", `   "data": { "toolCredentialId": "${targetCred.id}" }`);
  log("usage", "");
  log("usage", "3. With access cards (for scoped permissions):");
  log("usage", `   nexus access-card create --credential-id ${targetCred.id} --name "Send Only" --data '{"policies":{"gmail-send-email":{"parameters":{"to":{"enabled":true},"subject":{"enabled":true}}}}}'`);
  log("usage", "   (policies is a map actionId -> { parameters }; unlisted action = denied, unlisted parameter = stripped)");

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  success("Manage Credentials complete!");
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Access Card CRUD -- Full lifecycle: discover actions, create, list, update, delete
 *
 * Demonstrates: discover available actions for a credential, create an access
 * card with scoped policies, list cards, update policies, and clean up.
 *
 * Run:
 *   NEXUS_API_KEY=nxs_your_key npx tsx examples/06-access-card-crud.ts
 */

import { createClient } from "../../shared/api-client";
import {
  assert,
  assertContains,
  assertDefined,
  log,
  onCleanup,
  runCleanup,
  success
} from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 1: Find a credential to work with
  // ═══════════════════════════════════════════════════════════════════════════

  log("setup", "Listing credentials to find one for access card demo...");

  const { data: allCreds } = await api.get("/credentials?status=CONNECTED");
  const credentials = allCreds.credentials ?? [];

  if (credentials.length === 0) {
    log("setup", "No connected credentials found. Connect a tool first.");
    log("setup", "  nexus tool connect <toolId> --auth-type oauth --body '{\"service\":\"gmail\"}'");
    return;
  }

  const targetCred = credentials[0];
  log("setup", `Using credential: ${targetCred.name ?? "Unnamed"} (${targetCred.id})`);

  success("Credential selected");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 2: Discover available actions
  // ═══════════════════════════════════════════════════════════════════════════

  log("actions", "Discovering available actions for this credential...");

  const { data: actionsResult } = await api.get(
    `/credentials/${targetCred.id}/cards/available-actions`
  );

  assertDefined(actionsResult.actions, "actions array");
  log("actions", `Available actions (${actionsResult.actions.length}):`);

  // Each entry is an ActionDefinition object, never a bare string:
  //   { actionId, name, description, componentType?, parameters: [{ name, type, required, description }] }
  for (const action of actionsResult.actions.slice(0, 10)) {
    log("actions", `  - ${action.actionId} (${action.parameters.length} params)`);
  }
  if (actionsResult.actions.length > 10) {
    log("actions", `  ... and ${actionsResult.actions.length - 10} more`);
  }

  success("Available actions discovered");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 3: Create an access card with scoped policies
  // ═══════════════════════════════════════════════════════════════════════════

  // `policies` is a MAP keyed by actionId, not a list of action names:
  //   { "<actionId>": { "parameters": { "<name>": { "enabled": true } } } }
  //
  // Both halves come from available-actions. An action absent from the map is
  // DENIED — that is the point of a card. A parameter absent from `parameters`
  // is STRIPPED from the call, so every parameter the action needs must be
  // listed: `{ "<actionId>": {} }` allows the action and then calls it with no
  // parameters at all.
  const buildPolicy = (action: { parameters: { name: string }[] }) => ({
    parameters: Object.fromEntries(action.parameters.map((p) => [p.name, { enabled: true }]))
  });

  // Use the first two actions as a minimal policy scope
  const scopedActions = actionsResult.actions.slice(0, 2);
  const scopedPolicies = Object.fromEntries(
    scopedActions.map((a: { actionId: string; parameters: { name: string }[] }) => [
      a.actionId,
      buildPolicy(a)
    ])
  );
  const cardName = `Test Card (${new Date().toISOString().slice(0, 19)})`;

  log("create", `Creating access card: "${cardName}"...`);
  log("create", `  Allowed actions: ${JSON.stringify(Object.keys(scopedPolicies))}`);

  const { data: createdCard } = await api.post(
    `/credentials/${targetCred.id}/cards`,
    {
      name: cardName,
      policies: scopedPolicies
    }
  );

  assertDefined(createdCard.id, "card id");
  assertDefined(createdCard.policies, "card policies");

  log("create", `Card created:`);
  log("create", `  ID:           ${createdCard.id}`);
  log("create", `  Name:         ${createdCard.name}`);
  log("create", `  Credential:   ${createdCard.credentialId}`);
  log("create", `  Policies:     ${JSON.stringify(createdCard.policies)}`);

  // Register cleanup to delete the card
  const cardId = createdCard.id;
  onCleanup(async () => {
    log("cleanup", `Deleting access card ${cardId}...`);
    try {
      await api.del(`/access-cards/${cardId}`);
    } catch {
      // best effort
    }
  });

  success("Access card created with scoped policies");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 4: List access cards for the credential
  // ═══════════════════════════════════════════════════════════════════════════

  log("list", "Listing access cards for this credential...");

  const { data: cardList } = await api.get(
    `/credentials/${targetCred.id}/cards`
  );

  const cards = cardList.accessCards ?? [];
  log("list", `Found ${cards.length} access card(s):`);

  for (const card of cards) {
    log("list", `  - ${card.name ?? "Unnamed"} (${card.id})`);
    log("list", `    Policies: ${JSON.stringify(card.policies)}`);
  }

  assertContains(
    cards,
    (c: any) => c.id === cardId,
    "New card should appear in list"
  );

  success("Access cards listed");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 5: Get access card detail
  // ═══════════════════════════════════════════════════════════════════════════

  log("detail", `Getting detail for card: ${cardId}...`);

  const { data: cardDetail } = await api.get(`/access-cards/${cardId}`);

  assertDefined(cardDetail.id, "card detail id");
  assert(cardDetail.id === cardId, "Card ID should match");
  log("detail", `  Name:       ${cardDetail.name}`);
  log("detail", `  Credential: ${cardDetail.credentialId}`);
  log("detail", `  Policies:   ${JSON.stringify(cardDetail.policies)}`);
  log("detail", `  Created:    ${cardDetail.createdAt}`);

  success("Access card detail retrieved");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 6: Update access card policies
  // ═══════════════════════════════════════════════════════════════════════════

  // Narrow the policy to only the first action. PATCH replaces `policies`
  // wholesale, so the narrowed map is the card's complete new policy.
  const narrowedActions = scopedActions.slice(0, 1);
  const narrowedPolicies = Object.fromEntries(
    narrowedActions.map((a: { actionId: string; parameters: { name: string }[] }) => [
      a.actionId,
      buildPolicy(a)
    ])
  );

  log("update", `Updating card policies to: ${JSON.stringify(Object.keys(narrowedPolicies))}...`);

  const { data: updatedCard } = await api.patch(`/access-cards/${cardId}`, {
    policies: narrowedPolicies
  });

  log("update", `Updated policies: ${JSON.stringify(updatedCard.policies)}`);

  success("Access card policies updated");

  // ═══════════════════════════════════════════════════════════════════════════
  // STEP 7: Delete the access card
  // ═══════════════════════════════════════════════════════════════════════════

  log("delete", `Deleting access card: ${cardId}...`);

  const { data: deleteResult } = await api.del(`/access-cards/${cardId}`);
  assert(deleteResult.deleted === true, "deleted flag");

  // Verify removal
  const { data: finalCards } = await api.get(
    `/credentials/${targetCred.id}/cards`
  );
  const remaining = finalCards.accessCards ?? [];
  const stillExists = remaining.some((c: any) => c.id === cardId);
  assert(!stillExists, "Deleted card should not appear in list");

  success("Access card deleted and removal verified");

  // Clear cleanup since we manually deleted
  // (runCleanup will be a no-op for this card)

  // ═══════════════════════════════════════════════════════════════════════════
  // Cleanup
  // ═══════════════════════════════════════════════════════════════════════════

  await runCleanup();

  console.log("\n" + "=".repeat(60));
  success("Access Card CRUD complete!");
  log("summary", `Credential used: ${targetCred.name ?? targetCred.id}`);
  log("summary", `Available actions: ${actionsResult.actions.length}`);
  log("summary", `Card created, listed, updated, and deleted successfully`);
  console.log("=".repeat(60));
}

main().catch((err) => {
  console.error("\n\x1b[31mFailed:\x1b[0m", err.message);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * List and Inspect Traces
 *
 * Demonstrates: listing traces with filters, getting trace details,
 * inspecting nested generations.
 *
 * Run: NEXUS_API_KEY=nxs_... npx tsx examples/01-list-and-inspect-traces.ts
 */

import { createClient } from "../../shared/api-client";
import { assert, assertDefined, log, success } from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══ STEP 1: List recent traces ═══
  log("list", "Listing recent traces...");
  const { data: traces } = await api.get("/tracing/traces", {
    limit: 5,
    order: "desc",
    sortBy: "startedAt"
  });
  assert(Array.isArray(traces), "traces is array");
  log("list", `Found ${traces.length} traces`);

  if (traces.length === 0) {
    log("skip", "No traces found — run a workflow or chat to generate traces.");
    return;
  }

  // ═══ STEP 2: Get trace detail ═══
  const traceId = traces[0].id;
  log("get", `Getting trace ${traceId}...`);
  const { data: trace } = await api.get(`/tracing/traces/${traceId}`);
  assertDefined(trace.id, "trace.id");
  assertDefined(trace.status, "trace.status");
  log("get", `Trace status: ${trace.status}, generations: ${trace.generations?.length ?? 0}`);

  // ═══ STEP 3: Inspect a generation ═══
  if (trace.generations && trace.generations.length > 0) {
    const genId = trace.generations[0].id;
    log("get", `Getting generation ${genId}...`);
    const { data: gen } = await api.get(`/tracing/generations/${genId}`);
