async function main() {
  const api = createClient();

  const startDate = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
  const endDate = new Date().toISOString();

  // ═══ STEP 1: Get summary stats ═══
  log("summary", "Fetching analytics summary...");
  const { data: summary } = await api.get("/tracing/analytics/summary", { startDate, endDate });

  log("summary", `Total traces: ${summary.totalTraces}`);
  log("summary", `  Completed: ${summary.completedTraces}`);
  log("summary", `  Failed: ${summary.failedTraces}`);
  log("summary", `  In progress: ${summary.inProgressTraces}`);
  log("summary", `Total cost: $${summary.totalCost?.toFixed(4) ?? "0"}`);
  log("summary", `Input tokens: ${summary.totalInputTokens}`);
  log("summary", `Output tokens: ${summary.totalOutputTokens}`);
  log("summary", `Avg duration: ${summary.avgDurationMs?.toFixed(0) ?? "n/a"}ms`);
  log("summary", `Distinct models: ${summary.distinctModelCount}`);

  if (summary.previousPeriod) {
    const pct = (curr: number, prev: number) =>
      prev > 0 ? `${(((curr - prev) / prev) * 100).toFixed(1)}%` : "n/a";
    log("compare", `Cost change: ${pct(summary.totalCost, summary.previousPeriod.totalCost)}`);
    log(
      "compare",
      `Trace count change: ${pct(summary.totalTraces, summary.previousPeriod.totalTraces)}`
    );
  }

  // ═══ STEP 2: Cost breakdown by model ═══
