  const { data: byModel } = await api.get("/tracing/analytics/cost-breakdown", {
    startDate,
    endDate,
    groupBy: "model"
  });
  for (const entry of byModel.entries ?? []) {
    log(
      "breakdown",
      `  ${entry.groupLabel}: $${entry.totalCost.toFixed(4)} (${entry.generationCount} gens)`
    );
  }

  // ═══ STEP 3: Cost breakdown by agent ═══
  log("breakdown", "\nCost breakdown by agent:");
  const { data: byAgent } = await api.get("/tracing/analytics/cost-breakdown", {
    startDate,
    endDate,
    groupBy: "agent"
  });
