/**
 * Cost Analysis
 *
 * Demonstrates: finding expensive traces, analyzing cost patterns,
 * comparing cost across models and workflows.
 *
 * Run: NEXUS_API_KEY=nxs_... npx tsx examples/04-cost-analysis.ts
 */

import { createClient } from "../../shared/api-client";
import { log, success } from "../../shared/helpers";

async function main() {
  const api = createClient();

  // ═══ STEP 1: Find most expensive traces ═══
  log("cost", "Finding most expensive traces...");
  const { data: expensive } = await api.get("/tracing/traces", {
    sortBy: "totalCost",
    order: "desc",
    limit: 5,
    status: "COMPLETED"
  });

  for (const trace of expensive) {
    const cost = trace.totalCost != null ? `$${trace.totalCost.toFixed(4)}` : "n/a";
    const tokens =
      parseInt(trace.totalInputTokens || "0") + parseInt(trace.totalOutputTokens || "0");
    log("cost", `  ${trace.id}: ${cost} (${tokens} tokens, ${trace.generationCount} gens)`);
  }

  // ═══ STEP 2: Find expensive generations ═══
  log("cost", "\nMost expensive individual LLM calls:");
  const { data: expensiveGens } = await api.get("/tracing/generations", {
    sortBy: "costInUSDTenThousandths",
    order: "desc",
    limit: 5,
    status: "COMPLETED"
  });

  for (const gen of expensiveGens) {
    const cost =
      gen.costInUSDTenThousandths != null
        ? `$${(gen.costInUSDTenThousandths / 10000).toFixed(6)}`
        : "n/a";
    log("cost", `  ${gen.modelName}: ${cost} (in: ${gen.inputTokens}, out: ${gen.outputTokens})`);
  }

  // ═══ STEP 3: Compare model costs ═══
  log("compare", "\nCost by model:");
  const { data: byModel } = await api.get("/tracing/analytics/cost-breakdown", {
    groupBy: "model"
  });

  const totalCost = byModel.entries.reduce((sum: number, e: any) => sum + e.totalCost, 0);
  for (const entry of byModel.entries) {
    const pct = totalCost > 0 ? ((entry.totalCost / totalCost) * 100).toFixed(1) : "0";
    log("compare", `  ${entry.groupLabel}: $${entry.totalCost.toFixed(4)} (${pct}% of total)`);
  }

  // ═══ STEP 4: Compare workflow costs ═══
  log("compare", "\nCost by workflow:");
  const { data: byWorkflow } = await api.get("/tracing/analytics/cost-breakdown", {
    groupBy: "workflow"
  });

  for (const entry of byWorkflow.entries) {
    const avgPerTrace = entry.traceCount > 0 ? entry.totalCost / entry.traceCount : 0;
    log(
      "compare",
      `  ${entry.groupLabel || "unnamed"}: $${entry.totalCost.toFixed(4)} total, $${avgPerTrace.toFixed(4)}/trace`
    );
  }

  success("Cost analysis complete!");
}

main().catch((err) => {
  console.error("\nFailed:", err.message);
  process.exit(1);
});

