async function main() {
  const api = createClient();

  // ── Create test workflows ─────────────────────────────────────────────
  const names = ["Sales Pipeline Alpha", "Sales Pipeline Beta", "Customer Support Flow"];
  const ids: string[] = [];

  for (const name of names) {
