    });
  }
  success(`Created ${ids.length} test workflows`);

  // ── List with pagination ──────────────────────────────────────────────
  const { data: page1, meta } = await api.get("/workflows?page=1&limit=2");
  assert(Array.isArray(page1), "data is array");
  assertDefined(meta, "meta exists");
  assert(meta!.total >= 3, `total should be >= 3, got ${meta!.total}`);
  success(`Page 1: ${page1.length} items, total: ${meta!.total}, hasMore: ${meta!.hasMore}`);

  // ── Filter by status ──────────────────────────────────────────────────
  const { data: drafts } = await api.get("/workflows?status=DRAFT&limit=50");
  assert(
    drafts.every((w: any) => w.status === "DRAFT"),
    "all should be DRAFT"
  );
  success(`Filtered DRAFT: ${drafts.length} workflows`);

  // ── Search by name ────────────────────────────────────────────────────
  const { data: searched } = await api.get("/workflows?search=Sales+Pipeline&limit=10");
  assert(searched.length >= 2, `search should find >= 2, got ${searched.length}`);
  assert(
    searched.every((w: any) => w.name.includes("Sales Pipeline")),
    "all results should match search"
  );
  success(`Search 'Sales Pipeline': found ${searched.length} workflows`);

  // ── Iterate all pages ─────────────────────────────────────────────────
  let allWorkflows: any[] = [];
  let page = 1;
  let hasMore = true;
  while (hasMore) {
