#!/usr/bin/env npx tsx
/**
 * Workflow CRUD — Publish and unpublish workflows
 *
 * Demonstrates: POST /publish, POST /unpublish, status lifecycle
 * Shows: DRAFT → PUBLISHED → DRAFT, 409 conflict handling
 */

import { createClient, NexusApiError } from "../../../shared/api-client";
import { assert, assertEqual, onCleanup, runCleanup, success } from "../../../shared/helpers";

async function main() {
  const api = createClient();

  // ── Create a minimal publishable workflow ─────────────────────────────
  const { data: wf } = await api.post("/workflows", { name: "Publish Test" });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  // Replace trigger with webhookTrigger
  await api.put(`/workflows/${wf.id}/trigger`, { type: "webhookTrigger" });
  const { data: detail } = await api.get(`/workflows/${wf.id}`);
  const triggerId = detail.nodes.find((n: any) => n.type === "webhookTrigger")?.id;

  // Add a textFormatter + output node, connect edges
  const { data: textNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  await api.patch(`/workflows/${wf.id}/nodes/${textNode.id}`, {
    data: { text: `Processing: {{${triggerId}}}` }
  });

  const { data: outNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "outputNode" });
  await api.patch(`/workflows/${wf.id}/nodes/${outNode.id}`, {
    data: { instructions: `{{${textNode.id}}}` }
  });

  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: textNode.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: textNode.id, target: outNode.id });
  success("Built workflow: webhookTrigger → textFormatter → output");

  // ── Validate before publishing ────────────────────────────────────────
  const { data: validation } = await api.get(`/workflows/${wf.id}/validate`);
  success(`Validation: isValid=${validation.isValid}, readyToPublish=${validation.readyToPublish}`);

  // ── Publish ───────────────────────────────────────────────────────────
  const { data: published } = await api.post(`/workflows/${wf.id}/publish`);
  assertEqual(published.status ?? "PUBLISHED", "PUBLISHED", "status after publish");

  const { data: check } = await api.get(`/workflows/${wf.id}`);
  assertEqual(check.status, "PUBLISHED", "GET confirms PUBLISHED");
  success("Published successfully");

  // ── Double publish → 409 conflict ─────────────────────────────────────
  try {
    await api.post(`/workflows/${wf.id}/publish`);
    assert(false, "should have thrown 409");
  } catch (err) {
    assert(err instanceof NexusApiError, "should be NexusApiError");
    assert(err.status === 409 || err.status === 400, `expected 409/400, got ${err.status}`);
    success(`Double publish correctly rejected: ${err.status} ${err.code}`);
  }

  // ── Unpublish ─────────────────────────────────────────────────────────
  await api.post(`/workflows/${wf.id}/unpublish`);
  const { data: unpubCheck } = await api.get(`/workflows/${wf.id}`);
  assertEqual(unpubCheck.status, "DRAFT", "back to DRAFT after unpublish");
  success("Unpublished: back to DRAFT");

  // ── Double unpublish → 409 conflict ───────────────────────────────────
  try {
    await api.post(`/workflows/${wf.id}/unpublish`);
    assert(false, "should have thrown 409");
  } catch (err) {
    assert(err instanceof NexusApiError, "should be NexusApiError");
    success(`Double unpublish correctly rejected: ${(err as NexusApiError).status}`);
  }

  await runCleanup();
  success("Done");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

