  const { data: wfDetail } = await api.get(`/workflows/${wf.id}`);
  const triggerId = wfDetail.nodes.find((n: any) => n.type === "webhookTrigger")!.id;

  const { data: nodeA } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  const { data: nodeB } = await api.post(`/workflows/${wf.id}/nodes`, { type: "customScript" });
  const { data: nodeC } = await api.post(`/workflows/${wf.id}/nodes`, { type: "outputNode" });
  success(
    `Setup: trigger + 3 nodes (${nodeA.id.slice(0, 8)}, ${nodeB.id.slice(0, 8)}, ${nodeC.id.slice(0, 8)})`
  );

  // ── Create edges: trigger → A → B → C ────────────────────────────────
  const { data: edge1 } = await api.post(`/workflows/${wf.id}/edges`, {
    source: triggerId,
    target: nodeA.id
  });
  assertDefined(edge1.id, "edge1 id");
  success(`Edge: trigger → nodeA (${edge1.id.slice(0, 8)})`);

  const { data: edge2 } = await api.post(`/workflows/${wf.id}/edges`, {
    source: nodeA.id,
    target: nodeB.id
  });
  success(`Edge: nodeA → nodeB (${edge2.id.slice(0, 8)})`);

  const { data: edge3 } = await api.post(`/workflows/${wf.id}/edges`, {
    source: nodeB.id,
    target: nodeC.id
  });
  success(`Edge: nodeB → nodeC (${edge3.id.slice(0, 8)})`);

  // ── Verify edges in workflow detail ───────────────────────────────────
  const { data: afterEdges } = await api.get(`/workflows/${wf.id}`);
  assertEqual(afterEdges.edges.length, 3, "should have 3 edges");
  success(`Verified: ${afterEdges.edges.length} edges in workflow`);

  // ── Delete middle edge ────────────────────────────────────────────────
  await api.del(`/workflows/${wf.id}/edges/${edge2.id}`);
  const { data: afterDelete } = await api.get(`/workflows/${wf.id}`);
  assertEqual(afterDelete.edges.length, 2, "should have 2 edges after delete");
  assert(!afterDelete.edges.find((e: any) => e.id === edge2.id), "deleted edge should not exist");
  success(`Deleted edge ${edge2.id.slice(0, 8)} — now ${afterDelete.edges.length} edges`);

  // ── Re-create the edge ────────────────────────────────────────────────
  const { data: edge2b } = await api.post(`/workflows/${wf.id}/edges`, {
    source: nodeA.id,
    target: nodeB.id
  });
  assert(edge2b.id !== edge2.id, "re-created edge has new ID");
  success("Re-created edge with new ID — chain restored");

  await runCleanup();
  success("Done");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Edges — Validation rules demonstration
 *
 * Demonstrates all edge validation error codes:
 *   EDGE_SELF_LOOP, EDGE_DUPLICATE, EDGE_TARGET_OCCUPIED,
 *   EDGE_INVALID_SOURCE_HANDLE, EDGE_SCOPE_VIOLATION
 */

import { createClient, NexusApiError } from "../../../shared/api-client";
import { assert, onCleanup, runCleanup, success } from "../../../shared/helpers";

async function expectError(fn: () => Promise<any>, label: string) {
  try {
    await fn();
    assert(false, `${label}: should have thrown`);
  } catch (err) {
    assert(err instanceof NexusApiError, `${label}: should be NexusApiError`);
    assert(err.status >= 400, `${label}: expected 4xx, got ${err.status}`);
    success(`${label}: correctly rejected (${err.status} ${err.code})`);
  }
}

async function main() {
  const api = createClient();

  const { data: wf } = await api.post("/workflows", { name: "Edge Validation Demo" });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  await api.put(`/workflows/${wf.id}/trigger`, { type: "webhookTrigger" });
  const { data: detail } = await api.get(`/workflows/${wf.id}`);
  const triggerId = detail.nodes.find((n: any) => n.type === "webhookTrigger")!.id;

  const { data: nodeA } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  const { data: nodeB } = await api.post(`/workflows/${wf.id}/nodes`, { type: "customScript" });

  // Connect trigger → A → B
  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: nodeA.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: nodeA.id, target: nodeB.id });

  // ── 1. Self-loop ──────────────────────────────────────────────────────
  await expectError(
    () => api.post(`/workflows/${wf.id}/edges`, { source: nodeA.id, target: nodeA.id }),
    "SELF_LOOP"
  );

  // ── 2. Duplicate edge ─────────────────────────────────────────────────
  await expectError(
    () => api.post(`/workflows/${wf.id}/edges`, { source: nodeA.id, target: nodeB.id }),
    "DUPLICATE"
  );

  // ── 3. Target already occupied ────────────────────────────────────────
  await expectError(
    () => api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: nodeB.id }),
    "TARGET_OCCUPIED"
  );

  // ── 4. Branching without sourceHandle ─────────────────────────────────
  const { data: branchNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "branching" });
  await api.post(`/workflows/${wf.id}/nodes/${branchNode.id}/branches`, { name: "Yes" });
  const { data: extraNode } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter"
  });

  await expectError(
    () => api.post(`/workflows/${wf.id}/edges`, { source: branchNode.id, target: extraNode.id }),
    "BRANCHING_NO_SOURCEHANDLE"
  );

  // ── 5. Loop scope violation ───────────────────────────────────────────
  const { data: loopNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "loop" });
  const loopStartId = loopNode.children?.find((c: any) => c.type === "loopStart")?.id;
  const { data: innerNode } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter",
    parentId: loopNode.id
  });
  const { data: rootNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "outputNode" });

  // Inner → root = scope violation
  await expectError(
    () => api.post(`/workflows/${wf.id}/edges`, { source: innerNode.id, target: rootNode.id }),
    "SCOPE_VIOLATION"
  );

  await runCleanup();
  success("All edge validation rules verified");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Pattern: Linear Pipeline
 *
 * Builds: webhookTrigger → textFormatter → customScript → outputNode
 * Configures each node with data, connects edges, validates, and tests.
 */

import { createClient } from "../../../shared/api-client";
import {
  assertDefined,
  onCleanup,
  pollUntil,
  runCleanup,
  success} from "../../../shared/helpers";

async function main() {
  const api = createClient();

  // ── 1. Create workflow ────────────────────────────────────────────────
  const { data: wf } = await api.post("/workflows", {
    name: "Linear Pipeline Demo",
    description: "webhook → format → script → output"
  });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });
  success(`Created workflow: ${wf.id}`);

  // ── 2. Replace trigger with agentInputTrigger (testable via API) ─────
  // Note: webhookTrigger waits for external HTTP, agentInputTrigger can be tested directly
  await api.put(`/workflows/${wf.id}/trigger`, { type: "agentInputTrigger" });
  const { data: afterTrigger } = await api.get(`/workflows/${wf.id}`);
  const triggerId = afterTrigger.nodes.find((n: any) => n.type === "agentInputTrigger")!.id;
  success(`Trigger: ${triggerId.slice(0, 8)} (agentInputTrigger)`);

  // ── 3. Add processing nodes ───────────────────────────────────────────
  const { data: formatter } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter"
  });
  await api.patch(`/workflows/${wf.id}/nodes/${formatter.id}`, {
    data: {
      text: `Received webhook data: {{${triggerId}}}`,
      label: "Format Input"
    }
  });
  success(`Node: ${formatter.id.slice(0, 8)} (textFormatter, configured)`);

  const { data: script } = await api.post(`/workflows/${wf.id}/nodes`, { type: "customScript" });
  await api.patch(`/workflows/${wf.id}/nodes/${script.id}`, {
    data: {
      code: "function func(input) {\n  return {\n    processed: true,\n    timestamp: new Date().toISOString(),\n    summary: typeof input === 'string' ? input.slice(0, 100) : JSON.stringify(input).slice(0, 100)\n  };\n}",
      label: "Process Data"
    }
  });
  success(`Node: ${script.id.slice(0, 8)} (customScript, configured)`);

  const { data: output } = await api.post(`/workflows/${wf.id}/nodes`, { type: "outputNode" });
  await api.patch(`/workflows/${wf.id}/nodes/${output.id}`, {
    data: { instructions: `{{${script.id}}}`, label: "Final Output" }
  });
  success(`Node: ${output.id.slice(0, 8)} (outputNode, references script)`);

  // ── 4. Connect edges ──────────────────────────────────────────────────
  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: formatter.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: formatter.id, target: script.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: script.id, target: output.id });
  success("Edges: trigger → format → script → output");

  // ── 5. Auto-layout ────────────────────────────────────────────────────
  await api.post(`/workflows/${wf.id}/layout`);
  success("Layout applied");

  // ── 6. Validate ───────────────────────────────────────────────────────
  const { data: validation } = await api.get(`/workflows/${wf.id}/validate`);
  success(`Validation: isValid=${validation.isValid}, readyToPublish=${validation.readyToPublish}`);

  // ── 7. Test the workflow ──────────────────────────────────────────────
  const { data: testResult } = await api.post(`/workflows/${wf.id}/test`, {});
  const execId = testResult.executionId;
  assertDefined(execId, "executionId");
  success(`Test started: ${execId}`);

  // Poll until complete
  const finalStatus = await pollUntil(
    async () => {
      const { data } = await api.get(`/workflows/${wf.id}/executions/${execId}`);
      return data;
    },
    (data: any) => ["COMPLETED", "FAILED", "CANCELLED"].includes(data.status),
    { label: "execution", timeoutMs: 60000 }
  );
  success(`Execution: ${finalStatus.status}`);

  // ── 8. Get per-node results ───────────────────────────────────────────
  for (const [label, nodeId] of [
    ["Format", formatter.id],
    ["Script", script.id],
    ["Output", output.id]
  ]) {
    try {
      const { data: nodeResult } = await api.get(
        `/workflows/${wf.id}/executions/${execId}/nodes/${nodeId}`
      );
      const out = nodeResult.output
        ? JSON.stringify(nodeResult.output).slice(0, 120)
        : "(no output)";
      success(`  ${label}: ${nodeResult.status} → ${out}`);
    } catch {
      // Some nodes may not have results
    }
  }

  await runCleanup();
  success("Done — linear pipeline tested end-to-end");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Pattern: Branching Router
 *
 * Builds: agentInputTrigger → branching (3 branches) → action per branch
 * Shows: Branch creation, sourceHandle wiring, multi-path workflows
 */

import { createClient } from "../../../shared/api-client";
import { assert, onCleanup, runCleanup, success } from "../../../shared/helpers";

async function main() {
  const api = createClient();

  const { data: wf } = await api.post("/workflows", {
    name: "Lead Router Demo",
    description: "Routes leads to different handlers based on priority"
  });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  // ── Trigger ───────────────────────────────────────────────────────────
  await api.put(`/workflows/${wf.id}/trigger`, { type: "agentInputTrigger" });
  const { data: detail } = await api.get(`/workflows/${wf.id}`);
  const triggerId = detail.nodes.find((n: any) => n.type === "agentInputTrigger")!.id;
  success("Trigger: agentInputTrigger");

  // ── Branching node ────────────────────────────────────────────────────
  const { data: branching } = await api.post(`/workflows/${wf.id}/nodes`, { type: "branching" });
  success(`Branching node: ${branching.id.slice(0, 8)}`);

  // ── Create 3 branches (branches start EMPTY) ─────────────────────────
  await api.post(`/workflows/${wf.id}/nodes/${branching.id}/branches`, {
    name: "High Priority",
    description: "Score > 80"
  });
  await api.post(`/workflows/${wf.id}/nodes/${branching.id}/branches`, {
    name: "Medium Priority",
    description: "Score 40-80"
  });
  await api.post(`/workflows/${wf.id}/nodes/${branching.id}/branches`, {
    name: "Low Priority",
    description: "Score < 40"
  });

  const { data: branchList } = await api.get(`/workflows/${wf.id}/nodes/${branching.id}/branches`);
  const branches = branchList.branches ?? branchList;
  assert(branches.length === 3, `expected 3 branches, got ${branches.length}`);
  success(`Created 3 branches: ${branches.map((b: any) => b.name).join(", ")}`);

  // ── Action nodes per branch ───────────────────────────────────────────
  const { data: highNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  await api.patch(`/workflows/${wf.id}/nodes/${highNode.id}`, {
    data: {
      text: `URGENT: High priority lead from {{${triggerId}}}`,
      label: "High Priority Handler"
    }
  });

  const { data: medNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  await api.patch(`/workflows/${wf.id}/nodes/${medNode.id}`, {
    data: {
      text: `FOLLOW UP: Medium priority lead from {{${triggerId}}}`,
      label: "Medium Priority Handler"
    }
  });

  const { data: lowNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  await api.patch(`/workflows/${wf.id}/nodes/${lowNode.id}`, {
    data: { text: `QUEUE: Low priority lead from {{${triggerId}}}`, label: "Low Priority Handler" }
  });
  success("Created 3 action nodes (one per branch)");

  // ── Wire edges ────────────────────────────────────────────────────────
  // trigger → branching (no sourceHandle needed for incoming)
  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: branching.id });

  // branching → each action (MUST use sourceHandle = branch ID)
  const branchIds = branches.map((b: any) => b.id ?? b._id ?? b.key);
  await api.post(`/workflows/${wf.id}/edges`, {
    source: branching.id,
    target: highNode.id,
    sourceHandle: branchIds[0]
  });
  await api.post(`/workflows/${wf.id}/edges`, {
    source: branching.id,
    target: medNode.id,
    sourceHandle: branchIds[1]
  });
  await api.post(`/workflows/${wf.id}/edges`, {
    source: branching.id,
    target: lowNode.id,
    sourceHandle: branchIds[2]
  });
  success("Edges wired: trigger → branching → [high, medium, low]");

  // ── Layout + Validate ─────────────────────────────────────────────────
  await api.post(`/workflows/${wf.id}/layout`);
  const { data: validation } = await api.get(`/workflows/${wf.id}/validate`);
  success(
    `Validation: isValid=${validation.isValid}, variableIssues=${(validation.variableIssues ?? []).length}`
  );

  // ── Test ──────────────────────────────────────────────────────────────
  const { data: testResult } = await api.post(`/workflows/${wf.id}/test`, {});
  if (testResult.executionId) {
    success(`Execution started: ${testResult.executionId}`);
  }

  await runCleanup();
  success("Done — branching router tested");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Pattern: Loop Processor
 *
 * Builds: agentInputTrigger → loop { loopStart → textFormatter → customScript } → outputNode
 * Shows: loopStart auto-creation, parentId for inner nodes, scope rules
 *
 * IMPORTANT GOTCHAS:
 * - Loop creation auto-creates a loopStart child — find it in response.data.children
 * - Inner nodes MUST set parentId: loopNode.id
 * - Inner→root edges are rejected (SCOPE_VIOLATION)
 * - Variable references to loop data use the LOOP node ID (not loopStart)
 */

import { createClient } from "../../../shared/api-client";
import { assertDefined, onCleanup, runCleanup, success } from "../../../shared/helpers";

async function main() {
  const api = createClient();

  const { data: wf } = await api.post("/workflows", {
    name: "Batch Processor Demo",
    description: "Loops over items and processes each one"
  });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  // ── Trigger ───────────────────────────────────────────────────────────
  await api.put(`/workflows/${wf.id}/trigger`, { type: "agentInputTrigger" });
  const { data: detail } = await api.get(`/workflows/${wf.id}`);
  const triggerId = detail.nodes.find((n: any) => n.type === "agentInputTrigger")!.id;

  // ── Loop node — CRITICAL: auto-creates loopStart in children ──────────
  const { data: loopNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "loop" });
  const loopStartId = loopNode.children?.find((c: any) => c.type === "loopStart")?.id;
  assertDefined(loopStartId, "loopStart should be auto-created in children array");
  success(`Loop: ${loopNode.id.slice(0, 8)}, loopStart: ${loopStartId!.slice(0, 8)}`);

  // ── Configure iteration source — MUST use handler: "variable" ──────────
  await api.patch(`/workflows/${wf.id}/nodes/${loopNode.id}`, {
    data: {
      iterationsSetup: {
        items: {
          handler: "variable",
          variable: `{{${triggerId}.body.items}}`
        }
      }
    }
  });

  // ── Inner nodes — MUST use parentId to place inside loop ──────────────
  const { data: innerFormat } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter",
    parentId: loopNode.id // <-- REQUIRED: places node inside loop scope
  });
  await api.patch(`/workflows/${wf.id}/nodes/${innerFormat.id}`, {
    data: {
      text: `Processing item from {{${loopNode.id}}}`, // Reference LOOP node, not loopStart
      label: "Format Item"
    }
  });

  const { data: innerScript } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "customScript",
    parentId: loopNode.id
  });
  await api.patch(`/workflows/${wf.id}/nodes/${innerScript.id}`, {
    data: {
      code: "function func(input) { return { processed: true, item: input }; }",
      label: "Process Item"
    }
  });
  success("Inner nodes created with parentId inside loop scope");

  // ── Output node (root scope) ──────────────────────────────────────────
  const { data: output } = await api.post(`/workflows/${wf.id}/nodes`, { type: "outputNode" });
  await api.patch(`/workflows/${wf.id}/nodes/${output.id}`, {
    data: { instructions: `{{${loopNode.id}}}` }
  });

  // ── Edges ─────────────────────────────────────────────────────────────
  // Root: trigger → loop, loop → output
  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: loopNode.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: loopNode.id, target: output.id });

  // Inner: loopStart → format → script
  await api.post(`/workflows/${wf.id}/edges`, { source: loopStartId, target: innerFormat.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: innerFormat.id, target: innerScript.id });
  success("Edges: trigger → loop { loopStart → format → script } → output");

  // ── Layout + Validate ─────────────────────────────────────────────────
  await api.post(`/workflows/${wf.id}/layout`);
  const { data: validation } = await api.get(`/workflows/${wf.id}/validate`);
  success(`Validation: isValid=${validation.isValid}`);

  // ── Overview — verify structure ───────────────────────────────────────
  const { data: overview } = await api.get(`/workflows/${wf.id}/overview`);
  success(`Overview: ${overview.nodeCount} nodes, ${overview.edgeCount} edges`);

  await runCleanup();
  success("Done — loop processor with inner nodes");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Pattern: Kitchen Sink — Everything Combined
 *
 * Builds the most complex workflow possible via API:
 *   agentInputTrigger → textFormatter → branching (3 branches)
 *     → Branch A: customScript → outputNode
 *     → Branch B: loop { loopStart → textFormatter } → (loop output)
 *     → Branch C: textFormatter
 *
 * Shows: triggers, text formatting, branching, loops, variables, validation, testing
 */

import { createClient } from "../../../shared/api-client";
import {
  assertDefined,
  log,
  onCleanup,
  pollUntil,
  runCleanup,
  success} from "../../../shared/helpers";

async function main() {
  const api = createClient();
  log("kitchen-sink", "Building complex workflow...");

  const { data: wf } = await api.post("/workflows", {
    name: "Kitchen Sink Demo",
    description: "Complex workflow with branching, loops, and variables"
  });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  // ── Trigger ───────────────────────────────────────────────────────────
  await api.put(`/workflows/${wf.id}/trigger`, { type: "agentInputTrigger" });
  const { data: d } = await api.get(`/workflows/${wf.id}`);
  const triggerId = d.nodes.find((n: any) => n.type === "agentInputTrigger")!.id;

  // ── Text formatter after trigger ──────────────────────────────────────
  const { data: formatter } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter"
  });
  await api.patch(`/workflows/${wf.id}/nodes/${formatter.id}`, {
    data: { text: `Input: {{${triggerId}}}`, label: "Parse Input" }
  });

  // ── Branching ─────────────────────────────────────────────────────────
  const { data: branching } = await api.post(`/workflows/${wf.id}/nodes`, { type: "branching" });
  await api.patch(`/workflows/${wf.id}/nodes/${branching.id}`, {
    data: { instructions: "Route based on the input data type", label: "Router" }
  });

  await api.post(`/workflows/${wf.id}/nodes/${branching.id}/branches`, {
    name: "Process",
    description: "Custom processing"
  });
  await api.post(`/workflows/${wf.id}/nodes/${branching.id}/branches`, {
    name: "Batch",
    description: "Loop processing"
  });
  await api.post(`/workflows/${wf.id}/nodes/${branching.id}/branches`, {
    name: "Simple",
    description: "Direct output"
  });

  const { data: bl } = await api.get(`/workflows/${wf.id}/nodes/${branching.id}/branches`);
  const branches = bl.branches ?? bl;
  const bIds = branches.map((b: any) => b.id ?? b._id ?? b.key);
  success(`Branching: ${branches.length} branches`);

  // ── Branch A: customScript → outputNode ───────────────────────────────
  const { data: scriptNode } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "customScript"
  });
  await api.patch(`/workflows/${wf.id}/nodes/${scriptNode.id}`, {
    data: {
