    }
  });
  const { data: outputA } = await api.post(`/workflows/${wf.id}/nodes`, { type: "outputNode" });
  await api.patch(`/workflows/${wf.id}/nodes/${outputA.id}`, {
    data: { instructions: `{{${scriptNode.id}}}`, label: "Process Output" }
  });

  // ── Branch B: loop with inner nodes ───────────────────────────────────
  const { data: loopNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "loop" });
  const loopStartId = loopNode.children?.find((c: any) => c.type === "loopStart")?.id;
  assertDefined(loopStartId, "loopStart");

  const { data: innerText } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter",
    parentId: loopNode.id
  });
  await api.patch(`/workflows/${wf.id}/nodes/${innerText.id}`, {
    data: { text: `Batch item: {{${loopNode.id}}}`, label: "Format Batch Item" }
  });

  // ── Branch C: simple textFormatter ────────────────────────────────────
  const { data: simpleText } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter"
  });
  await api.patch(`/workflows/${wf.id}/nodes/${simpleText.id}`, {
    data: { text: `Simple output: {{${formatter.id}}}`, label: "Simple Path" }
  });

  success("All nodes created");

  // ── Wire ALL edges ────────────────────────────────────────────────────
  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: formatter.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: formatter.id, target: branching.id });

  // Branching → branches (with sourceHandle)
  await api.post(`/workflows/${wf.id}/edges`, {
    source: branching.id,
    target: scriptNode.id,
    sourceHandle: bIds[0]
  });
  await api.post(`/workflows/${wf.id}/edges`, {
    source: branching.id,
    target: loopNode.id,
    sourceHandle: bIds[1]
  });
  await api.post(`/workflows/${wf.id}/edges`, {
    source: branching.id,
    target: simpleText.id,
    sourceHandle: bIds[2]
  });

  // Branch A chain
  await api.post(`/workflows/${wf.id}/edges`, { source: scriptNode.id, target: outputA.id });

  // Loop internals
  await api.post(`/workflows/${wf.id}/edges`, { source: loopStartId, target: innerText.id });

  success("All edges wired");

  // ── Layout + Validate ─────────────────────────────────────────────────
  await api.post(`/workflows/${wf.id}/layout`);
  const { data: v } = await api.get(`/workflows/${wf.id}/validate`);
  success(`Validation: isValid=${v.isValid}, errors=${v.errors?.length ?? 0}`);

  // ── Overview ──────────────────────────────────────────────────────────
  const { data: overview } = await api.get(`/workflows/${wf.id}/overview`);
  success(`Overview: ${overview.nodeCount} nodes, ${overview.edgeCount} edges`);

  // ── Available variables for the output node ───────────────────────────
  const { data: vars } = await api.get(
    `/workflows/${wf.id}/nodes/${outputA.id}/available-variables`
  );
  success(`Output sees ${vars.variables.length} upstream variables`);

  // ── Test ──────────────────────────────────────────────────────────────
  const { data: testResult } = await api.post(`/workflows/${wf.id}/test`, {});
  if (testResult.executionId) {
    const exec = await pollUntil(
      async () => (await api.get(`/workflows/${wf.id}/executions/${testResult.executionId}`)).data,
      (d: any) => ["COMPLETED", "FAILED", "CANCELLED"].includes(d.status),
      { label: "kitchen-sink", timeoutMs: 60000 }
    );
    success(`Execution: ${exec.status}`);
  }

  await runCleanup();
  success("Done — kitchen sink: trigger → format → branch → [script+output, loop, simple]");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Pattern: Variable References
 *
 * Shows: available-variables, validate-variables, output-format endpoints
 * CRITICAL: Variables use node UUIDs, not type names!
 *   ✓ {{a1b2c3d4-e5f6-7890-abcd-ef1234567890.body.name}}
 *   ✗ {{trigger.body.name}}  ← WRONG
 */

import { createClient } from "../../../shared/api-client";
import {
  assert,
  assertDefined,
  assertEqual,
  onCleanup,
  runCleanup,
  success
} from "../../../shared/helpers";

async function main() {
  const api = createClient();

  const { data: wf } = await api.post("/workflows", { name: "Variables Demo" });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  // Build: trigger → formatter → script → output
  await api.put(`/workflows/${wf.id}/trigger`, { type: "agentInputTrigger" });
  const { data: d } = await api.get(`/workflows/${wf.id}`);
  const triggerId = d.nodes.find((n: any) => n.type === "agentInputTrigger")!.id;

  const { data: formatter } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter"
  });
  const { data: script } = await api.post(`/workflows/${wf.id}/nodes`, { type: "customScript" });
  const { data: output } = await api.post(`/workflows/${wf.id}/nodes`, { type: "outputNode" });

  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: formatter.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: formatter.id, target: script.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: script.id, target: output.id });

  // ── 1. Check available variables for the formatter ────────────────────
  const { data: formatterVars } = await api.get(
    `/workflows/${wf.id}/nodes/${formatter.id}/available-variables`
  );
  assert(formatterVars.variables.length >= 1, "formatter should see trigger");
  const triggerVar = formatterVars.variables.find((v: any) => v.source === triggerId);
  assertDefined(triggerVar, "trigger should be in available variables");
  success(
    `Formatter sees ${formatterVars.variables.length} upstream variable(s): ${triggerVar!.label}`
  );

  // ── 2. Configure with CORRECT variable references ─────────────────────
  // IMPORTANT: Use the actual node UUID, not "trigger" or type name
  await api.patch(`/workflows/${wf.id}/nodes/${formatter.id}`, {
    data: { text: `Input received: {{${triggerId}}}`, label: "Format Input" }
  });

  await api.patch(`/workflows/${wf.id}/nodes/${script.id}`, {
    data: { code: "function func(input) { return { result: input }; }", label: "Process" }
  });

  // ── 3. Check available variables for the output (sees all upstream) ───
  const { data: outputVars } = await api.get(
    `/workflows/${wf.id}/nodes/${output.id}/available-variables`
  );
  success(`Output sees ${outputVars.variables.length} upstream variables:`);
  for (const v of outputVars.variables) {
    const childCount = v.children?.length ?? 0;
    success(
      `  - ${v.label} (${v.path.slice(0, 12)}...) ${childCount > 0 ? `with ${childCount} properties` : ""}`
    );
  }

  // Configure output to reference the script node
  await api.patch(`/workflows/${wf.id}/nodes/${output.id}`, {
    data: { instructions: `{{${script.id}}}` }
  });

  // ── 4. Validate variables for formatter ───────────────────────────────
  const { data: formatterValidation } = await api.get(
    `/workflows/${wf.id}/nodes/${formatter.id}/validate-variables`
  );
  assertEqual(formatterValidation.valid, true, "formatter variables should be valid");
  success(`Formatter variable validation: valid=${formatterValidation.valid}`);

  // ── 5. Validate variables for output ──────────────────────────────────
  const { data: outputValidation } = await api.get(
    `/workflows/${wf.id}/nodes/${output.id}/validate-variables`
  );
  assertEqual(outputValidation.valid, true, "output variables should be valid");
  success(`Output variable validation: valid=${outputValidation.valid}`);

  // ── 6. Check output format (schema) of a node ────────────────────────
  const { data: triggerFormat } = await api.get(
    `/workflows/${wf.id}/nodes/${triggerId}/output-format`
  );
  success(
    `Trigger output format: ${JSON.stringify(triggerFormat.schema ?? triggerFormat).slice(0, 100)}`
  );

  // ── 7. Full workflow validation (includes variable checks) ────────────
  const { data: fullValidation } = await api.get(`/workflows/${wf.id}/validate`);
  const varIssues = fullValidation.variableIssues ?? [];
  success(
    `Workflow validation: isValid=${fullValidation.isValid}, variableIssues=${varIssues.length}`
  );

  await runCleanup();
  success("Done — variable references validated end-to-end");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

