#!/usr/bin/env npx tsx
/**
 * Template: Data Sync Pipeline
 *
 * A realistic workflow for batch data synchronization:
 *   agentInputTrigger → customScript (fetch data) → loop { loopStart → textFormatter (transform) }
 *     → outputNode (summary)
 *
 * Shows: script for data fetching, loop for batch processing, variable references
 */

import { createClient } from "../../../shared/api-client";
import {
  assertDefined,
  log,
  onCleanup,
  pollUntil,
  runCleanup,
  success} from "../../../shared/helpers";

async function main() {
  const api = createClient();
  log("template", "Building Data Sync Pipeline...");

  const { data: wf } = await api.post("/workflows", {
    name: "Data Sync Pipeline",
    description: "Fetches data, iterates over records, transforms each, and outputs summary"
  });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  // ── Trigger ───────────────────────────────────────────────────────────
  await api.put(`/workflows/${wf.id}/trigger`, { type: "agentInputTrigger" });
  const { data: d } = await api.get(`/workflows/${wf.id}`);
  const triggerId = d.nodes.find((n: any) => n.type === "agentInputTrigger")!.id;

  // ── Fetch data script ─────────────────────────────────────────────────
  const { data: fetcher } = await api.post(`/workflows/${wf.id}/nodes`, { type: "customScript" });
  await api.patch(`/workflows/${wf.id}/nodes/${fetcher.id}`, {
    data: {
      code: `function func(input) {
  // Simulate fetching records from an external source
  const records = [
    { id: 1, name: "Record A", value: 100 },
    { id: 2, name: "Record B", value: 200 },
    { id: 3, name: "Record C", value: 300 }
  ];
  return { records, fetchedAt: new Date().toISOString(), count: records.length };
}`,
      label: "Fetch Records"
    }
  });

  // ── Loop over records ─────────────────────────────────────────────────
  const { data: loopNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "loop" });
  const loopStartId = loopNode.children?.find((c: any) => c.type === "loopStart")?.id;
  assertDefined(loopStartId, "loopStart");

  // Inner: transform each record
  const { data: transformer } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter",
    parentId: loopNode.id
  });
  await api.patch(`/workflows/${wf.id}/nodes/${transformer.id}`, {
    data: {
      text: `Synced record from {{${loopNode.id}}}`,
      label: "Transform Record"
    }
  });

  // ── Summary output ────────────────────────────────────────────────────
  const { data: output } = await api.post(`/workflows/${wf.id}/nodes`, { type: "outputNode" });
  await api.patch(`/workflows/${wf.id}/nodes/${output.id}`, {
    data: { instructions: `{{${loopNode.id}}}`, label: "Sync Summary" }
  });

  // ── Wire edges ────────────────────────────────────────────────────────
  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: fetcher.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: fetcher.id, target: loopNode.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: loopStartId, target: transformer.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: loopNode.id, target: output.id });
  await api.post(`/workflows/${wf.id}/layout`);
  success("Built: trigger → fetch → loop { start → transform } → output");

  // ── Validate ──────────────────────────────────────────────────────────
  const { data: v } = await api.get(`/workflows/${wf.id}/validate`);
  success(`Validation: isValid=${v.isValid}`);

  // ── Test ──────────────────────────────────────────────────────────────
  const { data: test } = await api.post(`/workflows/${wf.id}/test`, {});
  if (test.executionId) {
    const exec = await pollUntil(
      async () => (await api.get(`/workflows/${wf.id}/executions/${test.executionId}`)).data,
      (d: any) => ["COMPLETED", "FAILED", "CANCELLED"].includes(d.status),
      { label: "data-sync", timeoutMs: 60000 }
    );
    success(`Execution: ${exec.status}`);

    try {
      const { data: fetchResult } = await api.get(
        `/workflows/${wf.id}/executions/${test.executionId}/nodes/${fetcher.id}`
      );
      if (fetchResult.output) {
        success(`  Fetched: ${JSON.stringify(fetchResult.output).slice(0, 150)}`);
      }
    } catch {}
  }

  await runCleanup();
  success("Done — Data Sync Pipeline template");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Template: Lead Processing Pipeline
 *
 * A realistic workflow that receives lead data, qualifies leads,
 * and routes them to different handlers based on priority.
 *
 * Structure:
 *   agentInputTrigger → textFormatter (parse) → branching (qualify)
 *     → Branch "Hot Lead": textFormatter (urgent alert)
 *     → Branch "Warm Lead": textFormatter (follow-up)
 *     → Branch "Cold Lead": textFormatter (nurture)
 *
 * Each branch terminates independently.
 * Uses variable references to pass data between nodes.
 */

import { createClient } from "../../../shared/api-client";
import {
  log,
  onCleanup,
  pollUntil,
  runCleanup,
  success} from "../../../shared/helpers";

async function main() {
  const api = createClient();
  log("template", "Building Lead Processing Pipeline...");

  // ── 1. Create workflow ────────────────────────────────────────────────
  const { data: wf } = await api.post("/workflows", {
    name: "Lead Processing Pipeline",
    description: "Qualifies incoming leads and routes them to appropriate handlers"
  });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  // ── 2. Agent input trigger (with parameter schema for lead data) ──────
  await api.put(`/workflows/${wf.id}/trigger`, { type: "agentInputTrigger" });
  const { data: d } = await api.get(`/workflows/${wf.id}`);
  const triggerId = d.nodes.find((n: any) => n.type === "agentInputTrigger")!.id;
  success("Trigger: agentInputTrigger (receives lead data)");

  // ── 3. Parse/format the incoming lead ─────────────────────────────────
  const { data: parser } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  await api.patch(`/workflows/${wf.id}/nodes/${parser.id}`, {
    data: {
      text: `Lead received: {{${triggerId}}}`,
      label: "Parse Lead Data"
    }
  });

  // ── 4. Branching node for qualification ───────────────────────────────
  const { data: branching } = await api.post(`/workflows/${wf.id}/nodes`, { type: "branching" });
  await api.patch(`/workflows/${wf.id}/nodes/${branching.id}`, {
    data: {
      instructions:
        "Route the lead based on priority. If the lead score is high or they expressed urgency, route to Hot Lead. If moderate interest, route to Warm Lead. Otherwise, route to Cold Lead.",
      label: "Qualify Lead"
    }
  });

  // Create 3 branches
  await api.post(`/workflows/${wf.id}/nodes/${branching.id}/branches`, {
    name: "Hot Lead",
    description: "High score or expressed urgency"
  });
  await api.post(`/workflows/${wf.id}/nodes/${branching.id}/branches`, {
    name: "Warm Lead",
    description: "Moderate interest, needs follow-up"
  });
  await api.post(`/workflows/${wf.id}/nodes/${branching.id}/branches`, {
    name: "Cold Lead",
    description: "Low interest, add to nurture sequence"
  });

  const { data: branchList } = await api.get(`/workflows/${wf.id}/nodes/${branching.id}/branches`);
  const branches = branchList.branches ?? branchList;
  const branchIds = branches.map((b: any) => b.id ?? b._id ?? b.key);
  success(`Branching: 3 branches — ${branches.map((b: any) => b.name).join(", ")}`);

  // ── 5. Action nodes per branch ────────────────────────────────────────
  const { data: hotHandler } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter"
  });
  await api.patch(`/workflows/${wf.id}/nodes/${hotHandler.id}`, {
    data: {
      text: `URGENT: Hot lead detected! Data: {{${parser.id}}}. Assign to senior sales rep immediately.`,
      label: "Hot Lead Alert"
    }
  });

  const { data: warmHandler } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter"
  });
  await api.patch(`/workflows/${wf.id}/nodes/${warmHandler.id}`, {
    data: {
      text: `Follow-up needed: Warm lead from {{${parser.id}}}. Schedule a demo within 48 hours.`,
      label: "Warm Lead Follow-up"
    }
  });

  const { data: coldHandler } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter"
  });
  await api.patch(`/workflows/${wf.id}/nodes/${coldHandler.id}`, {
    data: {
      text: `Add to nurture: Cold lead from {{${parser.id}}}. Add to email drip campaign.`,
      label: "Cold Lead Nurture"
    }
  });
  success("Created 3 handler nodes (hot, warm, cold)");

  // ── 6. Wire all edges ─────────────────────────────────────────────────
  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: parser.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: parser.id, target: branching.id });
  await api.post(`/workflows/${wf.id}/edges`, {
    source: branching.id,
    target: hotHandler.id,
    sourceHandle: branchIds[0]
  });
  await api.post(`/workflows/${wf.id}/edges`, {
    source: branching.id,
    target: warmHandler.id,
    sourceHandle: branchIds[1]
  });
  await api.post(`/workflows/${wf.id}/edges`, {
    source: branching.id,
    target: coldHandler.id,
    sourceHandle: branchIds[2]
  });
  success("Edges: trigger → parse → qualify → [hot, warm, cold]");

  // ── 7. Layout + Validate ──────────────────────────────────────────────
  await api.post(`/workflows/${wf.id}/layout`);
  const { data: v } = await api.get(`/workflows/${wf.id}/validate`);
  success(
    `Validation: isValid=${v.isValid}, errors=${v.errors?.length ?? 0}, variableIssues=${(v.variableIssues ?? []).length}`
  );

  // ── 8. Test the workflow ──────────────────────────────────────────────
  const { data: testResult } = await api.post(`/workflows/${wf.id}/test`, {});
  if (testResult.executionId) {
    const execution = await pollUntil(
      async () => (await api.get(`/workflows/${wf.id}/executions/${testResult.executionId}`)).data,
      (d: any) => ["COMPLETED", "FAILED", "CANCELLED"].includes(d.status),
      { label: "pipeline-test", timeoutMs: 60000 }
    );
    success(`Execution: ${execution.status}`);

    // Show which branch was taken
    for (const [label, id] of [
      ["Hot", hotHandler.id],
      ["Warm", warmHandler.id],
      ["Cold", coldHandler.id]
    ]) {
      try {
        const { data: nr } = await api.get(
          `/workflows/${wf.id}/executions/${testResult.executionId}/nodes/${id}`
        );
        if (nr.status === "COMPLETED") success(`  → ${label} branch executed`);
        else if (nr.status === "SKIPPED") success(`  → ${label} branch skipped`);
      } catch {}
    }
  }

  // ── 9. Final overview ─────────────────────────────────────────────────
  const { data: overview } = await api.get(`/workflows/${wf.id}/overview`);
  success(`Final: ${overview.nodeCount} nodes, ${overview.edgeCount} edges`);

  await runCleanup();
  success("Done — Lead Processing Pipeline template");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

