 *
 * Demonstrates: POST /nodes/:nodeId/test, GET /executions/:id/nodes/:nodeId
 * Shows: Node-level testing, execution polling, result inspection
 */

import { createClient } from "../../../shared/api-client";
import { assertDefined, onCleanup, pollUntil, runCleanup, success } from "../../../shared/helpers";

async function main() {
  const api = createClient();

  // Setup: workflow with trigger + textFormatter
  const { data: wf } = await api.post("/workflows", { name: "Node Test Demo" });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  await api.put(`/workflows/${wf.id}/trigger`, { type: "agentInputTrigger" });
  const { data: d } = await api.get(`/workflows/${wf.id}`);
  const triggerId = d.nodes.find((n: any) => n.type === "agentInputTrigger")!.id;

  const { data: textNode } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  await api.patch(`/workflows/${wf.id}/nodes/${textNode.id}`, {
    data: { text: `Hello from test! Trigger: {{${triggerId}}}`, label: "Greeting" }
  });
  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: textNode.id });
  success("Setup: trigger → textFormatter");

  // ── Test the textFormatter node ───────────────────────────────────────
  const { data: testResult } = await api.post(
    `/workflows/${wf.id}/nodes/${textNode.id}/test`,
    {} // optional input
  );

  const execId = testResult.executionId ?? testResult.testExecutionId;
  assertDefined(execId, "execution ID from node test");
  success(`Node test started: ${execId}`);

  // ── Poll for completion ───────────────────────────────────────────────
  const status = await pollUntil(
    async () => {
      const { data } = await api.get(`/workflows/${wf.id}/executions/${execId}`);
      return data;
    },
    (d: any) => ["COMPLETED", "FAILED", "CANCELLED"].includes(d.status),
    { label: "node-test", timeoutMs: 30000 }
