/**
 * Testing — Test a full workflow
 *
 * Demonstrates: POST /workflows/:id/test, execution polling, per-node results
 */

import { createClient } from "../../../shared/api-client";
import { assertDefined, onCleanup, pollUntil, runCleanup, success } from "../../../shared/helpers";

async function main() {
  const api = createClient();

  // ── Build a complete workflow ──────────────────────────────────────────
  const { data: wf } = await api.post("/workflows", { name: "Full Workflow Test" });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  await api.put(`/workflows/${wf.id}/trigger`, { type: "agentInputTrigger" });
  const { data: d } = await api.get(`/workflows/${wf.id}`);
  const triggerId = d.nodes.find((n: any) => n.type === "agentInputTrigger")!.id;

  const { data: n1 } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  await api.patch(`/workflows/${wf.id}/nodes/${n1.id}`, {
    data: { text: `Step 1: {{${triggerId}}}`, label: "Step 1" }
  });

  const { data: n2 } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  await api.patch(`/workflows/${wf.id}/nodes/${n2.id}`, {
    data: { text: `Step 2: {{${n1.id}}}`, label: "Step 2" }
  });

  const { data: output } = await api.post(`/workflows/${wf.id}/nodes`, { type: "outputNode" });
  await api.patch(`/workflows/${wf.id}/nodes/${output.id}`, {
    data: { instructions: `{{${n2.id}}}` }
  });

  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: n1.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: n1.id, target: n2.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: n2.id, target: output.id });
  success("Built: trigger → step1 → step2 → output");

  // ── Start full workflow test ──────────────────────────────────────────
  const { data: testResult } = await api.post(`/workflows/${wf.id}/test`, {});
  const execId = testResult.executionId;
  assertDefined(execId, "executionId");
  success(`Workflow test started: ${execId}`);

  // ── Poll execution until done ─────────────────────────────────────────
  const execution = await pollUntil(
    async () => {
      const { data } = await api.get(`/workflows/${wf.id}/executions/${execId}`);
      return data;
    },
    (d: any) => ["COMPLETED", "FAILED", "CANCELLED"].includes(d.status),
    { label: "workflow-test", timeoutMs: 60000 }
  );
  success(`Workflow execution: ${execution.status}`);

  // ── Get per-node results ──────────────────────────────────────────────
  const nodeIds = [
    { id: triggerId, label: "Trigger" },
    { id: n1.id, label: "Step 1" },
    { id: n2.id, label: "Step 2" },
    { id: output.id, label: "Output" }
