        ? JSON.stringify(nodeResult.output).slice(0, 150)
        : "(no output)";
      success(`  ${label}: ${nodeResult.status} → ${out}`);
    } catch {
      success(`  ${label}: (result not available)`);
    }
  }

  await runCleanup();
  success("Done — full workflow tested with per-node results");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Testing — Poll execution status and stop
 *
 * Demonstrates: Execution polling pattern, all statuses, stop execution
 * Shows: PENDING → RUNNING → COMPLETED/FAILED/CANCELLED
 */

import { createClient, NexusApiError } from "../../../shared/api-client";
import { assertDefined, log,onCleanup, runCleanup, sleep, success } from "../../../shared/helpers";

async function main() {
  const api = createClient();

  // Build a workflow that takes a few seconds to execute
  const { data: wf } = await api.post("/workflows", { name: "Execution Polling Demo" });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  await api.put(`/workflows/${wf.id}/trigger`, { type: "agentInputTrigger" });
  const { data: d } = await api.get(`/workflows/${wf.id}`);
  const triggerId = d.nodes.find((n: any) => n.type === "agentInputTrigger")!.id;

  // Chain of text formatters to create some execution time
  const { data: n1 } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  await api.patch(`/workflows/${wf.id}/nodes/${n1.id}`, {
    data: { text: `Step 1: {{${triggerId}}}` }
  });

  const { data: n2 } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  await api.patch(`/workflows/${wf.id}/nodes/${n2.id}`, { data: { text: `Step 2: {{${n1.id}}}` } });

  const { data: n3 } = await api.post(`/workflows/${wf.id}/nodes`, { type: "textFormatter" });
  await api.patch(`/workflows/${wf.id}/nodes/${n3.id}`, { data: { text: `Step 3: {{${n2.id}}}` } });

  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: n1.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: n1.id, target: n2.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: n2.id, target: n3.id });
  success("Built: trigger → step1 → step2 → step3");

  // ── Start execution ───────────────────────────────────────────────────
  const { data: testResult } = await api.post(`/workflows/${wf.id}/test`, {});
  const execId = testResult.executionId;
  assertDefined(execId, "executionId");
  success(`Execution started: ${execId}`);

  // ── Manual polling loop (showing all possible statuses) ───────────────
  const startTime = Date.now();
  const TIMEOUT = 60_000;
  const INTERVAL = 2_000;
  let finalStatus = "UNKNOWN";

  while (Date.now() - startTime < TIMEOUT) {
    const { data: execution } = await api.get(`/workflows/${wf.id}/executions/${execId}`);
    const elapsed = Math.round((Date.now() - startTime) / 1000);

    switch (execution.status) {
      case "PENDING":
        log("poll", `[${elapsed}s] PENDING — waiting for execution to start...`);
        break;
      case "RUNNING":
        log("poll", `[${elapsed}s] RUNNING — workflow is executing...`);
        break;
      case "COMPLETED":
        success(`[${elapsed}s] COMPLETED — workflow finished successfully`);
        finalStatus = "COMPLETED";
        break;
      case "FAILED":
        success(`[${elapsed}s] FAILED — workflow encountered an error`);
        finalStatus = "FAILED";
        break;
      case "CANCELLED":
        success(`[${elapsed}s] CANCELLED — workflow was stopped`);
        finalStatus = "CANCELLED";
        break;
      default:
        log("poll", `[${elapsed}s] Unknown status: ${execution.status}`);
    }

    if (["COMPLETED", "FAILED", "CANCELLED"].includes(execution.status)) break;
    await sleep(INTERVAL);
  }

  if (finalStatus === "UNKNOWN") {
    log("poll", "Timed out — attempting to stop execution...");

    // ── Stop a running execution ──────────────────────────────────────
    try {
      await api.post(`/workflows/${wf.id}/executions/${execId}/stop`);
      success("Execution stopped");
    } catch (err) {
      if (err instanceof NexusApiError) {
        success(`Stop response: ${err.status} ${err.code} (may already be done)`);
      }
    }
  }

  // ── Final status check ────────────────────────────────────────────────
  const { data: finalExec } = await api.get(`/workflows/${wf.id}/executions/${execId}`);
  success(`Final status: ${finalExec.status}`);
  success(`Started: ${finalExec.startedAt}`);
  success(`Completed: ${finalExec.completedAt ?? "(still running)"}`);

  // Show node results
  const nodeResults = finalExec.nodeResults ?? {};
  for (const [nodeId, result] of Object.entries(nodeResults)) {
    const r = result as any;
    success(`  Node ${nodeId.slice(0, 8)}: ${r.status}`);
  }

  await runCleanup();
  success("Done — execution polling with all statuses");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

#!/usr/bin/env npx tsx
/**
 * Testing — Validate a workflow
 *
 * Demonstrates: GET /validate, fix issues programmatically, re-validate
 * Shows: isValid, readyToPublish, readyToTest, nodeIssues, graphIssues, variableIssues
 */

import { createClient } from "../../../shared/api-client";
import { assertEqual, onCleanup, runCleanup, success } from "../../../shared/helpers";

async function main() {
  const api = createClient();

  // ── Create workflow with known issues ──────────────────────────────────
  const { data: wf } = await api.post("/workflows", { name: "Validation Demo" });
  onCleanup(async () => {
    await api.del(`/workflows/${wf.id}`).catch(() => {});
  });

  // Don't replace trigger — keep selectTrigger (not publishable)
  // Add unconfigured nodes (incomplete config)
  const { data: formatter } = await api.post(`/workflows/${wf.id}/nodes`, {
    type: "textFormatter"
  });
  // Don't configure text field — will be "incomplete"

  const { data: script } = await api.post(`/workflows/${wf.id}/nodes`, { type: "customScript" });
  // Don't configure code field — will be "incomplete"

  // Don't connect edges — disconnected nodes

  // ── Validate — expect issues ──────────────────────────────────────────
  const { data: v1 } = await api.get(`/workflows/${wf.id}/validate`);
  success(`Initial validation:`);
  success(`  isValid: ${v1.isValid}`);
  success(`  readyToPublish: ${v1.readyToPublish}`);
  success(`  readyToTest: ${v1.readyToTest}`);
  success(`  errors: ${v1.errors?.length ?? 0}`);
  success(`  warnings: ${v1.warnings?.length ?? 0}`);
  success(`  graphIssues: ${v1.graphIssues?.length ?? 0}`);

  // Show specific issues
  for (const err of (v1.errors ?? []).slice(0, 5)) {
    success(`  ⚠ ${err.nodeLabel ?? err.nodeType}: ${err.message}`);
  }
  for (const issue of (v1.graphIssues ?? []).slice(0, 5)) {
    success(`  ⚠ Graph: ${issue.message}`);
  }

  // ── Fix issues programmatically ───────────────────────────────────────
  // 1. Replace trigger with webhookTrigger
  await api.put(`/workflows/${wf.id}/trigger`, { type: "agentInputTrigger" });
  const { data: d } = await api.get(`/workflows/${wf.id}`);
  const triggerId = d.nodes.find((n: any) => n.type === "agentInputTrigger")!.id;
  success("Fix 1: Replaced selectTrigger with agentInputTrigger");

  // 2. Configure nodes
  await api.patch(`/workflows/${wf.id}/nodes/${formatter.id}`, {
    data: { text: `Processing: {{${triggerId}}}` }
  });
  await api.patch(`/workflows/${wf.id}/nodes/${script.id}`, {
    data: { code: "function func(input) { return { ok: true }; }" }
  });
  success("Fix 2: Configured both nodes");

  // 3. Add output + connect edges
  const { data: output } = await api.post(`/workflows/${wf.id}/nodes`, { type: "outputNode" });
  await api.patch(`/workflows/${wf.id}/nodes/${output.id}`, {
    data: { instructions: `{{${script.id}}}` }
  });
  await api.post(`/workflows/${wf.id}/edges`, { source: triggerId, target: formatter.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: formatter.id, target: script.id });
  await api.post(`/workflows/${wf.id}/edges`, { source: script.id, target: output.id });
  success("Fix 3: Added output + connected all edges");

  // ── Re-validate — should be clean ─────────────────────────────────────
  const { data: v2 } = await api.get(`/workflows/${wf.id}/validate`);
  success(`\nAfter fixes:`);
  success(`  isValid: ${v2.isValid}`);
  success(`  readyToPublish: ${v2.readyToPublish}`);
  success(`  readyToTest: ${v2.readyToTest}`);
  success(`  errors: ${v2.errors?.length ?? 0}`);
  success(`  variableIssues: ${(v2.variableIssues ?? []).length}`);

  assertEqual(v2.errors?.length ?? 0, 0, "should have 0 errors after fix");

  await runCleanup();
  success("Done — validation workflow: identify issues → fix → re-validate");
}

main().catch((e) => {
  console.error(e);
  runCleanup().then(() => process.exit(1));
});

