/**
 * Find and debug a failed workflow execution.
 * Run: npx tsx examples/01-debug-failed-run.ts
 */
const baseUrl = process.env.NEXUS_BASE_URL ?? "http://localhost:3001";
const apiKey = process.env.NEXUS_API_KEY ?? "nxs_test";

async function api(method: string, path: string) {
  const res = await fetch(`${baseUrl}/api/public/v1${path}`, {
    method,
    headers: { "api-key": apiKey }
  });
  return res.json();
}

async function main() {
  // Find failed executions
  const { data: execs } = await api("GET", "/workflows/executions?status=FAILED&limit=5");
  if (!execs?.length) {
    console.log("No failed executions");
    return;
  }

  const exec = execs[0];
  console.log(`Failed execution: ${exec.id} (workflow: ${exec.workflowName})`);
  console.log(`Started: ${exec.startedAt}, Error: ${exec.error}`);

  // Get the execution graph to find which node failed
  const { data: graph } = await api("GET", `/workflows/executions/${exec.id}/graph`);
  const failedNodes = graph.nodes.filter((n: any) => n.status === "FAILED");
  console.log(`\nFailed nodes (${failedNodes.length}):`);
  for (const node of failedNodes) {
    console.log(`  - ${node.label} (${node.nodeType}): ${node.error}`);
  }
}

main().catch(console.error);

