/**
 * Nexus Public API v1 — Lightweight HTTP Client
 *
 * Zero dependencies. Uses native fetch.
 * Every example script in the skills package imports this.
 *
 * Usage:
 *   import { createClient } from "../shared/api-client";
 *   const api = createClient();
 *   const { data } = await api.get("/workflows");
 */

const DEFAULT_BASE_URL = "http://localhost:3001";
const DEFAULT_API_KEY = process.env.NEXUS_API_KEY ?? "";

export interface ApiResponse<T = unknown> {
  success: boolean;
  data: T;
  meta?: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
    hasMore: boolean;
  };
}

export class NexusApiError extends Error {
  constructor(
    public readonly status: number,
    public readonly code: string,
    message: string,
    public readonly details?: unknown
  ) {
    super(`[${status}] ${code}: ${message}`);
    this.name = "NexusApiError";
  }
}

export interface ClientOptions {
  baseUrl?: string;
  apiKey?: string;
}

export function createClient(opts: ClientOptions = {}) {
  const baseUrl = opts.baseUrl ?? process.env.NEXUS_BASE_URL ?? DEFAULT_BASE_URL;
  const apiKey = opts.apiKey ?? DEFAULT_API_KEY;

  if (!apiKey) {
    throw new Error(
      "No API key. Set NEXUS_API_KEY env var or pass apiKey in options.\n" +
        "Get your key from the Nexus dashboard → Settings → API Keys."
    );
  }

  const prefix = `${baseUrl}/api/public/v1`;

  async function request<T>(method: string, path: string, body?: unknown): Promise<ApiResponse<T>> {
    const url = `${prefix}${path}`;
    const headers: Record<string, string> = {
      "api-key": apiKey,
      "Content-Type": "application/json"
    };

    const res = await fetch(url, {
      method,
      headers,
      body: body ? JSON.stringify(body) : undefined
    });

    // 204 No Content (DELETE responses)
    if (res.status === 204) {
      return { success: true, data: {} as T };
    }

    const json = await res.json().catch(() => null);

    if (!res.ok) {
      const err = json as any;
      throw new NexusApiError(
        res.status,
        err?.error?.code ?? err?.error ?? "UNKNOWN",
        err?.error?.message ?? err?.message ?? `HTTP ${res.status}`,
        err?.error?.details
      );
    }

    return json as ApiResponse<T>;
  }

  return {
    get: <T = any>(path: string) => request<T>("GET", path),
    post: <T = any>(path: string, body?: unknown) => request<T>("POST", path, body),
    patch: <T = any>(path: string, body?: unknown) => request<T>("PATCH", path, body),
    put: <T = any>(path: string, body?: unknown) => request<T>("PUT", path, body),
    del: <T = any>(path: string) => request<T>("DELETE", path),

    /** Upload file via FormData (for profile pictures, icons, documents) */
    async upload<T = any>(
      path: string,
      file: Blob | Buffer,
      fileName?: string
    ): Promise<ApiResponse<T>> {
      const url = `${prefix}${path}`;
      const form = new FormData();
      form.append("file", file instanceof Blob ? file : new Blob([file]), fileName ?? "file");

      const res = await fetch(url, {
        method: "POST",
        headers: { "api-key": apiKey },
        body: form
      });

      const json = await res.json().catch(() => null);
      if (!res.ok) {
        const err = json as any;
        throw new NexusApiError(
          res.status,
          err?.error?.code ?? "UPLOAD_ERROR",
          err?.error?.message ?? `Upload failed: HTTP ${res.status}`
        );
      }
      return json as ApiResponse<T>;
    }
  };
}

export type NexusClient = ReturnType<typeof createClient>;

/**
 * Shared helpers for Claude Code Skills examples.
 *
 * Provides assertions, polling, cleanup, and logging utilities.
 */

// ── Assertions ──────────────────────────────────────────────────────────────

export function assert(condition: boolean, message: string): asserts condition {
  if (!condition) throw new Error(`Assertion failed: ${message}`);
}

export function assertEqual<T>(actual: T, expected: T, label: string) {
  if (actual !== expected) {
    throw new Error(
      `${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`
    );
  }
}

export function assertDefined<T>(value: T | null | undefined, label: string): asserts value is T {
  if (value == null) throw new Error(`${label}: expected defined, got ${value}`);
}

export function assertContains<T>(arr: T[], predicate: (item: T) => boolean, label: string) {
  if (!arr.some(predicate)) throw new Error(`${label}: no matching item found in array`);
}

// ── Polling ─────────────────────────────────────────────────────────────────

export async function pollUntil<T>(
  fn: () => Promise<T>,
  predicate: (result: T) => boolean,
  opts: { intervalMs?: number; timeoutMs?: number; label?: string } = {}
): Promise<T> {
  const interval = opts.intervalMs ?? 3000;
  const timeout = opts.timeoutMs ?? 60000;
  const label = opts.label ?? "poll";
  const deadline = Date.now() + timeout;

  while (Date.now() < deadline) {
    const result = await fn();
    if (predicate(result)) return result;
    log(label, `waiting... (${Math.round((deadline - Date.now()) / 1000)}s remaining)`);
    await sleep(interval);
  }

  throw new Error(`${label}: timed out after ${timeout}ms`);
}

// ── Cleanup ─────────────────────────────────────────────────────────────────

const cleanupFns: Array<() => Promise<void>> = [];

export function onCleanup(fn: () => Promise<void>) {
  cleanupFns.push(fn);
}

export async function runCleanup() {
  for (const fn of cleanupFns.reverse()) {
    try {
      await fn();
    } catch {
      // best effort
    }
  }
  cleanupFns.length = 0;
}

// Auto-cleanup on exit
process.on("beforeExit", () => {
  runCleanup();
});
process.on("SIGINT", () => {
  runCleanup().then(() => process.exit(130));
});

// ── Utilities ───────────────────────────────────────────────────────────────

export function sleep(ms: number) {
  return new Promise((r) => setTimeout(r, ms));
}

export function log(section: string, message: string) {
  const CYAN = "\x1b[36m";
  const RESET = "\x1b[0m";
  console.log(`${CYAN}[${section}]${RESET} ${message}`);
}

export function success(message: string) {
  console.log(`\x1b[32m✓\x1b[0m ${message}`);
}

export function fail(message: string) {
  console.log(`\x1b[31m✗\x1b[0m ${message}`);
}

// ── Dashboard URLs ────────────────────────────────────────────────────────

export function dashboardUrl(path: string): string {
  const base = (process.env.NEXUS_DASHBOARD_URL ?? "https://gpt.nexus").replace(/\/+$/, "");
  return `${base}${path}`;
}

#!/usr/bin/env node
/**
 * conformance.mjs — deterministic contract checker for the agent tier + a skill's reference surface.
 *
 * Why this exists: a cross-artifact claim is a contract, and a contract nobody executes is a wish.
 * Every check here is a claim one file makes about another that nothing else reads.
 *
 *   node conformance.mjs [--root <repo .claude dir>] [--skill <name>] [--json] [--self-test]
 *
 * --self-test drives every check from BOTH directions, because a check has two ways to be useless:
 *
 *   CAN IT FIRE     — a known-bad fixture must produce a violation. A check that has never failed
 *                     proves nothing, and its green means nothing.
 *   DOES IT OVER-FIRE — a known-GOOD fixture must produce none. This half is the one that was
 *                     missing, and it is the more expensive failure: a checker that flags correct
 *                     work teaches its reader to skip it, and the real findings go with it.
 *
 * Both halves assert on the DELTA a fixture introduces against a fixture-free baseline, never on
 * the raw total — the sandbox copies one skill, so a cross-skill citation is unresolvable in it and
 * reports a violation in every run. An assertion phrased as "some violation carries this id" was
 * satisfied by that noise alone.
 *
 * A check with no known-good fixture is REPORTED as such, never counted as passing.
 *
 * A third half exists because the second one can pass vacuously: a known-good fixture that plants
 * content the check never reads is quiet for the wrong reason, and stays quiet with the check
 * deleted. So every known-good fixture is also planted with ONE defect grown in it, and must fire.
 *
 * CI runs `--self-test`, then the real pass, and the deploy job will not start until both are
 * green — `.github/workflows/deploy-skills.yml`, job `verify`.
 *
 * Exit 0 = clean. Exit 1 = at least one violation. Exit 2 = the checker itself is broken.
 */
import { readFileSync, writeFileSync, existsSync, readdirSync, statSync, mkdtempSync, rmSync, mkdirSync, cpSync } from 'node:fs';
import { join, dirname, resolve, relative, basename, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';
import { createHash } from 'node:crypto';

const HERE = dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const flag = (n, d = null) => { const i = argv.indexOf(n); return i >= 0 ? (argv[i + 1] ?? true) : d; };
const has = (n) => argv.includes(n);

const ROOT = resolve(flag('--root') || resolve(HERE, '..', '..', '..'));  // .../.claude
const SKILL = flag('--skill') || 'nexus-app-builder';
const AGENTS = join(ROOT, 'agents');
const SKILLDIR = join(ROOT, 'skills', SKILL);
const REFS = join(SKILLDIR, 'references');
const PROJECT_ROOT = dirname(ROOT);   // the dir that CONTAINS .claude/ — a lane's cwd, and the base every REF/… is relative to

// ── the lanes this checker governs: an agent file that names the skill's references or scripts ──
const LANE_RE = /^(app-.*|journey-verifier)\.md$/;

const violations = [];
const V = (check, file, line, msg, fix) => violations.push({ check, file, line, msg, fix });

const readLines = (p) => readFileSync(p, 'utf8').split('\n');
const lanes = () => existsSync(AGENTS)
  ? readdirSync(AGENTS).filter(f => LANE_RE.test(f)).sort()
  : [];
const rel = (p) => relative(ROOT, p) || p;

// walk every .md under a dir
function mdFiles(dir, acc = []) {
  if (!existsSync(dir)) return acc;
  for (const e of readdirSync(dir)) {
    const p = join(dir, e);
    if (statSync(p).isDirectory()) mdFiles(p, acc);
    else if (e.endsWith('.md')) acc.push(p);
  }
  return acc;
}

// frontmatter block (between the first two --- lines)
function frontmatter(lines) {
  if (lines[0]?.trim() !== '---') return {};
  const out = {};
  for (let i = 1; i < lines.length; i++) {
    if (lines[i].trim() === '---') break;
    const m = lines[i].match(/^([a-zA-Z_]+):\s*(.*)$/);
    if (m) out[m[1]] = { value: m[2].trim(), line: i + 1 };
  }
  return out;
}

// ────────────────────────────────────────────────────────────────────────────
// CHECK 1 — every REF/… and CAP token in a lane file resolves under the real references dir.
// The class: an agent file's pointers assume a base the lane never has.
// ────────────────────────────────────────────────────────────────────────────
function check1_refTokens() {
  const ID = 'REF-RESOLVES';
  for (const f of lanes()) {
    const p = join(AGENTS, f);
    readLines(p).forEach((ln, i) => {
      for (const m of ln.matchAll(/`REF\/([^`\s]+)`/g)) {
        if (/^[…\.]+$/.test(m[1]) || m[1].includes('<')) continue;   // the convention's own placeholder, not a pointer
        const target = join(REFS, m[1]);
        if (!existsSync(target)) {
          V(ID, rel(p), i + 1, `\`REF/${m[1]}\` does not resolve — no such file under ${rel(REFS)}/`,
            `create it, or correct the path`);
        }
      }
      // a bare legacy pointer form: any `…references/x.md` NOT expressed as REF/
      for (const m of ln.matchAll(/`((?:[\w.-]+\/)*references\/[\w./-]+\.(?:md|mjs|sh))`/g)) {
        V(ID, rel(p), i + 1, `legacy pointer \`${m[1]}\` — an agent file has no base for a relative path`,
          `rewrite as \`REF/${m[1].replace(/^.*references\//, '')}\``);
      }
    });
  }
}

// ────────────────────────────────────────────────────────────────────────────
// CHECK 2 — every path cited in the skill surface exists, and every quoted "## Section" matches a
// heading VERBATIM in its target. The class: a pointer that resolves to a file but not to a section.
// ────────────────────────────────────────────────────────────────────────────
/**
 * Paths that are RESOLVED AT RUN TIME in another repo — the app's own build tree, or a private npm
 * package the skill deliberately reads at build time rather than describing from recall. They are not
 * expected to exist here, and flagging them would train a reader to ignore this checker.
 */
const RUNTIME_PATHS = [
  /^docs\//, /^_/, /^journeys\//, /node_modules\//, /^ISSUE-LEDGER\.md$/,
  /^(AGENTS|CONTRIBUTING-AGENTS|PROVENANCE|RECIPES|ARCHITECTURE|DATA-MODEL|INDEX|record-core|THEMING|README)\.md$/,
  // ^ `README` joined that family for the reason the family exists, and it is the most
  //   generic member of it: every repo has one, so a backticked `README.md` in this
  //   corpus is describing SOMEBODY ELSE'S tree far more often than pointing into ours.
  //   `deploy-guide.md` says a freshly provisioned tenant repo arrives "containing
  //   `README.md`" — a statement about what the platform seeds, with no path, nothing
  //   to follow and nothing to correct. This checker read it as a dead pointer and told
  //   the reader to "correct the path", which is the shape that teaches people the
  //   checker is wrong and can be skipped.
  /^guard-fix\.mjs$/,          // authored PER APP by design (guard-fix-authoring.md)
  /^catalog\.json$/,
  /^(journeys|seams)\.py$/,
  /^INSTALL-note\.md$/,   // desktop-shell.md's per-app DMG note: generated INTO the app, not corpus
  /^(REPORT|HANDOFF|COVERAGE|report-1)\.md$/,
  // ^ lane-contract's LANE-MD bullet quotes these as RUNTIME artifact names (what a lane
  //   writes, or must NOT write) — the same generated-into-the-build class as journeys.py.
  // ^ the same family as `README.md` above, and admitted on the same reasoning: these are
  //   files in the APP repo a build produces, not files in this corpus. `journeys/` (the
  //   directory) is already exempt one line up; the bare `.py` spelling is the SINGLE-FILE
  //   form, and the decomposition doctrine cites it by its real name precisely because it
  //   is the measured anti-pattern — five lanes appending to one `journeys.py`. Telling a
  //   reader to "correct the path" on a filename quoted as a thing NOT to build is the
  //   shape that teaches people this checker is wrong and can be skipped.
];
const isRuntime = (c) => RUNTIME_PATHS.some(re => re.test(c));

function check2_skillPointers() {
  const ID = 'SKILL-POINTER';
  const files = [join(SKILLDIR, 'SKILL.md'), ...mdFiles(REFS)];
  for (const p of files) {
    if (!existsSync(p)) continue;
    const base = dirname(p);
    readLines(p).forEach((ln, i) => {
      // `path.md` optionally followed by "## Section"
      for (const m of ln.matchAll(/`([\w./-]+\.(?:md|mjs|sh|py))`(?:\s*"(##+ [^"]+)")?/g)) {
        const [, cited, section] = m;
        if (isRuntime(cited)) continue;
        if (cited.startsWith('REF/')) {                       // dispatch-resolved; check1 owns it
          const t = join(REFS, cited.slice(4));
          if (!/^[…\.]+$/.test(cited.slice(4)) && !existsSync(t))
            V(ID, rel(p), i + 1, `\`${cited}\` does not resolve under ${rel(REFS)}/`, 'correct the path');
          continue;
        }
        const cands = [join(base, cited), join(SKILLDIR, cited), join(REFS, cited), join(REFS, 'scripts', cited),
                       join(AGENTS, cited), join(ROOT, 'skills', cited), join(ROOT, cited),
                       join(PROJECT_ROOT, cited),                    // installed layout: <project>/.claude/…
                       join(ROOT, cited.replace(/^\.claude\//, ''))];  // distribution layout: the mirror
                       // ^ the same doc must validate in BOTH layouts. In an install, `.claude/skills/x`
                       //   hangs off the project root; in the distribution repo those contents ARE the root.
                       //   A path correct at runtime must not read as broken in the repo that ships it.
        const hit = cands.find(existsSync);
        if (!hit) {
          V(ID, rel(p), i + 1, `cited path \`${cited}\` does not exist from any sane base`, `correct the path`);
          continue;
        }
        if (section) {
          const body = readFileSync(hit, 'utf8');
          if (!body.split('\n').some(l => l.trim() === section.trim())) {
            V(ID, rel(p), i + 1, `quoted section "${section}" is not a verbatim heading in ${basename(hit)}`,
              `quote the target heading exactly (R#2)`);
          }
        }
      }
      // a bare quoted section ref with a named file earlier on the line, e.g. SKILL.md "Inner engine"
      for (const m of ln.matchAll(/([\w-]+\.md)\s+"([^"]{3,60})"/g)) {
        const [, cited, section] = m;
        if (isRuntime(cited)) continue;
        const cands = [join(base, cited), join(SKILLDIR, cited), join(REFS, cited), join(AGENTS, cited)];
        const hit = cands.find(existsSync);
        if (!hit) continue;
        const body = readFileSync(hit, 'utf8');
        const found = body.split('\n').some(l => /^#+\s/.test(l) && l.replace(/^#+\s*/, '').trim() === section.trim());
        if (!found) {
          V(ID, rel(p), i + 1, `"${section}" is not a verbatim heading in ${cited}`,
            `quote the heading exactly, or point at one that exists`);
        }
      }
    });
  }
}

// ────────────────────────────────────────────────────────────────────────────
// CHECK 3 — every lane carries the required contract sections.
// The class: the agent tier had no template, so section vocabulary drifted into 3 dialects.
// ────────────────────────────────────────────────────────────────────────────
const REQUIRED_SECTIONS = [
  { name: 'dispatch-carries', re: /^##\s+(Your dispatch carries|Inputs|Context to load)/im },
  { name: 'you-own',          re: /^##\s+You own/im },
  { name: 'done-when',        re: /^##\s+Done when/im },
];
// W27: the contract's own Method rule, enforced rather than assumed. Section PRESENCE was
// checked; what the section OPENS WITH was not — and a lane whose Method opens on a write is a
// lane that starts before it has read, which is the measured first-act failure.
function check3a_methodOpensWithRead() {
  const ID = 'METHOD-OPENS-WRITE';
  for (const f of lanes()) {
    const body = readFileSync(join(AGENTS, f), 'utf8');
    const lines = body.split('\n');
    const i = lines.findIndex(l => /^##\s+Method\b/i.test(l));
    if (i < 0) continue;
    let first = null;
    for (let k = i + 1; k < lines.length; k++) {
      if (/^##\s/.test(lines[k])) break;
      const t = lines[k].trim();
      if (t) { first = t; break; }
    }
    if (!first) continue;
    // Accept a READ imperative, or a pointer to the ordered opening that starts with one.
    if (!/^(#+\s*)?[*_\s]*\d*[.)]?[*_\s]*(READ|Read)\b/i.test(first)
        && !/first acts, in ORDER/i.test(first)) {
      V(ID, rel(join(AGENTS, f)), i + 2,
        'the first step under `## Method` is not a READ — this lane starts before it has read',
        'open Method with the read step (or with the ordered opening list that does)');
    }
  }
}

function check3_sections() {
  const ID = 'LANE-SECTIONS';
  for (const f of lanes()) {
    const p = join(AGENTS, f);
    const body = readFileSync(p, 'utf8');
    for (const s of REQUIRED_SECTIONS) {
      if (!s.re.test(body)) {
        V(ID, rel(p), 1, `missing required section: ${s.name}`,
          `add it — see references/agent-file-contract.md`);
      }
    }
    // a lane must be able to refuse an under-specified dispatch
    if (!/STOP and request|demand what is missing|STOP, request/i.test(body)) {
      V(ID, rel(p), 1, `no STOP-and-request rule — this lane cannot refuse an under-specified dispatch`,
        `add the stop clause to its dispatch-carries section`);
    }
  }
}

// ────────────────────────────────────────────────────────────────────────────
// CHECK 4 — the shared conduct block is byte-identical across every carrier.
// The class: N copies, no canonical source, drift is free.
// ────────────────────────────────────────────────────────────────────────────
// W27: three shared blocks now, not one. Any text duplicated across N lane files with no
// canonical source drifts for free, and the budget/write-scope blocks are carried by 13 files.
// W49: a FOURTH shared block existed all along and was never registered — so it drifted into
// four variants across 14 carriers, exactly as this comment predicts, on the one block the
// checker did not watch. The list is manually maintained; when a new heading is copy-pasted
// across lane files, its registration belongs in the SAME commit as the second copy.
const SHARED_HEADS = [
  '## Driving a browser — standing conduct',
  '## Working within your budget',
  '## Your write scope',
  '## Your addresses — FIXED, and nothing hands them to you',
];
function extractBlock(body, head) {
  const lines = body.split('\n');
  const s = lines.findIndex(l => l.trim() === head);
  if (s < 0) return null;
  let e = lines.length;
  for (let i = s + 1; i < lines.length; i++) if (/^##\s/.test(lines[i])) { e = i; break; }
  return lines.slice(s, e).join('\n').trimEnd();
}
function check4_blockDrift() {
  const ID = 'BLOCK-DRIFT';
  for (const head of SHARED_HEADS) {
    const seen = new Map();
    for (const f of lanes()) {
      const b = extractBlock(readFileSync(join(AGENTS, f), 'utf8'), head);
      if (b == null) continue;
      const h = createHash('sha256').update(b).digest('hex').slice(0, 16);
      if (!seen.has(h)) seen.set(h, []);
      seen.get(h).push(f);
    }
    if (seen.size > 1) {
      const groups = [...seen.entries()].map(([h, fs]) => `${h}: ${fs.join(', ')}`).join('  |  ');
      for (const [, fs] of seen) for (const f of fs) {
        V(ID, rel(join(AGENTS, f)), 1,
          `shared block "${head}" has drifted — ${seen.size} distinct versions across carriers`,
          `re-sync every carrier to one text. Groups → ${groups}`);
      }
    }
  }
}

// ────────────────────────────────────────────────────────────────────────────
// CHECK 5 — every typed final-message object carries the doctrine handoff fields.
// doctrine.md: "The orchestrator rejects a handoff missing `verified` … or `unverified`."
// ────────────────────────────────────────────────────────────────────────────
function check5_handoffSchema() {
  const ID = 'HANDOFF-SCHEMA';
  for (const f of lanes()) {
    const p = join(AGENTS, f);
    const lines = readLines(p);
    lines.forEach((ln, i) => {
      if (!/FINAL message is machine-consumed/i.test(ln)) return;
      const obj = ln.slice(ln.indexOf('{'));
      // W27 §6.1: docs_briefed[]/docs_read[] make a PARTIAL read visible at the moment of the
      // claim. The measured failure was a lane reporting "Reading complete" at 4-of-5 briefed
      // docs; a prose obligation the object cannot express is an obligation nobody can check.
      for (const req of ['verified', 'unverified', 'docs_briefed', 'docs_read']) {
        if (!new RegExp(`"${req}"`).test(obj)) {
          V(ID, rel(p), i + 1, `typed handoff omits "${req}" — doctrine.md rejects a handoff missing it`,
            `add "${req}":[…] to the object (empty is allowed; absent is not)`);
        }
      }
      if (/"not_verified"/.test(obj)) {
        V(ID, rel(p), i + 1, `uses "not_verified"; the doctrine field is "unverified"`, `rename the field`);
      }
    });
  }
}

// ────────────────────────────────────────────────────────────────────────────
