// ────────────────────────────────────────────────────────────────────────────
// CHECK 7 — frontmatter toolsets are real, and agree with the file's own prose.
// The class: `## Tools` prose and the `tools:` key are two declarations of one fact.
// ────────────────────────────────────────────────────────────────────────────
const REAL_TOOLS = new Set(['Bash','Read','Write','Edit','Grep','Glob','Skill','Agent','WebFetch','WebSearch',
  'NotebookEdit','Task','TaskCreate','TaskUpdate','TaskList','TaskGet','SendMessage','All tools','*']);
function check7_toolsets() {
  const ID = 'TOOLSET';
  for (const f of lanes()) {
    const p = join(AGENTS, f);
    const lines = readLines(p);
    const fm = frontmatter(lines);
    const body = lines.join('\n');
    if (fm.tools) {
      const raw = fm.tools.value;
      if (raw !== 'All tools' && raw !== '*') {
        const names = raw.split(',').map(s => s.trim()).filter(Boolean);
        for (const n of names) {
          if (!REAL_TOOLS.has(n)) {
            V(ID, rel(p), fm.tools.line, `\`tools:\` lists "${n}", which is not a tool name`,
              `enumerate real tools, or omit the key to inherit the default`);
          }
        }
        // prose says it writes, toolset grants no writer
        const claimsWrite = /Write access to|your only writes are|your writes are|You hold write access|write .{0,24}\.json|Write to the reviews dir/i.test(body);
        const hasWriter = names.includes('Write') || names.includes('Edit');
        if (claimsWrite && !hasWriter) {
          V(ID, rel(p), fm.tools.line, `prose says this lane WRITES an artifact, toolset grants neither Write nor Edit`,
            `add Write, or stop asking it to produce a file`);
        }
        // prose says it edits nothing, toolset grants a writer
        const claimsNoEdit = /You edit NOTHING|You edit nothing and score nothing/i.test(body);
        if (claimsNoEdit && hasWriter && !/your only writes are|your writes are/i.test(body)) {
          V(ID, rel(p), fm.tools.line, `prose says this lane edits NOTHING, toolset grants a writer`,
            `drop Write/Edit, or correct the prose`);
        }
      } else if (raw === 'All tools') {
        V(ID, rel(p), fm.tools.line, `\`tools: All tools\` is parsed as the two-name list ["All","tools"] — neither is a tool, so the lane inherits NOTHING`,
          `delete the key (inherits the full default) or enumerate real tool names`);
      }
    }
  }
}

// ────────────────────────────────────────────────────────────────────────────
// CHECK 8 — a doc may not promise enforcement that does not exist.
// Any "the <script> rejects/enforces/validates it" claim must name a script that has such a path.
// ────────────────────────────────────────────────────────────────────────────
function check8_promisedEnforcement() {
  const ID = 'PROMISED-ENFORCEMENT';
  const files = [join(SKILLDIR, 'SKILL.md'), ...mdFiles(REFS), ...lanes().map(f => join(AGENTS, f))];
  for (const p of files) {
    if (!existsSync(p)) continue;
    readLines(p).forEach((ln, i) => {
      const m = ln.match(/the\s+(\w[\w.-]*)\s+script\s+(rejects|validates|enforces)/i)
             || ln.match(/`([\w.-]+\.(?:mjs|sh|py))`\s+(rejects|validates|enforces)/i);
      if (!m) return;
      const name = m[1].endsWith('.mjs') || m[1].endsWith('.sh') || m[1].endsWith('.py') ? m[1] : `${m[1]}.mjs`;
      const cand = [join(REFS, 'scripts', name), join(ROOT, 'skills', 'shared', 'scripts', name)].find(existsSync);
      if (!cand) {
        V(ID, rel(p), i + 1, `claims "${name} ${m[2]}" but no such script exists`, `build it, or delete the claim`);
        return;
      }
      const src = readFileSync(cand, 'utf8');
      if (!/process\.exit\(1\)|throw new|REJECT|nonconformant|non-conformant|exit 1/i.test(src)) {
        V(ID, rel(p), i + 1, `claims "${name} ${m[2]}" but that script has no rejection path`,
          `add the validation to ${name}, or delete the claim — a promised net nobody built makes seats under-invest`);
      }
    });
  }
}

// ────────────────────────────────────────────────────────────────────────────
// CHECK 9 — no machine-specific absolute path may ship.
// The class: this repo is installed under a different folder, by a different user, on every machine
// that runs it. `/Users/<someone>/…` is correct exactly once and silently wrong everywhere else —
// the read just fails and the lane goes foraging. Addresses are project-root-relative or nothing.
// ────────────────────────────────────────────────────────────────────────────
const ABS_RE = /(^|[\s`'"(=])(\/(Users|home|root)\/[\w.-]+\/[^\s`'")]*)/;
function check9_machinePaths() {
  const ID = 'MACHINE-PATH';
  const files = [join(SKILLDIR, 'SKILL.md'), ...mdFiles(REFS), ...lanes().map(f => join(AGENTS, f))];
  for (const p of files) {
    if (!existsSync(p)) continue;
    if (p.includes(`${sep}built${sep}`)) continue;          // generated; regenerated from source
    readLines(p).forEach((ln, i) => {
      const m = ln.match(ABS_RE);
      if (!m) return;
      if (/~\/\.nexus-tools|~\/\.nexus-secrets/.test(ln)) return;   // documented home-relative tool paths
      V(ID, rel(p), i + 1, `machine-specific absolute path: ${m[2].slice(0, 60)}`,
        'express it relative to the project root (the dir containing `.claude/`) — this tree is installed under a different folder for every user');
    });
  }
}

// ────────────────────────────────────────────────────────────────────────────
// CHECK 10 — a SUPERSEDED rule may not survive anywhere in the surface.
// The class this exists for, measured: a contrast caveat was retired in two references with a dated
// note, and stayed live in three agent files — one of them as a numbered rule under "Critical decisions
// (first match wins)". Half a sweep is worse than none: the reference says the finding is real, the
// judge that reads the agent file discards it, and nothing reads both. Retiring a rule now means
// registering its phrasing here, so its survival anywhere fails deterministically.
// ────────────────────────────────────────────────────────────────────────────
const SUPERSEDED = [
  { retired: /contrast (fail|numbers?)[^.\n]{0,60}(is|are) (a )?candidates?/i,
    what: 'accent-element contrast as a "candidate" needing a shot-confirm',
    now:  'probe contrast is AUTHORITATIVE (oklab/oklch resolved in-page); only color-mix() with unresolved vars is skipped',
    on:   '2026-07' },
  { retired: /probe\.mjs/i,
    what: 'the pre-rename instrument name', now: 'capture.mjs', on: '2026-07' },
];
function check10_superseded() {
  const ID = 'SUPERSEDED';
  const files = [join(SKILLDIR, 'SKILL.md'), ...mdFiles(REFS), ...lanes().map(f => join(AGENTS, f))];
  for (const p of files) {
    if (!existsSync(p)) continue;
    if (p.endsWith('conformance.mjs')) continue;
    readLines(p).forEach((ln, i) => {
      if (/Superseded \d{4}-\d{2}|superseded[:,]/i.test(ln)) return;   // the dated retirement note itself
      for (const r of SUPERSEDED) {
        if (r.retired.test(ln)) {
          V(ID, rel(p), i + 1, `superseded rule still live: ${r.what} (retired ${r.on})`,
            `it now reads: ${r.now} — sweep this occurrence, or the judge reading this file will apply the retired rule`);
        }
      }
    });
  }
}

const CHECKS = [
